import torch
import torch.nn.functional as F 

def latent_loss(x_embedding: torch.Tensor, meta_embedding: torch.Tensor) -> torch.Tensor:
    batch_size = x_embedding.shape[0]
    # Multi-scale kernel density estimation
    scales = torch.tensor([0.1, 0.5, 1.0], device=x_embedding.device)
    dist_matrix = torch.cdist(x_embedding, x_embedding)

    density_loss = 0
    for scale in scales:
        kernel = torch.exp(-dist_matrix / (2 * scale * scale))
        density = kernel.sum(dim=1) / batch_size
        density_loss += -torch.log(density + 1e-6).mean()

    # Diffusion distance mapping
    transition = kernel / kernel.sum(dim=1, keepdim=True)
    diffused_x = torch.matmul(transition, x_embedding)
    diffusion_loss = torch.norm(diffused_x - x_embedding, dim=1).mean()

    # Task-specific repulsion
    x_norm = F.normalize(x_embedding, dim=1)
    meta_norm = F.normalize(meta_embedding, dim=1)
    task_sim = torch.matmul(x_norm, meta_norm.t())
    task_probs = F.softmax(task_sim / 0.1, dim=1)

    task_repulsion = torch.matmul(task_probs, task_probs.t())
    repulsion_loss = torch.mean(task_repulsion * torch.exp(-dist_matrix))

    # Smooth boundary transitions
    boundary_kernel = torch.exp(-task_sim)
    boundary_density = torch.matmul(boundary_kernel, task_probs)
    smoothness_loss = torch.mean((boundary_density - task_probs)**2)

    # Combined loss with balanced weights
    loss = (0.3 * density_loss +
            0.3 * diffusion_loss +
            0.2 * repulsion_loss +
            0.2 * smoothness_loss)

    return loss
\end{python}
