import torch 

def additional_loss(x_embedding: torch.Tensor, meta_embedding: torch.Tensor) -> torch.Tensor:
    x_dist = torch.cdist(x_embedding, x_embedding)
    m_dist = torch.cdist(meta_embedding, meta_embedding)

    x_rank = torch.argsort(torch.argsort(x_dist, dim=1), dim=1).float()
    m_rank = torch.argsort(torch.argsort(m_dist, dim=1), dim=1).float()

    rank_corr = torch.mean((x_rank - m_rank)**2)

    dist_ratio = x_dist / (m_dist + 1e-8)
    consistency = torch.mean(torch.abs(dist_ratio - torch.median(dist_ratio)))

    return rank_corr + 0.2 * consistency
\end{python}
