\section{Problem formulation, notation, and preliminaries}\label{sec-2}
\subsection{Model problem and finite element discretization}
Let $\Omega\subset\mathbb{R}^{d}$, $d=2,3$, be a bounded Lipschitz domain with a polygonal boundary $\Gamma:=\partial \Omega$ ($\Omega$ and $\Gamma$ may have nontrivial topologies). We consider the following curl-curl problem: Find ${\bm u}:\Omega\rightarrow \mathbb{R}^{d}$ such that
\begin{equation}\label{eq:continuous_model_prob}
\left\{
\begin{array}{lll}
 \nabla \times (\nu \nabla\times {\bm u}) + \kappa {\bm u}= {\bm f}\,\quad &{\rm in}\;\, \Omega \\[2mm]
  \qquad \qquad\quad\quad  {\bm n}\times {\bm u} = {\bm 0} \,\quad &{\rm on}\;\, \Gamma, 
\end{array}
\right.
\end{equation}
where ${\bm n}$ is the outward unit normal to $\Gamma$. To simplify the presentation, we only consider the homogeneous Dirichlet boundary condition in \cref{eq:continuous_model_prob}, but the methods presented in this paper are directly applicable to general boundary conditions. Before defining the weak formulation of problem \cref{eq:continuous_model_prob}, we introduce some notation that will be used throughout the paper. For a bounded Lipschitz domain $D\subset\mathbb{R}^{d}$, we define 
\begin{equation}
\begin{split}
{\bm H}({\rm curl};D) :&=\big\{{\bm u}\in {\bm L}^{2}(D): \nabla\times {\bm u}\in {\bm L}^{2}(D) \big\},\\
{\bm H}({\rm div};D) :&=\big\{{\bm u}\in {\bm L}^{2}(D): \nabla\cdot {\bm u}\in L^{2}(D) \big\},\\
{\bm H}_{0}({\rm curl};D) :&=\big\{{\bm u}\in {\bm H}({\rm curl};D): {\bm n}\times {\bm u} = {\bm 0}\;\;\text{on}\;\;\partial D \big\},\\
{\bm H}_{0}({\rm div};D) :&=\big\{{\bm u}\in {\bm H}({\rm div};D): {\bm n}\cdot {\bm u} = 0\;\;\text{on}\;\;\partial D \big\},
\end{split}
\end{equation}
which are equipped with the norms $\Vert {\bm u}\Vert_{{\bm H}({\rm curl};D)} : = \big(\Vert {\bm u}\Vert^{2}_{{\bm L}^{2}(D)} + \Vert \nabla\times {\bm u}\Vert^{2}_{{\bm L}^{2}(D)} \big)^{\frac12}$ and 
$\Vert {\bm u}\Vert_{{\bm H}({\rm div};D)} : = \big(\Vert {\bm u}\Vert^{2}_{{\bm L}^{2}(D)} + \Vert \nabla\cdot {\bm u}\Vert^{2}_{L^{2}(D)} \big)^{\frac12}$, respectively. Moreover, let ${\bm H}_{0}({\rm curl};D)^{\prime}$ denote the dual space of ${\bm H}_{0}({\rm curl};D)$. Throughout this paper, we assume that ${\bm f}\in {\bm H}_{0}({\rm curl};\Omega)^{\prime}$, and that the coefficients $\nu$ and $\kappa$ satisfy the following conditions.
\begin{assumption}\label{ass:coefficients}
\begin{enumerate}
\item[(i)] $\nu\in L^{\infty}(\Omega, \mathbb{R}_{\rm sym}^{d\times d})$, and there exist $0<\nu_{\rm min}\leq \nu_{\rm max}<+\infty$ such that $\nu_{\rm min}|{\bm \xi}|^{2}\leq \nu({\bm x}){\bm \xi}\cdot{\bm \xi}^{T} \leq \nu_{\rm max}|{\bm \xi}|^{2}$ for $a.e \; {\bm x}\in \Omega$ and all ${\bm \xi}\in \mathbb{R}^{d}$.

\vspace{1ex}
\item[(ii)] $\kappa\in L^{\infty}(\Omega, \mathbb{R}_{\rm sym}^{d\times d})$, and there exist $0<\kappa_{\rm min}\leq \kappa_{\rm max}<+\infty$ such that $\kappa_{\rm min}|{\bm \xi}|^{2}\leq \kappa({\bm x}){\bm \xi}\cdot{\bm \xi}^{T} \leq \kappa_{\rm max}|{\bm \xi}|^{2}$ for $a.e \; {\bm x}\in \Omega$ and all ${\bm \xi}\in \mathbb{R}^{d}$.


