For a domain $D\subset\Omega$, we define a bilinear form $a_{D}:{\bm H}({\rm curl};D)\times {\bm H}({\rm curl};D)\rightarrow \mathbb{R}$ as
\begin{equation}\label{local_sesqui_form}
    a_{D}({\bm v}, {\bm w}):=(\nu\nabla\times{\bm v}, \nabla\times{\bm w})_{{\bm L}^{2}(D)} + (\kappa{\bm v}, {\bm w})_{{\bm L}^{2}(D)}.
\end{equation} 
Moreover, we define the energy norm $\Vert {\bm v}\Vert_{a,D}:=\sqrt{a_{D}({\bm v},{\bm v})}$ for ${\bm v}\in {\bm H}({\rm curl};D)$. When $D=\Omega$, we drop the domain index and simply write $a(\cdot,\cdot)$ and $\Vert {\bm v}\Vert_{a}$. The weak formulation of problem \cref{eq:continuous_model_prob} is defined by: Find ${\bm u}\in {\bm H}_{0}({\rm curl};\Omega)$ such that 
\begin{equation}\label{eq:weak_form}
a({\bm u}, {\bm v}) =  \langle {\bm f},  {\bm v} \rangle_{\Omega}\quad \text{for all}\;\;{\bm v}\in {\bm H}_{0}({\rm curl};\Omega),  
\end{equation}
where $\langle \cdot,\cdot\rangle_{\Omega}$ denotes the duality pairing between ${\bm H}_{0}({\rm curl};\Omega)^{\prime}$ and ${\bm H}_{0}({\rm curl};\Omega)$. By \cref{ass:coefficients}, there exists a constant $C_{\rm ell}>0$, such that for any subdomain $D\subset\Omega$, 
\begin{equation*}
|a_{D}({\bm v}, {\bm v})|\geq C_{\rm ell} \Vert {\bm v}\Vert^{2}_{{\bm H}({\rm curl};D)} \quad \text{for all}\;\;{\bm v}\in {\bm H}({\rm curl};D).  
\end{equation*}
Therefore, by the Lax--Milgram theorem, problem \cref{eq:weak_form} is uniquely solvable.

% The curl-curl problem \cref{eq:continuous_model_prob} with \cref{ass:coefficients} covers two important cases of Maxwell's equations. The first case is the time-harmonic Maxwell's equations in an absorbing medium, with $\nu=\mu^{-1}$, $\kappa=-\textit{\textomega}^{2}\varepsilon + {\rm i}\textit{\textomega}\sigma$, and ${\bm F} = -{\rm i}\textit{\textomega}{\bm J}$. Here $\mu$ is the magnetic permeability, $\varepsilon$ is the electric permittivity, $\sigma$ is the conductivity, and ${\bm J}$ is the current density. In this case, the coercivity of $a_{D}(\cdot,\cdot)$ holds true; see \cite[Lemma 2.5]{bonazzoli2019domain}. The second case is semi-discretized (in time) Maxwell's equations with an implicit time stepping scheme. In this case, $\nu,\kappa>0$, and ${\bm F}\in {\bm H}_{0}({\rm curl};\Omega)^{\prime}$. Throughout the paper, we assume that the family $\{\mathcal{T}_{h}\}$ is shape regular in the sense of Ciarlet \cite{}.

Now we consider the standard finite element approximation of problem \cref{eq:continuous_model_prob}. Let $\{\mathcal{T}_{h}\}$ be a family of shape-regular simplicial triangulations of $\Omega$, indexed by the mesh size $h:= \max_{K\in \mathcal{T}_{h}} {\rm diam}(K)$. Given an element $K$, let $\mathbb{P}_{r}(K)$ be the set of polynomials of maximum total degree $r$ ($r\in\mathbb{N}$) defined on $K$. The Raviart-Thomas and N\'{e}d\'{e}lec polynomial spaces defined on $K$ are given as
\begin{align}\label{eq:element_polynomials}
\begin{split}
{\bm D}_{r}(K):= \big(\mathbb{P}_{r-1}(K)\big)^{d} \oplus {\bm x}\, \widetilde{\mathbb{P}}_{r-1}(K),\quad {\bm R}_{r}(K):= \big(\mathbb{P}_{r-1}(K)\big)^{d} \oplus \mathcal{\bm S}_{r}(K),
\end{split}
\end{align}
where $\widetilde{\mathbb{P}}_{r-1}(K)$ denotes the space of homogeneous polynomials of degree $r-1$ on $K$, and $\mathcal{\bm S}_{r}(K):=\big\{{\bm p}\in \big(\widetilde{\mathbb{P}}_{r}(K)\big)^{d}: {\bm x}\cdot {\bm p} = 0 \big\}$. On a triangulation $\mathcal{T}_h$, we define the $r$-order $H^{1}(\Omega)$-, ${\bm H}({\rm div};\Omega)$-, and ${\bm H}({\rm curl};\Omega)$-conforming finite element spaces as 
\begin{align}
\begin{split}
S_{h}(\Omega)&:= \big\{v\in H^{1}(\Omega): v|_{K} \in \mathbb{P}_{r}(K)\quad \forall K\in \mathcal{T}_h   \big\},\\    
  {\bm U}_{h}(\Omega)&:= \big\{{\bm v} \in {\bm H}({\rm div};\Omega): {\bm v}|_{K}  \in {\bm D}_r(K)\quad \forall K \in  \mathcal{T}_{h}\big\},\\
  {\bm Q}_{h}(\Omega)&:= \big\{{\bm v} \in {\bm H}({\rm curl};\Omega): {\bm v}|_{K}  \in {\bm R}_r(K)\quad \forall K \in  \mathcal{T}_{h}\big\}, \\
\end{split}
\end{align}
and set $S_{h,0}(\Omega):=S_{h}(\Omega)\cap H_{0}^{1}(\Omega)$, $ {\bm U}_{h,0}(\Omega):=  {\bm U}_{h}(\Omega)\cap {\bm H}_{0}({\rm div};\Omega)$, and ${\bm Q}_{h,0}(\Omega):=  {\bm Q}_{h}(\Omega)\cap {\bm H}_{0}({\rm curl};\Omega)$. 
% We define ${\bm Q}_{h}\subset {\bm H}_{0}({\rm curl};\Omega)$ as the N\'{e}d\'{e}lec curl-conforming finite element space of order $r$ on the mesh $\mathcal{T}_{h}$, consisting of functions with vanishing tangential trace on $\partial \Omega$. More precisely, 
% \begin{equation}
%   {\bm Q}_{h}:= \{{\bf u}_{h} \in \mathbf{H}_{0}({\rm curl};\Omega): \; {\bf u}_{h}|_{K}  \in {\bm R}_r(K), \; \forall K \in  \mathcal{T}_{h}\},
% \end{equation}
% where ${\bm R}_{r}$ is the $r$-order N\'{e}d\'{e}lec polynomial space (see \cite[Chapter 5]{monk2003finite}). 
The standard Galerkin finite element discretization of problem \cref{eq:weak_form} is defined by: Find ${\bm u}_{h}\in {\bm Q}_{h,0}(\Omega)$ such that 
\begin{equation}\label{eq:galerkin_discretization}
a({\bm u}_h, {\bm v}_h) =  \langle {\bm f},  {\bm v}_h \rangle_{\Omega}\quad \text{for all}\;\;{\bm v}_h\in {\bm Q}_{h,0}(\Omega).
\end{equation}
Let $\{{\bm w}_{j}\}_{j=1}^{m}$ be a basis for ${\bm Q}_{h,0}(\Omega)$ with $m:={\rm dim}\,{\bm Q}_{h,0}(\Omega)$. Then, the Galerkin discretization \cref{eq:galerkin_discretization} can be written as a linear system of equations:
\begin{equation}\label{eq:linear_system}
 {\bf Au} = {\bf f}\quad \text{with}\quad {\bf A}\in \mathbb{R}^{m\times m},\quad {\bf A}_{ij}= a({\bm w}_i, {\bm w}_j), \quad \text{and} \quad {\bf f}_i = \langle {\bm f},  {\bm w}_i \rangle_{\Omega}.  
\end{equation}
We conclude this subsection by fixing some notation that will be used in the sequel. For a subdomain $D$ of $\Omega$, we define
\begin{align}\label{eq:local_spaces}
\begin{split}
H^{1}_{\Gamma}(D)&:=\{v\in H^{1}(D): v=0\;\;\, \text{on}\;\;\Gamma\cap \partial D\},  \\
{\bm H}_{\Gamma}({\rm div};D)&:= \{{\bm v}\in {\bm H}({\rm div};D) : {\bm n}\cdot{\bm v}=0\;\;\, \text{on}\;\;\Gamma\cap \partial D\},  \\
{\bm H}_{\Gamma}({\rm curl};D)&:= \{{\bm v}\in {\bm H}({\rm curl};D) : {\bm n}\times{\bm v}={\bm 0}\;\;\, \text{on}\;\;\Gamma\cap \partial D\},\\
S_{h,\Gamma}(D):=\{&v_h|_{D}: v_h\in S_{h,0}(\Omega)\},\; S_{h,0}(D):=S_{h,\Gamma}(D)\cap H_{0}^{1}(D),\\
  {\bm U}_{h,\Gamma}(D):=\{&{\bm v}_h|_{D}: {\bm v}_h\in {\bm U}_{h,0}(\Omega)\},\;  {\bm U}_{h,0}(D) :=  {\bm U}_{h,\Gamma}(D)\cap {\bm H}_{0}({\rm div};D),\\
  {\bm Q}_{h,\Gamma}(D):=\{&{\bm v}_h|_{D}: {\bm v}_h\in {\bm Q}_{h,0}(\Omega)\},\;  {\bm Q}_{h,0}(D): =  {\bm Q}_{h,\Gamma}(D)\cap {\bm H}_{0}({\rm curl};D).
\end{split}
\end{align}
Furthermore, for an element $K\in \mathcal{T}_h$, let $\Sigma_{K}: {\bm H}^{1}(K)\rightarrow {\bm D}_{r}(K)$ and $\Pi_{K}: {\bm H}^{1}(K)\rightarrow {\bm R}_{r}(K)$
be, respectively, the Raviart-Thomas and N\'{e}d\'{e}lec interpolation operators defined by specifying the degrees of freedom (see, e.g., \cite[Chapter 2.5]{boffi2013mixed}). The global interpolation operators $\Sigma_h$ and $\Pi_h$ are defined elementwise as $\Sigma_h{\bm u}|_{K}:= \Sigma_{K} ({\bm u}|_K)$ and $\Pi_h{\bm u}|_{K}:= \Pi_{K} ({\bm u}|_K)$. The operators $\Sigma_h$ and $\Pi_h$ satisfy the following "commuting diagram property":
\begin{equation}\label{eq:commuting_property}
\nabla\times \Pi_h {\bm u} = \Sigma_h \nabla\times {\bm u}\quad \forall {\bm u} \in {\bm H}^{1}(\Omega) \;\text{with}\;\nabla\times {\bm u}\in {\bm H}^{1}(\Omega).    
\end{equation}


\subsection{Preliminaries}\label{subsec:preliminaries}
In this subsection, we present some lemmas and preliminaries that will be used for the analysis in \cref{sec-4}. The first lemma gives the regular decomposition of vector fields in ${\bm H}_{0}({\rm curl};\Omega)$, which can be found in \cite[Theorem 2, Remark 3]{hiptmair2020review} and \cite[Lemma 3.1]{faustmann2022h}. We note that while the proofs in \cite{hiptmair2020review,faustmann2022h} focus on the three-dimensional case, an extension to $\mathbb{R}^{2}$ is straightforward.
\begin{lemma}[Regular decomposition]\label{lem:regular_decomposition}
Let $\Omega\subset \mathbb{R}^{d}$ $(d=2,3)$ be a bounded Lipschitz polyhedral domain. Then for each ${\bm u}\in {\bm H}_{0}({\rm curl};\Omega)$, there exist ${\bm z}\in {\bm H}_{0}^{1}(\Omega)$ and $p\in H_{0}^{1}(\Omega)$ such that ${\bm u} = {\bm z} + \nabla p$, with the estimates
\begin{align}\label{eq:estimate_regular_decomp}
\begin{split}
 \Vert {\bm z}\Vert_{{\bm L}^{2}(\Omega)} +   \Vert  p\Vert_{L^{2}(\Omega)} &\leq C\Vert{\bm u}  \Vert_{{\bm L}^{2}(\Omega)},\\
\Vert \nabla {\bm z}\Vert_{{\bm L}^{2}(\Omega)} + {\rm diam}(\Omega)^{-1} \Vert {\bm z}\Vert_{{\bm L}^{2}(\Omega)}+ \Vert  \nabla p\Vert_{{\bm L}^{2}(\Omega)} &\leq C\Vert \nabla \times {\bm u}  \Vert_{{\bm L}^{2}(\Omega)}, 
\end{split}
\end{align}
where $C>0$ depends only on the shape of $\Omega$, but not on ${\rm diam}(\Omega)$.   
\end{lemma}
The next lemma gives error estimates for the interpolation operator $\Pi_h$ defined above.
\begin{lemma}[{\cite[Theorem 5.41]{monk2003finite}}]\label{lem:error_estimates_interpolation}
Let $\Pi_h$ be the N\'{e}d\'{e}lec interpolation operator, and let $K\in \mathcal{T}_h$ be an element. There exists a constant $C$ independent of $h_K$ such that for $1\leq s\leq r$,
\begin{align}\label{eq:error_nedelec_interpolation_1}
\begin{split}
\Vert {\bm u} -   \Pi_h{\bm u}\Vert_{{\bm L}^{2}(K)}  &\leq Ch_{K}^{s}\big(|{\bm u}|_{{\bm H}^{s}(K)}+  |\nabla\times {\bm u}|_{{\bm H}^{s}(K)}\big),\\
\Vert \nabla\times ({\bm u} -   \Pi_h{\bm u})\Vert_{{\bm L}^{2}(K)}  &\leq Ch_{K}^{s}|\nabla\times {\bm u}|_{{\bm H}^{s}(K)},
\end{split}
\end{align}
where $|\cdot|_{{\bm H}^{1}(K)}$ denotes the ${\bm H}^{1}(K)$ semi-norm. Moreover, if ${\bm u}\in {\bm H}^{1}(K)$ and $\nabla\times {\bm u}|_{K}\in {\bm D}_r(K)$, where ${\bm D}_r(K)$ is defined in \cref{eq:element_polynomials}, then
\begin{equation}\label{eq:error_nedelec_interpolation_2}
\Vert {\bm u} - \Pi_h{\bm u}\Vert_{{\bm L}^{2}(K)}\leq Ch_{K}\big(|{\bm u}|_{{\bm H}^{1}(K)} + \Vert \nabla \times {\bm u}\Vert_{{\bm L}^{2}(K)}\big).
\end{equation}
\end{lemma}

The following lemma shows that the $r$-order derivatives of a polynomial ${\bm p}\in {\bm R}_{r}(K)$ can be bounded by the $(r-1)$-order derivatives of its curl. This property is vital to the proof of a super-approximation estimate for N\'{e}d\'{e}lec elements in \cref{subsec:proof of Cac-inequality}. Whereas it is known for the lowest-order N\'{e}d\'{e}lec element (see, e.g., \cite[Lemma 4.1]{faustmann2022h}), the following result for arbitrary high-order elements seems new. 
\begin{lemma}\label{lem:equiv_norm}
There exists a constant $C$ depending only on $r$ and $d$, such that for any ${\bm p}\in {\bm R}_{r}(K)$, with ${\bm R}_{r}(K)$ defined in \cref{eq:element_polynomials}, 
\begin{equation}\label{eq:norm-control}
    \sum_{|\bm \alpha| = r} |\partial^{\bm \alpha} {\bm p} | \leq C\sum_{|\bm \alpha| = r-1} |\partial^{\bm \alpha} \nabla\times {\bm p} |,
\end{equation}
where ${\bm \alpha}=(\alpha_1,\cdots,\alpha_{d})$ is the multi-index with $\alpha_i\geq 0$, $|{\bm \alpha}| = \alpha_1+\cdots\alpha_d$, and $\partial^{\bm \alpha} = \partial^{\alpha_1}_{x_1}\cdots \partial^{\alpha_d}_{x_d}$. 
\end{lemma}
\begin{proof}
We prove this lemma by a direct computation. Noting that ${\bm R}_{r}(K)= \big(\mathbb{P}_{r-1}(K)\big)^{d} \oplus \mathcal{\bm S}_{r}(K)$, and that for ${\bm p}\in \big(\mathbb{P}_{r-1}(K)\big)^{d}$, $\partial^{\bm \alpha} {\bm p} = {\bm 0}$ for $|{\bm \alpha}| = r$, and $\partial^{\bm \alpha} \nabla\times {\bm p} = {\bm 0}$ for $|{\bm \alpha}| = r-1$, we only need to prove inequality \cref{eq:norm-control} for ${\bm p}\in \mathcal{\bm S}_{r}(K)$. Without loss of generality, we assume that $d=3$. By \cite{bergot2010generation}, the space $\mathcal{\bm S}_{r}(K)$ is spanned by the following polynomials vectors:
\begin{align*}
&\text{for} \;\;0\leq m+n\leq r,\; m\neq 0 \;\;\text{and}\;\;n\neq r: 
\left(
\begin{array}{cc}
x_1^{m-1}x_2^{n}x_3^{r-m-n+1} \\
0\\
-x_1^{m}x_2^{n}x_3^{r-m-n}
\end{array}
      \right),  \\[1ex] 
&\text{for} \;\;0\leq m+n\leq r,\; m\neq r \;\;\text{and}\;\;n\neq 0: 
\left(
\begin{array}{cc}
0\\
x_1^{m}x_2^{n-1}x_3^{r-m-n+1} \\
-x_1^{m}x_2^{n}x_3^{r-m-n}
\end{array}
      \right),  \\[1ex]
 &\text{for} \;\;m+n=r+1,\; m\neq 0 \;\;\text{and}\;\;n\neq 0: 
\left(
\begin{array}{cc}
x_1^{m-1}x_2^{n} \\
-x_1^{m}x_2^{n-1} \\
0
\end{array}
\right).
\end{align*}
For convenience, we denote these three sets of polynomials vectors by ${\bm u}_{m,n}$,  ${\bm v}_{m,n}$, and ${\bm w}_{m,n}$, respectively. Then, any ${\bm p}\in {\bm R}_{r}(K)$ can be written as 
\begin{equation}
    {\bm p} = \sum_{\substack{0\leq m+n\leq r,\\ {m\neq 0, \,n\neq r}}} a_{m,n}{\bm u}_{m,n} + \sum_{\substack{0\leq m+n\leq r,\\ {m\neq r, \,n\neq 0}}} b_{m,n}{\bm v}_{m,n} + \sum_{\substack{ m+n=r+1,\\ {m\neq 0, \,n\neq 0}}} c_{m,n}{\bm w}_{m,n},
\end{equation}
with $a_{m,n},b_{m,n}, c_{m,n}\in \mathbb{R}$. It suffices to prove that 
\begin{equation}\label{eq:reduced_result}
\sum_{|\bm \alpha| = r-1} |\partial^{\bm \alpha} \nabla\times {\bm p} |\geq C\Bigg(\sum_{\substack{0\leq m+n\leq r,\\ {m\neq 0, \,n\neq r}}} |a_{m,n}|  + \sum_{\substack{0\leq m+n\leq r,\\ {m\neq r, \,n\neq 0}}} |b_{m,n}| + \sum_{\substack{ m+n=r+1,\\ {m\neq 0, \,n\neq 0}}} |c_{m,n}|  \Bigg).    
\end{equation}
Noting that 
\begin{align*}
\begin{split}
    \nabla\times {\bm u}_{m,n} = \big(-nx_1^{m}x_2^{n-1}x_3^{r-m-n}, \;& (r-n+1)x_1^{m-1}x_2^{n}x_3^{r-m-n},\\
        -n x_1^{m-1}x_2^{n-1}x_3^{r-m-n+1} \big),  \;\;\nabla\times {\bm v}_{m,n} =& \big(-(r-m+1)x_1^{m}x_2^{n-1}x_3^{r-m-n}, \\
          mx_1^{m-1}x_2^{n}x_3^{r-m-n}, mx_1^{m-1}x_2^{n-1}x_3^{r-m-n+1} \big), & \nabla\times {\bm w}_{m,n} = \big(0, 0, -(m+n) x_1^{m-1}x_2^{n-1}\big),
\end{split}
\end{align*}
we find that for any $(m>1, n>1, m+n<r)$, the sum $\sum_{|\bm \alpha| = r-1} |\partial^{\bm \alpha} \nabla\times {\bm p}|^{2}$ contains the following two terms involving $a_{m,n}$ and $b_{m,n}$:
\begin{align*}
\begin{split}
    [m(n-1)(r-m-n)]^{2} \big(na_{m,n} &+ (r-m+1)b_{m,n}\big)^{2} \\
    + [(m-1)n(r-m-n)]^{2} \big((r-n+1)a_{m,n} &+ mb_{m,n}\big)^{2}  \geq C(|a_{m,n}|^{2} + |b_{m,n}|^{2}),
\end{split}
\end{align*}
where the inequality above follows from the fact that $m+n\neq r+1$. Similar estimates hold for other coefficients $(a_{m,n},b_{m,n})$ and also $c_{m,n}$. Therefore, inequality \cref{eq:reduced_result} holds true and the lemma is thus proved.
\end{proof}

Next we discuss the spaces of "harmonic forms". For a domain $D\subset \Omega$ which is a union of elements in $\mathcal{T}_h$ and may intersect $\Gamma$, we recall the spaces defined in \cref{eq:local_spaces} and consider the de Rham complex with \textit{partial boundary conditions}:
\begin{equation}\label{eq:continuous_deRham_complex} 
H^{1}_{\Gamma}(D) \xrightarrow{\;\; \nabla\;\;} {\bm H}_{\Gamma}({\rm curl};D) \xrightarrow{\;\; \nabla\times \;\;} {\bm H}_{\Gamma}({\rm div};D) \xrightarrow{\;\; \nabla\cdot \;\;} L^{2}(D).
\end{equation}
The corresponding discrete de Rham complex reads
\begin{equation}\label{eq:discrete_deRham_complex} 
S_{h,\Gamma}(D) \xrightarrow{\;\; \nabla\;\;} {\bm Q}_{h,\Gamma}(D) \xrightarrow{\;\; \nabla\times \;\;} {\bm U}_{h,\Gamma}(D) \xrightarrow{\;\; \nabla\cdot \;\;} Z_h(D),
\end{equation}
where $Z_h(D)\subset L^{2}(D)$ denotes the space consisting of piecewise polynomials of maximum total degree $r-1$. Furthermore, we consider the space of harmonic 1-forms (the first cohomology space) associated with the de Rham complex with the $\kappa$-weighted $L^{2}$-norm:
\begin{align}\label{eq:continuous-harmonic-forms}
\begin{split}
\mathcal{\bm H}(D):= \big\{{\bm v}\in {\bm H}_{\Gamma}({\rm curl};D): \nabla\times {\bm v} = {\bm 0},\;(\kappa{\bm v}, \nabla \xi)_{{\bm L}^{2}(D)} = 0 \;\, \forall\,\xi\in H^{1}_{\Gamma}(D)\big\},       
\end{split}
\end{align}
and its discrete counterpart:
\begin{align}\label{eq:general_discrete-harmonic-forms}
\begin{split}
\mathcal{\bm H}_{h}(D):= \big\{{\bm v}_h\in \,&{\bm Q}_{h,\Gamma}(D): \nabla\times {\bm v}_h = {\bm 0},\;\\
(\kappa{\bm v}_h, \nabla \xi_h)_{{\bm L}^{2}(D)} &= 0 \;\, \forall\,\xi_h\in S_{h,\Gamma}(D)\big\}.       
\end{split}
\end{align}
Whereas the de Rham complexes and the spaces of harmonic forms in the case of no boundary conditions ($\partial D\cap \Gamma = \emptyset$) or of full boundary conditions ($\partial D= \Gamma$) have been well studied (see \cite{arnold2006finite,arnold2010finite,arnold2018finite}), the case of partial boundary conditions is much less investigated. Of particular importance to our analysis is the dimension of $\mathcal{\bm H}_{h}(D)$. Indeed, ${\rm dim}\,\mathcal{\bm H}_{h}(D)$ depends only on $D$, but not on the underlying triangulation, as shown by the following lemma. We also note that ${\rm dim}\,\mathcal{\bm H}_{h}(D)$ is independent of the coefficient $\kappa$ that satisfies \cref{ass:coefficients}(ii); see \cite[section 6.1]{arnold2010finite}.

\begin{lemma}\label{lem:dimension_harmonic_forms}
Let $D$ be a subdomain of $\Omega$ which is a union of elements in $\mathcal{T}_h$. Then, ${\rm dim}\,\mathcal{\bm H}_{h}(D) = {\rm dim}\,\mathcal{\bm H}(D)$.
\end{lemma}
\begin{proof}
We show this result by following the proofs in \cite{arnold2018finite,arnold2006finite} for the case of no boundary conditions. In fact, there are two ways to prove the result. The first is based on de Rham's theorem \cite[Theorem 2.2]{arnold2018finite} and de Rham's mappings. The second way is to use \cite[Theorem 5.1]{arnold2018finite}, which shows the isomorphism of cohomology between the continuous and discrete complexes under the assumption of the existence of a bounded cochain projection. The required projection has been constructed recently in \cite{licht2019smoothed} for the case of partial boundary conditions (see also \cite{hiptmair2019discrete}). 
\end{proof}

Next we discuss the dimension of $\mathcal{\bm H}(D)$. When $\partial D\cap \Gamma \neq \emptyset$, ${\rm dim}\,\mathcal{\bm H}(D)$ depends not only on the topology of $D$, but also on the connectedness of $\partial D\cap \Gamma$. Let $b_{1}(D,\Gamma\cap \partial D)$ denote the first \textit{relative} Betti number of the pair ($D$, $\Gamma\cap \partial D$), which is defined as the dimension of the first singular homology group of $D$ relative to $\Gamma\cap \partial D$; see \cite[Chapter 4, Section 4]{spanier1989algebraic} for details. By \cite[Theorem 5.3]{gol2011hodge}, we have the following result.
\begin{lemma}\label{lem:Betti-numbers}
Let $D$ be a subdomain of $\Omega$ which is a union of elements in $\mathcal{T}_h$. Then, ${\rm dim}\,\mathcal{\bm H}(D) = b_{1}(D, \Gamma\cap \partial D)$.
\end{lemma}
\begin{remark}
If $\Gamma\cap \partial D = \emptyset$, then $b_{1}(D, \Gamma\cap \partial D)$ reduces to the classical first Betti number of $D$, which is the number of holes (or `tunnels' in 3D) through the domain. In general, it depends on topological properties of $D$ and $\Gamma\cap \partial D$. For example, if $D = (0,1)^{3}$ and $\Gamma\cap \partial D$ has $M$ connected components, then $b_{1}(D, \Gamma\cap \partial D) = M-1$. We refer to \cite[Propositions 3.8 and 3.13]{amrouche2021vector} for its value for more complicated domains.    
\end{remark}


