\section{Local exponential convergence}\label{sec-4}
We have seen from \cref{thm:global_error_bound} that the global error of MS-GFEM is essentially bounded by the maximum local approximation error, which, in turn, controls the convergence rates of the iterative MS-GFEM and the preconditioned GMRES algorithms. Therefore, it is critical to derive an explicit decay rate for the local approximation errors, or equivalently, for the $n$-width $d_{n}(P_i)$ in terms of $n$. For ease of presentation, we first consider the special case where $\omega_i$ and $\omega_i^{\ast}$ are simply connected domains with $\omega_i^{\ast}\subset\subset \Omega$. More general situations will be treated in \cref{subsec:nontrivial_topology}. Our result needs two technical assumptions. For a domain $D\subset\omega_i^{\ast}$, let  
\begin{equation}
\mathcal{T}_{h}(D):=\{ K\in \mathcal{T}_h: |K\cap D|>0\}, \quad D^{+}:= {\rm int} \Big( \bigcup_{K\in \mathcal{T}_{h}(D)} \overline{K}\Big),     
\end{equation}
and we define a set of domains 
\begin{align}\label{eq:set_of_domains}
    \begin{split}
 \mathscr{E}_h(D) := \big\{  \widetilde{D}: D^{+}\subset &\widetilde{D}\subset \overline{\omega_i^{\ast}}, \;\widetilde{D}\; \text{is a union of elements in}\;\mathcal{T}_h,\\
& {\rm dist}(\partial \widetilde{D}\setminus \partial \Omega, \partial D\setminus \partial\Omega) \leq 2h\big\}.
    \end{split}
\end{align}
\begin{assumption}\label{ass:simply-connected}
For a simply connected domain $D\subset\omega_i^{\ast}$, there exists a simply connected domain $\widetilde{D}\in  \mathscr{E}_h(D)$.
\end{assumption}
Roughly speaking, \cref{ass:simply-connected} means that given a simply connected domain $D$, we can find a slightly larger, simply connected domain by adding one or two layers of adjoining elements to $D$. This is generally doable by filling the `holes'. The second assumption is on the regularity of the partition of unity $\{\chi_i\}_{i=1}^{M}$. We need a higher regularity than it has to be to estimate the norm of the operators $\Xi_{h,i}$ defined in \cref{eq:discrete_pou}.
\begin{assumption}\label{ass:POU}
For each $i=1,\cdots,M$, $\chi_i\in W^{2,\infty}(\omega_i)$, and there exist $C>0$ depending only on $d$ and $\rho_i>0$ such that $|\chi_i|_{W^{j,\infty}(\omega_i)}\leq C\rho^{-j}_i$ for $j=1,2$.    
\end{assumption}
We note that $\rho_i$ above is related to the size of overlap.

The following theorem is the main result of this paper that gives an exponential decay estimate for the $n$-width $d_{n}(P_i)$. For brevity, we omit the subdomain index, and denote by $\Vert \Xi_{h}\Vert$ the norm of the operator $\Xi_{h}: ({\bm Q}_{h,\Gamma}(\omega),\,\Vert\cdot\Vert_{a,\omega})\rightarrow ({\bm Q}_{h,0}(\omega),\,\Vert\cdot\Vert_{a,\omega})$.
% \begin{theorem}\label{thm:exponential_boxes}
% Let $\omega_i\subset \omega_i^{\ast}\subset\subset \Omega$ be concentric boxes with ${\rm dist}(\omega_i,\omega_i^{\ast})>0$. Then, there exists $n_0>0$ and $b>0$, such that when $n>n_0$ and $h\leq h_0$, 
% \begin{equation*}
%   d_{n}(P_i)\leq e^{-bn^{1/(d+1)}}.  
% \end{equation*}
% \end{theorem}

\begin{theorem}\label{thm:exponential_convergence}
Let $\omega\subset \omega^{\ast}\subset\subset\Omega$ with $\delta^{\ast}:={\rm dist}(\omega,\partial \omega^{\ast})>0$ be simply connected domains, and let \cref{ass:simply-connected} be satisfied. Then, there exist $n_0: = C_1|\omega^{\ast}|/(\delta^{\ast})^{d}$ and $b:=\frac{1}{2}\big(C_{1}|\omega^{\ast}|/(\delta^{\ast})^{d}\big)^{-1/(d+1)}$, such that if $n>n_0$,
\begin{equation}\label{eq:exponential_decay_nwidth}
  d_{n}(P)\leq  \Vert \Xi_{h}\Vert \max\{\delta^{\ast}, 1/\delta^{\ast} \}\, e^{-bn^{1/(d+1)}},  
\end{equation}
where the constant $C_1$ depends only on $d$, the shape of $\Omega$, $\kappa_{\rm min}$, $\kappa_{\rm max}$, $\nu_{\rm min}$, $\nu_{\rm max}$, the polynomial degree $r$, and the shape-regularity of the mesh $\mathcal{T}_h$. Moreover, if \cref{ass:POU} holds, then
\begin{equation}
\Vert \Xi_{h}\Vert\leq C_2(1+\rho^{-1}),    
\end{equation}
where $C_2$ depends only on the coefficient bounds and the shape-regularity of $\mathcal{T}_h$.
\end{theorem}

% To this end, we apply the theoretical framework established in \cite[section 3.1]{ma2023unified}. Based on this framework, the proof of exponential decay of the $n$-width $d_{n}(P_i)$ boils downs to the verification of two important properties of the discrete $a$-harmonic space: a Caccioppoli-type inequality and a weak approximation property. We state these two properties in the following two lemmas.

The proof of \cref{thm:exponential_convergence} relies on two important properties of the discrete harmonic space ${\bm W}_{h}(D)$ (defined following \cref{eq:harmonic-space} for a general domain $D$): a Caccioppoli-type inequality and a weak approximation property, which are stated in the following two lemmas. We note that the assumption on the topology of the domains is only relevant to the weak approximation property.

\begin{lemma}[Discrete Caccioppoli inequality]\label{lem:caccioppoli_inequality}
Let $D\subset D^{\ast}$ be subdomains of $\Omega$ with $\delta:={\rm dist}\big(D, \, \partial D^{\ast}\setminus\partial \Omega\big)>0$, and let $h_{K}\leq \delta/3$ for each $K\in \mathcal{T}_{h}$ with $K\cap (D^{\ast}\setminus D)\neq \emptyset$. Then, for any ${\bm v}_{h}\in {\bm W}_{h}(D^{\ast})$,
\begin{equation}
 \Vert {\bm v}_h\Vert_{a,D}\leq C_{\rm cac}\delta^{-1}\Vert {\bm v}_h\Vert_{{\bm L}^{2}(D^{\ast}\setminus D)}, 
\end{equation}
where the constant $C_{\rm cac}$ depends on $d$, the polynomial degree $r$, the coefficient bounds, and the shape-regularity of the mesh $\mathcal{T}_{h}$. 
\end{lemma}

\begin{lemma}[Weak approximation property]\label{lem:weak_approximation}
Let $D\subset D^{\ast}\subset\subset \Omega$ be simply connected domains with $\delta:={\rm dist} ({D},\partial D^{\ast}) > 0$, and let \cref{ass:simply-connected} be satisfied. Suppose that $h\leq \delta/4$. Then there exists a family of subspaces ${\bm V}_{H,\epsilon}(D)$ of ${\bm W}_{h}(D)$, parameterized by $H\in (0,\delta)$ and $\epsilon\in (0,1)$, such that ${\rm dim} \, {\bm V}_{H,\epsilon}(D)\leq C_{{\rm dim}}\big(|D^{\ast}|/H^{d} + (|D^{\ast}|/\delta^{d})|\log \epsilon|^{d+1}\big)$, and that for any ${\bm u}_{h}\in {\bm W}_{h}(D^{\ast})$,
\begin{align}\label{eq:weak_approx_estimate}
\begin{split}
&\inf_{{\bm z}_{h}\in {\bm V}_{H,\epsilon}(D)} \Vert {\bm u}_{h} - {\bm z}_{h}\Vert_{{\bm L}^{2}(D)}\\
&\leq C_{\rm app} \big(H(\Vert \nabla \times {\bm u}_{h}\Vert_{{\bm L}^{2}(D^{\ast})} + \delta^{-1}\Vert {\bm u}_{h}\Vert_{{\bm L}^{2}(D^{\ast})}) + \epsilon \Vert {\bm u}_{h}\Vert_{{\bm L}^{2}(D^{\ast})}\big),    
\end{split}    
\end{align}
where the constants $C_{\rm dim}$ and $C_{\rm app}$ depend only on $d$, $\kappa_{\rm max}/\kappa_{\rm min}$, the shape-regularity of the mesh $\mathcal{T}_{h}$, and the shape of the domain $\Omega$ ($C_{\rm app}$ only). 
\end{lemma}

We prove \cref{lem:caccioppoli_inequality,lem:weak_approximation} in \cref{subsec:proof of Cac-inequality,subsec:proof_weak_approx}, respectively. The proof of \cref{thm:exponential_convergence} is given in \cref{subsec:proof_main_theorem} based on these two lemmas.

\subsection{Proof of the discrete Caccioppoli inequality}\label{subsec:proof of Cac-inequality}
In this subsection, we prove \cref{lem:caccioppoli_inequality}. Whereas the discrete Caccioppoli inequality has been proved for the lowest-order N\'{e}d\'{e}lec element (see, e.g., \cite[Lemma 4.1]{faustmann2022h}), we consider arbitrary high-order elements here, which is particularly relevant to the approximation of Maxwell's equations with large wavenumbers. A key tool for our proof are the following super-approximation estimates for N\'{e}d\'{e}lec elements.

\begin{lemma}\label{lem:super_approximation}
Let $\eta\in C^{r+1}(\Omega)$ satisfy $|\eta|_{W^{j,\infty}(\Omega)}\leq C\delta^{-j}$ for each $0\leq j\leq r+1$. Then for each ${\bm v}_{h}\in {\bm Q}_{h}(\Omega)$ and each element $K$ with $h_{K} :={\rm diam}(K)\leq \delta$, 
\begin{align}
{\displaystyle \Vert \nabla\times(\eta^{2}{\bm v}_{h}- \Pi_{h}(\eta^{2}{\bm v}_{h}))\Vert_{{\bm L}^{2}(K)}\leq C\big(\frac{h_{K}}{\delta}\Vert \nabla \times (\eta {\bm v}_{h})\Vert_{{\bm L}^{2}(K)}+\frac{h_{K}}{\delta^{2}}\Vert {\bm v}_{h}\Vert_{{\bm L}^{2}(K)}\big),\label{eq:super_approx_1}}\\
{\displaystyle \Vert \eta^{2}{\bm v}_{h}- \Pi_{h}(\eta^{2}{\bm v}_{h})\Vert_{{\bm L}^{2}(K)}\leq C\big(\frac{h^{2}_{K}}{\delta}\Vert \nabla \times (\eta {\bm v}_{h})\Vert_{{\bm L}^{2}(K)}+\frac{h^{2}_{K}}{\delta^{2}}\Vert {\bm v}_{h}\Vert_{{\bm L}^{2}(K)}\big),\label{eq:super_approx_2}}
\end{align}
where $\Pi_{h}$ is the N\'{e}d\'{e}lec interpolation operator.    
\end{lemma}

We postpone the proof of \cref{lem:super_approximation} to the end of this subsection. 

\begin{proof}[Proof of \cref{lem:caccioppoli_inequality}]
Let $D_{e}$ and $D^{\ast}_{e}$ be the union of elements in $\mathcal{T}_{h}$ that intersect $D$ and that are contained in $D^{\ast}$, respectively. By the assumption $\delta:={\rm dist}\,\big(D, \, \partial D^{\ast}\setminus\partial \Omega\big)\geq 3\max_{K\cap (D^{\ast}\setminus D)\neq \emptyset}h_{K}$, we have $D\subset D_{e}\subset D^{\ast}_{e}\subset D^{\ast}$ and ${\rm dist}\,\big(D_{e}, \, \partial D^{\ast}_{e}\setminus\partial \Omega\big) \geq \frac{1}{3}\delta$. Let $\eta\in C^{\infty}(\overline{{D}_{e}^{\ast}})$ be a cut-off function such that $\eta \equiv 1$ in $D_{e}$, $\eta = 0$ on $\partial {D}_{e}^{\ast}\setminus\partial \Omega$, and $|\eta|_{W^{j,\infty}(D_{e}^{\ast})}\leq C\delta^{-j}$ for $0\leq j\leq r+1$. A direct calculation yields that for any ${\bm v}_{h}\in {\bm Q}_{h}({D}_{e}^{\ast})$, 
\begin{equation}\label{eq:identity}
\begin{split}
\big\Vert \eta{\bm v}_h\big\Vert^{2}_{a, {D}_{e}^{\ast}} &= \big\Vert \nu^{1/2}\nabla \eta\times {\bm v}_h\big\Vert^{2}_{{\bm L}^{2}({D}_{e}^{\ast})} + a_{{D}_{e}^{\ast}}({\bm v}_h,\eta^{2}{\bm v}_h) \\
&\leq C\nu_{\rm max}\delta^{-1} \Vert {\bm v}_h\big\Vert^{2}_{{\bm L}^{2}({D}_{e}^{\ast}\setminus D_e)} +  a_{{D}_{e}^{\ast}}({\bm v}_h,\eta^{2}{\bm v}_h).    
\end{split}
\end{equation}
It remains to estimate the term $a_{{D}_{e}^{\ast}}({\bm v}_h,\eta^{2}{\bm v}_h)$. Let $\Pi_{h}$ be the N\'{e}d\'{e}lec interpolation operator. Note that for ${\bm v}_{h}\in {\bm W}_{h}({D}_{e}^{\ast})$, $\Pi_{h}(\eta^{2}{\bm v}_h) \in {\bm Q}_{h,0}({D}_{e}^{\ast})$ and thus $a_{{D}_{e}^{\ast}}({\bm v}_h,\Pi_{h}(\eta^{2}{\bm v}_h)) = 0$. Using this equation and noting that $\eta \equiv 1$ in $D_{e}$, we find
\begin{equation}\label{eq:identity_2}
\begin{split}
    a_{{D}_{e}^{\ast}}&({\bm v}_h,\eta^{2}{\bm v}_h) = \big(\nu \nabla\times {\bm v}_h,  \nabla\times(\eta^{2}{\bm v}_h- \Pi_{h}(\eta^{2}{\bm v}_h))\big)_{{\bm L}^{2}({D}_{e}^{\ast}\setminus D_{e})} \\
    &+    \big(\kappa {\bm v}_h,  \eta^{2}{\bm v}_h- \Pi_{h}(\eta^{2}{\bm v}_h)\big)_{{\bm L}^{2}({D}_{e}^{\ast}\setminus D_{e})} := I_1 + I_2.
\end{split}
\end{equation}
The estimate of the two terms $I_1$ and $I_2$ above relies on the super-approximation results. Using \cref{eq:super_approx_1} and an inverse inequality (local to each element), we have 
\begin{equation*}
\begin{split}
I_1\leq &  \sum_{K\subset D_{e}^{\ast}\setminus D_{e}}C\nu_{\rm max} h_{K}\Vert \nabla\times {\bm v}_h\Vert_{{\bm L}^{2}(K)} \big(\delta^{-1} \Vert\nabla \times (\eta {\bm v}_h)\Vert_{{\bm L}^{2}(K)} + \delta^{-2} \Vert {\bm v}_h\Vert_{{\bm L}^{2}(K)}\big) \\
\leq & C\nu_{\rm max}^{2}/(\nu_{\rm min}\delta^{2})\sum_{K\subset D_{e}^{\ast}\setminus D_{e}}  \Vert {\bm v}_h\Vert^{2}_{{\bm L}^{2}(K)} + \frac{\nu_{\rm min}}{4}\sum_{K \subset D_{e}^{\ast}}  \Vert\nabla \times (\eta {\bm v}_h)\Vert_{{\bm L}^{2}(K)}\\
 \leq & C\nu_{\rm max}^{2}/(\nu_{\rm min}\delta^{2})\Vert {\bm v}_h\Vert^{2}_{{\bm L}^{2}(D_{e}^{\ast}\setminus D_{e})} + \frac{1}{4}\Vert \eta {\bm v}_{h}\Vert^{2}_{a, D_e^{\ast}}.
\end{split}
\end{equation*}
Similarly, we can prove that $I_{2}\leq C\kappa_{\rm max} \Vert {\bm v}_h\Vert^{2}_{{\bm L}^{2}(D_{e}^{\ast}\setminus D_{e})}$. Combining \cref{eq:identity}, \cref{eq:identity_2}, and the estimates for $I_1$ and $I_2$ gives the desired estimate.
\end{proof}

