It remains to prove \cref{lem:super_approximation} where \cref{lem:equiv_norm} plays a key role.
\begin{proof}[Proof of \cref{lem:super_approximation}]
We only prove \cref{eq:super_approx_1}. The other estimate can be proved using similar arguments. For ease of notation, we drop the dependence of the norms and the element-size on $K$. Using error estimates \cref{eq:error_nedelec_interpolation_1} for the interpolation operator $\Pi_{h}$, we obtain
\begin{equation}\label{eq:sum_two_terms}
\begin{split}
    \Vert \nabla\times (\eta^{2}{\bm v}_{h}- \Pi_{h}(\eta^{2}{\bm v}_{h}))\Vert_{{\bm L}^{2}}\leq Ch^{r+d/2} |\nabla \times (\eta^{2}{\bm v}_{h})|_{{\bm W}^{r,\infty}}\\
    \leq Ch^{r+d/2}\sum_{|{\bm \alpha} |=r} \big(\Vert \partial^{\bm \alpha} (\nabla(\eta^{2})\times{\bm v}_h) \Vert_{{\bm L}^{\infty}} + \Vert\partial^{\bm \alpha}(\eta^{2}\nabla\times{\bm v}_h) \Vert_{{\bm L}^{\infty}}\big).
\end{split}
\end{equation}
It is easy to see that
\begin{equation}\label{eq:first_term_1}
\begin{split}
\sum_{|{\bm \alpha} |=r}\Vert \partial^{\bm \alpha} (\nabla(\eta^{2})\times{\bm v}_h) \Vert_{{\bm L}^{\infty}}& \\
\leq \sum_{\substack{|{\bm \alpha} | + |{\bm \beta}|=r,\\  |{\bm \beta}|\leq r-1}}\Vert \partial^{\bm \alpha} (2\eta \nabla\eta) \Vert_{{\bm L}^{\infty}} \Vert \partial^{\bm \beta} {\bm v}_h \Vert_{{\bm L}^{\infty}}+&\sum_{|{\bm \beta}|= r}\Vert \nabla (\eta^{2}) \times \partial^{\bm \beta} {\bm v}_h \Vert_{{\bm L}^{\infty}}. 
\end{split}
\end{equation}
Using the assumptions on $\eta$ and an inverse inequality, we can prove
\begin{equation}\label{eq:first_term_2}
     Ch^{r+d/2} \sum_{\substack{|{\bm \alpha} | + |{\bm \beta}|=r,\\  |{\bm \beta}|\leq r-1}}\Vert \partial^{\bm \alpha} (2\eta \nabla\eta) \Vert_{{\bm L}^{\infty}} \Vert \partial^{\bm \beta} {\bm v}_h \Vert_{{\bm L}^{\infty}} \leq Ch\delta^{-2} \Vert{\bm v}_h\Vert_{{\bm L}^{2}}.
\end{equation}
To estimate the second term in \cref{eq:first_term_1}, we define $\widehat{\eta}:= |K|^{-1}\int_{K}\eta \,d{\bm x}$. Using the following error estimate: $\Vert \eta - \widehat{\eta}\Vert_{L^{\infty}}\leq Ch|\eta|_{W^{1,\infty}}\leq Ch\delta^{-1}$, we have
\begin{equation}\label{eq:first_term_3}
\begin{split}
 \Vert \nabla (\eta^{2}) \times \partial^{\bm \beta} {\bm v}_h \Vert_{{\bm L}^{\infty}}\leq C\delta^{-1}\Vert \eta \partial^{\bm \beta} {\bm v}_h \Vert_{{\bm L}^{\infty}}\\
 \leq C\delta^{-1}\big(\Vert (\eta-\widehat{\eta}) \partial^{\bm \beta} {\bm v}_h \Vert_{{\bm L}^{\infty}} + \Vert \widehat{\eta} \partial^{\bm \beta} {\bm v}_h \Vert_{{\bm L}^{\infty}}\big)\\
 \leq Ch\delta^{-2} \Vert \partial^{\bm \beta} {\bm v}_h \Vert_{{\bm L}^{\infty}} + C\delta^{-1} \Vert \widehat{\eta} \partial^{\bm \beta} {\bm v}_h \Vert_{{\bm L}^{\infty}}.
\end{split}
\end{equation}
It follows from \cref{eq:first_term_3}, an inverse inequality, and \cref{lem:equiv_norm} that
\begin{equation}\label{eq:first_term_4}
\begin{split}
  h^{r+d/2}  \sum_{|{\bm \beta}|= r}  &\Vert \nabla (\eta^{2}) \times \partial^{\bm \beta} {\bm v}_h \Vert_{{\bm L}^{\infty}} \leq Ch\delta^{-2} \Vert{\bm v}_h\Vert_{{\bm L}^{2}}
  + C h \delta^{-1} \Vert \widehat{\eta}\,\nabla\times {\bm v}_h \Vert_{{\bm L}^{2}}\\
 \leq  Ch\delta^{-2} &\Vert{\bm v}_h\Vert_{{\bm L}^{2}} + Ch\delta^{-1} \big(  \Vert \nabla\times  ((\widehat{\eta}-\eta){\bm v}_h) \Vert_{{\bm L}^{2}} + \Vert \nabla\times  (\eta{\bm v}_h) \Vert_{{\bm L}^{2}}\big)\\
    \leq Ch\delta^{-2} &\Vert{\bm v}_h\Vert_{{\bm L}^{2}} + Ch\delta^{-1} \Vert \nabla\times  (\eta{\bm v}_h) \Vert_{{\bm L}^{2}}.
\end{split}
\end{equation}
Inserting \cref{eq:first_term_2,eq:first_term_4} into \cref{eq:first_term_1} gives
% \begin{equation}
%  h_{K}^{r+d/2}  \sum_{|{\bm \beta}|= r}  \Vert \nabla (\eta^{2}) \times \partial^{\bm \beta} {\bm v}_h \Vert_{{\bm L}^{\infty}} \leq Ch_{K}\delta^{-2} \Vert{\bm v}_h\Vert_{{\bm L}^{2}} + Ch_{K}\delta^{-1} \Vert \nabla\times  (\eta{\bm v}_h) \Vert_{{\bm L}^{2}},   
% \end{equation}
% and thus we have
\begin{equation}\label{eq:first_term_5}
h^{r+d/2}\sum_{|{\bm \alpha} |=r}\Vert \partial^{\bm \alpha} (\nabla(\eta^{2})\times{\bm v}_h) \Vert_{{\bm L}^{\infty}} \leq  Ch\delta^{-2} \Vert{\bm v}_h\Vert_{{\bm L}^{2}} + Ch\delta^{-1} \Vert \nabla\times  (\eta{\bm v}_h) \Vert_{{\bm L}^{2}}.   
\end{equation}
It remains to estimate the second term in \cref{eq:sum_two_terms}. Noting that $\partial^{\bm \beta} (\nabla\times {\bm v}_h) = {\bm 0}$ for any $|\bm \beta|=r$, we have
\begin{equation}\label{eq:second_term_1}
    \sum_{|{\bm \alpha} |=r}\Vert \partial^{\bm \alpha} (\eta^{2}\nabla\times{\bm v}_h) \Vert_{{\bm L}^{\infty}}
    = \sum_{\substack{|{\bm \alpha} | + |{\bm \beta}|=r,\\  |{\bm \beta}|\leq r-1}}\Vert \partial^{\bm \alpha} (\eta^{2}) \partial^{\bm \beta} \nabla\times {\bm v}_h \Vert_{{\bm L}^{\infty}}. 
\end{equation}
We estimate the sum on the RHS of \cref{eq:second_term_1} similarly as above to obtain
\begin{equation}\label{eq:second_term_2}
    h^{r+d/2} \sum_{|{\bm \alpha} |=r}\Vert \partial^{\bm \alpha} (\eta^{2}\nabla\times{\bm v}_h) \Vert_{{\bm L}^{\infty}} \leq Ch\delta^{-2} \Vert{\bm v}_h\Vert_{{\bm L}^{2}} + Ch\delta^{-1} \Vert \nabla\times  (\eta{\bm v}_h) \Vert_{{\bm L}^{2}}.
\end{equation}
Estimate \cref{eq:super_approx_1} then follows by inserting \cref{eq:first_term_5,eq:second_term_2} into \cref{eq:sum_two_terms}.    
\end{proof}

\subsection{Proof of the weak approximation property}\label{subsec:proof_weak_approx}
We first assume that $D\subset D^{\ast}$ are general subdomains of $\Omega$ with ${\rm dist}(D, \partial D^{\ast}\setminus \partial \Omega) = \delta$, and prove several auxiliary lemmas. The proof of \cref{lem:weak_approximation} will be given at the end of this subsection where we restrict ourselves to the special case that $D\subset D^{\ast}\subset\subset \Omega$ are simply connected domains. Before proceeding, we recall the local spaces defined in \cref{eq:local_spaces}. 

Let $D^{+}$ with $D\subset D^{+}\subset D^{\ast}$ be a domain such that ${\rm dist}({D}, \partial D^{+}\setminus \partial \Omega) = {\rm dist}({D}^{+}, \partial D^{\ast}\setminus \partial \Omega) = \delta /2$, and let $\widetilde{D}^{+} \in \mathscr{E}_h(D^{+})$ (see \cref{eq:set_of_domains} for the definition of $\mathscr{E}_h(D^{+})$) be a union of elements. By the assumption $h\leq \delta/4$, we see that $\widetilde{D}^{+}\subset D^{\ast}$ with ${\rm dist}(\widetilde{D}^{+}, \partial D^{\ast}\setminus \partial \Omega)\geq \delta/4$. Our proof relies on the regular decomposition of the vector field ${\bm u}_{h} \in {\bm W}_{h}(D^{\ast})$. To avoid dependence of the stability of the decomposition on the domain $D^{\ast}$, we shall use the technique of a cut-off function. Let $\eta\in W^{1,\infty}(\Omega)$ be a cut-off function such that 
\begin{equation}\label{eq:cut-off-estimate}
 \eta \equiv 1 \;\;\text{on} \;\; \widetilde{D}^{+},\quad {\rm supp}(\eta) \subset \overline{D^{\ast}}, \quad \Vert \nabla \eta\Vert_{{\bm L}^{\infty}(\Omega)}\lesssim \delta^{-1}.  
\end{equation}
It follows that ${\eta} {\bm u}_{h}\in {\bm H}_{0}({\rm curl};\Omega)$. We can apply the regular decomposition (see \cref{lem:regular_decomposition}) to ${\eta} {\bm u}_{h}$, and write it as ${\eta} {\bm u}_{h}={\bm w} + \nabla p$ on $\Omega$, where ${\bm w}\in {\bm H}^{1}_{0}(\Omega)$ and $p\in H_{0}^{1}(\Omega)$. Combining \cref{eq:cut-off-estimate} and the stability estimates \cref{eq:estimate_regular_decomp} gives
\begin{align}\label{eq:estimates_reg_decomposition}
\begin{split}
\Vert \nabla {\bm w}\Vert_{{\bm L}^{2}(\Omega)}\leq C\Vert \nabla\times (\eta {\bm u}_{h})\Vert_{{\bm L}^{2}(\Omega)} &\leq C(\Vert \nabla\times {\bm u}_{h}\Vert_{{\bm L}^{2}(D^{\ast})} + \delta^{-1}\Vert {\bm u}_{h}\Vert_{{\bm L}^{2}(D^{\ast})}),\\    
\Vert {\bm w}\Vert_{{\bm L}^{2}(\Omega)} +  \Vert \nabla p\Vert_{{\bm L}^{2}(\Omega)}&\leq C\Vert \eta {\bm u}_{h}\Vert_{{\bm L}^{2}(\Omega)}\leq C\Vert {\bm u}_{h}\Vert_{{\bm L}^{2}(D^{\ast})},
\end{split}    
\end{align}
where the constant $C$ depends only on shape of $\Omega$, but not on its diameter. 

In order to prove the weak approximation property, we use ideas from \cite{faustmann2022h} to establish a suitable decomposition for ${\bm u}_{h}$. Let ${P}_{\widetilde{D}^{+}}$ be the orthogonal projection of ${\bm L}^{2}(\widetilde{D}^{+})$ onto $\nabla S_{h,\Gamma}(\widetilde{D}^{+})$ with respect to the weighted $L^{2}$ norm $(\kappa\cdot,\cdot)_{{\bm L}^{2}(\widetilde{D}^{+})}$. Moreover, we let $p_{h},\psi_{h}\in S_{h,\Gamma}(\widetilde{D}^{+})$ such that ${P}_{\widetilde{D}^{+}} \nabla p =  \nabla p_{h}$ and ${P}_{\widetilde{D}^{+}} {\bm w} = \nabla \psi_{h}$, i.e.,
\begin{align}\label{eq:orthogonal_projection}
\begin{split}
    (\kappa \nabla p_{h},\nabla v_h)_{{\bm L}^{2}(\widetilde{D}^{+})} =  (\kappa \nabla p,\nabla v_h)_{{\bm L}^{2}(\widetilde{D}^{+})}\quad &\forall v_{h}\in S_{h,\Gamma}(\widetilde{D}^{+}),\\    
    (\kappa \nabla \psi_{h},\nabla v_h)_{{\bm L}^{2}(\widetilde{D}^{+})} =  (\kappa {\bm w},\nabla v_h)_{{\bm L}^{2}(\widetilde{D}^{+})}\quad &\forall v_{h}\in S_{h,\Gamma}(\widetilde{D}^{+}).
\end{split}    
\end{align}    
Let ${\bm w}_{h}:={\bm u}_{h}|_{\widetilde{D}^{+}}-\nabla p_{h} \in {\bm Q}_{h,\Gamma}(\widetilde{D}^{+})$. Since $\eta \equiv 1$ on $\widetilde{D}^{+}$, we have ${\bm u}_{h} = {\bm w} + \nabla p = {\bm w}_{h} + \nabla p_{h}$ on $\widetilde{D}^{+}$. Then we can decompose ${\bm u}_{h}$ on $\widetilde{D}^{+}$ as 
\begin{equation}\label{eq:four_terms_decomposition}
    {\bm u}_{h} = {\bm w}_{h} + \nabla p_{h} = ({\bm w}_{h} - {\bm w}) + \nabla (p_{h} + \psi_{h}) +  {\bm w} - \nabla \psi_{h}.
\end{equation}
In the following, we approximate the four terms on the right-hand side of \cref{eq:four_terms_decomposition}, based on the observations: (i) ${\bm w}_{h}$ and ${\bm w}$ are close; (ii) $p_{h} + \psi_{h}$ is discrete harmonic on $\widetilde{D}^{+}$ and therefore can be approximated in $D$ with exponential accuracy; (iii) ${\bm w}\in {\bm H}^{1}$ can be approximated in ${\bm L}^2$ using usual techniques; (iv) $\nabla \psi_{h}$ is the $L^{2}$ projection of ${\bm w}$ onto $\nabla S_{h,\Gamma}(\widetilde{D}^{+})$, and hence its approximation follows from (iii). To approximate ${\bm w}_{h} - {\bm w}$, we introduce the space of discrete `harmonic forms' (see \cref{subsec:preliminaries}):
\begin{align}\label{eq:discrete-harmonic-forms}
\begin{split}
\mathcal{\bm H}_{h}(\widetilde{D}^{+}):= \big\{{\bm v}_h\in {\bm Q}_{h,\Gamma}(\widetilde{D}^{+}): \nabla\times {\bm v}_h = {\bm 0},\;\\
(\kappa {\bm v}_h, \nabla \xi_h)_{{\bm L}^{2}(\widetilde{D}^{+})} = 0 \quad \forall\,\xi_h\in S_{h,\Gamma}(\widetilde{D}^{+})\big\}.       
\end{split}
\end{align}

%The lemma can be proved by combining the proof of \cite[lemma 3.11]{faustmann2022h} and interpolation error estimates for Nedelec elements, and we only give its sketch here.

\begin{lemma}\label{lem:estimate_term_1}
Let ${\bm w}$, ${\bm w}_{h}$, and $\mathcal{\bm H}_{h}(\widetilde{D}^{+})$ be defined as above. Then
\begin{equation*}
\inf_{{\bm v}_h\in \mathcal{\bm H}_{h}(\widetilde{D}^{+})}\Vert {\bm w} - {\bm w}_{h}-{\bm v}_h \Vert_{{\bm L}^{2}(\widetilde{D}^{+})} \leq C\Big(\frac{\kappa_{\rm max}}{\kappa_{\rm min}}\Big)^{1/2}h\big(\Vert \nabla {\bm w}\Vert_{{\bm L}^{2}(\widetilde{D}^{+})} + \Vert \nabla \times {\bm w}\Vert_{{\bm L}^{2}(\widetilde{D}^{+})} \big),    
\end{equation*}
where $C$ depends only on the shape-regularity of the mesh. 
\end{lemma}
\begin{proof}
Let $\Pi_{h}$ and $\Sigma_h$ be the N\'{e}d\'{e}lec and Raviart--Thomas interpolation operators, respectively, and let ${\bm U}_{h,\Gamma}(\widetilde{D}^{+})$ be the Raviart-Thomas element space defined in \cref{eq:local_spaces}. Since ${\bm w}\in {\bm H}^{1}(\Omega)$ and $\nabla \times {\bm w} = \nabla \times {\bm u}_{h}$ in $\widetilde{D}^{+}$, we see that the interpolant $\Pi_{h}{\bm w}$ is well defined. Moreover, using \cref{eq:commuting_property} and the fact that $\nabla\times {\bm w} = \nabla\times {\bm w}_h$ gives
\begin{equation*}
\nabla\times (\Pi_{h}{\bm w}) = \Sigma_h(\nabla\times {\bm w}) =  \Sigma_h(\nabla\times {\bm w}_h) = \nabla\times {\bm w}_h,   
\end{equation*}
i.e., $\nabla \times ({\bm w}_{h} - \Pi_{h}{\bm w}) = 0$. Hence, we have the decomposition ${\bm w}_{h} - \Pi_{h}{\bm w} = \nabla \varphi_{h} + {\bm z}_h$, with $\varphi_{h}\in S_{h,\Gamma}(\widetilde{D}^{+})$ and ${\bm z}_h\in \mathcal{\bm H}_{h}(\widetilde{D}^{+})$. Using this decomposition and \cref{eq:orthogonal_projection} yields
\begin{align*}
\begin{split}
 \big(\kappa ({\bm w} &- {\bm w}_{h} - {\bm z}_h),\, {\bm w}_{h} - \Pi_{h}{\bm w} - {\bm z}_h\big)_{{\bm L}^{2}(\widetilde{D}^{+})} =   \big(\kappa ({\bm w} - {\bm w}_{h}-{\bm z}_h),\, \nabla \varphi_h\big)_{{\bm L}^{2}(\widetilde{D}^{+})}   \\
& = \big(\kappa (\nabla p_h - \nabla p),\, \nabla \varphi_h\big)_{{\bm L}^{2}(\widetilde{D}^{+})}  - \big(\kappa {\bm z}_h,\, \nabla \varphi_h\big)_{{\bm L}^{2}(\widetilde{D}^{+})} = 0. 
\end{split}    
\end{align*}
It follows that
\begin{align*}
\begin{split}
\big(\kappa ({\bm w}_{h} &- {\bm w} - {\bm z}_h), \,{\bm w}_{h} - {\bm w}-{\bm z}_h\big)_{{\bm L}^{2}(\widetilde{D}^{+})} =\big(\kappa ({\bm w} - {\bm w}_{h}-{\bm z}_h),\, \Pi_{h}{\bm w} - {\bm w}\big)_{{\bm L}^{2}(\widetilde{D}^{+})}\\
&\leq \Vert \kappa^{1/2}({\bm w}_{h} - {\bm w}-{\bm z}_h)\Vert_{{\bm L}^{2}(\widetilde{D}^{+})} \Vert  \kappa^{1/2}(\Pi_{h}{\bm w} - {\bm w})\Vert_{{\bm L}^{2}(\widetilde{D}^{+})},
\end{split}
\end{align*}
which leads to
\begin{equation}\label{eq:mid_estimate}
 \Vert {\bm w} - {\bm w}_{h}- {\bm z}_h\Vert_{{\bm L}^{2}(\widetilde{D}^{+})} \leq (\kappa_{\rm max}/\kappa_{\rm min})^{1/2} \Vert\Pi_{h}{\bm w} - {\bm w} \Vert_{{\bm L}^{2}(\widetilde{D}^{+})}.   
\end{equation}
% In general, to estimate $\Vert\Pi_{h}{\bm w} - {\bm w} \Vert_{{\bm L}^{2}(\widetilde{D}^{+})}$, we need the boundedness of $\Vert \nabla \times {\bm w}\Vert_{{\bm L}^{p}}$ ($p>2$). 
Noting that $\nabla \times {\bm w} = \nabla \times {\bm u}_{h}\in {\bm U}_{h,\Gamma}(\widetilde{D}^{+})$, we use the error estimate \cref{eq:error_nedelec_interpolation_2} to derive
\begin{equation}\label{eq:L2error_estimate}
\Vert\Pi_{h}{\bm w} - {\bm w} \Vert_{{\bm L}^{2}(\widetilde{D}^{+})} \leq Ch(\Vert \nabla {\bm w}\Vert_{{\bm L}^{2}(\widetilde{D}^{+})} + \Vert \nabla \times {\bm w}\Vert_{{\bm L}^{2}(\widetilde{D}^{+})}).    
\end{equation}
Combining \cref{eq:mid_estimate,eq:L2error_estimate} concludes the proof of the lemma.
\end{proof}
\begin{remark}
If the domain $\widetilde{D}^{+}$ is simply connected and $\partial \widetilde{D}^{+}\cap \Gamma$ is connected, then $\mathcal{\bm H}_{h}(\widetilde{D}^{+})=\{ 0\}$.      
\end{remark}

Next we approximate the term $\nabla (p_{h} + \psi_{h})$. Using \cref{eq:orthogonal_projection} and recalling the regular decomposition, we see that 
\begin{align}
\begin{split}
(\kappa (\nabla p_{h}&+\psi_{h}), \,\nabla v_h)_{{\bm L}^{2}(\widetilde{D}^{+})}  = (\kappa({\bm w} + \nabla p), \,\nabla v_h)_{{\bm L}^{2}(\widetilde{D}^{+})} \\
&= (\kappa{\bm u}_{h}, \,\nabla v_h)_{{\bm L}^{2}(\widetilde{D}^{+})} = 0 \quad \forall v_{h}\in S_{h,0}(\widetilde{D}^{+}),    
\end{split}
\end{align}
i.e., $p_{h} + \psi_{h}$ lies in the following scalar discrete harmonic space 
\begin{equation}\label{eq:scalar-harmonic-space}
W_{h}(\widetilde{D}^{+}):=\big\{u_h\in S_{h,\Gamma}(\widetilde{D}^{+}): (\kappa \nabla u_h,\,\nabla v_h)_{{\bm L}^{2}(\widetilde{D}^{+})} = 0 \quad \forall v_h\in S_{h,0}(\widetilde{D}^{+})\big\}.    
\end{equation}
We can approximate $\nabla(p_{h} + \psi_{h})$ using previous results for scalar elliptic equations. 
\begin{lemma}\label{lem:estimate_term_2}
Let $p_{h}$ and $\psi_{h}$ be defined by \cref{eq:orthogonal_projection}. Then for $\epsilon \in (0,1)$, there exists a space ${\bm V}_{\epsilon}(D)\subset {\bm L}^{2}(D)$ with ${\rm dim}\,{\bm V}_{\epsilon}(D)\leq C_1(|\widetilde{D}^{+}|/\delta^{d}) |\log \epsilon|^{d+1}$ such that  
\begin{equation}\label{eq:harmonic_approx}
\inf_{{\bm v}\in {\bm V}_{\epsilon}(D)}\Vert \nabla(p_{h} + \psi_{h}) - {\bm v}\Vert_{{\bm L}^{2}(D)} \leq  C_2\epsilon (\Vert {\bm w}\Vert_{{\bm L}^{2}(\widetilde{D}^{+})} +  \Vert \nabla p\Vert_{{\bm L}^{2}(\widetilde{D}^{+})}),    
\end{equation}
where $C_1$ and $C_2$ depend only on $d$, ${\kappa_{\rm max}}/{\kappa_{\rm min}}$, the polynomial degree $r$, and the shape-regularity of the mesh $\mathcal{T}_h$.
\end{lemma}

\begin{proof}
We use established exponential decay estimates for a Kolmogorov $n$-width for Poisson-type problems. Noting that ${\rm dist}({D}, \,\partial \widetilde{D}^{+}\setminus \partial \Omega)\geq \delta/2$, by \cite[Theorem 3.8]{ma2025unified}, we know that the following Kolmogorov $n$-width 
\begin{equation*}
d_{n}(D, \widetilde{D}^{+}): = \inf_{Q(n)\subset W_{h}(D)}\sup_{u\in W_{h}(\widetilde{D}^{+})} \inf_{v_h\in Q(n)}\frac {\Vert \kappa^{1/2}\nabla (u_h-v_h)\Vert_{{\bm L}^{2}(D)}}{\Vert \kappa^{1/2}\nabla u_h\Vert_{{\bm L}^{2}(\widetilde{D}^{+})}}    
\end{equation*}
satisfies that $d_{n}(D, \widetilde{D}^{+}) \leq e^{-cn^{1/(d+1)}}$, where $c = C_0(\delta^{d}/|\widetilde{D}^{+}|)^{1/(d+1)}$, with $C_0$ depending only on $d$, ${\kappa_{\rm max}}/{\kappa_{\rm min}}$, the polynomial degree $r$, and the shape-regularity of $\mathcal{T}_h$. Let $n = c^{-(d+1)}|\log \epsilon|^{d+1}$, and ${\bm V}_{\epsilon}(D) = Q^{\rm opt}(n)$, where $Q^{\rm opt}(n)$ is the optimal approximation space associated with $d_{n}(D, \widetilde{D}^{+})$. Since $p_{h} + \psi_{h}\in W_{h}(\widetilde{D}^{+})$, we have
\begin{equation}\label{eq:epsilon_estimate}
\inf_{{\bm v}\in {\bm V}_{\epsilon}(D)}\big\Vert \kappa^{1/2}\big(\nabla(p_{h} + \psi_{h}) - {\bm v}\big)\big\Vert_{{\bm L}^{2}(D)} \leq \epsilon \Vert \kappa^{1/2} \nabla(p_{h} + \psi_{h}) \Vert_{{\bm L}^{2}(\widetilde{D}^{+})}.
\end{equation}
Moreover, it follows from \cref{eq:orthogonal_projection} that $\Vert \kappa^{1/2}\nabla (p_{h} + \psi_{h}) \Vert_{{\bm L}^{2}(\widetilde{D}^{+})}\leq \kappa^{1/2}_{\rm max} \big( \Vert \nabla p\Vert_{{\bm L}^{2}(\widetilde{D}^{+})} +\Vert {\bm w}\Vert_{{\bm L}^{2}(\widetilde{D}^{+})}\big)$. Inserting this estimate into \cref{eq:epsilon_estimate} gives \cref{eq:harmonic_approx}.
\end{proof}
We proceed to approximate ${\bm w}$ and $\nabla \psi_{h}$. 
\begin{lemma}\label{lem:estimate_term_3_4}
Let ${\bm w}$ and $\phi_h$ be defined as above. Then for $0<H<\delta$, there exists a space ${\bm V}_{H}(\widetilde{D}^{+})\subset {\bm L}^{2}(\widetilde{D}^{+})$ with ${\rm dim}\,{\bm V}_{H}(\widetilde{D}^{+}) \leq C_1|D^{\ast}|/H^{d}$ such that 
\begin{align}
   \inf_{{\bm v}\in {\bm V}_{H}(\widetilde{D}^{+})}\Vert {\bm w} - {\bm v}\Vert_{{\bm L}^{2}(\widetilde{D}^{+})} &\leq C_2 H\Vert \nabla {\bm w}\Vert_{{\bm L}^{2}(D^{\ast})}, \label{eq:approximation_w}   \\
\inf_{{\bm v}\in {\bm U}_{H}(\widetilde{D}^{+})}\Vert \nabla \psi_{h} - {\bm v}\Vert_{{\bm L}^{2}(\widetilde{D}^{+})} &\leq C_2(\kappa_{\rm max}/\kappa_{\rm min})^{1/2}H\Vert \nabla {\bm w}\Vert_{{\bm L}^{2}(D^{\ast})}, \label{eq:approximation_psi}  
\end{align}
where ${\bm U}_{H}(\widetilde{D}^{+})=P_{\widetilde{D}^{+}} {\bm V}_{H}(\widetilde{D}^{+})$, and $C_1$, $C_2$ depend only on $d$.
\end{lemma}
\begin{proof}
Noting that ${\bm w}\in {\bm H}^{1}(\widetilde{D}^{+})$ and that ${\rm dist}(\widetilde{D}^{+}, \partial D^{\ast}\setminus \partial \Omega)\geq \delta/4$, we can approximate ${\bm w}$ following \cite[Lemma 5.5(ii)]{ma2025unified} by means of piecewise constant functions. Moreover, recalling that $\nabla \psi_{h} = P_{\widetilde{D}^{+}} {\bm w}$, we have $\Vert \kappa^{1/2}(\nabla \psi_{h} - P_{\widetilde{D}^{+}}{\bm v})\Vert_{{\bm L}^{2}(\widetilde{D}^{+})} \leq \Vert  \kappa^{1/2}( {\bm w} - {\bm v})\Vert_{{\bm L}^{2}(\widetilde{D}^{+})}$. Combining this inequality with \cref{eq:approximation_w} yields \cref{eq:approximation_psi}.   
\end{proof}

Now we are ready to prove \cref{lem:weak_approximation}.

\begin{proof}[\textit{Proof of \cref{lem:weak_approximation}}]
By assumption, $D\subset D^{\ast}\subset\subset\omega^{\ast}$ are simply connected domains. Therefore, we can let $D^{+}$ and thus $\widetilde{D}^{+}$ be also simply connected domains (see \cref{ass:simply-connected}). In this case, $\mathcal{\bm H}_{h}(\widetilde{D}^{+}) = \{0\}$. Let ${\bm V}_{\epsilon}(D)$, ${\bm V}_{H}(\widetilde{D}^{+})$, and ${\bm U}_{H}(\widetilde{D}^{+})$ be as in \cref{lem:estimate_term_2,lem:estimate_term_3_4}, and let $\widehat{\bm V}_{H,\epsilon}(D)={\bm V}_{\epsilon}(D) + {\bm V}_{H}(\widetilde{D}^{+})|_{D}+{\bm U}_{H}(\widetilde{D}^{+})|_{D}$ with $\epsilon\in (0,1)$ and $H\in (0,\delta)$. Then ${\rm dim}\,\widehat{\bm V}_{H,\epsilon}(D)\leq C_1 \big(|D^{\ast}|/H^{d} + (|D^{\ast}|/\delta^{d}) |\log \epsilon|^{d+1}\big)$. Using \cref{eq:four_terms_decomposition}, \cref{eq:estimates_reg_decomposition}, and \cref{lem:estimate_term_1,lem:estimate_term_2,lem:estimate_term_3_4,} leads us to
\begin{align}\label{eq:aux_final_approx}
\begin{split}
&\inf_{{\bm v}\in \widehat{\bm V}_{H,\epsilon}(D)}\Vert {\bm u}_h- {\bm v}\Vert_{{\bm L}^{2}(D)}\\
\leq C(h+H)&\big(\Vert \nabla {\bm w}\Vert_{{\bm L}^{2}(D^{\ast})} + \Vert \nabla \times {\bm w}\Vert_{{\bm L}^{2}(D^{\ast})}\big) + C\epsilon (\Vert {\bm w}\Vert_{{\bm L}^{2}(D^{\ast})} +  \Vert \nabla p\Vert_{{\bm L}^{2}(D^{\ast})})  \\
\leq C(h+H)&(\Vert \nabla\times {\bm u}_{h}\Vert_{{\bm L}^{2}(D^\ast)} + \delta^{-1}\Vert {\bm u}_{h}\Vert_{{\bm L}^{2}(D^{\ast})}) + C\epsilon \Vert {\bm u}_{h}\Vert_{{\bm L}^{2}(D^{\ast})}. 
\end{split}
\end{align}
We define the desired approximation space ${\bm V}_{H,\epsilon}(D)$ as the ${\bm L}^{2}$ orthogonal projection of $\widehat{\bm V}_{H,\epsilon}(D)$ onto ${\bm W}_{h}(D)$. Assuming $h\leq H$ and using \cref{eq:aux_final_approx} and properties of the ${\bm L}^{2}$ orthogonal projection, we obtain the estimate \cref{eq:weak_approx_estimate}. When $h>H$, we can simply choose $\widehat{\bm V}_{H,\epsilon}(D) = {\bm W}_{h}(D)$ which satisfies that ${\rm dim}\,\widehat{\bm V}_{H,\epsilon}(D)\leq C_{d}|\widetilde{D}^{+}|/h^{d}\leq C_d|D^{\ast}|/H^{d}$. In this case, the estimate holds trivially since the infimum on the left is zero.
\end{proof}  

%and the fact that $\inf_{{\bm v}\in {\bm V}_{\rm fin}}\Vert {\bm u}_h - {\bm v}\Vert_{{\bm L}^{2}(D_2)} \leq \inf_{{\bm v\in {\bm V}}}\Vert {\bm u}_h - {\bm v}\Vert_{{\bm L}^{2}(D_2)}$ 

\subsection{Proof of \cref{thm:exponential_convergence}}\label{subsec:proof_main_theorem}
We prove \cref{thm:exponential_convergence} by first combining the Caccioppoli inequality and the weak approximation property to obtain a one-step approximation in the energy norm, and then iterating the obtained result over a family of nested subdomains between $\omega$ and $\omega^{\ast}$. Although similar proofs have been well presented in previous works \cite{babuska2011optimal,ma2021novel,ma2025unified}, a special treatment is needed here due to the presence of the term $\delta^{-1}$ in the weak approximation estimate \cref{eq:weak_approx_estimate}. As mentioned above, we first combine \cref{lem:caccioppoli_inequality,lem:weak_approximation} to obtain an auxiliary approximation result. For a domain $D\subset \Omega$ and $\delta>0$, we introduce the following weighted energy norm:
\begin{equation}\label{eq:weighted_norm}
  \Vert {\bm u}\Vert_{a, D, \delta}:= \big(\Vert \nu^{1/2}\nabla\times {\bm u}\Vert^{2}_{{\bm L}^{2}(D)} + \delta^{-2}\Vert \kappa^{1/2}{\bm u}\Vert^{2}_{{\bm L}^{2}(D)}\big)^{1/2} \quad \text{for}\;\;{\bm u}\in {\bm H}({\rm curl};D).
\end{equation}
\vspace{-2ex}
\begin{lemma}\label{lem:aux_approximation}
Let $D\subset D^{\ast}\subset\subset \omega^{\ast}$ with $\delta:={\rm dist} ({D},\partial D^{\ast}\setminus \partial \Omega) > 0$ be simply connected domains, and let $H\in (0,\delta/2)$, $\epsilon\in (0,1)$, and $h\in (0,\delta/8)$. Then, there exists a subspace ${\bm V}_{H,\epsilon}(D)$ of ${\bm W}_{h}(D)$ with ${\rm dim} \, {\bm V}_{H,\epsilon}(D)\leq C^{\prime}_{\rm dim}\big( |D^{\ast}|/H^{d} + (|D^{\ast}|/\delta^{d})|\log \epsilon|^{d+1}\big)$ such that for any ${\bm v}_{h}\in {\bm W}_{h}(D^{\ast})$, 
\begin{equation}\label{eq:single_step_estimate}
\inf_{{\bm z}_h\in {\bm V}_{H,\epsilon}(D)}\Vert {\bm v}_h - {\bm z}_h\Vert_{a, D, \delta} \leq C^{\prime}_{\rm app}(H/\delta + \epsilon) \Vert {\bm v}_h\Vert_{a, D^{\ast}, \delta},    
\end{equation}
where $C^{\prime}_{\rm dim} = 2^{d} C_{\rm dim}$ and $C^{\prime}_{\rm app} = \sqrt{2}C_{\rm app}\max\big\{\nu^{-1/2}_{\rm min},2\kappa^{-1/2}_{\rm min}\big\} (2C_{\rm cac}+ \kappa^{1/2}_{\rm max})$, with $C_{\rm dim}$, $C_{\rm app}$, and $C_{\rm cac}$ from \cref{lem:weak_approximation,lem:caccioppoli_inequality}.
\end{lemma}
\begin{proof}
Let $D^{+}$ be a simply connected domain between $D$ and $D^{\ast}$ such that ${\rm dist}(D, \partial D^{+}\setminus \partial \Omega) = {\rm dist}(D^{+}, \partial D^{\ast} \setminus \partial \Omega) = \delta/2$. Applying \cref{lem:weak_approximation} to $D^{+}\subset D^{\ast}$ and using the weighted norm \cref{eq:weighted_norm}, we know that there exists a subspace $\widehat{\bm V}_{H,\epsilon}(D^{+})$ of ${\bm W}_{h}(D^{+})$ with ${\rm dim} \, \widehat{\bm V}_{H,\epsilon}(D^{+}) \leq C_{\rm dim}\big(|D^{\ast}|/H^{d} + (2^{d}|D^{\ast}|/\delta^{d})|\log \epsilon|^{d+1}\big)$ such that 
\begin{align}\label{eq:aux_1}
\begin{split}
\inf_{{\bm z}_{h}\in \widehat{\bm V}_{H,\epsilon}(D^{+})} \Vert {\bm v}_{h} - {\bm z}_{h}&\Vert_{{\bm L}^{2}(D^{+})}\leq  C_{\rm app}\big(H(\Vert \nabla \times {\bm v}_{h}\Vert_{{\bm L}^{2}(D^{\ast})} + 2\delta^{-1}\Vert {\bm v}_{h}\Vert_{{\bm L}^{2}(D^{\ast})})\\
+ \epsilon \Vert {\bm v}_{h}\Vert_{{\bm L}^{2}(D^{\ast})} \big)&\leq \sqrt{2}C_{\rm app}\max\big\{\nu^{-1/2}_{\rm min},2\kappa^{-1/2}_{\rm min}\big\}(H+\epsilon \delta)  \Vert {\bm v}_h\Vert_{a, D^{\ast}, \delta}.  
\end{split}    
\end{align}
Next we apply the Caccioppoli inequality in \cref{lem:caccioppoli_inequality} to $D\subset D^{+}$ and find
\begin{align}\label{eq:aux_2}
\begin{split}
\Vert {\bm v}_{h}\Vert_{a, D, \delta} &\leq C_{\rm cac}(\delta/2)^{-1}\Vert {\bm v}_h\Vert_{{\bm L}^{2}(D^{+}\setminus D)} + \kappa^{1/2}_{\rm max}\delta^{-1} \Vert {\bm v}_h\Vert_{{\bm L}^{2}(D)}\\
&\leq (2C_{\rm cac}+ \kappa^{1/2}_{\rm max})\delta^{-1}  \Vert {\bm v}_h\Vert_{{\bm L}^{2}(D^{+})} \quad \text{for all}\;\; {\bm v}_{h}\in {\bm W}_{h}(D^{+}).
\end{split}    
\end{align}
Combining \cref{eq:aux_1,eq:aux_2} and setting ${\bm V}_{H,\epsilon}(D):=  \widehat{\bm V}_{H,\epsilon}(D^{+})|_{D}$ yields \cref{eq:single_step_estimate}. 
\end{proof}

