Next we estimate the norm of the partition of unity operators. 
\begin{lemma}\label{lem:norm_estimate_POU}
Let the partition of unity operator $\Xi_h$ be defined by \cref{eq:discrete_pou}, and let \cref{ass:POU} be satisfied. Then with $\rho>0$ defined in \cref{ass:POU},
\begin{equation}\label{eq:stability_pou}
\Vert \Xi_h({\bm v}_h)\Vert_{a,\omega}\leq C(1+\rho^{-1}) \Vert {\bm v}_h\Vert_{a,\omega} \quad \text{for all}\;\; {\bm v}_h\in {\bm Q}_{h,\Gamma}(\omega), 
\end{equation}
where $C$ depends on $\kappa_{\rm min}$, $\kappa_{\rm max}$, $\nu_{\rm min}$, $\nu_{\rm max}$, and the shape regularity of the mesh $\mathcal{T}_h$.
\end{lemma}
\begin{proof}
Using the error estimates \cref{eq:error_nedelec_interpolation_1} for the interpolation operator $\Pi_h$, we have
\begin{align}\label{eq:estimate_pou_1}
\begin{split}
    \Vert \chi {\bm v}_h -& \Pi_{h}(\chi {\bm v}_h)\Vert_{{\bm L}^{2}(K)}+ \Vert \nabla\times (\chi {\bm v}_h - \Pi_{h}(\chi {\bm v}_h))\Vert_{{\bm L}^{2}(K)} \\
    &\leq Ch \big(|\chi {\bm v}_h|_{{\bm H}^{1}(K)} + |\nabla\times (\chi {\bm v}_h)|_{{\bm H}^{1}(K)} \big).
\end{split}
\end{align}
Furthermore, it follows from \cref{ass:POU} and an inverse estimate that 
\begin{equation}\label{eq:estimate_pou_2}
h \big(|\chi {\bm v}_h|_{{\bm H}^{1}(K)} + |\nabla\times (\chi {\bm v}_h)|_{{\bm H}^{1}(K)} \big) \leq C(1+\rho^{-1}) \Vert {\bm v}_h\Vert_{{\bm H}({\rm curl};\,K)}.    
\end{equation}
Inserting \cref{eq:estimate_pou_2} into \cref{eq:estimate_pou_1}, summing the result over all elements $K\subset\omega$, and using a triangle inequality and \cref{ass:POU} again, we obtain
\begin{align}
\begin{split}
\Vert \Pi_h(\chi {\bm v}_h)\Vert_{{\bm H}({\rm curl};\omega)} &\leq \Vert \chi {\bm v}_h\Vert_{{\bm H}({\rm curl};\omega)} + \Vert \chi {\bm v}_h -  \Pi_h(\chi {\bm v}_h)\Vert_{{\bm H}({\rm curl};\omega)}   \\
&\leq C(1+\rho^{-1}) \Vert {\bm v}_h\Vert_{{\bm H}({\rm curl;\omega})},
\end{split}
\end{align}
which immediately gives \cref{eq:stability_pou}.
\end{proof}

Now we are ready to prove \cref{thm:exponential_convergence}. For $N\in \mathbb{N}$, let $\{\omega^{k} \}_{k=2}^{N}$ be a family of simply connected domains between $\omega$ and $\omega^{\ast}$ with $\omega^{N+1}:=\omega\subset \omega^{N}\subset\cdots\subset\omega^{1}:=\omega^{\ast}$ and $\delta:={\rm dist}(\omega^{k+1},\partial \omega^{k}\setminus \partial \Omega) =  \delta^{\ast}/N$. For each $1\leq k\leq N$, let ${\bm V}^{k}_{H,\epsilon}$ be the space as in \cref{lem:aux_approximation} with $D^{\ast}$ and $D$ replaced by $\omega^{k}$ and $\omega^{k+1}$, respectively, and let $\widehat{\bm V}_{\rm app} = {\bm V}_{H,\epsilon}^{1}|_{\omega} + \cdots + {\bm V}_{H,\epsilon}^{N}|_{\omega} \subset {\bm W}_{h}(\omega)$. We first assume that $h\leq \delta/8$. By repeatedly applying \cref{lem:aux_approximation}, we see that for each ${\bm v}_{h}\in {\bm W}_{h}(\omega^{\ast})$,
\begin{equation}
\inf_{{\bm z}_h\in \widetilde{\bm V}_{\rm app}}\Vert {\bm v}_h|_{\omega} - {\bm z}_h\Vert_{a, \omega, \delta} \leq \big[C^{\prime}_{\rm app}(H/\delta + \epsilon) \big]^{N} \Vert {\bm v}_h\Vert_{a, \omega^{\ast}, \delta}.    
\end{equation}
Next we choose $C^{\prime}_{\rm app}H/\delta = C^{\prime}_{\rm app}NH/\delta^{\ast} = 1/(2e)$ and $C^{\prime}_{\rm app}\epsilon = 1/(2e)$. It follows that for each $1\leq k\leq N$, ${\rm dim} \, {\bm V}_{H,\epsilon}^{k} \leq  C^{\prime\prime}_{\rm dim}N^{d}|\omega^{\ast}|/(\delta^{\ast})^{d}$ with $C^{\prime\prime}_{\rm dim}:=C^{\prime}_{\rm dim}\big((2eC^{\prime}_{\rm app})^{d} + \log^{d+1}{(2eC^{\prime}_{\rm app})}\big)$. Moreover, we have, with ${\rm dim} \, \widehat{\bm V}_{\rm app} \leq  C^{\prime\prime}_{\rm dim}N^{d+1}|\omega^{\ast}|/(\delta^{\ast})^{d}$, 
\begin{equation}\label{eq:weighted_exponential_decay}
\inf_{{\bm z}_h\in \widehat{\bm V}_{\rm app}}\Vert {\bm v}_h|_{\omega} - {\bm z}_h\Vert_{a, \omega, \delta} \leq e^{-N} \Vert {\bm v}_h\Vert_{a, \omega^{\ast},\delta}.     
\end{equation}
When $h>\delta/8$, we can simply let $\widehat{\bm V}_{\rm app} := {\bm W}_h(\omega)$. In this case, ${\rm dim} \, \widehat{\bm V}_{\rm app} \leq C_{d} |\omega|/h^{d} \leq C_{d}N^{d}|\omega|/(\delta^{\ast})^{d}$, and \cref{eq:weighted_exponential_decay} holds trivially since ${\bm v}_h|_{\omega}\in {\bm W}_h(\omega)$. Using \cref{eq:weighted_exponential_decay} and recalling the definition of the norm $\Vert \cdot\Vert_{a, \omega, \delta}$, we further have
\begin{align}
  \begin{split}
& \inf_{{\bm z}_h\in \widehat{\bm V}_{\rm app}}\Vert {\bm v}_h - {\bm z}_h\Vert_{a, \omega}\leq \max\{1,\delta\}\inf_{{\bm z}_h\in \widehat{\bm V}_{\rm app}}\Vert {\bm v}_h - {\bm z}_h\Vert_{a, \omega, \delta} \\
& \leq \max\{1,\delta\} e^{-N} \Vert {\bm v}_h\Vert_{a, \omega^{\ast}, \delta}\leq   \max\{\delta,\delta^{-1}\} e^{-N}\Vert {\bm v}_h\Vert_{a, \omega^{\ast}}, \\[1ex]
&\leq \max\{\delta^{\ast}, 1/\delta^{\ast}\} Ne^{-N}\Vert {\bm v}_h\Vert_{a, \omega^{\ast}} \leq \max\{\delta^{\ast}, 1/\delta^{\ast}\} e^{-N/2}\Vert {\bm v}_h\Vert_{a, \omega^{\ast}}.
\end{split}  
\end{align}
Let $n:={\rm dim} \widehat{\bm V}_{\rm app}\leq C^{\prime\prime}_{\rm dim}N^{d+1}|\omega^{\ast}|/(\delta^{\ast})^{d}$ and $b:= \frac{1}{2}\big(C^{\prime\prime}_{\rm dim}|\omega^{\ast}|/(\delta^{\ast})^{d}\big)^{-1/(d+1)}$. It follows that $N\geq 2b n^{1/(d+1)}$ and thus
\begin{equation}\label{eq:nonweighted_exponential_decay}
\inf_{{\bm z}_h\in \widehat{\bm V}_{\rm app}}\Vert {\bm v}_h - {\bm z}_h\Vert_{a, \omega}\leq  \max\{\delta^{\ast}, 1/\delta^{\ast}\} e^{-bn^{1/(d+1)}}\Vert {\bm v}_h\Vert_{a, \omega^{\ast}}.  
\end{equation}
Let ${\bm V}_{\rm app}:= \Xi_h(\widehat{\bm V}_{\rm app})\subset {\bm Q}_{h,0}(\omega)$. Then ${\rm dim}\,{\bm V}_{\rm app} \leq n$. Combining \cref{eq:nonweighted_exponential_decay} and \cref{lem:norm_estimate_POU} yields
\begin{align}\label{eq:aux_exponential_decay}
\begin{split}
 \inf_{{\bm z}_h\in {\bm V}_{\rm app}}&\Vert \Xi_h({\bm v}_h) - {\bm z}_h\Vert_{a, \omega} \leq \Vert\Xi_h\Vert \inf_{{\bm z}_h\in \widehat{\bm V}_{\rm app}}\Vert {\bm v}_h - {\bm z}_h\Vert_{a, \omega} \\
 \leq &C(1+\rho^{-1}) \max\{\delta^{\ast}, 1/\delta^{\ast}\} e^{-bn^{1/(d+1)}}   \Vert{\bm v}_h\Vert_{a, \omega^{\ast}}. 
\end{split}
\end{align}
% \begin{equation}
