\begin{assumption}\label{ass:dimension_harmonic_forms}
For each $N\in\mathbb{N}$, let $\{\omega_{N}^{k} \}_{k=1}^{N+1}$ be a family of domains between $\omega$ and $\omega^{\ast}$ with $\omega_{N}^{N+1}:=\omega\subset \cdots\subset\omega_{N}^{1}:=\omega^{\ast}$ and ${\rm dist}(\omega_{N}^{k+1},\partial \omega_{N}^{k}\setminus \partial \Omega) = \delta^{\ast}/N$. There exists $d_{\mathtt{har}}\in\mathbb{N}$ such that for each $N\in \mathbb{N}$ and $k=1,\cdots,N+1$, 
\begin{equation}
\min_{D\in \mathscr{E}_h(\omega_N^{k})}{\rm dim}\,\mathcal{\bm H}_{h}(D)\leq d_{\mathtt{har}},    
\end{equation}
where $\mathscr{E}_h(\omega_N^{k})$ is defined in \cref{eq:set_of_domains}. 
\end{assumption}

Using \cref{ass:dimension_harmonic_forms} and following along the same lines as in the proof of \cref{lem:weak_approximation}, we can prove a similar weak approximation property in this case.  
\begin{lemma}\label{lem:weak_approximation_general_domain}
Let \cref{ass:dimension_harmonic_forms} be satisfied, and let $D\subset D^{\ast}$ be from the family of domains defined in \cref{ass:dimension_harmonic_forms} with $\delta:={\rm dist} ({D},\partial D^{\ast}\setminus \partial \Omega) > 0$. Suppose that $h\leq \delta/4$. Then there exists a family of subspaces ${\bm V}_{H,\epsilon}(D)$ of ${\bm W}_{h}(D)$ with ${\rm dim} \, {\bm V}_{H,\epsilon}(D)\leq d_{\mathtt{har}}+C_{{\rm dim}}\big(|D^{\ast}|/H^{d} + (|D^{\ast}|/\delta^{d})|\log \epsilon|^{d+1}\big)$, such that for any ${\bm u}_{h}\in {\bm W}_{h}(D^{\ast})$,
\begin{align}
\begin{split}
&\inf_{{\bm z}_{h}\in {\bm V}_{H,\epsilon}(D)} \Vert {\bm u}_{h} - {\bm z}_{h}\Vert_{{\bm L}^{2}(D)}\\
&\leq C_{\rm app} \big(H(\Vert \nabla \times {\bm u}_{h}\Vert_{{\bm L}^{2}(D^{\ast})} + \delta^{-1}\Vert {\bm u}_{h}\Vert_{{\bm L}^{2}(D^{\ast})}) + \epsilon \Vert {\bm u}_{h}\Vert_{{\bm L}^{2}(D^{\ast})}\big),    
\end{split}    
\end{align}
where the constants $C_{\rm dim}$ and $C_{\rm app}$ are as in \cref{lem:weak_approximation}. 
\end{lemma}
Using \cref{lem:weak_approximation_general_domain} and similar arguments as in the proof of \cref{thm:exponential_convergence}, we can prove an exponential decay for the $n$-width, analogous to \cref{thm:exponential_convergence}. 
\begin{theorem}\label{thm:exponential_convergence_general_domain}
Let $\omega\subset \omega^{\ast}$ with $\delta^{\ast}:={\rm dist}(\omega,\partial \omega^{\ast})>0$, and let \cref{ass:dimension_harmonic_forms} and \cref{ass:POU} be satisfied. Then, there exist $n_0: = (C_1+d_{\mathtt{har}})|\omega^{\ast}|/(\delta^{\ast})^{d}$ and $b:=\frac{1}{2}\big((C_1+d_{\mathtt{har}})|\omega^{\ast}|/(\delta^{\ast})^{d}\big)^{-1/(d+1)}$, such that if $n>n_0$,
\begin{equation}
  d_{n}(P)\leq  C_2(1+\rho^{-1}) \max\{\delta^{\ast}, 1/\delta^{\ast} \}\, e^{-bn^{1/(d+1)}},  
\end{equation}
where $C_1$ and $C_2$ are as in \cref{thm:exponential_convergence}.
\end{theorem}

\section{Numerical experiments}\label{sec-5}
In this section, we present numerical results to illustrate the performance of the proposed methods. The numerical experiments are performed using the software \texttt{FreeFEM} \cite{hecht2012new}, in particular based on its \texttt{ffddm} \cite{FFD:Tournier:2019} module designed to facilitate the use of two-level Schwarz domain decomposition solvers. The local boundary value problems and the coarse problem in MS-GFEM are solved by direct solvers. The local eigenproblems are solved using the techniques presented in \cite[section 2.3]{ma2025unified} and a built-in eigensolver in \texttt{FreeFEM} which is a wrapper of \texttt{Arpack}. The convergence tolerance of GMRES corresponding to a relative residual reduction is set to $10^{-6}$. 

