function check_inductive(n,a,cst,ctxt) {
	var u = getUniverse(a);
	cst.forEach(function(cst) {
	   var tCst = type_check(extend_type(n,a,ctxt),cst[1]);
	   var eq   = equal_expr(tCst,u);
	   positive(cst[1],n) );
	}); 
	return a;
}  
\end{lstlisting}
\caption{Type Checking Inductive Definitions.}
\label{fig:webpie:type_inductivedef}

\end{figure}


\begin{figure}[h!] % the figure provides the caption
\begin{lstlisting}
 function check_match(c,e,cases,ctxt) {
      var IndT    = normalise(type_check(ctxt,e),ctxt);
      var c_type  = normalise(type_check(ctxt,c),ctxt);
      var Ind     = findInductive(IndT); 
      var pargs   = countArgs(Ind.arity);
      verify_c_type(c_type,Ind,pargs);
      var constructors = Ind.constructors;
      checkMatchLength(constructors,cases);
      cases.map( function(cs,i) { 
           var cstT = constructors[i].ctype;
           var case_type  = normalise(makeTypeForCase(cstT,c,cs.name),ctxt);
           var e_it = type_check(ctxt,cs.expr); 
           var x = check_equal(e_it,case_type,ctxt);    
      }); 
      return normalise(App(makeRApp(c,IndT,pargs),e),ctxt); 
 }     
\end{lstlisting}
\caption{Type Checking a Match Expression.}
\label{fig:webpie:type_match}
\end{figure} 


Extensions to the implementation of the type checker
consists of adding cases for the constructors, inductive types
and case matching. Because the programmer cannot type in
a constructor himself typing the constructor is as simple as
returning the field of the inductive definition.

Typing inductive definitions consist of checking that the
universes correspond and that the constructors are well
formed, as shown in Figure~\ref{fig:webpie:type_inductivedef}. 
In our implementation getUniverse and positive corresponds to $\Upsilon$ and $C(x, e)$ in the formalisation.


Finally type checking case matches (Figure~\ref{fig:webpie:type_match}) differs a little bit from
the formalisation because the syntax of the formalisation and
the implement differ slightly. In the implementation the
programmer needs to supply an abstraction with the
correct number of arguments for the constructor i.e. 
\lstinline{Succ => (λn:Nat. (Succ (add n y))) }instead of 
\lstinline{(Succ n)=> (Succ (add n y)))}.
The code first verifies whether the value over which
we case match is an inductive type. Then it verifies whether
the constructors match the cases. We then verify for each of
the constructors that the right hand side of the cases match.
In the implementation we do this by explicitly building up a
$\Pi$ type and apply normalisation with \lstinline{makeTypeForCase}.

\section{Safe Printf in WebPie}
As a final example of using WebPie, we show how to encode the safe \lstinline{printf} example of the introduction. 
As WebPie does not have any primitives for input output we merely simulate a safe \lstinline{printf}.

The implementation of our safe \lstinline{printf} (shown in Figure~\ref{fig:webpie:printf}) starts by defining an inductive type \lstinline{FormatString} to construct format strings. 
In our case the format string is either \lstinline{End} or a type appended to the format string, i.e. a list of types. 
Given a list of types the function \lstinline{computeType} gives us the type of a function that expects all the argument in the list and eventually returns the type \lstinline{Void}. 
Finally, the function \lstinline{printF} is a dependently typed function that given a format string \lstinline{e} has the type \lstinline{(computeType e)}.
The implementation of \lstinline{printF} makes use of dependent pattern matching on the format string. If the end of the format string has been reached it will simply return \lstinline{Null}. 
In the other case it will create a new function that expects the head for the format string and recursively creates a new function based on the rest of the format string. 

\begin{figure}[h!] % the figure provides the caption
\begin{lstlisting}
Inductive FormatString : Type :=
  | End  : FormatString
  | Cons : Set -> FormatString -> FormatString;

def computeType(e:FormatString) : Set  {
  <(Πf:FormatString.Set)> 
  match e with  {
     End   => Void ;
     Cons  => (λhf:Set.
               (λrf:FormatString.
                  hf -> (computeType rf)))
  }
};

def printF( e:FormatString ) : (computeType e) {
  <(Πf:FormatString.(computeType f))> 
  match e with  {
     End => Null;
     Cons => (λhf:Set.
               (λrf:FormatString.
                 (λx:hf.
                  (printF rf))))
  }
};
\end{lstlisting}
\caption{Implementation of printF.}
\label{fig:webpie:printf}
\end{figure} 


