\section{Proofs over natural numbers}


\begin{lstlisting}
Inductive Nat : Set :=
  | Zero : Nat 
  | Succ : Nat  -> Nat;
Inductive Plus : Nat -> Nat -> Nat -> Set :=
  | Plus_Zero  : Πn:Nat.(Plus Zero n n)
  | Plus_Succ  : Πx:Nat.Πy:Nat.Πs:Nat.Πp:(Plus x y s).
                          (Plus (Succ x)  y (Succ s));

Inductive Eq : Nat -> Nat -> (Type 1) :=  
 | Eq_Rfl  : Πn:Nat.(Eq n n)
 | Eq_Succ : Πx:Nat.Πy:Nat.(Eq x y) -> (Eq  (Succ x) (Succ y));

def nat_ind
( P  : Nat -> Prop,
  f  : (P Zero),
  fn : (Πn:Nat.(P n) -> (P (Succ n))),
   n : Nat 
) :  (P n)  
{
   <(λn:Nat.(P n))> 
   match n  with {
      Zero  => f;
      Succ  => (λn:Nat. (fn n (nat_ind P f fn n)))
   }   
};

def add(x:Nat,y:Nat) : Nat {
  <(λn:Nat.Nat)>
  match x with {
     Zero  => y;
     (Succ z)  => (λz:Nat. (Succ (add z y)))
  }
};

def add_zero(n:Nat) : (Eq (add Zero n) n) {
   (Eq_Rfl n)
};






def add_x_zero(x:Nat): (Eq (add x Zero) x) {
  ((nat_ind
   (λn:Nat.(Eq (add n Zero) n))
   (Eq_Rfl Zero)
   (λn:Nat.(λIH:(Eq (add n Zero) n).
      (Eq_Succ (add n Zero) n IH))))
   x)
};

def plus_x_zero(x:Nat) : (Plus x Zero x) {
  (nat_ind
         (λn:Nat.(Plus n Zero n))
   (Plus_Zero Zero)
   (λy:Nat.(λIH:(Plus y Zero y). (Plus_Succ y Zero y IH)))
   x)
}
\end{lstlisting}

