\subsection{$\alpha$-stable Spatial Measure for Sound Source Localization} \label{sec:related_SSL}

% In \cite{fontaine2017sketching, fontaine2017scalable} the multichannel observed signal $\mbx_{ft} \in \mathbb{C}^{M}$
% % in the short-time Fourier transform (STFT) domain for the time-frequency bin (TF) $f,t  \in \{1, \dots, F\} \times \{1, \dots, T\}$ where $F,T$ are the total number of frequency bins and time frame respectively
% is assumed to be decomposed as follows with $M$ the number of microphones:
% \begin{align}
% \mbx_{ft} = \sum_{l=1}^{L}\mba_{lf}s_{lft}  \label{eq:mix_model}
% \end{align}
% where $\mba_{lf} \in \mathbb{C}^M$ are the direct-path steering vector pointing toward $s_{lft}\in \mathbb{C}$. Here, $l \in [1, L]$ represents one potential position on a grid (can be azimuth elevations or cartesian coordinates for instance) of a potential active source. We denote $N <  L$ being the number of sources we aim to localize.

Following \cite{fontaine2017sketching, fontaine2017scalable},
an $M$-channel observed mixture signal $\mbx_{ft} \in \mathbb{C}^{M}$
is assumed to be a sum of source images propagated from $L$ potential source locations:
\begin{align}
\mbx_{ft} = \sum_{l=1}^{L}\mba_{lf}s_{lft} , \label{eq:mix_model}
\end{align}
where $\mba_{lf} \in \mathbb{C}^M$ is the direct-path SV pointing toward $s_{lft}\in \mathbb{C}$
and $l \in [1, L]$ represents one potential source location on a grid (e.g., in the polar or Cartesian coordinate system).
Given $\mbx_{ft}$ and the number of sources of interest $N$, we aim to estimate the locations of $N$ sources ($N < L$).

% The assumption made here is that the $N$ sources of interest can be seen as ``outliers'' in terms of energy in their respective position and that the rest can be considered as noise. 

Each \( s_{lft} \) is assumed to follow a complex univariate isotropic \( \alpha \)-stable distribution \cite{samoradnitsky1994stable} with a frequency- and time-invariant scale parameter $\Upsilon_l \in \mathbb{R}_+$, denoted as \( s_{lft} \sim \ComplexStable{\alpha}{}{\Upsilon_l} \).
The $N$ active source signals coming from their respective locations can be seen as ``outliers'' in terms of energy since $\Upsilon_{l^\prime} \approx 0$ when $l^\prime$ is not a position of an active source.
% Here, \( \ComplexStable{\alpha}{}{\sigma} \) represents a univariate complex isotropic \( \alpha \)-stable distribution with a scale parameter \( \sigma \geq 0 \) and a characteristic exponent \( \alpha \in (0,2) \).
The characteristic exponent $\alpha \in (0,2]$ determines the heaviness of the distribution's tail: smaller \( \alpha \) leads to heavier tails (which allows more outliers),
whereas \( \alpha = 2 \) corresponds to the Gaussian distribution.
For the non-Gaussian case ($\alpha < 2$), it can be shown that $\mbx_{ft}$ follows a complex isotropic $\alpha$-stable distribution with a unique discrete \textit{spatial measure} $\mbUp \triangleq [\Upsilon_1, \dots, \Upsilon_L] \in \mathbb{R}_+^{L}$ \cite{fontaine2017scalable}.

Due to the absence of an analytic form for the probability density function,
we use
the time-invariant Lévy exponent $I_f(\mbth) \in \mathbb{R}$ given a parameter $\mbth \in \mathbb{C}^{M}$
to establish a relationship between $\mbUp$, $\mbx_{ft}$, and
% a normalized SV $\tilde{\mba}_{lf} \triangleq \mba_{lf} / \Vert \mba_{lf} \Vert_2^2$
$\mba_{lf}$
as
\begin{align}
I_{f}(\mbth) \triangleq  -\ln \mathbb{E}[e^{\mathrm{i}\Re(\mbth^{\mathsf{H}})\mbx_{ft}}] = \sum_{l=1}^L \Upsilon_l\left|\mbth^\mathsf{H}{\tilde{\mba}}_{lf}\right|^\alpha ,
\label{eq:levy_exp}
\end{align}
where $\tilde{\mba}_{lf} \triangleq \mba_{lf} / \Vert \mba_{lf} \Vert_2^2$ is a normalized SV.

Following \cite{fontaine2017scalable},
instead of using a Lévy exponent given a single parameter $\mbth$ as above,
we consider a set of parameters $\mbth_{lf} \triangleq \tilde{\mba}_{lf}$ to provide physical interpretation
and use the nonnegative estimator of the Lévy exponent given by
\begin{align}
\hat{I}_f(\tilde{\mba}_{lf}) = -2\ln \left| \frac{1}{T} \sum_{t=1}^{T} \exp\left(\mathrm{i}\frac{\Re(\tilde{\mba}_{lf}^\mathsf{H}\mbx_{ft})}{2^{1/\alpha}}\right)\right| .
\end{align}
By defining $\hat{\mbI}_f \triangleq [\hat{I}_f(\tilde{\mba}_{1f}), \dots, \hat{I}_f(\tilde{\mba}_{Lf})]^\top \in \mathbb{R}_+^{L}$  
and $\mbPs_f \triangleq \big[\big|\tilde{\mba}_{lf}^\mathsf{H}\tilde{\mba}_{l^\prime f}\big|^\alpha\big]_{l=1,l^\prime = 1}^{L,L} \in \mathbb{R}_+^{L \times L}$,
we have the relation $\hat{\mbI}_f \approx \mbPs_f\mbUp$.
% It was then shown in \cite{fontaine2017scalable} that a nonnegative estimator of $I_f$ can be formulated. In particular, an empirical approach that considers a set $\mbth_{lf}$ equal to the normalized steering vectors $\tilde{\mba}_{lf}$ appears to be a good trade-off, providing an interpretable set of samples derived from the physical properties of the model.
% If we define $\hat{\mbI}_f \triangleq [\hat{I}_f(\tilde{\mba}_{1f}), \dots, \hat{I}_f(\tilde{\mba}_{Lf})]^\top \in \mathbb{R}_+^{L}$, where  
% \begin{align}
% \hat{I}_f(\tilde{\mba}_{lf}) = -2\ln \left| \frac{1}{T} \sum_{t=1}^{T} \exp\left(\mathrm{i}\frac{\Re(\tilde{\mba}_{lf}^\mathsf{H}\mbx_{ft})}{2^{1/\alpha}}\right)\right|
% \end{align}
% and define $\mbPs_f \triangleq \left[\left|\tilde{\mba}_{lf}^\mathsf{H}\tilde{\mba}_{l^\prime f}\right|^\alpha\right]_{l=1,l^\prime = 1}^{L,L} \in \mathbb{R}_+^{L \times L}$, we obtain the approximation $\mbI_f \approx \mbPs_f\mbUp$.
Since $\mbUp$ is frequency-independent, we concatenate all $\hat{\mbI}_f$ and $\mbPs_f$ matrices along the frequency axis to form a vector $\hat{\mbI} \in \mathbb{R}_+^{FL}$ and a matrix $\mbPs \in \mathbb{R}_+^{FL \times L}$, respectively, leading to the relation:
\begin{align}
\hat{\mbI} \approx \mbPs\mbUp. \label{eq:approx_I}
\end{align}
As $\mbPs$ may still be ill-conditioned making it inversion unstable,
we instead minimize the pointwise $\beta$-divergence%
\footnote{It corresponds to the Itakura-Saito divergence ($\beta=0$), the Kullback-Leibler divergence ($\beta=1$), or the Euclidean distance ($\beta=2$)}
between the left- and right-hand sides of Eq.~\eqref{eq:approx_I},
% we aim to minimize the discrepancy between the left- and right-hand sides of Eq.~\eqref{eq:approx_I}.
% To achieve this, %
% denoted $d_\beta (\cdot | \cdot)$ (e.g., for $\beta=0, \beta=1, \beta=2$, this corresponds to the Itakura-Saito, Kullback-Leibler, and Euclidean divergences, respectively),
% while imposing a penalty constraint on $\mbUp$ due to its high sparsity \cite{fontaine2017sketching}.
while imposing a sparsity penalty constraint on $\mbUp$ \cite{fontaine2017sketching}.
This optimization problem ultimately leads to the following iterative update strategy:  
\begin{align}
\hat{\mbUp} \leftarrow \hat{\mbUp} \odot \frac{\mbPs^\top\left(\left(\mbPs\hat{\mbUp}\right)^{\beta-2} \odot \hat{\mbI}\right)}{\mbPs^\top\left(\left(\mbPs\hat{\mbUp}\right)^{\beta-1}\right) + \lambda} , \label{eq:updates}
\end{align}  
where $\lambda \in \mathbb{R}_+$ is the sparsity penalty coefficient
with $a \odot b$ and $\frac{a}{b}$ denote element-wise multiplication and division, respectively.  

