        \begin{align}
            \frac{1}{r_1}\cdot ((\ref{girth10 1})-(\ref{girth10 8})): e_4-e_1=& d_1(c_1-c_4)  \label{girth10 9}\\
            \frac{1}{r_2}\cdot ((\ref{girth10 3})-(\ref{girth10 2})): e_1-e_2 =& d_2(c_2-c_1)\label{girth10 10}\\
            \frac{1}{r_3}\cdot ((\ref{girth10 5})-(\ref{girth10 4})): e_2-e_3=& d_3(c_3-c_2) \label{girth10 11}\\
            \frac{1}{r_4}\cdot ((\ref{girth10 7})-(\ref{girth10 6})): e_3-e_4 =& d_4(c_4-c_3)\label{girth10 12}
        \end{align}
        \begin{align}
            (\ref{girth10 9})+(\ref{girth10 10})+(\ref{girth10 11})+(\ref{girth10 12}): 0=&c_1(d_1-d_2)+c_2(d_2-d_3)+c_3(d_3-d_4)+c_4(d_4-d_1) \label{girth10 f1}\\
            (\ref{g10 9}),(\ref{g10 10}),(\ref{g10 11}),(\ref{g10 12}) \rightarrow (\ref{girth10 f1}):  0=&c_1^2(r_1-r_2)+c_2^2(r_2-r_3)+c_3^2(r_3-r_4)+c_4^2(r_4-r_1) \notag\\
            & -(c_1(r_1-r_2)+c_2(r_2-r_3)+c_3(r_3-r_4)+c_4(r_4-r_1)\notag\\
            =&(r_1-r_2)(c_1^2-c_2^2+c_3^2-c_4^2-(c_1-c_2+c_3-c_4))\notag\\
            (\ref{girth10 c}) \implies 0=&(r_1-r_2)(c_1^2-c_2^2+c_3^2-(c_1-c_2+c_3)^2)\notag\\
            =&2(r_1-r_2)(c_2-c_3)(c_1-c_2)\notag .
