    \centering
    \includegraphics[width=.875\textwidth]{fig_quant_transformer_block_combined.pdf}
    \caption{\textbf{Top:} Transformer layers quantized to \texttt{MXFP8} inside a single transformer block. \textbf{Bottom:} Training workflow for a single layer during \texttt{FPROP}, \texttt{DGRAD} and \texttt{WGRAD}.}
