\section{Fast Ground Completion Introducing Additional Constants}\label{gyors}


From now on throughout this section, let $\Sigma$ be a signature,  $E$ and $F$ be  GTESs over $\S$, 
$W=ST(E\cup F)$, 
and   $n= size(E)+size(F)$.  
We recall  the fast ground completion  algorithm of F\"ul\"op and V\'agv\"olgyi \cite{eatcs/FuloopV91}. Its input is $\S$, $E$, and
$F $.  Their fast ground completion  algorithm \cite{eatcs/FuloopV91} produces in 
$O(n \,\mathrm{log}\; n)$ time a finite set of  new  constants and 
a reduced GTRS  $ R \langle E, F \rangle  $
over $\S$ extended with the new constants
such  that $\tthue E=\tthue {R\langle E, F  \rangle } \cap \ts \times \ts $.
 Their algorithm calls a
 congruence closure algorithm  on  the  subterm dag for $E\cup F$ \cite{jacm/DowneyST80}, and runs in 
$O(n \, \mathrm{log}\, n)$ time by Proposition \ref{lezaras}. 

We now cite the  Claim on \cite[p.~167]{Kozen77}.
  \begin{prop} \label{kozen}{\em \cite{Kozen77}}
     $\Theta\langle E, F \rangle= \{\, (\widehat{x}, \widehat{y}) \mid (x, y)\in \rho
\langle E, F  \rangle\, \}$.
  \end{prop}



\begin{df}\label{szeder}  \rm We put
$C\langle E, F  \rangle = \{\,  t/_{\Theta\langle E, F  \rangle}  \mid t \in W \, \}$.
\end{df} 
By Proposition \ref{kozen}, 
for each equivalence class $\vartheta \in W /_{  \Theta\langle E, F \rangle }$, there exists exactly one   equivalence  class $\eta \in V/_{\rho\langle E, F  \rangle  } $ such that 
$\vartheta= \{\, \widehat{x} \mid x\in \eta\, \}$.
To simplify our notations, we give  $\vartheta$
 the  unique name of $\eta$.  The elements of $ C\langle E, F  \rangle$
are viewed as constants, and we  define the  signature   $\Sigma \cup  C\langle E, F  \rangle$.



\begin{sta}\label{darabsz}
$|C\langle E, F   \rangle|\leq |W|\leq size(W )\leq n$. 
\end{sta}
\begin{proof}
By Definition \ref{szeder}.
\end{proof}
\begin{df}\label{szabaly}\rm\cite{eatcs/FuloopV91}
Let
 \begin{quote} $R\langle E, F  \rangle= \newline
  \{\, \s( t_1/_{\Theta\langle E, F \rangle}, \ldots,  t_m/_{\Theta\langle E, F  \rangle}) \dot{\rightarrow}  \s(t_1, \ldots,t_m)/_{\Theta\langle E, F  \rangle}
  \mid \s\in \S_m, m\in \Nat, t_1, \ldots, t_m \in \ts,  \s(t_1, \ldots, t_m)\in W \, \}$ 
  \end{quote}
  be a GTRS over the ranked alphabet  $\S \cup C\langle E, F  \rangle$.
  \end{df}
Note that for any $\s(t_1, \ldots, t_m) \in W$ with  $\s\in \S_m$, $m\in \Nat$,
and $t_1, \ldots, t_m \in \ts  $ there exists at most one
rewrite rule 
 with left-hand side $ \s( t_1/_{\Theta\langle E, F  \rangle}, \ldots,  t_m/_{\Theta\langle E, F  \rangle})$ in $R \langle E, F \rangle $.
  \begin{df}\label{csurig} \rm
  We say that GTRS $R \langle E, F \rangle $
is  total if for any  $\s\in \S_m$ with $m\in \Nat$, and   $a_1, \ldots, a_m \in C\langle E, F \rangle$,  there exists a rewrite rule in
 GTRS $R \langle E, F \rangle $ with left-hand side 
$\s(a_1, \ldots, a_m)$. 
\end{df}
F\"ul\"op and V\'agv\"olgyi \cite{eatcs/FuloopV91}
 showed the following properties of $R\langle E, F  \rangle$.
 \begin{prop}\label{elso}{\em \cite{eatcs/FuloopV91}}
   $R\langle E, F  \rangle$ is reduced.
\end{prop}
By Proposition \ref{elso} and  Proposition \ref{mozart}, we have the following result.
 \begin{prop}\label{rhcp}{\em \cite{eatcs/FuloopV91}}
   $R\langle E, F  \rangle$ is convergent.
\end{prop}



 \begin{prop} \label{masodik}
{\em \cite{eatcs/FuloopV91}}
   For every $t\in W  $, we have $t \tred {R\langle E, F  \rangle}  t/_{\Theta\langle E, F  \rangle}$.
\end{prop}

\begin{prop} \label{beszur}
{\em \cite{eatcs/FuloopV91}} Every $t\in W $ has a unique $ R\langle E, F  \rangle$ normal form.
  For every $t\in W $, we have $t{\downarrow}_{R\langle E, F  \rangle}=
   t/_{\Theta\langle E, F  \rangle}$.
\end{prop}
\begin{proof} Let $t\in W  $. 
 By Proposition \ref{masodik}, 
 we have $t \tred {R\langle E, F  \rangle}  t/_{\Theta\langle E, F  \rangle}$. 
 By direct inspection of the rewrite rules of $R\langle E, F  \rangle$, we get that for each
$t\in W $,
$ t/_{\Theta\langle E, F  \rangle}$ is irreducible for $R\langle E, F  \rangle$. Accordingly $t/_{\Theta\langle E, F  \rangle}$ is a $\red {R\langle E, F  \rangle} $ normal form 
 of $t$.
By Proposition \ref{nulladik}, Proposition \ref{rhcp}
 $t\in W $ has a unique normal form, 
 $t{\downarrow}_{R\langle E, F  \rangle}$.  Then we have $t{\downarrow}_{R\langle E, F  \rangle}=
   t/_{\Theta\langle E, F  \rangle}$.
\end{proof}


\begin{prop}\label{harmadik}
{\em \cite{eatcs/FuloopV91}}
  For all $s\in \ts$
  and $t \in W $, 
  \begin{quote} if $s \tred {R\langle E, F  \rangle}  t/_{\Theta\langle E, F  \rangle}$,
  then $s \tthue E t$.
  \end{quote} 
\end{prop}


\begin{prop}\label{negyedik}
{\em \cite{eatcs/FuloopV91}}
  For all $s, t \in \ts$,  
  \begin{quote} 
   $s \tthue E t$ if and only if $s{\downarrow}_{R\langle E, F  \rangle}= t{\downarrow}_{R\langle E, F  \rangle}$.
  \end{quote}
\end{prop}


\begin{prop}\label{otodik}
{\em \cite{eatcs/FuloopV91}}
  For all $s\in \ts$ and
  $t \in W $,
  \begin{quote}   
   if   $s \tthue E t$, then  $s \tred {R\langle E, F  \rangle}   t/_{\Theta\langle E, F  \rangle}$.
   \end{quote} 
\end{prop}



\begin{prop}\label{hatodik}
{\em \cite{eatcs/FuloopV91}}
  $\tthue E =\tthue {R\langle E, F  \rangle} \cap \ts\times \ts$.
\end{prop}

  By Proposition \ref{harmadik} and Proposition
  \ref{otodik}, we have the following result.


\begin{prop}\label{szazadik}
  For all $s\in \ts$   and $t \in W $,
  \begin{quote} 
  $s \tred {R\langle E, F  \rangle}  t/_{\Theta\langle E, F  \rangle}$
 if and only if  $s \tthue E t$.
 \end{quote} 
\end{prop}
\begin{sta}
If $R \langle E, F \rangle =\emptyset$, then $R \langle E, F \rangle $ is not total. 
\end{sta}
\begin{proof}
Let $\s\in \S_0$. There does not exists a rule in  $R \langle E, F \rangle $ with left-hand side $\s$. Consequently, 
 $R \langle E, F \rangle $ is not total. 
\end{proof}
 \begin{lem} \label{abecsikapu} If   \,$\bigcup W /_{\tthue E}=\ts$, then  
  $R\langle E, F  \rangle$ is
 total. 
\end{lem}
\begin{proof}
 Let  $\s\in \S_m$ with $m\in \Nat$, and let  $t_1/_{\Theta\langle E, F  \rangle}, \ldots,  t_m/_{\Theta\langle E, F  \rangle}$
 be  equivalence classes
of $\Theta\langle E, \; F \rangle$ for some $t_1, \ldots t_m \in W $.  By our assumption, there exists $s\in W $ such that  
$\s(t_1, \ldots, t_m)\tthue E s$. By Proposition \ref{negyedik}, 
$\s(t_1, \ldots, t_m){\downarrow}_{R\langle E, F  \rangle}= s{\downarrow}_{R\langle E, F  \rangle}$. By Proposition
\ref{beszur}
$s{\downarrow}_{R\langle E, F  \rangle}=   s/_{\Theta\langle E, F  \rangle}$. Thus 
$\s(t_1, \ldots, t_m){\downarrow}_{R\langle E, F  \rangle}= s/_{\Theta\langle E, F  \rangle}$.
Therefore, 
\begin{quote} $\s(t_1, \ldots, t_m)\tred {R\langle E, F  \rangle}
\s(t_1{\downarrow}_{R\langle E, F  \rangle}, \ldots, t_m{\downarrow}_{R\langle E, F  \rangle})= $ (by Proposistion \ref{masodik})\newline
$\s( t_1/_{\Theta\langle E, F  \rangle}, \ldots,  t_m/_{\Theta\langle E, F  \rangle}) \red {R\langle E, F  \rangle} 
 s/_{\Theta\langle E, F  \rangle}$ \hspace{3 mm} (by direct inspection of the form of the rewrite rules of $R\langle E, F  \rangle$).
\end{quote}
By direct inspection of the rewrite rules of $R$, we get that
in the last step of the sequence of reductions we applied the rewrite rule \begin{quote}
  $\s( t_1/_{\Theta\langle E, F  \rangle}, \ldots,  t_m/_{\Theta\langle E, F  \rangle}) \dot{\rightarrow}  s/_{\Theta\langle E, F  \rangle}$
     in $R\langle E, F  \rangle$. \qedhere \end{quote}
\end{proof}






\begin{lem}\label{ezredik} If 
$R\langle E, F  \rangle$  is a total GTRS,  then  for each $s\in \ts$, 
there exists $t \in W $ such that 
$s{\downarrow}_ {R\langle E, F  \rangle}=t/_{\Theta\langle E, F  \rangle}$.
 \end{lem}
 \begin{proof}
 We proceed by induction on
$height(s)$.

{\em Base case:} Let 
$height(s)=0$.
Then $s=\s$ for some $\s\in \S_0$. By our assumption that  $R\langle E, F  \rangle$ is  a total GTES and by Definitions \ref{szabaly}  and \ref{csurig},
there is a rewrite  rule
$\s\dot{\rightarrow}  \s/_{\Theta\langle E, F  \rangle}$ in $R\langle E, F  \rangle$. 
Then $\s\in W $ and $s{\downarrow}_ {R\langle E, F  \rangle} = \s/_{\Theta\langle E, F  \rangle}$.


{\em Induction step:} 
Let   $k\in \Nat$, and let us assume that we have shown the
lemma for all integers less than or equal to $k$. Let $height(s)=k+1$.
Then $s=\s(s_1, \ldots,s_m)$ for some $\s \in \S_m$, $m\geq 1$,  and $s_1, \ldots,s_m\in \ts$.
By the induction hypothesis, for each $i \in \{\, 1, \ldots, m\,\}$, 
 there exist $t_i \in W   $ such that
 $s_i{\downarrow}_ {R\langle E, F  \rangle}= t_i/_{\Theta\langle E, F  \rangle}$.
 By our assumption that  $R\langle E, F  \rangle$  
  is  a total GTRS, there is a rewrite rule 
  with left-hand side     $\s( t_1/_{\Theta\langle E, F  \rangle}, \ldots,  t_m/_{\Theta\langle E, F  \rangle})$ in 
  $R\langle E, F  \rangle$.  
  By Definition \ref{szabaly}, this rule is of the form
  $$\s( t_1/_{\Theta\langle E, F  \rangle}, \ldots,  t_m/_{\Theta\langle E, F  \rangle}) \dot{\rightarrow}  \s(p_1, \ldots, p_m)/_{\Theta\langle E, F  \rangle}$$ 
 in $R\langle E, F  \rangle$ for some $p_i\in t_i/_{\Theta\langle E, F  \rangle}$  for every $i\in \{\, 1, \ldots, m\, \}$. 
 Moreover  $\s(p_1, \ldots, p_m)\in W$.
 Then 
 \begin{quote}
  $s=\s(s_1, \ldots,s_m)\tred {R\langle E, F  \rangle} s( t_1/_{\Theta\langle E, F  \rangle}, \ldots,  t_m/_{\Theta\langle E, F  \rangle})
  \red {R\langle E, F  \rangle}  \s(p_1, \ldots, p_m)/_{\Theta\langle E, F  \rangle}$.
  \end{quote} By direct inspection of  Definition \ref{szabaly}, we get that $ p_{\Theta\langle  E, F \rangle}$ is irreducible for   $R\langle E, F \rangle $.
   Thus 
$s{\downarrow}_ {R\langle E, F  \rangle}=   \s(p_1, \ldots, p_m)/_{\Theta\langle E, F  \rangle}$. \qedhere
\end{proof}


