\section{The Auxiliary  dpwpa  for the GTESs $E$ and $F$}
\label{three-way} 
From now  on  throughout the paper,  $E$ and $F$ are GTESs over a  signature   $\S$, $n=size(E)+size(F)$, and  $W$ stands for
$ST\langle E \cup F\rangle$. 
 We  define the auxiliary dpwpa $ AUX[ E;  F ]=
(C\langle E\cup F, \emptyset \rangle, A[ E;  F] \rangle]$ 
for the GTESs $E$ and $F$.
To simplify our notations, each vertex  of the dpwpa $ AUX [E; F] \rangle$ is a constant  $a\in C\langle E\cup F, \emptyset \rangle$,
i.e, an  equivalence class of  $\Theta\langle E\cup F, \emptyset\rangle$. 
 Furthermore, we study $R\langle {E \cup F}, \emptyset \rangle$ reachability of a constant  $a\in C\langle E\cup F,  \emptyset \rangle$
   from    a proper extension    of a constant  $b\in C\langle E\cup F,  \emptyset \rangle$.

 \begin{df}\label{mimika}\rm  Let
 $E$ and $F$ be  GTESs over  a signature $\Sigma$. 
 Then  let \begin{quote} $INC( E\cup F, E) = \{\, (a, b) \mid a\in C \langle E \cup F, \emptyset \rangle,  b\in C\langle E, F\rangle,
  \mbox{  and } b\subseteq a \, \}$,  \newline
   $NUM(  E\cup F, E) = \{\, (a, k) \mid a\in C \langle E \cup F, \emptyset \rangle, k=|\{ b\in C\langle E, F\rangle \mid 
   b\subseteq a\, \}| \, \}$,  \newline
   $INC( E\cup F, F) = \{\, (a, b) \mid a\in C\langle E \cup F, \emptyset\rangle, b\in C \langle F, E \rangle \mbox{  and } b\subseteq a \, \}$, and \newline
  $NUM( E\cup F, F) = \{\, (a, k) \mid a\in C \langle E \cup F, \emptyset \rangle, k=|\{ b\in C\langle F, E\rangle\mid 
  b\subseteq a\, \}| \, \}$.
 \end{quote}
 \end{df}
 Intuitively, $INC( E\cup F, E)$ shows the inclusions between the elements of $C \langle E \cup F, \emptyset \rangle$ and $C\langle E, F\rangle$. 
 $NUM( E\cup F, E)$ consists of all pairs $(a, k)$, where the second component $k$ is the number of all pairs 
 in $INC( E\cup F, E)$, with first component $a$.

 \begin{sta} \label{csorvas} Let
 $E$ and $F$ be  GTESs over  a signature $\Sigma$. Then 
 $|INC( E\cup F, E)|\leq n $ and $|INC( E\cup F, F)|\leq n $. 
 \end{sta}
 \begin{proof}
 By Statement \ref{darabsz}, $|C\langle E, F  \rangle|\leq n$. For each $b\in C \langle E, F \rangle $, there exists at most one
 $ a\in C \langle E \cup F, \emptyset \rangle $ such that $ (a, b) \in INC( E\cup F, E)  $.
Therefore,   $|INC( E\cup F, E)|\leq |C\langle E, F  \rangle|\leq n $. 

We can show similarly that  $|INC( E\cup F, F)|\leq |C\langle F, E  \rangle|\leq n $. 
\end{proof}




 \begin{sta}\label{dan}
 1.  For every $ a\in C \langle E \cup F, \emptyset \rangle $,  there exists a unique ordered pair $ (a, b) \in INC( E\cup F, E) $
 if and only if  $ a\in C \langle E, F \rangle $. Similarly, for every $ a\in C \langle E \cup F, \emptyset \rangle $,  there exists a unique ordered pair $ (a, b) \in 
 INC( E\cup F, F) $
 if and only if  $ a\in C \langle F, E \rangle $. 

 2. For every $ a\in C \langle E \cup F, \emptyset \rangle $,  there exists a unique ordered pair $ (a, k) \in NUM (E\cup F, E) $. Here  $k=1$
 if and only if  $ a\in C \langle E, F \rangle $. Similarly, for every $ a\in C \langle E \cup F, \emptyset \rangle $,  there exists a unique ordered pair $ (a, \ell) \in 
 NUM (E\cup F, F) $. Here  $\ell=1$ 
 if and only if  $ a\in C \langle F, E \rangle $. 

 \end{sta}
 \begin{proof} By direct inspection of Definition \ref{mimika}
 \end{proof}

 \begin{df}\label{lepesttart} Let
 $E$ and $F$ be  GTESs over  a signature $\Sigma$, and  $a\in C\langle E\cup F, \emptyset\rangle$. 
     We say that GTRS $R\langle E, F \rangle$  keeps up with the  GTRS 
$R\langle E\cup F, \emptyset \rangle$ writing the constant  $a\in C\langle E\cup F, \emptyset\rangle$ if 
\begin{quote}
for every rewrite rule  of the form 
 $\s(a_1, \ldots, a_m) \dot{\rightarrow} a\in  R\langle {E \cup F}, \emptyset \rangle$ with $m\in \Nat$, \newline
 for every  $b_1, \ldots, b_m \in C\langle E, F\rangle$ with $b_i \subseteq  a_i$
 for every $i\in \{\, 1, \ldots, m\, \}$,  \newline
  there exists a rewrite rule in $ R\langle E, F\rangle$ of the form 
 $\s(b_1, \ldots, b_m )\dot{\rightarrow} b $ for some $b\in C\langle E, F\rangle$.\end{quote} 
 \end{df}
 Note that  for the constant $b\in C\langle E, F\rangle$ appearing in the definition above, we have  
   $b \subseteq a$. 
Definition \ref{lepesttart} also defines the notion that GTRS $R\langle F, E \rangle$  keeps up with the  GTRS 
$R\langle E\cup F, \emptyset \rangle$ writing the constant  $a\in C\langle E\cup F, \emptyset\rangle$.




\begin{df}\label{inaskodik}\rm  Let 
 $E$ and $F$ be  GTESs over  a signature  $\Sigma$. 
The auxiliary dpw
for the GTESs $E$ and $F$  is  $ AUX  [ E;  F] = (C\langle E\cup F, \emptyset\rangle,  A[E; F])$, where 
$ A[E; F]=BSTEP\langle E\cup F, \emptyset \rangle$.
      We assign the attributes 
      \begin{quote} $equal_E,\; equal_F,\;  keeps_E, \;  keeps_F, \;       
       visited\_outer\_loop, \;
      visited\_inner\_loop_E, \;
      visited\_inner\_loop_F, \; and \;
      visited: \mathrm{Boolean}$ 
      \end{quote} to the  vertices of $C\langle E\cup F, \emptyset \rangle$.  
     Furthermore, we  assign the satellite data
      $ counter_E, counter_F:  \Nat$
      to the rewrite rules of $ R \langle E\cup F, \emptyset \rangle$.      
 \end{df}



  For each vertex  $a\in $,  our  decision algorithm computes the values of the above attributes such that the following conditions hold:  
  \begin{itemize}
\item [1.] $  a.equal_E=\mathrm{true}$ if and only if 
$  a \in C\langle E, F\rangle$. 
\item [2.] $  a.equal_F=\mathrm{true}$ if and only if 
$  a \in C\langle F, E\rangle$. 
\item [3.] $  a .keeps_E= \mathrm{true}$ if and only if  $ R \langle E, F \rangle$   keeps up with  $ R \langle E\cup F, \emptyset \rangle$ writing $a $.
\item [4.] $  a .keeps_F= \mathrm{true}$ if and only if  $ R \langle F, E \rangle$   keeps up with  $ R \langle E\cup F, \emptyset \rangle$ writing $a $.
\end{itemize}
Recall  that for each vertex $a\in C\langle E \cup F, \emptyset\rangle $, 
list $Adj(a)$  consists of all  vertices  $  b\in C\langle E \cup F, \emptyset\rangle $ such that  there
exists a rewrite rule $\s(a_1, \ldots, a_m)\dot{\rightarrow} a$ in $ R \langle E \cup  F, \emptyset\rangle$ with $\s\in \S_m$, $m\geq 1$, and $b=a_i$ for some $i\in \{\, 1, \ldots, m \, \}$.

\begin{sta}\label{iszap} Let 
 $E$ and $F$ be  GTESs over a signature   $\Sigma$. Then 
  $|A[E; F]|\leq n$.
 \end{sta}
 \begin{proof} 
 By Definition \ref{inaskodik}, Statement \ref{drrszam},  we have 
 $|A[E; F]|=
 |BSTEP\langle E\cup F, \emptyset \rangle| \leq n$.
 \end{proof}







Intuitively if  $ R \langle E\cup F, \emptyset \rangle$ 
 reach a constant  $a\in C\langle E\cup F,  \emptyset \rangle$ from   a proper extension   of a constant    $b\in C\langle E\cup F,  \emptyset \rangle$,
then there exists a  $1$-context 
 $\zeta$  over $\S$ such that 
such that \begin{itemize}
\item $\zeta\neq \diamondsuit$,
\item $ R \langle E\cup F, \emptyset \rangle$ reach  $a$ from  $\zeta[b]$, and 
\item  $ R \langle E\cup F, \emptyset \rangle$  reduces the subterms of $\zeta[b]$ at different  prefixes of $\mathrm{addr}(\zeta)$ -- except possibly for the pair  
   of $\varepsilon$ and   $\mathrm{addr}(\zeta)$ --
  to different constants in  $ C\langle E\cup F,  \emptyset \rangle$.
   \end{itemize}
  Thus the length of  $\mathrm{addr}(\zeta)$ is less than equal to  $|C\langle E\cup F, \emptyset \rangle| $.
 \begin{lem} \label{kokusz}  Let 
  $E$ and $F$  be  GTESs over a  signature   $\S$.
 Let 
  $ R \langle E\cup F, \emptyset \rangle$ reach a constant  $a\in C\langle E\cup F,  \emptyset \rangle$ from a proper extension  of a constant   $b\in C\langle E\cup F,  \emptyset \rangle$. 
          Then  there exists a $1$-context $\zeta$ over $\Sigma$, where
   \begin{itemize}
   \item [{\rm (a)}] $\zeta\neq \diamondsuit$,
      \item  [{\rm (b)}] $k\geq 1$ denotes   $\mathrm{length}(\mathrm{addr}(\zeta) )$, 
  \item [{\rm (c)}]
  for every $i\in\{\, 0, \ldots, k\,\}$,   $\alpha_i$ denotes  the prefix of $\mathrm{addr}(\zeta) $ of length $i$ 
  \end{itemize}   such that  
    \begin{itemize}
       \item  [{\rm (d)}] $\zeta[b]{\downarrow}_ {R\langle E\cup F, \emptyset \rangle} =a$,
       \item  [{\rm (e)}] $\zeta[b]|_{\alpha_i }  {\downarrow}_ {R\langle E\cup F, \emptyset \rangle} \neq \zeta[b]|_{\alpha_j } {\downarrow}_ {R\langle E\cup F, \emptyset \rangle}$  for any  $0\leq i < j \leq k$ such that 
   $1\leq i $ or $  j \leq k-1$,
      and 
  \item  [{\rm (f)}] $k \leq |C\langle E\cup F, \emptyset \rangle |$.
    \end{itemize}        
 \end{lem} 
 \begin{proof}  
  Intuitively, the basic idea of the proof  is similar to that of the pumping lemma for regular languages \cite{sipser2006},  
 context-free languages  \cite{sipser2006}, and regular tree languages  \cite{gs}, \cite{eng2}.  The main difference from the proof of the pumping lemma is that we iterate contracting the ground term rather than pumping it.
  We stop when we get such a  small ground term that  we cannot contract it any more.   

  It is sufficient to prove that there exists a $1$-context $\zeta$ over $\Sigma$ such that  
Conditions (a)--(e) hold. Because for any  $1$-context $\zeta$ over $\Sigma$ satisfying Conditions (a)--(e),  Condition (f) holds as well.
 By Statement \ref{olvaseler}, 
     there exists a $1$-context $\delta$ over $\Sigma$ such that $\delta\neq\diamondsuit$ and $\delta[b]{\downarrow}_ {R\langle E\cup F, \emptyset \rangle} =a$, i.e. 
     Conditions (a)--(d) hold for $\zeta=\delta $.
    We now distinguish two cases:

 {\em Case 1:}    
 Conditions  (e)  holds for $\zeta=\delta $. Then we are done. 


    {\em Case 2:} Condition (e) does not hold for $\zeta=\delta $. 
    For every $i\in\{\, 0, \ldots, n\,\}$,   let $\beta_i$ denote the prefix of $\mathrm{addr}(\delta) $ of length $i$.
 There exist $i, j \in \{\, 0, \ldots, k \, \}$ 
  such that  
 \begin{quote}
 $\left(0\leq i < j \leq k-1  \mbox{ or } 1\leq i < j \leq k\right)$ and 
   $\zeta[b]|_{\beta_i }  {\downarrow}_ {R\langle E\cup F, \emptyset \rangle} = \zeta[b]|_{\beta_j } {\downarrow}_ {R\langle E\cup F, \emptyset \rangle}$.
 \end{quote}  
        We define  $\delta'\in CON_{\Sigma, 1}$  from  $\delta$  by replacing  the subterm $ \delta|_{\beta_i}$ at $\beta_i$ by the subterm   $\delta|_{\beta_j}$
   at $\beta_j$.  Then 
     \begin{quote}
     $\delta'\neq \diamondsuit$, 
    $\mathrm{length}(\mathrm{addr}(\delta')) < \mathrm{length}(\mathrm{addr}(\delta))$,  and 
     $\delta'[b]{\downarrow}_ {R\langle E\cup F, \emptyset \rangle} =a$ i.e.   Conditions (a)--(d) hold for $\zeta=\delta' $.
      \end{quote}
  We now distinguish two cases:



    {\em Case 2.1:} Condition (e) holds for $\zeta=\delta'$. Then Conditions (a)--(e) hold for $\zeta=\delta'$. In this case we are done.



    {\em Case 2.2:}  Condition (e) does  not hold for $\zeta=\delta'$. In this case we let $\delta =\delta'$ and repeat the procedure of contracting $\delta$  described above
    finitely many times until Condition (e) holds for $\zeta=\delta'$.  Then Conditions (a)--(e) hold for $\zeta=\delta'$. 
 \end{proof}
 Intuitively, 
 we now consider two constants, $a$ and $b$ in $C\langle E\cup F, \emptyset\rangle$   and a sequence of rewrite rules in  $R\langle {E \cup F}, \emptyset \rangle$
 of which consecutive applications leads  us from  $b$  to 
 $a$.
   Let $a, b \in C\langle E\cup F, \emptyset \rangle$, $k\geq 1$,  and
  for each $j=1, \ldots, k$, let 
  \begin{itemize}
 \item  $\s_j(a_{j1}, \ldots, a_{jm_j}) \dot{\rightarrow} a_j\in  R\langle {E \cup F}, \emptyset \rangle$, $m_j\geq 1$, 
  be a rewrite rule and 
\item  $i_j \in \{\, 1, \ldots, m_j\, \}$ be an integer 
 \end{itemize}
 such that \begin{itemize}
 \item $b= a_{1i_1}$, 
 \item 
for each $j=1, \ldots, k-1$, $a_j= a_{(j+1)i_{j+1}}$, and 
 \item 
 $a=a_k$.
 \end{itemize}
The above  sequence of rewrite rules  is connected in the sense that   we can apply them one after another, the right-hand side of each rule appears on the left-hand side of the next rule.
  Furthermore,  the consecutive applications of these rewrite rules leads us from the constant  $b$  to the constant
 $a$ since  $b$ appears on the left-hand side of the first rule, and $a$ is the right-hand side of the last rule.
 We can apply the above rewrite rules one after another in the following way: 
  \newline $b$ appears in the left-hand side of the first rewrite rule, 
   \newline
   we apply the first rewrite rule to its left-hand side, $\s_1(a_{11}, \ldots, a_{1m_1}) $, we get the right-hand side $a_1$, 
    which appears on  the left-hand side of the second rewrite rule, \newline we apply the second  rewrite rule to its left-hand side, $\s_2(a_{21}, \ldots, a_{2m_2}) $, we get the right-hand side $a_2$,
    which appears on  the left-hand side of the third rewrite rule, \newline we apply the third rewrite rule to its left-hand side, $\s_3(a_{31}, \ldots, a_{3m_3}) $, we get the right-hand side $a_3$, 
     which appears on the left-hand side of the fourth  rewrite rule, and son on.\newline
   Finally, the right-hand side $a_{k-1}$ of the last but one rewrite rule appears in the left-hand side of the last rewrite rule,  \newline
   we apply the last rewrite rule to 
    its left-hand side, $\s_k(a_{k1}, \ldots, a_{km_k}) $, we get its right-hand side $a_k=a$.

  We now state formally and show the following intuitive statement: if   $ R \langle E\cup F, \emptyset \rangle$ reach a constant  $a\in C\langle E\cup F,  \emptyset \rangle$ from   a proper extension   of a  constant    $b\in C\langle E\cup F,  \emptyset \rangle$, then 
  there exists a connected sequence of   rewrite rules in  $ R \langle E\cup F, \emptyset \rangle$ that  leads us from  the constant $b$  to the constant $a$.
   Moreover, $b$ and the 
  intermediate 
  constants between $b$ and $a$, appearing as the right-hand sides  of the applied rewrite rules except for  the last one, are pairwise different. 
  \begin{lem} \label{banan} 
   Let 
  $E$ and $F$  be  GTESs over a  signature   $\S$.
  Let 
  $ R \langle E\cup F, \emptyset \rangle$ reach a constant  $a\in C\langle E\cup F, \emptyset \rangle$ from   a proper extension   of a constant    $b\in C\langle E\cup F,  \emptyset \rangle$. 
          Then there exists an integer     $1\leq  k \leq |C\langle E\cup F, \emptyset \rangle |$ and 
    for each $j=1, \ldots, k$, there exists  a rewrite rule 
 $\s_j(a_{j1}, \ldots, a_{jm_j}) \dot{\rightarrow} a_j\in  R\langle {E \cup F}, \emptyset  \rangle$, $m_j\geq 1$, and an integer $i_j \in \{\, 1, \ldots, m_j\, \}$ 
 such that 
  \begin{itemize}
 \item $b= a_{1i_1}$, 
  \item 
for each $j=1, \ldots, k-1$,  $a_j= a_{(j+1)i_{j+1}}$, 
  \item $b \not\in \{\, a_1, \ldots, a_{k-1}\, \}$ and 
  for any  $ 1 \leq  i < j \leq  k-1$,  $a_i \neq a_j$, 
 and 
 \item 
 $a=a_k$.
 \end{itemize}
  \end{lem} 
 \begin{proof}
 By Lemma \ref{kokusz},
 there exists a $1$-context $\zeta$ over $\Sigma$, where
   \begin{itemize}
   \item  [{\rm (a)}] $\zeta\neq \diamondsuit$, 
      \item  [{\rm (b)}] $k\geq 1$ denotes   $\mathrm{length}(\mathrm{addr}(\zeta) )$, 
  \item  [{\rm (c)}]
  for every $i\in\{\, 0, \ldots, k\,\}$,   $\alpha_i$ denotes  the prefix of $\mathrm{addr}(\zeta) $ of length $i$ 
  \end{itemize}   such that 
   \begin{itemize}
       \item  [{\rm (d)}] $\zeta[b]{\downarrow}_ {R\langle E\cup F, \emptyset \rangle} =a$,
       \item  [{\rm (e)}] $\zeta[b]|_{\alpha_i }  {\downarrow}_ {R\langle E\cup F, \emptyset \rangle} \neq \zeta[b]|_{\alpha_j } {\downarrow}_ {R\langle E\cup F, \emptyset \rangle}$  for any  $0\leq i < j \leq k$ such that 
   $1\leq i $ or $  j \leq k-1$,
      and 
  \item  [{\rm (f)}] $k \leq |C\langle E\cup F, \emptyset \rangle |$.
    \end{itemize} 
    As $\mathrm{addr}(\xi)=\alpha_k$, we have $\xi[b]|_{\alpha_k} =b$.
   \begin{quote}  For each $i\in \{1, \ldots, k-1\, \}$, let 
  $a_i=\zeta[b]|_{\alpha_i }  {\downarrow}_ {R\langle E\cup F, \emptyset \rangle} $. 
  \end{quote} 
  Since 
  $b=\zeta[b]|_{\alpha_k }  {\downarrow}_ {R\langle E\cup F, \emptyset \rangle} $,   
   by Condition (e) 
 we have  \begin{quote}   $b \not\in \{\, a_1, \ldots, a_{k-1}\, \}$ and 
  for any  $ 1 \leq  i < j \leq  k-1$,  $a_i \neq a_j$.
    \end{quote} 
     Then consider a sequence of  $ R\langle {E \cup F}, \emptyset \rangle$   reductions, where we indicate the rewrite rules applied at the positions 
     $\alpha_{k-1}$, $\alpha_{k-2}$, $\ldots$, $\alpha_0$:
  \begin{quote}
$\zeta[b]=t_0 \tred {  R\langle {E \cup F}, \emptyset \rangle} s_1     \red {[ \alpha_{k-1}, \s_1(a_{11}, \ldots, a_{1m_1}) \dot{\rightarrow} a_1]}t_1 
  \tred {  R\langle {E \cup F}, \emptyset \rangle} s_2 \red {[ \alpha_{k-2}, \s_2(a_{21}, \ldots, a_{2m_2}) \dot{\rightarrow} a_2]}
  t_2 \tred {  R\langle {E \cup F}, \emptyset \rangle} \newline
  \cdots
      \red {[ \alpha_1, \s_{k-1}(a_{(k-1)1}, \ldots, a_{(k-1)m_1}) \dot{\rightarrow} a_{k-1}]}t_{k-1} 
   \tred {  R\langle {E \cup F}, \emptyset \rangle} s_k \red {[ \alpha_0, \s_k(a_{k1}, \ldots, a_{km_k}) \dot{\rightarrow} a_k ]} a_k=  a $.
\end{quote}
Here
 \begin{itemize}
 \item $s_i\in T_{\Sigma \cup C\langle E\cup F, \emptyset \rangle }  $ for every $i\in \{1, \ldots, k\, \}$, and $t_i \in 
  T_{\Sigma \cup C\langle E\cup F, \emptyset \rangle} $ for every $i\in \{0, \ldots, k-1\, \}$,
 \item for each $i\in \{1, \ldots, k\, \}$,
  $a_i=\zeta[b]|_{\alpha_{k-i }}  {\downarrow}_ {R\langle E\cup F, \emptyset \rangle} $, 

 \item $b= a_{1i_1}$ for some  $i_1\in \{\, 1, \ldots, m_1 \, \}$, 
      \item for each $j\in \{1, \ldots, k\, \}$,
   $\s_j(a_{j1}, \ldots, a_{jm_j}) \dot{\rightarrow} a_j\in  R\langle {E \cup F}, \emptyset \rangle$, $m_j\geq 1$,  

 \item 
 for each $j=1, \ldots, k-1$, there exists  $i_{j+1}\in \{\, 1, \ldots, m_{j+1} \, \}$ such that 
 $a_j= a_{(j+1)i_{j+1}}$, and

 \item 
 $a=a_k$. \qedhere
   \end{itemize} 
 \end{proof} 

 \begin{lem}\label{napsutes} Let 
  $E$ and $F$  be  GTESs over a  signature   $\S$.
 If  $ R \langle E\cup F, \emptyset \rangle$ 
 reach a constant  $a\in C\langle E\cup F,  \emptyset \rangle$ from   a proper extension   of a constant    $b\in C\langle E\cup F,  \emptyset \rangle$, then there exists 
  a path of positive length or a cycle   from    the vertex $a$ to the vertex $b$  in the auxiliary dpwpa   
$ AUX[ E;  F] =
(C\langle E \cup F, \emptyset\rangle,A[E; F])$.
    \end{lem}
    \begin{proof}
    We have the lemma by Lemma \ref{banan},  Statement  \ref{olvaseler},     
     and by the definition of $A[E; F]$ in Definition \ref{inaskodik}. 
        \end{proof}


 We now show the converse of Lemma \ref{napsutes}. 
Intuitively,  
  if there exists a connected sequence of  rewrite rules in  $ R \langle E\cup F, \emptyset \rangle$ 
  that leads us from a constant $b\in C\langle E\cup F,  \emptyset \rangle$  to a constant $a\in C\langle E\cup F,  \emptyset \rangle$,
 then   $ R \langle E\cup F, \emptyset \rangle$ reach the  constant  $a$  from a proper extension of the constant  $b$.  


 \begin{lem}\label{millio} Let 
  $E$ and $F$  be  GTESs over a  signature   $\S$.
 Let 
 $\s(a_1, \ldots, a_m) \dot{\rightarrow} a\in  R\langle {E \cup F}, \emptyset \rangle$
 be a rewrite rule, where $m\geq 1$, $a_1, \ldots, a_m, a\in C\langle E \cup F, \emptyset\rangle$. Let $i\in \{\, 1, \ldots, m\, \}$.
 Then there exist ground terms $s_1, \ldots, s_{i-1}, s_{i+1}, \ldots, s_m\in \ts$ such that 
 \begin{quote}
   $\s(s_1, \ldots, s_{i-1},a_i,  s_{i+1}, \ldots, s_m )\tred {R\langle E \cup F, \emptyset\rangle}\s(a_1, \ldots, a_m) \red {R\langle E \cup F, \emptyset\rangle} a$.
   \end{quote}
   \end{lem}
 \begin{proof} By Definition \ref{szeder}, Definition \ref{szabaly},  and Proposition \ref{masodik} we have the lemma.
 \end{proof}



 \begin{lem}\label{trillio}  Let 
  $E$ and $F$  be  GTESs over a  signature   $\S$.
 Let   $k\geq 1$,   and 
  $(a_k, a_{k-1}), \, (a_{k-1}, a_{k-2}),\,  \ldots , \, (a_1, a_0) \in A[E; F]$. 
  Then there exists a $1$-context $\delta$ over $\Sigma$ such that  $\delta\neq \diamondsuit$  and 
  $\delta[a_0]\tred {R\langle E\cup F, \emptyset\rangle} a_k$.
     \end{lem}
 \begin{proof} By Definition \ref{inaskodik} and Definition \ref{zug}, 
  for each $j=1, \ldots, k$, there exists a rewrite rule 
 $\s_j(a_{j1}, \ldots, a_{jm_j}) \dot{\rightarrow} a_j\in  R\langle {E \cup F}, \emptyset \rangle$, $m_j\geq 1$, 
 such that 
 \begin{quote}$a_0\in \{\, a_{11}, \ldots, a_{1m_1} \, \}$ and 
for each $j=1, \ldots, k-1$, there exists  $i_{j+1}\in \{\, 1, \ldots, m_{j+1} \, \}$ such that 
 $a_j= a_{(j+1)i_{j+1}}$. \end{quote} 
 We proceed by induction on $k$.

   {\em Base case:} $k=1$. By Lemma \ref{millio}, we are done.  

 {\em Induction Step:}  Let $k\geq 1$, and  assume that the statement of the lemma is true for $k$. We now show that it is true for $k+1$.
 By the induction hypothesis, 
  there exists a $1$-context $\delta$ over $\Sigma$ such that  
   \begin{quote}
  $\delta\neq \diamondsuit$  and $\delta[a_0]\tred {R\langle E \cup F, \emptyset\rangle} a_k$. 
\end{quote}
By Lemma \ref{millio},  there exist ground terms $s_1, \ldots, s_{i-1}, s_{i+1}, \ldots,  s_{m_{k+1}}\in \ts$ such that 
\begin{quote}
$\s_{k+1}(s_1, \ldots, s_{i_{k+1} -1},  a_k, s_{i_{k+1} +1}, \ldots, s_{m_{k+1}})= 
\s_{k+1}(s_1, \ldots, s_{i_{k+1} -1},   a_{(k+1)i_{k+1} }, s_{i_{k+1} +1}, \ldots, s_{m_{k+1}})
\tred {R\langle E\cup F, \emptyset\rangle}
\newline 
 \s_{k+1}(a_{(k+1)1},  \ldots, a_{(k+1)i_{k+1} -1},   a_{(k+1)i_{k+1} }, a_{(k+1)i_{k+1} +1}, \ldots , a_{(k+1)m_{k+1}})
\red {R\langle E\cup F, \emptyset\rangle}a_{k+1}$.
\end{quote}
Thence we have 
 \begin{quote}
$\s_{k+1}(s_1, \ldots, s_{i_{k+1} -1},  \delta[a_0], s_{i_{k+1} +1}, \ldots, s_{m_{k+1}})\tred {R\langle E\cup F, \emptyset\rangle} 
\s_{k+1}(s_1, \ldots, s_{i_{k+1} -1},  a_k, s_{i_{k+1} +1}, \ldots, s_{m_{k+1}})= \newline
\s_{k+1}(s_1, \ldots, s_{i_{k+1} -1},   a_{(k+1)i_{k+1} }, s_{i_{k+1} +1}, \ldots, s_{m_{k+1}})
\tred {R\langle E\cup F, \emptyset\rangle}\newline
\s_{k+1}(a_{(k+1)1}, \ldots, a_{ (k+1) i_{k+1} -1},   a_{(k+1)i_{k+1} }, a_{(k+1) i_{k+1} +1}, \ldots,  a_{(k+1)m_{k+1}})
\red {R\langle E\cup F, \emptyset\rangle}
 a_{k+1}$. \qedhere
\end{quote}
 \end{proof}




 \begin{lem}\label{napkelte}  Let 
  $E$ and $F$  be  GTESs over a  signature   $\S$.
  If there exists 
  a path of positive length or a cycle   from   a vertex $a$ to a vertex $b$  in the auxiliary dpwpa   
$ AUX[ E;  F] =
(C\langle E \cup F, \emptyset\rangle,A[E; F])$, then 
 $ R \langle E\cup F, \emptyset \rangle$ 
 reach the constant  $a\in C\langle E\cup F,  \emptyset \rangle$ from a proper extension of the constant  $b\in C\langle E\cup F,  \emptyset \rangle$.
     \end{lem}
    \begin{proof}
    We have the lemma
by    Lemma \ref{trillio}. 
    \end{proof}



\begin{lem}\label{rozmaring} Let
 $E$ and $F$ be  GTESs over  a signature $\Sigma$.
  $ R \langle E\cup F, \emptyset \rangle$ reach a constant $a\in C\langle E\cup F, \emptyset \rangle$ from   a proper extension   of a constant    $b\in C\langle E\cup F,   \emptyset \rangle$
     if and only if there is a path of positive length or a cycle   from  
  the vertex $a$ to the vertex $b$
 in the auxiliary dpwpa   
$ AUX[ E;  F] =
(C\langle E \cup F, \emptyset\rangle, A[E; F])$.

 \end{lem}
 \begin{proof} 
 By Lemma \ref{napsutes} and Lemma \ref{napkelte}, we  have the lemma. 
  \end{proof}













