 \section{Constructing the Auxiliary  dpwpa  for the GTESs $E$ and $F$}\label{epit}

We construct the  sets and relations and dpwpa, which we introduced in Section \ref{three-way}  and our decision procedure needs. 

We define a mapping $ counter_E: R \langle E \cup F, \emptyset\rangle \rightarrow \Nat$, 
to each rewrite rule $\s(a_1, \ldots, a_m) \dot{\rightarrow} a$, $m\in \Nat$, 
in $ R \langle E \cup  F,  \emptyset \rangle$, we assign the  number of rules $\s(b_1, \ldots, b_m) \dot{\rightarrow} b$ in $ R \langle  E, F\rangle $,
where
$b_i \subseteq  a_i$ for every  $i\in \{\, 1, \ldots, m\, \}$.
 In pseudocode we treat the nonnegative integer $counter_E(\s(a_1, \ldots, a_m) \dot{\rightarrow} a)   $ as  satellite data 
 of   the rewrite rule
 $\s(a_1, \ldots, a_m) \dot{\rightarrow} a$, and denote it as  
 $\s(a_1, \ldots, a_m) \dot{\rightarrow} a.counter_E$. In this way, we store the mapping  $counter_E$.
    We define the  mapping $ counter_F: R \langle E \cup  F, \emptyset \rangle \rightarrow \Nat$ and treat $counter_F(\s(a_1, \ldots, a_m) \dot{\rightarrow} a)   $  in a similar way.  


\begin{df}\label{augbarack}\rm 
Algorithm Constructing Auxiliary   dpwpa $ AUX[ E;  F] $
(CAD for short)\newline 
Input: 
 A signature $ \Sigma$  and  GTESs $E$ and $F$ over $\S$.
\newline 
Output:
\begin{itemize}
\item the relations  $\rho\langle E, F\rangle$, $\rho\langle F, E\rangle$,  and $\rho\langle E\cup F, \emptyset\rangle$;
\item the  set of nullary symbols  $C\langle E, F\rangle$, $C\langle F, E\rangle$, and
$C\langle E \cup F, \emptyset\rangle$;
\item  $INC( E\cup F, E)$ stored  without duplicates in a red-black tree saved in a  variable  $RBT1$,
 for every ordered pair$(a, b)\in INC\langle E\cup F, E \rangle$, the search key is the first component $a$, the second component, $b$ is  satellite data;
\item  $INC(E\cup F, F)$ stored in a red-black tree  saved   without duplicates in a  variable    $RBT2$,
for every ordered pair$(a, b)\in INC( E\cup F, F)$, the search key is the first component $a$, the second component, $b$ is  satellite data;
\item $NUM(  E\cup F, E)$ stored in a red-black tree  saved   without duplicates in a  variable    $RBT3$,
for every ordered pair$(a, k)\in NUM(E\cup F, E )$, the search key is the first component $a$, the second component, $k$ is  satellite data;
\item $NUM( E\cup F, F)$ stored in a red-black tree  saved   without duplicates in a  variable    $RBT4$
for every ordered pair$(a, k)\in NUM(E\cup F, F )$, the search key is the first component $a$, the second component, $k$ is  satellite data;
\item the GTRS $R\langle E\cup F, \emptyset\rangle$  stored in a red-black tree saved   without duplicates in a  variable  $RBT5$;
 each node  in  $RBT5$ contains a serach key which is  a rule in $R\langle E\cup F, \emptyset\rangle$, and satellite data $counter_E$ and $counter_F$;
\item $BSTEP\langle E\cup F, \emptyset \rangle$ stored in a red-black tree saved   without duplicates in a  variable   $RBT6$; 
for every ordered pair$(a, b)\in BSTEP\langle E\cup F, \emptyset \rangle$, the search key is the first component $a$, the second component, $b$ is  satellite data;
 \item the GTRS $R\langle E, F\rangle$ stored in a red-black tree saved   without duplicates in a  variable  $RBT7$;
  \item the GTRS $R\langle  F, E\rangle$ stored in a red-black tree  saved   without duplicates in a  variable   $RBT8$; 
 \item 
the auxiliary dpwpa $ AUX[ E;  F] =
(C\langle E\cup F, \emptyset \rangle, A[E; F])$ for the GTESs $E$ and $F$, and 
   for every vertex $a\in C\langle E \cup  F,  \emptyset \rangle$,
the values of  the  attributes $a.equal_E$, $a.equal_F$, $a.keeps_E$, and $a.keeps_F$;
\end{itemize} 
\begin{quote} {\bf var} $i$, $m$: integer;  $\s$:  symbol in $\Sigma$; \newline
$a, a_1, \ldots, a_{mar_{\Sigma}}: C \langle E \cup F, \emptyset \rangle$;\;
$b, b_1,  \ldots, b_ {mar_{\Sigma}}:C \langle E, F \rangle$; \;
$c, c_1,  \ldots, c_{mar_{\Sigma}}:C \langle F, E \rangle$; \newline
$RBT1$, $RBT2$, $RBT3$, $RBT4$, $RBT6$, $RBT5$, $RBT7$, $RBT8$: red-black trees.
\end{quote}
