\section{Preparatory  Results}\label{preparatory}
 The  decidability and complexity results of the following sections require some preparatory results which we group together here. 
\begin{prop} \label{valodi}
    Let $A$ be a set, $a\in A$, and let $\rho,\tau, \omega$ be 
equivalence relations on $A$ such that  $ a/_\rho \subset  a/_\omega$ and
$ a/_\tau \subset  a/_\omega$. Then $ a/_\rho \cup  a/_\tau\subset  a/_\omega$.
    \end{prop}
  \begin{proof} There exist $b, c\in A$, such that $b\in  a/_\omega \setminus  a/_\rho $ and
  $c\in  a/_\omega \setminus  a/_\tau $. 
  We now distinguish three cases.

  {\em Case 1: }
  $(b, c )\in \rho $. Then  by the definition of $b$, $(a, c)\not \in \rho$. By the definition of $c$, $(a, c)\not \in \tau$. Thence
  $(a, c)\not \in \rho\cup \tau$.

  {\em Case 2: }
  $(b, c )\in \tau $. Then by the definition of $c$,
  $(a, b)\not \in \tau$.  By the definition of $b$, $(a, b)\not \in \rho$. Consequently
  $(a, b)\not \in \rho\cup \tau$.

   {\em Case 3: }
   $(b, c )\not \in \rho \cup \tau$. Then by the definition of $b$ and $c$,
   $(b, c )\in  \omega$, and hence 
   $(b, c )\in  \omega \setminus (\rho \cup \tau)$.

 In all  three cases we have  $ a/_\rho \cup  a/_\tau\subset  a/_\omega$.
  \end{proof}

\begin{prop} \label{kovetkezmeny}
    Let $A$ be a set, $a\in A$, and let $\rho,\tau, \omega$ be 
    equivalence relations on $A$ such that
$ a/_\rho \cup  a/_\tau=   a/_\omega$. Then 
    $ a/_\rho =  a/_\omega$ or $ a/_\tau =  a/_\omega$. 
    \end{prop}
\begin{proof} By contradiction, assume that $ a/_\rho \neq   a/_\omega$ and  $ a/_\tau \neq  a/_\omega$.
Then   $ a/_\rho \subset  a/_\omega$ and
$ a/_\tau \subset  a/_\omega$. Consequently, by Proposition \ref{valodi}, 
$ a/_\rho \cup  a/_\tau\subset  a/_\omega$.
\end{proof}
\begin{lem} \label{teljes}  Let 
  $E$ and $F$  be  GTESs over a  signature   $\S$.
If 
GTRS $R\langle E, F\rangle$ is total, then $R\langle E\cup F, \emptyset\rangle$ 
is total as well.
\end{lem}
\begin{proof}
Let $\s\in \Sigma_m$, $m\in \Nat$, and $a_1, \ldots, a_m\in  C\langle E\cup F, \emptyset\rangle$. Then there exist $ t_1, \ldots, t_m \in W$ such that
for every $i \in \{\, 1, \ldots, m\, \}$, $t_i/_ {\Theta\langle E\cup F ,  \emptyset \rangle}=a_i$. 
As GTRS $R\langle E, F\rangle$ is total, there exists a rewrite rule 
$\s(t_1/_  {\Theta\langle E, F \rangle},  \ldots, t_m/_  {\Theta\langle E, F \rangle}) \dot{\rightarrow} t/_  {\Theta\langle E, F \rangle}$ in $R\langle E, F\rangle$. Accordingly, by the definition of $R\langle E, F\rangle$,
 $\s(t_1, \ldots, t_m)\in W$ and  
$\s(t_1, \ldots, t_m)\tthue E t$. Then $\s(t_1, \ldots, t_m)\tthue {E\cup F}  t$. 
For every $i \in \{\, 1, \ldots, m\, \}$, 
$t_i/_  {\Theta\langle E\cup F, \emptyset \rangle}\in C \langle E\cup F, \emptyset\rangle  $.
Thus, by the definition of $R\langle E\cup F,  \emptyset \rangle$, the rewrite rule 
$\s(t_1/_  {\Theta\langle E \cup F , \emptyset \rangle}, \ldots, t_m/_  {\Theta\langle E \cup F, \emptyset \rangle}) \dot{\rightarrow} t/_ {\Theta\langle E \cup F, \emptyset \rangle}$ is in $R\langle E\cup F, \emptyset\rangle$. 
\end{proof}


\begin{prop}\label{egyenlo}
  For any 
  GTESs  $E$ and $F$ over a  signature   $\S$,
  the following four statements are equivalent:
    \begin{itemize}
    \item[1.] $\tthue {E\cup F}\subseteq \tthue E\cup \tthue F$.
    \item[2.] $\tthue {E\cup F}= \tthue E\cup \tthue F$.
    \item[3.]
    There exists a GTES $H$ over $\S$ such that $\tthue H=\tthue E\cup \tthue F$.
    \item[4.] $\tthue E\cup \tthue F$ is a congruence on the ground term algebra   ${\cal T}(\Sigma)$.
      \end{itemize}
\end{prop}
\begin{proof}  
$(1\Rightarrow 2)$ For the GTES  $ E\cup F$, we have
$\tthue {E\cup F}\subseteq \tthue E\cup \tthue F\subseteq \tthue {E\cup F}$.
Thence $\tthue {E\cup F}= \tthue E\cup \tthue F$.

$(2 \Rightarrow 3)$ For the GTES $E\cup F$, we have  $\tthue {E\cup F}= \tthue E\cup \tthue F$.

$(3 \Rightarrow 4)$
$\tthue H$ is a congrunce on the ground term algebra   ${\cal T}(\Sigma)$, hence  $\tthue E\cup \tthue F$ is a congruence on the ground term algebra   ${\cal T}(\Sigma)$. 


$(4 \Rightarrow 1)$ $\tthue E\cup \tthue F$ is a congruence on the ground term algebra   ${\cal T}(\Sigma)$.
 Since $\tthue {E\cup F}$ is the least congruence on $\ts$ containing $E\cup F$,
  we have 
   $\tthue {E\cup F}\subseteq \tthue E\cup \tthue F$.
   \end{proof}
In  light of Proposition \ref{egyenlo}, from now on we decide for 
GTESs  $E$ and $F$ over a  signature   $\S$,  whether $\tthue {E\cup F}\subseteq \tthue E\cup \tthue F$.



 \begin{lem} \label{alapvetes} Let $E$ and $F$ be GTESs over a unary  signature   $\Sigma$. Let $W= ST\langle E \cup F\rangle$. 
  \begin{quote}
  $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$
  if and only if 
 for each $p\in W  $, $\left( p/_{\tthue {E\cup F}}=  p/_{\tthue E} \mbox{ or }
p/_{\tthue {E\cup F}}=  p/_{\tthue F}\right)$.
\end{quote}
\end{lem}
\begin{proof}
($\Rightarrow$) If $W=\emptyset$, then we are done. Assume that $W\neq \emptyset$.  
Let $p\in W$, $s\in \ts$,  and $p\tthue {E\cup F}  s$. Then
 $p\tthue E  s$ or  $p\tthue F  s$. Consequently 
 $ p/_{\tthue {E\cup F}}\subseteq  p/_{\tthue E} \cup   p/_{\tthue F}$.
 Since $p/_{\tthue E} \cup   p/_{\tthue F}\subseteq  p/_{\tthue {E\cup F}}$, we have $ p/_{\tthue {E\cup F}}= p/_{\tthue E} \cup   p/_{\tthue F}$.
By Proposition \ref{kovetkezmeny},  $ p/_{\tthue {E\cup F}}= p/_{\tthue E}$ or 
$ p/_{\tthue {E\cup F}}= p/_{\tthue F}$.


($\Leftarrow$)
Let $s, t \in \ts$ be arbitrary such that $s\tthue {E\cup F} t$. Then 
\begin{quote} $s=q_0
  \thue  { [\alpha_1,(l_1, r_1) ]} q_1 \thue  { [\alpha_2,(l_2, r_2) ]}
  q_2 \thue  { [ \alpha_3, (l_3, r_3) ]} \cdots  \thue  { [ \alpha_n, (l_n, r_n) ]}
  q_n =t$
  for some $n\in \Nat$,  \end{quote} where for every $i\in \{\, 0, \ldots, n\, \}$, $q_i \in \ts $ and for every $i\in \{\, 1, \ldots, n\, \}$, 
 $l_i \doteq r_i \in E\cup F$.
  We now show that 
 \begin{quote}
  $s\tthue E t$ or
    $s\tthue F t$.
\end{quote} 
If $n=0$, then $s=t$ and hence $s\tthue E t$. Let us assume that $n\geq 1$.
Let $\alpha_i$ be a  shortest word in the set
$\{\, \alpha_1, \alpha_2, \ldots, \alpha_n\, \}$, where  $i\in \{\, 1, \ldots, n\, \}$. Then
there exist
$\delta\in CON_{\Sigma, 1}$,  $v, z \in \ts$  such that
\begin{itemize}
\item  $addr(\delta)= \alpha_i$, 
  \item 
$s=\delta [v]$,
   $t=\delta [z]$, and
   \item  $q_{i-1}=\delta [l_i]$,   $q_i=\delta [r_i]$.
  \end{itemize}
So,  \begin{quote} $v\tthue {E\cup F} l_i \thue {E\cup F} r_i \tthue {E\cup F} z$\,  or \, $v\tthue {E\cup F} r_i \thue {E\cup F} l_i \tthue {E\cup F} z$. \end{quote}
Consequently, 
$v, z \in  l_i/_{\tthue {E\cup F}}$.
As 
 $ l_i/_{\tthue {E\cup F}}=  l_i/_{\tthue E}$ or 
$ l_i/_{\tthue {E\cup F}}=  l_i/_{\tthue F}$, we have 
$v, z \in  l_i/_{\tthue E}$ or $v, z \in  l_i/_{\tthue F}$. 
Therefore 
\begin{quote}
  $v \tthue E z$ or   
  $v\tthue  F z$.
\end{quote}
Then 
\begin{quote}
  $s=\delta [v]\tthue E \delta [z] =t$ or
    $s=\delta [v]\tthue F \delta [z] =t$. \qedhere
\end{quote}
\end{proof}
