 \begin{lem} \label{het} Let 
  $E$ and $F$  be  GTESs over a  signature   $\S$ such that GTRS $R\langle E \cup F , \emptyset\rangle$ is total. Let $W= ST\langle E \cup F\rangle$. 
  Then $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$
  if and only if for each $p\in W  $, 
  \begin{quote}
  $ p/_{\tthue {E\cup F}}=  p/_{\tthue E}$ or 
$ p/_{\tthue {E\cup F}}=  p/_{\tthue F}$.
\end{quote}
\end{lem}
\begin{proof}
($\Rightarrow$)
Let $p\in W$, $s\in \ts$,  and $p\tthue {E\cup F}  s$. Then
 $p\tthue E  s$ or  $p\tthue F  s$. Consequently 
 $ p/_{\tthue {E\cup F}}\subseteq  p/_{\tthue E} \cup   p/_{\tthue F}$.  
 Observe that 
 $p/_{\tthue E} \cup   p/_{\tthue F}\subseteq  p/_{\tthue {E\cup F}}  $.  
 Thus  $ p/_{\tthue {E\cup F}}=  p/_{\tthue E} \cup   p/_{\tthue F}$. 
By Proposition \ref{kovetkezmeny},  $ p/_{\tthue {E\cup F}}= p/_{\tthue E}$ or 
$ p/_{\tthue {E\cup F}}= p/_{\tthue F}$.


($\Leftarrow$) 
Let $s, t \in \ts$ be arbitrary such that $s\tthue {E\cup F} t$. Then by Lemma \ref{ezredik},
$s \tred {R\langle E\cup F, \emptyset \rangle}  p/_{\Theta\langle E\cup F, \emptyset \rangle}$ for some $p \in W$. Consequently, 
 $s\tthue {E\cup F}p$.
 Since $s\tthue {E\cup F} t$,
 we have  $t\tthue {E\cup F}p$.
 Then by our assumption, 
 \begin{quote}
 $s\tthue E p$ and $t\tthue E p$ or 
 $s\tthue F p$ and $t\tthue F p$.
 \end{quote}
  For this reason $s\tthue E t$ or  $s\tthue F t$. Thence  $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$.
 \end{proof}

 \begin{lem} \label{duna} Let 
  $E$ and $F$  be  GTESs over a  signature   $\S$ such that GTRS
  $R\langle E, F \rangle$
  is total. Let $W= ST\langle E \cup F\rangle$. Then for each $p\in W  $,
  \begin{quote}
   $p/_{\tthue {E\cup F}}=  p/_{\tthue E} \mbox{  if and only if }
   p/_{\Theta\langle E\cup F, \emptyset \rangle}= p/_{\Theta\langle E, F \rangle}$.
   \end{quote}
\end{lem}
\begin{proof}
($\Rightarrow$) Let $p \in W$. By the definition of ${\Theta\langle E, F \rangle}$ and ${\Theta\langle E\cup F, \emptyset  \rangle}$,
\begin{quote}
$p/_{\Theta\langle E\cup F, \emptyset \rangle}= p_{\tthue {E\cup F}} \cap \ts \times \ts$ and
$p/_{\Theta\langle E, F \rangle}= p_{\tthue E}  \cap \ts \times \ts$.
\end{quote}
 Thus, 
\begin{quote}
$ p/_{\Theta\langle E\cup F, \emptyset \rangle}= p/_{\Theta\langle E, F \rangle}$.
\end{quote}

 ($\Leftarrow$)
  Let $p \in W$.
 Since $\tthue E \subseteq \tthue {E\cup F}$, we have  $ p/_{\tthue E}\subseteq p/_{\tthue {E\cup F}}$. Our aim is to show that  
 $ p/_{\tthue {E\cup F}}\subseteq   p/_{\tthue E}$. To this end, let 
 $s\in \ts $ be such that $s\tthue {E \cup F} p$. We now show that   $s\tthue E  p$ as well.
As $R\langle E, F \rangle$ is total,  by Lemma  \ref{ezredik}, 
\begin{quote}
$s{\downarrow}_ {R\langle E, F \rangle} = t/_{\Theta\langle E, F \rangle}$ for some $t \in W$.
\end{quote}
By Propositon \ref{harmadik},   $s\tthue E  t$. 
Then \begin{quote}
$t \tthue  E s \tthue {E \cup F} p$. 
\end{quote}
Thus
\begin{quote}
$t \tthue {E \cup F} p$. 
\end{quote} Since $t, p \in W$, by the definition of $\Theta\langle E\cup F, \emptyset \rangle$, we have 
\begin{quote}
$(t, p)\in {\Theta\langle E\cup F, \emptyset \rangle}$.
\end{quote}
 As $\tthue E \subseteq \tthue {E\cup F}$, we have 
  \begin{quote}
 $t_{\Theta\langle E, F \rangle}  \subseteq t_{\Theta\langle E\cup F, \emptyset \rangle}=  p_{\Theta\langle E\cup F, \emptyset \rangle}= p/_{\Theta\langle E, F \rangle}$.
 \end{quote}
Consequently 
\begin{quote}
$t/_{\Theta\langle E, F \rangle}\subseteq p_{\Theta\langle E, F \rangle}$.
\end{quote}
Thence
\begin{quote}
$t/_{\Theta\langle E, F \rangle}= p_{\Theta\langle E, F \rangle}$.
\end{quote}
 Consequently,  $s\tthue E t \tthue E p$.  
 For this reason, by the definition of $s$, \begin{quote}
  $ p/_{\tthue {E\cup F}}\subseteq   p/_{\tthue E}$. 
  \end{quote}
  Thus, 
 $ p/_{\tthue {E\cup F}}=  p/_{\tthue E}$. 
\end{proof}

    \begin{lem} \label{asas}
Let $E$ and $F$ be GTESs over  a  signature   $\Sigma$ such that  
 GTRS $R\langle E, F\rangle$ and GTRS $R\langle F, E\rangle$ are  total.  
   Then 
   \begin{quote}
  $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$
  if and only if for each $p\in W  $, 
  $\left( p/_{\tthue {E\cup F}}=  p/_{\tthue E} \mbox{ or }
 p/_{\tthue {E\cup F}}=  p/_{\tthue F}\right)$.
 \end{quote}
   \end{lem}
   \begin{proof}
   By Lemma \ref{teljes},
  $R\langle E\cup F, \emptyset\rangle$ 
is total as well. Consequently, by Lemma \ref{het} and Lemma \ref{duna}, we have the lemma.
 \end{proof}


 \section{GTRS $R\langle E, F \rangle$ and GTRS $R\langle F, E \rangle$ 
together  simulate the  GTRS $R\langle E \cup F, \emptyset \rangle$}\label{jointly}
 We now introduce the notion of GTRS $R\langle E, F \rangle$
simulating  the  GTRS $R\langle E\cup F, \emptyset \rangle$ on a constant $a\in C\langle  E \cup F, \emptyset \rangle$, then the  
 concept of GTRS $R\langle E, F \rangle$ and GTRS $R\langle F, E \rangle$
together  simulate the  GTRS $R\langle E \cup F, \emptyset \rangle$. Then we describe the connection between the latter concept and 
the auxiliary   dpwpa   $ AUX[ E;  F] =
(C\langle E \cup F, \emptyset\rangle, A[E; F] )$. 




  \begin{df}\label{singlesimulate}  \rm Let $E$ and $F$ be GTESs over  a signature   $\Sigma$, and let $a\in C\langle  E \cup F, \emptyset \rangle $.
  We say that GTRS $R\langle E, F \rangle$
simulates the  GTRS $R\langle E\cup F, \emptyset \rangle$ on the constant $a\in C\langle  E \cup F, \emptyset \rangle $ if Conditions 1 and 2 hold:
 \begin{itemize}
\item[1.] $a\in C\langle  E, F \rangle $.



\item[2.] For every $b\in C\langle E\cup F, \emptyset \rangle$,
  if
 $R\langle {E \cup F}, \emptyset \rangle$ reach   $a$ from    a proper extension    of the constant $b$, then \newline
 for every rewrite rule  of the form
 $\s(b_1, \ldots, b_m) \dot{\rightarrow} b\in  R\langle {E \cup F}, \emptyset \rangle$ with $m\in \Nat$, \newline
 for all $c_1, \ldots, c_m  \in  C \langle E, F \rangle$   with
 $c_i \subseteq  b_i$ for all $i\in \{\, 1, \ldots, m\, \}$, \newline
 there exists $c \in  C \langle E, F \rangle$ 
 such that the rewrite rule   
 $\s(c_1, \ldots, c_m ) \dot{\rightarrow} c$ is in $R\langle E, F \rangle$.
 \end{itemize}
    \end{df}\begin{sta}\label{sobriety}
  $c\subseteq b$ for $c, b$ appearing in Condition 2 in  Definition \ref{singlesimulate}.
  \end{sta}
Intuitively, in Condition 2  in  Definition \ref{singlesimulate},  the rewrite rule   
 $\s(c_1, \ldots, c_m ) \dot{\rightarrow} c$  in $R\langle E, F \rangle$ fits to the rewrite rule
 $\s(b_1, \ldots, b_m) \dot{\rightarrow} b\in  R\langle {E \cup F}, \emptyset \rangle$.

 \begin{sta} \label{hasznos}
   Let $E$ and $F$ be GTESs over  a signature   $\Sigma$ such that  
 GTRS $R\langle E, F\rangle$ is   total,   and let $a\in C\langle  E \cup F, \emptyset \rangle $.
 GTRS $R\langle E, F \rangle$
simulates the  GTRS $R\langle E\cup F, \emptyset \rangle$ on the constant  $a\in C\langle  E \cup F, \emptyset \rangle $ if and only if    $a\in C\langle  E, F \rangle $.
  \end{sta}
  \begin{proof} By direct inspection of Definition \ref{csurig} and
 Definition  \ref{singlesimulate}. 
  \end{proof}




  \begin{df}\label{defsimulate}\rm  Let $E$ and $F$ be GTESs over  a signature   $\Sigma$.
    We say that GTRS $R\langle E, F \rangle$ and GTRS $R\langle F, E \rangle$
together  simulate the  GTRS $R\langle E \cup F, \emptyset \rangle$
 if 
   for each constant $a\in C\langle  E \cup F, \emptyset \rangle $, GTRS  $R\langle E, F \rangle$  or GTRS  $R\langle F, E \rangle$
    simulate  the GTRS  $R\langle E \cup F, \emptyset \rangle$ on  $a $. 
   \end{df}

 \begin{sta}\label{szabill} Let  
 $E$ and $F$ be  GTESs over a signature   $\Sigma$ such that GTRS  $R\langle E, F\rangle$ is total.  
 GTRS $R\langle E, F \rangle$ and  GTRS $R\langle F, E \rangle$ together  simulate the  GTRS $R\langle E \cup F, \emptyset \rangle$  
  if and only if for each constant $a\in C\langle  E \cup F, \emptyset \rangle $, 
    Conditions 1 or  2 hold: 
    \newline
    1.        $ a\in C\langle  E, F \rangle $. \newline  
 2.   $ a\in C\langle  F, E\rangle $ and   GTRS $R\langle F, E \rangle$
simulates the  GTRS $R\langle E\cup F, \emptyset \rangle$ on $a$.  
 \end{sta}
 \begin{proof}
 We have the satement by direct inspection of  Definition \ref{defsimulate} and Statement \ref{hasznos}.
 \end{proof}


   \begin{lem}\label{fax} Let $E$ and $F$ be GTESs over a  signature   $\Sigma$.
   GTRS $R\langle E, F \rangle$ and GTRS $R\langle F, E \rangle$
together  simulate the  GTRS $R\langle E \cup F, \emptyset \rangle$
   if and only if  for each constant $a\in C\langle  E \cup F, \emptyset \rangle $, 
    Conditions 1 or  2 hold: 



 1.       $ a\in C\langle  E, F \rangle $  and 
        for each $b \in C\langle  E \cup F, \emptyset \rangle $ if there is a  path of positive length or a cycle     from  
  $a$ to $b$
 in the auxiliary   dpwpa   $ AUX[ E;  F] =
(C\langle E \cup F, \emptyset\rangle, A[E; F] )$, then  
$ R \langle E, F \rangle$  keeps up with  $ R \langle E\cup F, \emptyset \rangle$  writing $b $.

 2.  $ a\in C\langle  F, E \rangle $  and 
        for each $b \in C\langle  E \cup F, \emptyset \rangle $ if there is a  path of positive length or a cycle     from  
  $a$ to $b$ 
 in the auxiliary   dpwpa   $ AUX[ E;  F] =
(C\langle E \cup F, \emptyset\rangle,A[E; F])$, then  
$ R \langle F, E \rangle$  keeps up with  $ R \langle E\cup F, \emptyset \rangle$  writing $b $.
  \end{lem}   
     \begin{proof}
  By Definitions \ref{singlesimulate} and \ref{defsimulate}, and  Lemma \ref{rozmaring}, and Definition \ref{lepesttart}, we have the lemma.
 \end{proof}


   \begin{lem}\label{telex}     Let 
 $E$ and $F$ be  GTESs over  a signature $\Sigma$ such that $R\langle E, F\rangle$ is total.
   GTRS $R\langle E, F \rangle$ and GTRS $R\langle F, E \rangle$
together  simulate the  GTRS $R\langle E \cup F, \emptyset \rangle$
   if and only if  for each  constant $a\in C\langle  E \cup F, \emptyset \rangle $, 
    Conditions 1 or  2 hold: 



 1.       $ a\in C\langle  E, F \rangle $.

 2.  $ a\in C\langle  F, E \rangle $  and 
        for each  constant $b \in C\langle  E \cup F, \emptyset \rangle $ if there is a  path of positive length or a cycle     from  
  $a$ to $b$ 
 in the auxiliary   dpwpa   $ AUX[ E;  F] =
(C\langle E \cup F, \emptyset\rangle, A[E; F])$, then  
$ R \langle F, E \rangle$  keeps up with  $ R \langle E\cup F, \emptyset \rangle$  writing $b $.
