 Recall that 
 \begin{quote}    $\#/_{\Theta\langle E \cup F, \emptyset \rangle}.equal_E=\mathrm{false}$,
    $\#/_{\Theta\langle E \cup F, \emptyset \rangle}.equal_F =\mathrm{false}$, and \newline
      $\#/_{\Theta\langle E \cup F, \emptyset \rangle}.keeps_E =\mathrm{false}$,  
      $\#/_{\Theta\langle E \cup F, \emptyset \rangle}.keeps_F =\mathrm{false}$.
 \end{quote}


Observe that neither Condition 1 in  nor Condition  2 in Lemma \ref{fax} holds
 for the  vertex $\#/_{\Theta\langle E\cup F  ,\emptyset \rangle}$.
  Thus by Lemma \ref{fax}, GTRS $R\langle E, F \rangle$ and GTRS $R\langle F, E \rangle$ 
together do not   simulate the  GTRS $R\langle E \cup F, \emptyset \rangle$.
    \end{exa} 



Intuitively, assume that GTRS $R\langle E, F \rangle$ simulates the  GTRS $R\langle E \cup F, \emptyset \rangle$
on a vertex  $c\in C\langle  E \cup F, \emptyset \rangle $ of  $ AUX[ E;  F] $. 
Consider a term $\delta[a_1,  \ldots, a_k]$
for some $\delta\in CON_{\Sigma,k} $,   $a_1, \ldots,  a_k \in  C\langle {E\cup F}, \emptyset \rangle$ and a sequence of reductions
\begin{quote}(i) \, 
$\delta[a_1,  \ldots, a_k]\tred {R \langle  E \cup F, \emptyset  \rangle }c$. 
\end{quote} Furthermore, consider  any  constants $b_1, \ldots, b_k \in C \langle E, F \rangle$ such that 
 $b_j \subseteq a_j $ for every $j\in \{\, 1, \ldots, k\, \}$. We substitute $b_j$ for $a_j$ in $\delta[a_1,  \ldots, a_k]$, in this way, we get the term 
 $\delta[b_1,  \ldots, b_k]$. Since
   GTRS $R\langle E, F \rangle$ simulates the  GTRS $R\langle E \cup F, \emptyset \rangle$, 
 we construct  a fitting  sequence  of reductions 
 \begin{quote} (ii) \,  
$\delta[b_1,  \ldots, b_k]\tred {R \langle  E \cup F, \emptyset  \rangle }d$ 
\end{quote} for some $d\in C \langle E, F \rangle$.  We obtain (ii) following step  by step the reductions in (i). For each reduction of (i), 
  we  apply a fitting rule at the same position in (ii). Then for each reduction step,  
for the two terms $s$ and  $t$ obtained in (i) and (ii), respectively,
each constant  $b\in C\langle  E, F \rangle $ appearing in $t$  corresponds to the constant $a\in C\langle  E \cup F, \emptyset \rangle $ 
appearing  at the same position in $s$.
Moreover $b$, as congruence class,  is  
 subset of the corresponding constant $a$.  Finally, constant $d$ corresponds to constant $c$, and $d \subseteq c$. 
Formally, we state and prove the following result.

  \begin{lem}\label{holnap} Let 
 $E$ and $F$ be  GTESs over  a signature $\Sigma$ such that   GTRS $R\langle E, F \rangle$ simulates the  GTRS $R\langle E \cup F, \emptyset \rangle$  
  on a constant   $c\in C\langle  E \cup F, \emptyset \rangle $.
 Let Conditions (a) and (b) hold. 
\begin{itemize}
 \item [\em{(a)}]
 $\delta_n[a_{n1},  \ldots, a_{nk_n}]
 \red {R \langle  E \cup F, \emptyset  \rangle } \delta_{n-1}[a_{(n-1)1},  \ldots, a_{(n-1)k_{n-1}}]\red {R \langle  E \cup F,  \emptyset   \rangle }
 \delta_{n-2}[a_{(n-2)1},  \ldots, a_{(n-2)k_{n-2}}]
  \red {R \langle E \cup  F, \emptyset  \rangle }  \cdots \newline 
 \red {R \langle E \cup  F, \emptyset  \rangle } \delta_1[a_{11},  \ldots, a_{1k_1}]\red {R \langle  E \cup F, \emptyset  \rangle }c$, \newline 
where 
 $n\geq 1$, 
 for every $i\in \{\, 1, \ldots, n\, \}$, 
 $\delta_i \in CON_{\Sigma, {k_i}} $, $k_i \in \Nat$, and   $a_{i1}, \ldots,  a_{i{k_i}}\in 
 C\langle {E\cup F}, \emptyset\rangle$.
  \end{itemize} 
 \begin{itemize}
 \item [{\rm (b)}] For every $j\in \{\, 1, \ldots, k_n\, \}$,  $b_{nj}\in C \langle E, F \rangle$ and  $b_{nj} \subseteq a_{nj}$.
 \end{itemize} 
  Then 
    for any  $i\in \{\, 1, \ldots, n-1\, \}$, $j\in \{\, 1, \ldots, k_i\, \}$, there exist $b_{ij}\in C \langle E, F \rangle$
  with  $b_{ij} \subseteq a_{ij}$,   and there exists $d\in C \langle E, F \rangle$ with $d \subseteq c$ 
   such that the following sequence of reductions holds:
\begin{quote}
  $\delta_n[b_{n_1},  \ldots, b_{nk_n}]
 \red {R \langle  E, F \rangle }
 \delta_{n-1}[b_{(n-1)1},  \ldots, b_{(n-1)k_{n-1}}]\red {R \langle  E, F \rangle }
 \delta_{n-2}[b_{(n-2)1},  \ldots, b_{(n-2)k_{n-2}}]
  \red {R \langle E, F \rangle } 
 \cdots \red {R \langle E, F \rangle } \newline \delta_1[b_{11},  \ldots, b_{1k_1}]\red {R \langle E, F \rangle }d$. \qedhere
 \end{quote} 
 \end{lem}

 \begin{proof}
 We proceed by induction on $n$.

 {\em Base Case:} $n=1$.  Assume that  Conditions (a) and (b) hold. Then $\delta_1=\s(\diamondsuit, \ldots, \diamondsuit)$ for some $\s\in \Sigma_{k_1}$,
 $k_1\in \Nat$, where
  \begin{quote}
 $\delta_1[a_{11},  \ldots, a_{1k_1}]= \s(a_{11},  \ldots, a_{1k_1})$, \, 
  $\s(a_{11},  \ldots, a_{1k_1} ) \dot{\rightarrow}  c\in  R\langle {E \cup F}, \emptyset \rangle$, \, and \, 
 $\s(a_{11},  \ldots, a_{1k_1} )\red {R \langle E \cup  F, \emptyset  \rangle } c$.
 \end{quote}
   By Condition (b), for every $j\in \{\, 1, \ldots, k_1\, \}$,   $b_{1j}\in C \langle E, F \rangle$ and  $b_{1j} \subseteq a_{1j}$.
  We assumed that 
  GTRS $R\langle E, F \rangle$ simulates the  GTRS $R\langle E \cup F, \emptyset \rangle$  
   on the constant $c\in C\langle  E \cup F, \emptyset \rangle $. 
 Consequently  by the rewrite rule $\s(a_{11},  \ldots, a_{1k_1} ) \dot{\rightarrow}  c\in  R\langle {E \cup F}, \emptyset \rangle$ and Definition \ref{singlesimulate},  and Statement \ref{sobriety}, there exists a rewrite rule
  \begin{quote}
  $\s(b_{11},  \ldots, b_{1k_1}) \dot{\rightarrow} b \in R \langle E, F \rangle$, where $b \subseteq c$.
\end{quote} Since 
 $\delta_1[b_{11},  \ldots, b_{1k_1}]= \s(b_{11},  \ldots, b_{1k_1})$, we have 
  \begin{quote}
 $\delta_1[b_{11},  \ldots, b_{1k_1}]\red {R \langle E, F \rangle }b $,
 where $b\in C \langle E, F \rangle$ and $b \subseteq c$.
 \end{quote} 

 {\em Induction Step:} Let $n\geq 1$, and  assume that the statement of the claim  is true for $n$. We now show 
 that it is also true for $n+1$ as well.
 Assume that  Conditions ($\mathrm{a}^\prime$) and ($\mathrm{b}^\prime$) hold:
 \begin{itemize}
 \item [($\mathrm{a}^\prime$)] $\delta_{n+1}[a_{(n+1)1}, \ldots, a_{(n+1) k_{n+1}}]\red {R \langle  E\cup F, \emptyset  \rangle } 
  \delta_n[a_{n1},  \ldots, a_{nk_n}]
 \red {R \langle  E\cup F, \emptyset  \rangle } \delta_{n-1}[a_{(n-1)1},  \ldots, a_{(n-1)k_{n-1}}]\red {R \langle  E\cup F, \emptyset  \rangle } \newline
 \cdots 
\red {R \langle E\cup F, \emptyset  \rangle }
  \delta_2[a_{21},  \ldots, a_{2k_2}]
 \red {R \langle E\cup F, \emptyset  \rangle } 
 \delta_1[a_{11},  \ldots, a_{1k_0}]\red {R \langle E\cup F, \emptyset  \rangle }c$,
 \newline 
where 
  for every $i\in \{\, 0, \ldots, n+1\, \}$, 
 $\delta_i \in CON_{\Sigma, {k_i}} $, $k_i  \in \Nat $, and   $a_{i1}, \ldots,  a_{i{k_i}}\in 
 C\langle {E\cup F}, \emptyset\rangle$.
 \end{itemize}
 \begin{itemize}
 \item [($\mathrm{b}^\prime$)] For every $j\in \{\, 1, \ldots, k_{n+1}\, \}$,  $b_{(n+1)j}\in C \langle E, F \rangle$ and  $b_{(n+1)j} \subseteq 
 a_{(n+1)j}$.
 \end{itemize} 
  Then Conditions (c)--(f) hold:
   \begin{itemize}
 \item [{\rm (c)}] We obtain $\delta_{n+1}$ from $\delta_n$ by replacing the $j$th occurrence  from left to right of the hole 
  $\diamondsuit$  by the context 
  $\s(\diamondsuit, \ldots, \diamondsuit )$, where 
 $j \in \{\, 1, \ldots, k_n\, \}$,   $\s\in \Sigma_m$, $m \in \Nat$,  and $k_n= k_{n+1}-m+1$.
  \item [{\rm (d)}] $\delta_{n+1}
  [a_{(n+1)1}, \ldots,   a_{(n+1)k_{n+1}}]= 
  \delta_n [ a_{(n+1)1}, \ldots, a_{(n+1)(j-1)}, \s(a_{(n+1)j}, \ldots, a_{(n+1)(j+m-1)}), a_{(n+1)(j+m)}, 
  \ldots,   a_{(n+1) k_{n+1}}]$. 
 \item [{\rm (e)}]    
For every $\ell\in \{1, \ldots, j-1\, \}$,  $a_{n\ell}= a_{(n+1)\ell}$ and
    for every $\ell\in \{j+1, \ldots, k_n \, \}$,    $a_{n\ell}= a_{(n+1)(\ell+m-1)}$.
  \item [{\rm (f)}] In the last reduction step  of (a') we apply the rule $\s(a_{(n+1)j}, \ldots, a_{(n+1)(j+m-1)} ) \dot{\rightarrow}   a_{nj}\in  R\langle {E \cup F}, \emptyset  \rangle$.
 \end{itemize}  
  By Condition ($\mathrm{a}^\prime$), $R \langle E\cup F, \emptyset  \rangle $ reach  $c$
 from a proper extension of $a_{nj}$.   By Condition    ($\mathrm{b}^\prime$),
 for every $\ell \in \{\, j, \ldots, j+m-1\, \}$,  $b_{(n+1)\ell}\in C \langle E, F \rangle$ and   $b_{(n+1)\ell} \subseteq a_{n\ell}$.
  We assumed that 
  GTRS $R\langle E, F \rangle$ simulates the  GTRS $R\langle E \cup F, \emptyset \rangle$  
  on the constant  $c\in C\langle  E \cup F, \emptyset \rangle $.
Therefore  by the rewrite rule appearing in Condition (f) there exists a rewrite rule   
  \begin{quote}
  $\s(b_{(n+1)j}, \ldots, b_{(n+1) (j+m-1)})\dot{\rightarrow} b$ in $R \langle E, F \rangle$ with $b\subseteq a_{nj} $.
\end{quote}
 \begin{quote} 
For every $\ell\in \{1, \ldots, j-1\, \}$, let  $b_{n\ell}= b_{(n+1)\ell}$, \newline  let $b_{nj}=b$, \newline
  for every $\ell\in \{j+1, \ldots, k_n \, \}$, let  $b_{n\ell}= b_{(n+1)(\ell+j-1)}$.
  \end{quote}
  Thence
  \begin{quote} for every $\ell\in \{\, 1, \ldots, k_n\,\}$, 
 $b_{n\ell}\subseteq a_{n\ell}$ and    
 $\delta_{n+1}[b_{(n+1)1},  \ldots, b_{(n+1)k_{n+1}}]
 \red {R \langle  E, F \rangle } \delta_n[b_{n1},  \ldots, b_{nk_n}]$.
 \end{quote}
 By the sequence of reductions $(a^\prime)$ we have
 \begin{quote}
$\delta_n[a_{n1},  \ldots, a_{nk_n}]
 \red {R \langle  E\cup F, \emptyset  \rangle } \delta_{n-1}[a_{(n-1)1},  \ldots, a_{(n-1)k_{n-1}}]\red {R \langle  E\cup F, \emptyset  \rangle } 
 \cdots 
\red {R \langle E\cup F, \emptyset  \rangle }
  \delta_2[a_{21},  \ldots, a_{2k_2}]
 \red {R \langle E\cup F, \emptyset  \rangle } \newline
 \delta_1[a_{11},  \ldots, a_{1k_0}]\red {R \langle E\cup F, \emptyset  \rangle }c$.
 \end{quote}
 Consequently by the induction hypothesis, 
 \begin{quote}
  for any  $i\in \{\, 1, \ldots, n-1\, \}$ and  $\ell\in \{\, 1, \ldots, k_i\, \}$, there exist $b_{i\ell}\in C \langle E, F \rangle$,
  with $b_{i\ell} \subseteq a_{i\ell}$,    and  \newline
there exists
 $d\in C \langle E, F \rangle$ with $d \subseteq c$ 
 \end{quote} such that the following sequence of reductions holds:
   \begin{quote} $\delta_n[b_{n1},  \ldots, b_{nk_n}]\red {R \langle  E, F \rangle }
 \delta_{n-1}[b_{(n-1)1},  \ldots, b_{(n-1)k_{n-1}}]
 \red {R \langle E, F \rangle } 
 \cdots \red {R \langle E, F \rangle } \delta_1[b_{11},  \ldots, b_{1k_1}]\red {R \langle E, F \rangle }d$.
   \end{quote} 
  Then we have 
     \begin{quote} 
 $\delta_{n+1}[b_{(n+1)1},  \ldots, b_{(n+1)k_{n+1}}]
 \red {R \langle  E, F \rangle } \delta_n[b_{n1},  \ldots, b_{nk_n}]\red {R \langle  E, F \rangle }
 \delta_{n-1}[b_{(n-1)1},  \ldots, b_{(n-1)k_{n-1}}]
 \red {R \langle E, F \rangle } \newline
 \cdots \red {R \langle E, F \rangle } \delta_1[b_{11},  \ldots, b_{1k_1}]\red {R \langle E, F \rangle }d$.\qedhere
    \end{quote}
  \end{proof}

  \begin{lem}\label{hurnegyszog} Let 
 $E$ and $F$ be  GTESs over  a signature $\Sigma$ such that   GTRS $R\langle E, F \rangle$ simulates the  GTRS $R\langle E \cup F, \emptyset \rangle$  
   on a constant  $c\in C\langle  E \cup F, \emptyset \rangle $. Let $s\in \ts$ and $s\tred {R\langle E \cup F, \emptyset \rangle}c$. 
  Then 
 there exists $d\in C \langle E, F \rangle$ with $d \subseteq c$ 
  such that $s\tred {R\langle E, F\rangle}d$. 
 \end{lem}
 \begin{proof}  Lemma \ref{holnap} implies the lemma.
   \end{proof}

  \begin{lem}\label{sportos}  Let 
 $E$ and $F$ be  GTESs over a signature   $\Sigma$.
 \begin{quote}
    For each   $t\in W $, 
  $\left( t/_{\tthue{ E\cup F} }=  t/_{{\tthue E}} \mbox{ or } t/_{\tthue{ E\cup F} }=  t/_{{\tthue F}} 
  \right) $
   \end{quote}
  if and only if 
  GTRS $R\langle E, F \rangle$ and GTRS $R\langle F, E \rangle$
together  simulate the  GTRS $R\langle E \cup F, \emptyset \rangle$.
 \end{lem}

 \begin{proof} 
 $(\Rightarrow)$ Let
  $t\in W $.  Then by our assumption, 
  \begin{quote}
    $ t/_{\Theta\langle E\cup F, \emptyset \rangle }=  t/_{\Theta\langle E, F \rangle } \mbox{ or }
   t/_{\Theta\langle E\cup F, \emptyset \rangle }=  t/_{\Theta\langle F, E \rangle }  $.
   \end{quote}
   Assume that $ t/_{\tthue{ E\cup F} }=  t/_{{\tthue E}} $. The case  $t/_{\tthue{ E\cup F} }=  t/_{{\tthue F}} $
      is similar. We now show that  GTRS $R\langle E, F \rangle$ simulates the  GTRS $R\langle E \cup F, \emptyset \rangle$ on $ t/_{\Theta\langle E\cup F, \emptyset \rangle }$.
 To this end, let  $c \in C\langle E\cup F, \emptyset \rangle$ be such that 
 $R\langle {E \cup F}, \emptyset \rangle$ reach   $t/_{\Theta\langle {E\cup F}, \emptyset \rangle}$ from   a proper extension    of the constant  $c$. 
 Then there exists $\delta\in CON_{\Sigma, 1}$
 such that $\delta[c] \tred {R\langle E \cup F, \emptyset \rangle} t/_{\Theta\langle {E\cup F}, \emptyset \rangle}$. 
 Let 
 $\s(a_1, \ldots, a_m) \dot{\rightarrow} c\in  R\langle {E \cup F}, \emptyset\rangle$ be a rewrite rule with $a_1, \ldots, a_m \in 
 C\langle {E \cup F}, \emptyset\rangle$, and let  $b_1, \ldots, b_m  \in C \langle E, F \rangle$   with
 $b_i \subseteq a_i$ for all $i\in \{\, 1, \ldots, m\, \}$. We now show that 
  there exists a rewrite rule  in  $R\langle E, F \rangle$ with left-hand side 
 $\s(b_1, \ldots, b_m) $. 
  Let $t_1\in b_1, \ldots, t_m \in b_m$. By Definition \ref{szeder},  we have  
  \begin{quote}
  $t_1, \ldots, t_m \in W$, \newline
 $t_1/_{\Theta\langle E, F \rangle}=b_1, \ldots,t_m/_{\Theta\langle E, F \rangle}=b_m$, \newline
 $t_1/_{\Theta\langle {E\cup F}, \emptyset \rangle}=a_1, \ldots,t_m/_{\Theta\langle {E\cup F} , \emptyset \rangle}=a_m$. \newline
  Hence 
  $\s(t_1/_{\Theta\langle {E\cup F}, \emptyset\rangle}, \ldots,t_m/_{\Theta\langle {E\cup F} , \emptyset \rangle}) \dot{\rightarrow} c
 \in  R\langle {E \cup F}, \emptyset \rangle$.
 \end{quote}  
 Then by Proposition    \ref{masodik},  \begin{quote}
 $\delta [\s(t_1,  \ldots, t_m)] \tred {R\langle E \cup F, \emptyset \rangle} \delta [\s(a_1,  \ldots, a_m)] \red {R\langle E \cup F, \emptyset \rangle} 
 \delta[c]\tred {R\langle E \cup F, \emptyset \rangle} t/_{\Theta\langle {E\cup F}, \emptyset \rangle}$. 
 \end{quote}  
 By Proposition \ref{harmadik}, 
 $\delta [\s(t_1,  \ldots, t_m)] \tthue { E\cup F} t$.
    By  the equation $t/_{\tthue {E\cup F}}=  t/_{\tthue E}$, we have 
   $\delta [\s(t_1,  \ldots, t_m)] \tthue E  t$. 
     By Proposition \ref{otodik}, \begin{quote}
     $\delta [\s(t_1,  \ldots, t_m)]\tred {R\langle E, F \rangle}  t_{\Theta\langle  E, F \rangle}$. \end{quote} 
        By Proposition \ref{rhcp},  
   $R\langle E, F \rangle $ is convergent. Observe that $ t_{\Theta\langle  E, F \rangle}$ is irreducible for   $R\langle E, F \rangle $.
   Thence  we have 
   \begin{quote}
     $\delta [\s(t_1,  \ldots, t_m)] {\downarrow}_{R\langle E, F \rangle} =t/_{\Theta\langle E, F \rangle}$.
  \end{quote}     
 By the set memberships $t_1, \ldots, t_m \in W$ and by Proposition \ref{masodik}, we have    
 $t_j \tred {R\langle E, F \rangle} t_j/_{\Theta\langle { E}, F\rangle}$ for every $j \in \{\, 1, \ldots, m\, \}$.
  Then 
\begin{quote}$\delta [\s(t_1,  \ldots, t_m)]\tred {R\langle E, F \rangle} 
\delta[\s(t_1/_{\Theta\langle { E}, F\rangle}, \ldots,t_m/_{\Theta\langle {E}, F\rangle} ) ]$.
      \end{quote}  
       By Proposition \ref{rhcp},  
   $R\langle E, F \rangle $ is convergent.    Thence  we have    
   \begin{quote}  
    $\delta[\s(t_1/_{\Theta\langle { E}, F\rangle}, \ldots,t_m/_{\Theta\langle {E}, F\rangle} )]
    {\downarrow}_{R\langle E, F \rangle} =t/_{\Theta\langle E, F \rangle}$.
   \end{quote}    
 Therefore,  there exists
  a rewrite rule  with left-hand side $\s(t_1/_{\Theta\langle { E}, F\rangle}, \ldots,t_m/_{\Theta\langle {E}, F\rangle} ) $
   in $R\langle {E}, F\rangle$.







  $(\Leftarrow)$    Let $t \in W$.  We assumed that  GTRS $R\langle E, F \rangle$ and GTRS $R\langle F, E \rangle$
together  simulate the  GTRS $R\langle E \cup F, \emptyset \rangle$. By Definition \ref{defsimulate} GTRS $R\langle E, F \rangle$ or 
GTRS $R\langle F, E \rangle$ simulate the  GTRS $R\langle E \cup F, \emptyset \rangle$   
  on  the constant  $  t/_{\tthue {E\cup F}}\in C\langle  E \cup F, \emptyset \rangle $.  
    Assume that  GTRS $R\langle E, F \rangle$ simulates the  GTRS $R\langle E \cup F, \emptyset \rangle$   
  on $  t/_{\tthue {E\cup F}}$.   Then $t/_{\Theta\langle E\cup F, \emptyset \rangle}= t/_{\Theta\langle E, F \rangle}$.   
     Let   $s\in  t/_{\tthue {E\cup F}}$. 
 Consequently by Proposition \ref{otodik},
  $s\tred {R \langle E\cup F, E \rangle } t/_{\Theta\langle {E\cup F},\emptyset\rangle}$. 
  By Lemma \ref{hurnegyszog}, there exists  $d\in C \langle E, F \rangle$ such that  $d \subseteq  t/_{\Theta\langle {E \cup F}, \emptyset \rangle}$ and 
  $s\tred {R \langle E, F \rangle } d$.
   Then $d=p/_{\Theta\langle E, F \rangle}$ for some $p\in W$.
   By Proposition \ref{harmadik},
   $s \tthue { E\cup F}t$ and  $s \tthue { E} p$. 
   Then $s \tthue { E\cup F}p$. Thus    
  $d = p/_{\Theta\langle E, F \rangle}\subseteq t/_{\Theta\langle E\cup F, \emptyset \rangle}= t/_{\Theta\langle E, F \rangle}$.  Consequently 
   $d = t/_{\Theta\langle E, F \rangle}$. 
    Hence 
     $s\in  t/_{\tthue E}$.  
  Consequently, 
  for any  $s\in  t/_{\tthue {E\cup F}}$, we have
    $s\in  t/_{\tthue E}$. 
Thus
  $ t/_{\tthue {E\cup F}}\subseteq  t/_{\tthue E}$, and hence  $ t/_{\tthue {E\cup F}}=  t/_{\tthue E} $. 
 We showed that if  GTRS $R\langle E, F \rangle$ simulates the  GTRS $R\langle E \cup F, \emptyset \rangle$   
  on $  t/_{\tthue {E\cup F}}$, then  $ t/_{\tthue {E\cup F}}=  t/_{\tthue E} $. 


 We can show similarly that if  GTRS $R\langle F, E \rangle$ simulates the  GTRS $R\langle E \cup F, \emptyset \rangle$   
  on $  t/_{\tthue {E\cup F}}$, then  $ t/_{\tthue {E\cup F}}=  t/_{\tthue F} $. 
    Consequently,  \begin{quote}
    for each   
  $t\in W $, 
  $\left( t/_{\tthue {E\cup F}}=  t/_{\tthue E} \mbox{ or }
   t/_{\tthue {E\cup F}}=  t/_{\tthue F}\right)$. \qedhere
   \end{quote}
   \end{proof}
