\begin{lem} \label{abcd}
Let $E$ and $F$ be GTESs over  a  signature   $\Sigma$ such that  
 GTRS $R\langle E, F\rangle$ and GTRS $R\langle F, E\rangle$ are  total. 
  Then \begin{quote} 
  for each $t\in W $, $\left( t/_{\tthue {E\cup F}}=  t/_{\tthue E} \mbox{ or }
   t/_{\tthue {E\cup F}}=  t/_{\tthue F}\right)$ 
  if and only if
  \newline 
for each $t\in W $, $ \left( t/_{\Theta\langle {E\cup F}, \emptyset \rangle}=
  t/_{\Theta\langle {E, F \rangle} } \mbox{  or  }
   t/_{\Theta\langle {E\cup F}, \emptyset \rangle}=  t/_{\Theta\langle {F}, E \rangle}\right)$.
  \end{quote}
\end{lem}
\begin{proof}
($\Rightarrow$)
If
$ t/_{\tthue {E\cup F}}=  t/_{\tthue E} $, then by Definition \ref{alfa}, 
$ t/_{\Theta\langle {E\cup F}, \emptyset \rangle}= t/_{\tthue {E\cup F}}\cap  W\times W
=  t/_{\tthue E} \cap  W\times W= t/_{\Theta\langle {E, F \rangle} } $.

 If
$ t/_{\tthue {E\cup F}}=  t/_{\tthue F} $, then 
$ t/_{\Theta\langle {E\cup F}, \emptyset \rangle}= t/_{\tthue {E\cup F}}\cap  W\times W
=  t/_{\tthue F} \cap  W\times W= t/_{\Theta\langle {E, F \rangle} } $.


($\Leftarrow$)
 Let $t\in W $ and $s \in  t/_{\tthue {E\cup F}}$.
 By Proposition \ref{otodik},
\begin{quote}
$s \tred {R\langle E\cup F, \emptyset \rangle}   t/_{\Theta\langle E\cup F, \emptyset \rangle}$.
\end{quote}
As $R\langle E, F\rangle$ and $R\langle F, E\rangle$ 
are total, by Lemma \ref{ezredik}, 
\begin{quote} 

$s{\downarrow}_ {R\langle E, F \rangle} = p/_{\Theta\langle E, F \rangle}$ for some $p \in W$,
\end{quote}
and 
\begin{quote}
  $s {\downarrow}_ {R\langle F, E \rangle}=  q/_{\Theta\langle F, E \rangle}$ for some
  $q \in W$.
\end{quote}
Consequently,
by Proposition \ref{harmadik},
\begin{quote}
  $s\tthue {E\cup F} t$, $s\tthue E p$ and $s\tthue F q$.
  \end{quote}
Therefore  $t\tthue {E\cup F}s\tthue E p$ and $t\tthue {E\cup F} s
\tthue E q$.
Therefore,
\begin{quote} $p \in  t/_{\Theta\langle {E\cup F}, \emptyset \rangle}$ and
$q \in  t/_{\Theta\langle {E\cup F}, \emptyset \rangle}$.
\end{quote}
By our assumption, 
\begin{quote}
$t/_{\Theta\langle {E\cup F}, \emptyset\rangle}=
  t/_{\Theta\langle {E, F \rangle} } $ or  $
   t/_{\Theta\langle {E\cup F}, \emptyset\rangle}=  t/_{\Theta\langle {F}, E \rangle})$.
   \end{quote}
First, suppose that 
 $ t/_{\Theta\langle {E\cup F}, \emptyset\rangle}=
 t/_{\Theta\langle {E, F \rangle} } $. Therefore,  we have 
$p \in  t/_{\Theta\langle {E, F \rangle}}$. 
Thus, by  $s\tthue E p$, we have
$s\tthue E p\tthue E t$.
Accordingly,  $s\in  t/_{\tthue E}$.  By the definition of $s$,  
\begin{quote}
$ t/_{\tthue {E\cup F}} \subseteq  t/_{\tthue E} $.
\end{quote}
 Since $E \subseteq E \cup F
$,  $ t/_{\tthue E} \subseteq  t/_{\tthue {E\cup F}}$.
Thus,  $ t/_{\tthue {E\cup F}}=  t/_{\tthue E} $.


Second, suppose  that  $ t/_{\Theta\langle {E\cup F}, \emptyset \rangle}=
  t/_{\Theta\langle {F, E \rangle} } $. Then by a similar argument as above we can show that
 $ t/_{\tthue {E\cup F}}=  t/_{\tthue F} $.
\end{proof}

 \begin{lem} \label{lennon}  Let $E$ and $F$ be GTESs over  a  signature   $\Sigma$ such that   GTRSs $R\langle E, F\rangle$ and  $R\langle F, E\rangle$ are total.
   Then we can decide in $O(n\,\mathrm{log}\, n)$  time whether
   $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$.
   \end{lem}
   \begin{proof}
   By Lemma \ref{teljes},
  $R\langle E\cup F, \emptyset\rangle$ 
is total as well. Consequently, by Lemma \ref{het},
\begin{quote}
  $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$
  if and only if  for each $p\in W  $, 
  $\left( p/_{\tthue {E\cup F}}=  p/_{\tthue E} \mbox{ or }
 p/_{\tthue {E\cup F}}=  p/_{\tthue F}\right)$.
\end{quote} Consequently, by Lemma \ref{abcd},
   \begin{quote}
     $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$
   if and only if
 for each $p\in W $, $ \left( p/_{\Theta\langle {E\cup F}, \emptyset \rangle}=
  p_{\Theta\langle {E, F \rangle} } \mbox{  or  }
   p/_{\Theta\langle {E\cup F}, \emptyset \rangle}=  p/_{\Theta\langle {F}, E \rangle}\right)$.
  \end{quote}
  Justified by the above observations and by Statement \ref{dan}, we compute as follows.
  Recall that  $NUM( E\cup F, E)$ stored in a red-black tree   $RBT3$, 
 and $NUM(  E\cup F, F)$ stored in a red-black tree    $RBT4$.
  Alternately in a coordinated way, we traverse the red-black trees $RBT3$ and $RBT4$ 
in in-order  traversal,  
For each $a\in C\langle E\cup F, \emptyset\rangle$, we read the pair  $(a, k)$, where 
$ k=|\{ b\in C\langle E, F\rangle \mid    b\subseteq a\, \}|$, and the pair 
 $(a, \ell)$, where
$ \ell=|\{ b\in C\langle F, E\rangle \mid    b\subseteq a\, \}|$.
 In this way, 
  we decide in    $O(n)$ 
 time whether each $\Theta\langle E\cup F, \emptyset \rangle$  equivalence    class is equal to a 
 $\Theta\langle E, F \rangle$ equivalence    class or a $\Theta\langle F, E \rangle$ equivalence    class, see Definition \ref{szeder}. 
    If the answer is 'yes', then  $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$, otherwise, $\tthue {E\cup F}\not\subseteq \tthue E \cup \tthue F$.
\end{proof}



