 Then the following conditions are pairwise equivalent: 
  \begin{itemize}
  \item[(i)]
  $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$, 
    \item[(ii)]
 for each $t\in W  $, 
 $\left( 
     t/_{\tthue {E\cup F}}=  t/_{\tthue E}  \mbox{  or } 
t/_{\tthue {E\cup F}}=  t/_{\tthue F}\right) $. 


\item[(iii)]
   For each $t\in W  $, 
    $\left( t/_{\Theta\langle E\cup F, \emptyset \rangle}= t/_{\Theta\langle E, F \rangle}\mbox{  or } t/_{\Theta\langle E\cup F, \emptyset \rangle}= t/_{\Theta\langle F, E \rangle} \right) $. 




 \item[(iv)]  GTRS $R\langle E, F \rangle$ and GTRS $R\langle F, E \rangle$ 
together  simulate the  GTRS $R\langle E \cup F, \emptyset \rangle$.

  \item[(v)]  
    for each $a\in C\langle  E \cup F, \emptyset \rangle $, 
   \begin{itemize}
   \item
     $ a\in C\langle  E, F \rangle $ or  
       $ a\in C\langle  F, E \rangle $  and 
      \item if 
     $ a\not \in C\langle  E, F \rangle $, then  
  for each $b \in C\langle  E \cup F, \emptyset \rangle $ if there is a  path of positive length or a cycle     from  
  $a$ to $b$
 in the auxiliary dpwpa   
$ AUX[ E;  F] =
(C\langle E \cup F, \emptyset\rangle,A[E; F])$, then  $ R \langle F, E \rangle$  keeps up with  $ R \langle E \cup  F, \emptyset  \rangle$  writing $b $.
\end{itemize}


 \item[(vi)]     for each $a\in C\langle  E \cup F, \emptyset \rangle $, 
