\begin{thm} \label{morandi}
  Let $\S$ be a  signature   such that 
   $\S_k\neq \emptyset$ for some $k\geq 2$. Let 
  $E$ and $F$ be GTESs over $\S$ such that
     GTRS  $ R \langle E, F \rangle$ and GTRS $ R \langle F, E\rangle$  are not total. 
  Then   \begin{quote}
    $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$
  if and only if
  $E \subseteq \tthue F$ or
    $ F \subseteq \tthue E $.
    \end{quote}
\end{thm}
\begin{proof}
$(\Rightarrow)$  We proceed by contrapositive. Assume that
$E \not\subseteq \tthue F$ and 
    $ F \not\subseteq \tthue E $.
That is, there exists
$l_1\doteq r_1\in E$ such that  $(l_1, r_1)\not \in \tthue F$ and 
there exists
$l_2\doteq r_2\in F$ such that  $(l_2, r_2)\not \in \tthue E$.
Then $l_1\neq r_1$ and $l_2\neq r_2$.  Let $\s\in \S_k$ with $k\geq 2$, and  by Lemma  \ref{halle}, let $v\in \ts \setminus  \bigcup  W /_{\tthue E}$,
and   $ z\in  \ts \setminus \bigcup W /_{\tthue F}$.
Then
\begin{quote}
$\s(\s(v, l_1, \ldots, l_1),  \s(z, l_2, \ldots, l_2), v, \ldots,  v)\tthue {E\cup F}
\s(\s(v, r_1, \ldots, r_1), \s(z, r_2, \ldots, r_2),  v, \ldots,  v)$.
\end{quote}
We now show that
\begin{quote}
$(\s(\s(v, l_1, \ldots, l_1),  \s(z, l_2, \ldots, l_2),  v, \ldots,  v), 
\s(\s(v, r_1, \ldots, r_1), \s(z, r_2, \ldots, r_2),  v, \ldots,  v))\not\in 
\tthue E\cup \tthue F$,
  \end{quote}
  and hence  we have 
  \begin{quote}
  $\tthue {E\cup F}\not \subseteq \tthue E \cup \tthue F$.
  \end{quote}
 To this end, first we show that 
  \begin{quote}
 $(\s(\s(v, l_1, \ldots, l_1),  \s(z, l_2, \ldots, l_2),  v, \ldots,  v), 
\s(\s(v, r_1, \ldots, r_1), \s(z, r_2, \ldots, r_2),  v, \ldots,  v))
 \not \in \tthue E $.
\end{quote}  
As $l_1\neq r_1$ and $l_2\neq r_2$,         
\begin{quote}
$\s(\s(v, l_1, \ldots, l_1),  \s(z, l_2, \ldots, l_2), v, \ldots,  v    )\neq 
\s(\s(v, r_1, \ldots, r_1), \s(z, r_2, \ldots, r_2), v, \ldots,  v)$.
  \end{quote}
We now show that 
  \begin{quote}
$(\s(\s(v, l_1, \ldots, l_1), \s(z, l_2, \ldots, l_2), v, \ldots,  v),
 \s(\s(v, r_1, \ldots, r_1), \s(z, r_2, \ldots, r_2), v, \ldots,  v))\not \in \plusthue E $.
\end{quote} 
To this purpose we now show the following statement.
\begin{cla}\label{muszaki}
Let \begin{equation}\label{huszka}
\s(\s(v, l_1, \ldots, l_1),  \s(z, l_2, \ldots, l_2), v, \ldots,  v)
  =s_0\thue {[ \alpha_1, p_1\doteq q_1]}
  s_1 \thue { [\alpha_2, p_2\doteq q_2 ]} \cdots \thue {[ \alpha_n, p_n \doteq q_n ]}
  s_n=t, \;n\geq 1.
\end{equation}
be a sequence of  $E$-rewrite steps.
Then for each $i\in \{\, 1, \ldots, n\,\}$, $\alpha_i$ is not a prefix of $11$.
\end{cla}
\begin{proof} By induction on $n$, we show that  for each $i\in \{\, 1, \ldots, n\,\}$, $\alpha_i$ is not a prefix of $11$.

{\em Base case:} $n=1$.
By the definition of $v$, $v\not\in \bigcup  W /_{\tthue E}$, hence 
\begin{quote} $v$ is not a subterm of
$\s(\s(v, l_1, \ldots, l_1),  \s(z, l_2, \ldots, l_2), v, \ldots,  v) |_{\alpha_1}$,
\end{quote}
 thus 
$\alpha_1$ is not a prefix of $11$.

{\em Induction step:} Let $n\geq 2$ and let us assume that we have shown the
statement for $n-1$. Then by  the induction hypothesis, for each $i\in \{\, 1, \ldots, n-1\,\}$, $\alpha_i$ is not a prefix of $11$. Accordingly
we have $v=s_0|_{11 } \tthue E s_n|_{11 }$. Consequently, by 
$v\not \in \bigcup  W /_{\tthue E}$, we have   $ s_n|_{11}\not \in  \bigcup W /_{\tthue E}$.
Thus 
$ s_n|_{11}$ is not a subterm of $p_n\in W$. As a consequence,
$\alpha_n$ is not a prefix of $11$. Then the  induction step is complete. 
\end{proof}

Consider the  sequence (\ref{huszka}) of  $E$ rewrite steps.
By Claim \ref{muszaki},
for each $i\in \{\, 1, \ldots, n\,\}$, $\alpha_i$ is not a prefix of 
$11$. Consequently $t=\s(\s( t_1, t_2, \ldots t_k), p_1, \ldots, p_{k-1} )$ for some $p_1, \ldots, p_{k-1}\in \ts$, and 
for each $j\in \{\, 2, \ldots, k\,\}$,
$l_1 \tthue E  t_j$.  Recall  that  $(l_1, r_1)\not \in \tthue E$. Therefore 
 for each $j\in \{\, 2, \ldots, k\, \}$, $t_j\neq r_1$. Hence 
  \begin{quote}
 $t\neq \s(\s(v, r_1, \ldots, r_1), \s(z, r_2, \ldots, r_2),  v, \ldots,  v)$.
 \end{quote}
 Then
 \begin{quote}
$(\s(\s(v, l_1, \ldots, l_1), \s(z, l_2, \ldots, l_2),  v, \ldots,  v),
 \s(\s(v, r_1, \ldots, r_1), \s(z, r_2, \ldots, r_2),  v, \ldots,  v))\not \in \tthue E$.
\end{quote}

 We can show similarly that
  \begin{quote}
$(\s(\s(v, l_1, \ldots, l_1), \s(z, l_2, \ldots, l_2),  v, \ldots,  v)),
 \s(\s(v, r_1, \ldots, r_1), \s(z, r_2, \ldots, r_2),  v, \ldots,  v))\not \in \tthue F $.
\end{quote}
 Consequently, 
  $\tthue {E\cup F}\not \subseteq \tthue E \cup \tthue F$.




$(\Leftarrow)$
 If   $E \subseteq \tthue F$,  then $\tthue {E\cup F}\subseteq \tthue F$, and hence $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$.
 If  $ F \subseteq \tthue E $, 
 then $\tthue {E\cup F}\subseteq \tthue E$, and hence  $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$.
 \end{proof}


\begin{cons} \label{cabello}
  Let $\S$ be a  signature   such that 
   $\S_k\neq \emptyset$ for some $k\geq 2$. Let 
  $E$ and $F$ be GTESs over $\S$ such that
  $R\langle E, F\rangle$ and 
 $R\langle F, E\rangle$ are not  total.
  Then   \begin{quote}
    $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$
  if and only if
  $E \subseteq \Theta \langle F, E \rangle   $  or
  $ F \subseteq \Theta\langle E, F \rangle   $. 
    \end{quote}
\end{cons}
\begin{proof} By  Definition \ref{alfa},   we have
$\Theta\langle F,E \rangle=\tthue F \cap W\times W$ and
$\Theta\langle E,F\rangle=\tthue E \cap W\times W$.
Hence Theorem  \ref{morandi} implies our consequence.
\end{proof}



\begin{lem} \label{orangutan} Let $\S$ be a  signature   such that
   $\S_k\neq \emptyset$ for some $k\geq 2$, and let 
   $E$ and $F$ be GTESs over  $\Sigma$ such that 
 $R\langle E, F\rangle$ and 
 $R\langle F, E\rangle$  are  not  total.
  We can decide in  $O(n \, \mathrm{log} \, n )$  time whether   $\tthue {E\cup F}\subseteq \tthue E \cup \tthue F$.
\end{lem}
\begin{proof} By Consequence \ref{cabello}, we  proceed as follows.
Recall that we have run Algorithm CAD  on $\Sigma$, $E$, and $F$. 
By Proposition \ref{kecskemet}, we got 
the relations  $\rho\langle E, F\rangle$, $\rho\langle F, E\rangle$,  and $\rho\langle E\cup F, \emptyset\rangle$ in   $O(n \, \mathrm{log} \, n )$ time.

First we decide whether $E \subseteq \Theta \langle F, E \rangle   $.
By  Consequence \ref{cabello} and Proposition \ref{kozen}, 
\begin{quote}
 $E \subseteq \Theta \langle F, E \rangle   $ if and only if \newline for  each  $l \doteq  r $ in $ E$, $ (l, r)\in \Theta\langle F, E\rangle$
 if and only if \newline
for each  $(u, v) \in \tau\langle E, F \rangle$, 
$u/_{\rho\langle F, E\rangle}=v/_{\rho\langle F, E\rangle}$ if and only if \newline 
$\mathrm{FIND}_{\rho\langle F, E\rangle}(u)= \mathrm{FIND}_{\rho\langle F, E\rangle}(v)$. 
\end{quote} 
We decide whether
for each  $(u, v) \in \tau\langle E, F \rangle$, $\mathrm{FIND}_{\rho\langle F, E\rangle}(u)= \mathrm{FIND}_{\rho\langle F, E\rangle}(v)$.
If so,   $E \subseteq \Theta \langle F, E \rangle   $,  otherwise   $E \not \subseteq \Theta \langle F, E \rangle   $. 

Second, similarly to above, we decide whether $F \subseteq \Theta \langle E, F \rangle   $.

We call above the functions   $\mathrm{FIND}_{\rho\langle F, E\rangle}$ and $\mathrm{FIND}_{\rho\langle E, F\rangle}$ a total of 
at most $2n$ times,
 where  $n=size(E)+size(F)$.
  These callings,  by the main
result of \cite{journals/jacm/Tarjan75},
 require $O(n)$ time. 
 As a result, the time complexity of our entire computation is     $O(n\, \mathrm{log}\, n)$.
\end{proof}


