  %\node  at (0,0) {\footnotesize $q$};


  \draw[thick,>=stealth] (q) edge[loop left] node[left] {$C$} (q);
  \draw[thick,>=stealth] (q) edge[loop right] node[right] {$C$} (q);



  \node[circle, draw,thick] (q1) at (6,0) {\footnotesize $q_1$};

  \node[circle, draw,thick] (q2) at (8,0) {\footnotesize $q_2$};

  \draw[thick,>=stealth,->] (q1) edge[bend left] node[above] {$C$} (q2);
  \draw[thick,>=stealth] (q1) edge[loop above] node[above] {$C$} (q1);
  \draw[thick,>=stealth] (q2) edge[loop above] node[above] {$C$} (q2);

\end{tikzpicture}

\caption{A scalar-heavy cycle (left), a center- or side-ambiguous cycle (middle) and a barbell (right), with the assumption that the $C$-runs are distinct in the middle and $q_1\neq q_2$ on the right.}\label{fig:barbell}
\end{figure}

Note that barbells do not take weights into account.

\begin{theorem}[{Caralp, Reynier \& Talbot~\cite[\S6]{VPAmult}\protect\footnote{See Caralp's dissertation~\cite[Théorème~4.4.1]{Caralp} for the proof (in French).}}]\label{thm:finamb}
  A trim $\bbN$-weighted tree automaton is bounded if and only if it does not contain
  any heavy cycle, nor any barbell.
\end{theorem}

A variant of this theorem was proved earlier by Seidl~\cite[Section~2]{Seidl}.
More precisely, for trim tree automata, he shows that unbounded ambiguity is
equivalent to the disjunction of two conditions (T1) and (T2). While these
conditions are stated in a local fashion using a \enquote{branch automaton}
(cf.~\Cref{rem:branch-automata}), whereas Caralp et al.~\cite{VPAmult} speak of
one-hole contexts, the proofs in~\cite[\S2]{Seidl} make it clear that:
\begin{itemize}
  \item (T1) corresponds precisely to side-ambiguous cycles, as we saw while proving Prop.~\ref{prop:side-amb};
  \item (T2) corresponds precisely to barbells (cf.~\cite[Fig.~3]{Seidl}).
\end{itemize}
Thanks to this last item we can also reuse the following result from~\cite{Seidl}:
\begin{lemma}[Seidl~{\cite[proof of Proposition~2.2]{Seidl}}]\label{lem:all-pairs-barbell}
  One can compute in cubic time all the pairs of states between which there is a
  barbell, i.e.\ the set $\{(q_1,q_{2}) \mid q_{1} \Rrightarrow q_{2}\}$.
\end{lemma}

Let us mention and rephrase the key idea of Seidl's algorithm, which is morally
the same as in the case of word automata (see for instance~\cite[proof of
Theorem~13]{AllauzenMR11}) modulo the fact that a one-hole context does not consist only of its central branch:
\begin{claim}
  Consider the shallow digraph of the product $\cA\times\cA\times\cA$. For each
  pair of states $q,q'$, let us add an edge from $(q,q',q')$ to $(q,q,q')$.
  Then $q_{1} \Rrightarrow q_{2}$ in $\cA$ if and only if:
  \begin{itemize}
    \item the vertices $(q_{1},q_{1},q_{2})$ and $(q_{1},q_{2},q_{2})$ are
          distinct, but belong to the same strongly connected component of this
          extended graph;
    \item this component contains some edge that was already in the shallow digraph of $\cA\times\cA\times\cA$.
  \end{itemize}
\end{claim}
\begin{remark}\label{rem:branch-automata}
  The presentation using \enquote{branch automata} in~\cite{Seidl} seems to be
  chosen in order to make algorithmic testing convenient. For us, this purpose
  is fulfilled by the linear-time construction of the shallow digraph
  (\Cref{lem:shallow-digraph}) which encapsulates the algorithmics needed to
  work effectively with conditions stated in terms of contexts.
\end{remark}

\subsection{Characterizing the polynomial degree of growth}\label{sec:chara-poly}

In this section, we consider the polynomially bounded case. In other words,
\textbf{we assume that our trim $\bbN$-weighted tree automaton $\cA$ has no heavy cycle}.

However, it may have barbells. Those play an important role in determining the
degree of growth, but the situation is a bit subtle (at least more so over trees
than over strings). This is already true in the unweighted case, when looking at the ambiguity.

\begin{example}\label{ex:exp-degree}
  Consider, for $N\in\bbN$, the tree automaton whose transitions are:
  \[ \{(c,q'),\; (q',b,q'),\; (q',b,q_{N}),\; (q_{N},b,q_{N}),\; (q_{N},q_{N},a,q_{N-1}),\; \dots,\; (q_{1},q_{1},a,q_{0})\} \]
  (where $\rank(a)=2$, $\rank(b)=1$ and $\rank(c)=0$), with accepting state $q_{0}$.

  It has a single pair of states forming a barbell, namely
  $q' \Rrightarrow q_{N}$ (this can be witnessed by the context $b(\square)$, or
  by $b(b(\square))$, etc.). At the same time, the degree of growth of its
  ambiguity is ${2^{N}}$.
\end{example}

We now introduce patterns involving barbells that
witness lower bounds for the degree of growth. They are finite ranked trees over
an infinite alphabet that consists of the original ranked alphabet $\Sigma$
plus, for each one-hole context $C$, a rank 1 node $\pumpnode{C}$.
\begin{definition}\label{def:pumping}
  We define inductively the \emph{pumping patterns} for each state of $\cA$:
  \begin{itemize}
    \item if $\cA$ contains a transition $(q_1,\dots,q_k,a,q)$ and
          $\Pi_{i}$ is a pumping pattern for $q_{i}$, for each $i\in\{1,\dots,k\}$,
          then $a(\Pi_{1},\dots,\Pi_{k})$ is a pumping pattern for $q$;
    \item if $q' \Rrightarrow_{C} q$ and $\Pi'$ is a pumping pattern for $q'$ then
          $\pumpnode{C}(\Pi')$ is a pumping pattern for $q$.
  \end{itemize}
  The \emph{degree} $\deg(\Pi)$ of a pattern $\Pi$ is its number of
  $\pumpnode{-}$ nodes. For $n\in\bbN$, by structural induction on a pumping
  pattern, we set:
  \begin{align*}
    \pump(n,a(\Pi_{1},\dots,\Pi_{k})) &= a(\pump(n,\Pi_{1}),\dots,\pump(n,\Pi_{k}))\\
    \pump(n,\pumpnode{C}(\Pi)) &= C^{n}[\pump(n,\Pi)]
  \end{align*}
\end{definition}
\begin{remark}
  If $t\in\tree\Sigma$ admits a run ending in state $q$ at the root, then $t$
  can be seen as a pumping pattern of degree 0 for $q$. In particular, since
  the tree automaton $\cA$ is assumed to be trim, for any state there is at
  least one pumping pattern.
\end{remark}

As a non-degenerate example, the automaton of Ex.~\ref{ex:exp-degree}
(parameterized by $N\in\bbN$) admits a pumping pattern $\Pi_{N}$ of degree
$2^{N}$, defined by $\Pi_{0} = \pumpnode{b(\square)}(c)$ and
$\Pi_{i+1} = a(\Pi_{i},\Pi_{i})$, for $i\in \set{0,\ldots,N-1}$.

\begin{claim}\label{clm:pump-lower-bound}
  Let $\Pi$ be a pumping pattern for a state $q$ and $q \to_{C} q_{\mathsf{a}}$ where
  $q_{\mathsf{a}}$ is accepting. Then $|C[\pump(n,\Pi)]|=O(n)$ while the ambiguity over
  $C[\pump(n,\Pi)]$ is at least $n^{\deg(\Pi)}$.
\end{claim}
\begin{claimproof}
  We only detail the proof for the lower bound on the ambiguity. It suffices to
  show that there are at least $n^{\deg(\Pi)}$ runs on $\pump(n,\Pi)$ with $q$
  at the root. By structural induction:
  \begin{description}
    \item[case $\Pi=a(\Pi_{1},\dots,\Pi_{k})$:] by definition, there is a
          transition $(q_{1},\dots,q_{k},a,q)$ such that each $\Pi_{i}$ is a
          pumping pattern for $q_{i}$. By induction hypothesis, there are at
          least $n^{\deg(\Pi_{i})}$ runs on $\pump(n,\Pi_{i})$ with $q_{i}$ at
          the root. These runs plus the aforementioned transition can be
          assembled to yield
          $n^{\deg(\Pi_{1})} \times \dots \times n^{\deg(\Pi_{k})} = n^{\deg(\Pi)}$
          distinct runs on $\pump(n,\Pi)$.
    \item[case $\Pi = \pumpnode{C}(\Pi')$:] by definition, $\Pi'$ is a pumping
          pattern for some state $q'$ such that $q' \Rrightarrow_{C} q$. The key
          observation (from~\cite[proof of Proposition~2.2]{Seidl}) is that
          there are at least $n$ runs over the context $C^{n}$ with $q'$ at the
          hole and $q$ at the root, namely:
          \[ \overbrace{q' \to_{C} \dots \to_{C} q'\phantom{'}}^{\text{\(m-1\) times \(C\)}} \to_{C} \overbrace{\phantom{'}q \to_{C} \dots \to_{C} q}^{\text{\(n-m\) times \(C\)}} \]
          These runs over $C^{n}$ can be plugged with the $n^{\deg(\Pi')}$ runs over $\pump(n,\Pi')$ with $q'$ at the root to give $n\times n^{\deg(\Pi')}=n^{\deg(\Pi)}$ runs on $\pump(n,\Pi)$. \claimqedhere
  \end{description}
\end{claimproof}

\noindent
The ambiguity of $\cA$ on an input is at most its value on the same input, and
we have assumed in this subsection that $\cA$ is polynomially bounded. Together
with \Cref{clm:pump-lower-bound}, this entails that there must be a global bound
on the degrees of pumping patterns --- which ensures that the degree of a state,
introduced below, is a well-defined natural number. (It is an adaptation to
tree automata of the notion of \enquote{height of a state}
from~\cite[\S4.4.2]{gaetanPhD}.)
\begin{definition}
  The \emph{degree} $\deg(q)$ is the maximum degree of a pumping pattern for $q$.
\end{definition}

\begin{claim}\label{clm:deg-ineq}
  These inequalities follow from the definition of pumping patterns:
    \begin{itemize}
    \item if $\cA$ contains a transition $(q_1,\dots,q_k,a,q)$ then
          $\deg(q_1) + \cdots + \deg(q_k) \leqslant \deg(q)$ -- in particular,
          $\deg$ is monotone with respect to $\to$;
    \item if $q' \Rrightarrow q$ then $\deg(q') + 1 \leqslant \deg(q)$.
  \end{itemize}
\end{claim}

\noindent
The degrees of the states are lower
bounds on the polynomial degree of growth of $\cA$. Next, we prove a
matching upper bound. To do so, we start by distinguishing some transitions.
\begin{definition}\label{def:critical}
  A transition $(q_{1},\dots,q_{m},a,q)$ is \emph{critical} when
  \[\deg(q) > \deg(q_{1}) + \cdots + \deg(q_{m}) \qquad [=0\ \text{when}\ m=0].\]
  A \emph{critical node} for a run over some tree is a node where the transition
  taken is critical.
\end{definition}

We may draw an analogy with flows in directed graphs: non-critical nodes satisfy
the \enquote{conservation of flow} equation
$\deg(q) = \deg(q_{1}) + \cdots + \deg(q_{m})$ while critical nodes serve as
\enquote{sources} for the flow of degrees. Since the root is the only
\enquote{sink}, we have:
\begin{claim}\label{clm:crit-degree}
  The number of critical nodes in a (not necessarily accepting) run is bounded
  by the degree of the state at the root.
\end{claim}
\begin{claimproof}[Proof idea]
  The degree at the root is the sum, for each node, of the \enquote{entering
    flow} at that node, i.e.\ $\deg(q) - \deg(q_{1}) - \cdots - \deg(q_{m})$ if
  the transition taken is $(q_{1},\dots,q_{m},a,q)$. Each critical node
  contributes $\geqslant1$ to that sum, while the other nodes contribute 0.
\end{claimproof}

Furthermore, the set of critical nodes of an accepting run in our $\bbN$-weighted tree automaton $\cA$ almost determines
this run, and the weight of this run is bounded:
\begin{lemma}\label{lem:crit-bounded}
  The sum of weights of accepting runs in $\cA$ over any given input tree whose set of critical
  nodes equals any prescribed value is bounded by a computable function of $\cA$.
\end{lemma}
\begin{proof}
  We build an $\bbN$-weighted tree automaton $\cB$ with the same states as $\cA$, but with input alphabet $\Sigma\times\{0,1\}$ (the ranks are inherited from $\Sigma$).
  For each critical (resp.\ non-critical) transition $(q_{1},\dots,q_{m},a,q)$ in $\cA$, we add a transition $(q_{1},\dots,q_{m},(a,[\text{1 (resp.\ 0)}]), q)$ to $\cB$, with the same weight. This way, the runs in $\cA$ over an input $t\in\tree\Sigma$ whose set of critical nodes is $S\subseteq\nodes(t)$ correspond precisely to the runs in $\cB$ over the tree $t_{S}$ obtained by replacing the label $a$ of each node $\nu$ by $(a,1)$ if $\nu\in S$ or by $(a,0)$ if $\nu\notin S$.

  Therefore, it suffices to show that $\cB$ is bounded. To do so, we apply \Cref{thm:finamb}. Let us check its assumptions:
  \begin{itemize}
    \item $\cA$ is trim and has no heavy cycles (by assumption), therefore $\cB$ too.
    \item Suppose for the sake of contradiction that $q_{1} \Rrightarrow_{C} q_{2}$ in $\cB$. Then in $\cA$, $q_{1} \Rrightarrow q_{2}$ is witnessed by the context obtained from $C$ by projecting on the first component; thus, $\deg(q_{1}) < \deg(q_{2})$ (we only speak of degrees in $\cA$). Furthermore, by definition of $\Rrightarrow$, we have $q_{1} \to_{C} q_{1}$ and $q_{1} \to_{C} q_{2}$ in $\cB$. These are jointly impossible because, by a \enquote{conservation of flow} argument (cf.\ above), if $q' \to_{C} q''$, then $\deg(q') < \deg(q'')$ if and only if $C$ contains a node with label in $\Sigma\times\{1\}$.
  \end{itemize}
  Finally, the maximum value of $\cB$ can be computed by translating it into an $\bbN$-weighted visibly pushdown automaton ($\bbN$-VPA) --- see~\cite[Appendix~C.2]{VPAmult} or~\cite[\S2.3.3]{Caralp} --- then applying the exponential-time algorithm of Caralp et al.~\cite[Theorem~4]{VPAmult} for $\bbN$-VPA.
\end{proof}

\noindent
We are now in a position to bound the value of $\cA$ over an input tree of size $n$:
\begin{itemize}
  \item there are $O(n^{\max(\deg(\text{states}))})$ possible sets of critical
        nodes for the runs by \Cref{clm:crit-degree};
  \item for each of these possibilities, the contribution of the corresponding
        runs to the total value is $O(1)$ by the above lemma.
\end{itemize}
Combined with the matching lower bound obtained in \Cref{clm:pump-lower-bound}, we see that, using the definition of growth rate from the beginning of the introduction:
\begin{claim}\label{clm:growth-tight-bound}
  $\growth[\cA](n) = \Theta(n^{\max(\deg(\text{states}))})$.
\end{claim}
Thus, to prove \Cref{thm:degree-weighted}, we just have to efficiently compute the degrees.

\subsection{Computing the degrees of all states in cubic time}

To compute the degree map, we first characterize it more abstractly as the
\emph{smallest} map that satisfies the inequalities of \Cref{clm:deg-ineq}. In
other words:
\begin{lemma}\label{lem:deg-abstract}
  The function that maps each state to its degree is the least fixed point of
  \[ f \mapsto \left[ q \mapsto \max\left(\bigl\{f(q)\bigr\}\cup\left\{\sum_{i=1}^{k} f(q_i) \middle| (q_1,\dots,q_k,a,q)\ \text{trans.}\right\} \cup \Bigl\{f\bigl(q'\bigl)+1 \,\Big|\, q' \Rrightarrow q\Bigr\}\right) \right]. \]
\end{lemma}
\begin{proof}[Proof sketch]
  Let $S(q) = \{\deg(\Pi) \mid \Pi\ \text{is a pumping pattern for}\ q\}$. From
  \Cref{def:pumping} we can extract a direct inductive definition of $S$, that
  can be expressed by general considerations as a least fixed point in a lattice
  of set-valued functions. To translate this into an expression for the degree
  map, observe that $S(q) = \{0,\dots,\deg(q)\}$ (indeed, $S(q)$ is
  downwards-closed because $\pumpnode{C}(\Pi)$ can be replaced by $C[\Pi]$ to
  decrement the degree of a pattern).
\end{proof}

  To compute the degree map, we can iterate the above operator (starting from
  $q\mapsto0$) until we reach a fixed point. This naive algorithm terminates
  because it builds a bounded increasing sequence of $\bbN$-valued functions
  with finite domain: such a sequence must be finite.
  Slightly less naively, we can precompute
  $\{(q_{1},q_{2}) \mid q_{1}\Rrightarrow q_{2}\}$ in cubic time
  (cf.~\Cref{lem:all-pairs-barbell}) before iterating. Subsequently, each
  iteration can be carried out in quadratic time, by examining each of the
  $O(|\cA|)$ transitions once and each of the $O(|\cA|^{2})$ barbells once.

  To get a cubic bound on the total running time, it now suffices to show that \emph{the fixed point is reached after a linear number of iterations}.
  We denote by $f_\tau$ the map from states to $\bbN$ obtained after $\tau$
  iterations of the aforementioned operator, and by $Q(\tau)$ the set of states that are mapped to the correct value after $\tau$ iterations: $Q(\tau) = \{q \mid f_\tau(q)=\deg(q)\}$.
  We call a set of states $S$ a \emph{trigger} for a state $q$ if:
  \begin{itemize}
    \item either $S=\set{q'}$ and $q'\Rrightarrow q$ and $\deg(q)=\deg(q')+1$,
    \item or $S=\set{q_1,\ldots,q_k}$ and $\deg(q)=\sum_{i=1}^{k} \deg(q_i)$.
  \end{itemize}

\begin{claim}\label{clm:trigger}
   $Q(\tau+1)=Q(\tau) \cup \set{q \mid q\text{ has a trigger included in }Q(\tau)}$.
\end{claim}
\begin{claimproof}
  If a state $q$ has a trigger included in $Q(\tau)$, then this trigger witnesses that
  \[ \deg(q) \in \left\{\sum_{i=1}^{k} f_\tau(q_i) \middle| (q_1,\dots,q_k,a,q)\ \text{trans.}\right\} \cup\{f_\tau(q')+1 \mid q' \Rrightarrow q\} \]
  Actually, this is an equivalence. Indeed, let's say that $\deg(q) = f_\tau(q')+1$ for some $q' \Rrightarrow q$ (the other case is similar). Because of the barbell, $\deg(q')+1 \leqslant \deg(q)$, so we have $f_\tau(q')\geqslant\deg(q')$. But the converse inequality is an invariant of the algorithm, so $f_\tau(q')=\deg(q')$, i.e.\ the trigger $\{q'\}$ is included in $Q(\tau)$.

  The result follows by comparing this equivalence with the definition of $f_{\tau+1}$ from $f_\tau$.
\end{claimproof}
\begin{claim}
  If $Q(\tau+1)=Q(\tau)$ then a fixed point is reached in at most $\tau$ iterations.
\end{claim}
\begin{claimproof}
  As a consequence of the previous claim, whenever $Q(\tau+1)=Q(\tau)$, for any $N\in\bbN$ we have $Q(\tau)=Q(\tau+N)$. This means that the fixed point has been reached: indeed, by definition, the algorithm halts at the first time $\tau'$ when $Q(\tau')$ is the full set of states.
\end{claimproof}

Thus, $Q(\tau)$ has to be strictly increasing before it stabilizes. Therefore, the number of iterations is bounded by the number of states. This concludes the proof of \Cref{thm:degree-weighted}.

\begin{remark}
  In the case of word automata, the computation of the degrees can be seen as a
  longest-path problem in a weighted graph without positive cycles: take the
  transitions of the automaton as weight 0 edges, and barbells as weight 1
  edges. This problem can be solved by the classical Bellman--Ford algorithm
  (cf.~\cite[\S8.4]{DurrVie}), whose iterative relaxations are very similar to
  our own procedure.
\end{remark}

\section{Reparameterization of MSO queries}
\label{sec:queries}

Let us now deduce \Cref{thm:reparam-intro} (stated in more detail as
\Cref{thm:reparam-details}) from the properties of critical transitions that we
just saw in the previous section.

We use the standard definition of monadic second-order (MSO) logic and its
semantics over relational structures; see for instance~\cite[Chapter~5]{courcellebook}. As
usual, uppercase letters $X,Y,\ldots$ denote second-order variables (ranging
over subsets of the domain) whereas lowercase letters $x,y,\ldots$ denote
first-order variables (ranging over elements of the domain). A formula is closed
when it has no free variables.

\subparagraph{Trees and DAGs as relational structures.}

To a ranked alphabet $\Sigma$, we associate a relational signature that consists of:
\begin{itemize}
  \item a unary symbol $a$ for each $a\in \Sigma$;
  \item a binary symbol $\child_i$ for each $i\in\set{1,\ldots,\max(\rank(\Sigma))}$;
  \item a binary symbol $\leqslant$.
\end{itemize}
\begin{definition}
We define a \emph{rooted DAG (directed acyclic graph)} over $\Sigma$ to be a finite structure $\graph$ over the above signature, such that the following hold:
\begin{itemize}
  \item $\graph$ interprets the formula $\child_1(x_1,x_2)\lor\dots\lor\child_{\max(\rank(\Sigma))}(x_1,x_2)$
    as an \emph{irreflexive and acyclic} binary relation over its domain, whose reflexive transitive closure is equal to $\leqslant$;
  \item the partial order $\leqslant$ has a unique minimum element, called the \emph{root};
  \item for each vertex (i.e.\ domain element) $u\in\dom(\graph)$:
    \begin{itemize}
    \item there is a unique $a\in\Sigma$ such that $G\models a(u)$;
    \item for $i\in\set{1,\ldots,\rank(a)}$, there is a unique $v \in \dom(\graph)$ such that $\graph\models \child_i(u,v)$;
    \item for $i > \rank(a)$, there is no $v\in \dom(\graph)$ such that $\graph\models \child_i(u,v)$.
    \end{itemize}
\end{itemize}
When $\graph\models u \leqslant v$, we say that $u$ is an \emph{ancestor} of $v$ and that $v$ is a \emph{descendant} of $u$.
\end{definition}
\begin{remark}
  All these axioms are definable in MSO.
\end{remark}

Let us illustrate the power of MSO for querying DAGs encoded as relational structures.
\begin{example}\label{ex:paths}
  A \emph{rooted path} in $\graph$ is a finite sequence $(u_{0},i_{1},u_{1},\dots,i_{n},u_{n})$ such that:
  \begin{itemize}
    \item $u_{0}$ is the root;
    \item $\graph\models \child_{i_{k}}(u_{k-1},u_{k})$ for $k\in\{1,\dots,n\}$.
  \end{itemize}
  We may encode such a path as an $r$-tuple of sets, for $r=\max(\rank(\Sigma))$:
  \[ (P_{1},\dots,P_{r}) \in \powerset(\dom(\graph))^{r} \quad\text{where}\quad P_{i} = \{u_{k-1} \mid k \in \{1,\dots,n\},\; i_{k} = i\}\]
  (in particular, the path with only the root ($k=0$) is encoded as $(\varnothing,\dots,\varnothing)$).

  Then $\vec{P}$ is an encoding of a rooted path if and only if $\graph\models \Fpath(\vec{P})$
  for some MSO formula $\Fpath(X_{1},\dots,X_{r})$. We can then say that this formula defines an MSO set query whose results are the rooted paths.
  Explicitly, $\Fpath$ may be defined as the conjunction of:
  \begin{itemize}
    \item $\forall x.\; X_{i}(x) \Rightarrow \displaystyle\bigvee_{\mathclap{a\in\Sigma,i\leqslant\rank(a)}} a(x)$ (take one such subformula for each $i\in\{1,\dots,r\}$);
    \item $\forall x.\; \displaystyle\bigvee_{\mathclap{1\leqslant i \leqslant r}} X_{i}(x) \Rightarrow\Big( (\forall y.\; x \leqslant y) \lor \bigvee_{\mathclap{1\leqslant j\leqslant r}} \exists y.\; X_{j}(y) \land \child_{j}(y,x)\Big)$;
    \item the predicates $X_{i}$ define disjoint subsets (this can be expressed in MSO).
  \end{itemize}

\end{example}
\begin{remark}
  We work with structures whose interpretation of $\leqslant$ is fully
  determined by their interpretation of the other symbols. But from the point of
  view of expressive power, it is well known that having direct access to the
  descendent order makes a difference in first-order logic (see e.g.\ the
  introduction to~\cite{BenediktS09}) --- this is important for the
  decomposition of \Cref{lem:mso-via-fo}. It also matters for the structures
  outputted by MSO interpretations (\S\ref{sec:set-interpretations}), as
  explained in~\cite[\S2.2]{msoInterpretations}.
\end{remark}

Any tree over $\Sigma$ can be turned into a rooted DAG whose domain is the set
of nodes of the tree, with the intuitive interpretations of the relation
symbols. This defines an injection from trees to DAGs, whose range can be
characterized up to isomorphism of structures:
\begin{definition}
  If every vertex of a rooted DAG $\graph$ has its set of ancestors totally ordered
  by the descendant order $\leqslant$, then $\graph$ is called a \emph{tree structure}.
\end{definition}

For $t \in \tree\Sigma$ and $F$ a formula, we abbreviate \enquote{$[\text{the
      tree structure for}\ t] \models F$} as $t \models F$. This abuse of
notation extends to formulas with first-order (resp.\ second-order) variables
instantiated by nodes (resp.\ subsets of nodes) of $t$ --- as used, for
instance, in the introduction when defining the set query $\wn F$ specified
by an MSO formula $F(X_1,\dots,X_\ell)$.


\subparagraph{Logic-automata correspondence.}

The fundamental theorem of MSO on trees is that the sets of trees defined by
closed MSO formulas are precisely the regular tree languages: those recognized
by nondeterministic tree automata or equivalently by deterministic bottom-up tree
automata; cf.\ e.g.~{\cite[Theorem~2.7]{HandbookAutomataTrees}}. (The language recognized by an automaton is the set of inputs with an accepting run.) Furthermore, these
equivalences are effective, i.e.\ witnessed by computable translations. In fact,
the correspondence between MSO and tree automata works not just for closed
formulas defining languages, but also for formulas with free variables defining
queries, as follows:\footnote{Indeed, one classical proof --- which is the one given in~\cite[proof of Theorem~2.7]{HandbookAutomataTrees} --- of this correspondence translates MSO to tree automata by induction over the syntax; the induction hypothesis needs to apply to subformulas with free variables, so it ends up being the statement of \Cref{thm:mso-vs-tree-automata} that is proved. Alternatively, \Cref{thm:mso-vs-tree-automata} can be quickly reduced to the case of closed formulas.}
\begin{theorem}\label{thm:mso-vs-tree-automata}
  Let $\ell\in\bbN$ and, for each $t\in\tree\Sigma$, let $\Xi_t \subseteq \powerset(\nodes(t))^\ell$.
  The following are equivalent, with effective conversions:
  \begin{itemize}
    \item there is an MSO formula $F(X_1,\dots,X_\ell)$ such that $\Xi_t = \wn F(t)$ for all $t\in\tree\Sigma$;
    \item the \enquote{language of marked trees} $\{\marked(t,\vec{P}) \mid t\in\tree\Sigma,\, \vec{P} \in \Xi_t\} \subseteq \tree(\Sigma\times\{0,1\}^\ell)$ is regular, where $\marked(t,P_1,\dots,P_\ell)$ is the tree such that
    \begin{itemize}
      \item by projecting all labels to their first coordinate, one recovers the tree $t$ (for this to make sense, we define the ranks on $\Sigma\times\{0,1\}^{\ell}$ to be inherited from the ranks on $\Sigma$);
      \item the $(i+1)$-th coordinate of the label of a node is 1 if and only if the corresponding node in $t$ belongs to $P_{i}$.
    \end{itemize}
  \end{itemize}
\end{theorem}

\subparagraph{Number of query results vs ambiguity.}

Let $F(X_{1},\dots,X_{\ell})$ be an MSO formula on trees over the ranked alphabet $\Sigma$. Let $\cA_{F}$ be an \emph{unambiguous} tree automaton over $\Sigma\times\{0,1\}^{\ell}$ --- e.g.\ a deterministic bottom-up tree automaton --- that recognizes the corresponding language of marked trees, according to \Cref{thm:mso-vs-tree-automata}. We build another automaton $\cB_{F}$ as follows:
\begin{itemize}
  \item its states are of the form $(q,a,\vec{b})$ where $q$ is a state of $\cA_{F}$ and $(a,\vec{b}) \in \Sigma\times\{0,1\}^{\ell}$;
  \item the accepting states in $\cB_{F}$ are those whose first component is accepting in $\cA_{F}$;
  \item its transitions are $((q_{1},a_{1},\vec{b}_{1}),\dots,(q_{m},a_{m},\vec{b}_{m}),a,(q,a,\vec{b}))$ for each $\vec{b}_{1},\dots,\vec{b}_{m},\vec{b}\in\{0,1\}^{\ell}$ and $a\in\Sigma$ such that $\cA_{F}$ contains the transition $(q_{1},\dots,q_{m},(a,\vec{b}),q)$.
\end{itemize}
\begin{claim}[Explicit version of~\Cref{clm:query-vs-ambiguity-intro}]\label{clm:query-vs-ambiguity}
  The results of the query $\wn F$ are in canonical bijection with the set of accepting runs of $\cB_{F}$ over every input tree in $\tree\Sigma$.
\end{claim}
\begin{claimproof}
  By construction, the accepting runs of $\cB_{F}$ over an input $t\in\tree\Sigma$
  are in bijection with
  \[ \{ (t',\; \underbrace{\text{some accepting run of}\ \cA_{F}\ \text{over}\ t'}_{\mathclap{\text{unique because}\ \cA_{F}\ \text{is unambiguous}}}) \mid [\text{project node labels on}\ \Sigma](t') = t \} \]
  By definition of
  the language of marked trees recognized by $\cA_{F}$, the trees $t'$ appearing in the above set are
  precisely those of the form $\marked(t,\vec{P})$ for $\vec{P} \in \wn F(t)$.
\end{claimproof}

As stated in the introduction, the properties that we have established
concerning the ambiguity of tree automata can therefore be transferred to MSO set
queries. Since the correspondence in \Cref{thm:mso-vs-tree-automata} is
effective, what we get is:
\begin{corollary}\label{cor:set-query-growth}
  The number of results of an MSO set query grows either polynomially or
  exponentially in the input size, with a computable degree in $\bbN\cup\{\infty\}$.
\end{corollary}

\subparagraph{The reparameterization theorem.}

In the case of polynomial growth, we have:

\begin{theorem}[precise statement of {\Cref{thm:reparam-intro}}]\label{thm:reparam-details}
  Given an MSO formula $F(X_1,\dots,X_\ell)$ over trees on $\Sigma$ whose
  number of results has a growth rate of degree $k < \infty$, one can compute
  an MSO formula $G(X_1,\dots,X_\ell,z_1,\dots,z_k)$ and $B\in\bbN$ such that,
  for every $t \in \tree\Sigma$:
  \begin{itemize}
    \item $\wn G(t) \subset \powerset(\nodes(t))^{\ell} \times \nodes(t)^{k}$ is the graph of some map $g_{t} \colon \wn F(t) \to \nodes(t)^{k}$;
    \item this map satisfies $|g_{t}^{-1}(\{u\})| \leqslant B$ for every $u \in \nodes(t)$.
  \end{itemize}
  Thus, $(g_{t})_{t\in\tree\Sigma}$ is a finite-to-one family of functions with computable bound.
\end{theorem}
\begin{example}\label{ex:gpath}
  Consider the MSO formula $\Fpath(X_{1},\dots,X_{r})$ where
  $r=\max(\rank(\Sigma))$ from \Cref{ex:paths}, which selects the encodings of
  rooted paths in a DAG over $\Sigma$. As announced in the introduction
  (\Cref{ex:paths-intro}), over \emph{trees}, the query $\wn\Fpath$ has linear
  growth, and there is an explicit reparameterization: map each rooted path
  to its endpoint (i.e.\ the last vertex in the path), which determines the path uniquely ($B=1$):
  \[ \Gpath(\vec{X},z) = \Fpath(\vec{X}) \land \forall z'.\; z \leqslant z' \Leftrightarrow \overbrace{\bigwedge_{\mathclap{1\leqslant i \leqslant r}} \forall x.\,\forall y.\, X_{i}(x) \land \child_{i}(x,y) \Rightarrow y \leqslant z'}^{\text{\enquote{\(z'\) is an upper bound of all vertices in the path}}} \]
  This MSO formula selects the endpoint of a rooted path in any rooted DAG --- a level of generality that will be convenient for later reuse. (Though this is not finite-to-one over DAGs; in fact, there
  can be up to exponentially many rooted paths to a given endpoint.)
\end{example}
\begin{proof}[Proof of \Cref{thm:reparam-details}]
  Let $\cB'_{F}$ be obtained by trimming the tree automaton $\cB_{F}$ defined earlier; they have the same accepting runs.
  By the assumption $k <\infty$ and \Cref{clm:query-vs-ambiguity}, $\cB'_{F}$ is polynomially ambiguous: it satisfies the assumptions of \Cref{sec:chara-poly}. This allows us to speak of the critical nodes for the runs of $\cB'_{F}$ (\Cref{def:critical}).
  Using the bijective correspondence of \Cref{clm:query-vs-ambiguity}, we can define a family of functions indexed by $t\in\tree\Sigma$ as follows:
  \[ \vec{P} \in \wn F(t) \mapsto \{\text{critical nodes for the accepting run of}\ \cB'_{F}\ \text{over}\ t\ \text{corresponding to}\ \vec{P}\} \]
  By \Cref{lem:crit-bounded}, this family is finite-to-one with computable bound. Furthermore, it can be defined in MSO by some formula $H(X_{1},\ldots,X_{\ell},Y)$ using standard techniques for representing runs of tree automata in MSO. Note also that the range of any function in this family only contains sets of nodes of cardinality at most $k$, according to Claims~\ref{clm:crit-degree} and~\ref{clm:growth-tight-bound}.

  The next step is to devise an MSO formula $J(Y,z_{1}\dots,z_{k})$ that defines a finite-to-one family of functions
  $\{ \text{subsets of}\ \nodes(t)\ \text{of size} \leqslant k \} \to \nodes(t)^{k}$ for $t\in\tree\Sigma$.
  One possible solution is to use a prefix of the output tuple to list the elements of the input set, in a fixed MSO-definable order, and pad the remaining output coordinates with the root node.

  Finally, we take $G(\vec{X},\vec{z}) = \exists Y.\, H(\vec{X},Y) \land J(Y,\vec{z})$. This works because the composition of two finite-to-one families of functions is itself finite-to-one.
\end{proof}


\section{Dimension minimization for MSO set interpretations}
\label{sec:set-interpretations}

We now apply the newly established \Cref{thm:reparam-details} to prove \Cref{thm:msosi-min}.

Let us first recall the notion of MSO set interpretation. The basic idea is that
the domain of an output structure contains the results of an MSO set query over
the input structure.
\begin{definition}
  \label{def:mso-set-interp}
  An \emph{MSO set interpretation} $\cI$ from a family of finite relational
  structures to another, over fixed input and output signatures, consists of a
  positive integer\footnote{Strictly speaking, Colcombet and Löding's original
    definition~\cite[\S2.3]{ColcombetL07} corresponds to taking $\ell=1$. The
    case $\ell>1$ has been considered for example by Rabinovich and
    Rubin~\cite[§II.C]{RabinovichR12} and by Filiot, Lhote and
    Reynier~\cite{Lex}; as far as we know, it does not pose additional
    difficulties.} $\ell$ and some MSO formulas over the
  input signature with \emph{second-order} free variables:
  \[  \cI_\dom(X_1,\dots,X_\ell) \qquad\qquad \underbrace{\cI_R(X_{1,1},\dots,X_{1,\ell},X_{2,1},\dots,X_{m,\ell})}_{\mathclap{\text{for each $m$-ary relation symbol $R$ in the output signature}}}\]
  It defines the function $f$ such that $\dom(f(S)) = \wn\cI_{\dom}(S)  \subseteq \powerset(\dom(S))^{\ell}$ and
  \[ f(S) \models R(\langle P_{1,1},\dots,P_{1,\ell}\rangle,\dots, \langle P_{m,1},\dots,P_{m,\ell}\rangle) \quad \iff \quad S\models\cI_R(P_{1,1},\dots,P_{m,\ell})\]
  for every input structure $S$ and output symbol $R$.
\end{definition}

An MSO set interpretation maps isomorphic inputs to isomorphic outputs. We may therefore identify structures up to isomorphism; this allows us to treat trees (processed by automata and transducers) and tree structures (handled by interpretations) interchangeably without losing relevant information.
\begin{example}
  \label{ex:unfold}
  We define the \emph{unfolding} $\unfold(\graph)$ of a rooted DAG $\graph$, illustrated by the right-hand side of \Cref{fig:msots}, as a tree structure (over the same ranked alphabet $\Sigma$):
  \begin{itemize}
    \item the domain elements (nodes) are the rooted paths in $\graph$, cf.\ \Cref{ex:paths};
    \item each path $\pi\in\dom(\unfold(\graph))$ inherits the label of its endpoint: $\unfold(\graph) \models a(\pi)$ if and only if $\pi = (\dots,u)$ with $\graph\models a(u)$;
    \item the descendent order $\leqslant$ is the prefix ordering on paths;
    \item $\unfold(\graph) \models \child_{i}(\pi,\pi')$ for
          $\pi,\pi' \in \dom(\unfold(\graph))$ if and only if $\pi$ extended by
          going to the $i$-th child of its endpoint equals $\pi'$ --- in other
          words, the two paths are of the form $(u_{0},i_{1},u_{1},\dots,u_{n})$ and
          $(u_{0},i_{1},u_{1},\dots,u_{n},i,u_{n+1})$ respectively.
  \end{itemize}
\begin{figure}
  \centering
    \begin{tikzpicture}
