\subsection{Optimization function}

The operation cost of a total number of $\mathrm{I}$ DCs will be optimized at the same time using: 
\begin{equation}
    \min \mathrm{\sum\nolimits_{i=1}^{I} {\left( {\omega ^{OC} C_i^{OC} + \omega ^{EC} C_i^{EC} +\omega ^{Mig}  C_i^{Mig} } \right)}}
    \label{eq:obj}
\end{equation}
where, $\mathrm{C_i^{Mig}}$ is the workload migration cost, and $\mathrm{i}$ is the DC index. $\mathrm{\omega ^{OC}}$, $\mathrm{\omega ^{EC}}$, and $\mathrm{\omega ^{Mig}}$ are weighting coefficients that reflect the relative importance of the three items.
\subsubsection{Operation cost $\mathrm{C^{OC}}$} To minimize the operational carbon cost of DCs, we require the grid power consumption $\mathrm{P_{i}^{grid}(t)}$ and regional carbon intensity $\mathrm{CI^{OC}_{i}(t)}$, monetized through the coefficient of carbon emission cost  $\mathrm{\alpha^{C}}$ ($\mathrm{\$/kgCO_2}$)  using:
\begin{equation}
    \mathrm{C_i^{OC} = \sum\nolimits_{t=1}^{24} {\alpha ^{C}CI^{OC}_{i}(t)P_{i}^{grid}(t)\Delta t}} 
    \label{eq:Carcost}
\end{equation}
where, $\mathrm{\Delta t}$ is the time interval of the operating strategy, which is 1 hour.

\subsubsection{Embodied carbon emission} 

The daily embodied carbon emissions $\mathrm{C_{i}^{EC}}$ of $\mathrm{i^{th}}$ DC is the sum of the embodied carbon emission from $\mathrm{K}$ server groups, given by:
\begin{equation}
    \mathrm{C_{i}^{EC} = \sum\nolimits_{k=1}^{K} {C_{k,i}^{EC}}}
    \label{eq:EC1}
\end{equation}
To estimate the daily embodied carbon emission $\mathrm{C_{k, i}^{EC}}$ of the server group $\mathrm{k}$ in $\mathrm{i^{th}}$ DC, a model based on the entire lifetime of the servers or its component is proposed: 
\begin{equation}
    \mathrm{C_{k,i}^{EC} = {\alpha ^C}CI_{k,i}^{EC}{N_{k,i}}\Delta {t^{Eq}_{k,i}}} 
    \label{eq:EC2}
\end{equation}
where, $\mathrm{N_{k,i}}$ is the number of servers. $\mathrm{\Delta {t^{Eq}_{k,i}}}$ is measured in units of day, corresponding to the equivalent daily operating time of server cluster $\mathrm{k^{th}}$.
The daily embodied carbon intensity $\mathrm{CI_{k,i}^{EC}}$ is calculated using \eqref{eq:EC3}, where the manufacturing carbon footprint $\mathrm{C_{k,i}^{M}}$ of $\mathrm{N_{k,i}}$ servers is distributed into its expected calendar lifetime $\mathrm{T_{k,i}^{Can}}$.
\begin{equation}
    \mathrm{CI_{k,i}^{EC} = \frac{{C_{k,i}^{M} \cdot N_{k,i}}}{T_{k,i}^{Can}}}
    \label{eq:EC3}
\end{equation}

As shown in Fig. \ref {lifetime} and defined in \eqref{eq:EC4}, the expected calendar lifetime $\mathrm{T_{k,i}^{Can}}$ of server group $\mathrm{k}$ should be calculated based on its past calendar operating time $\mathrm{T_{k,i}^{PC}}$ and its expected future calendar operating time $\mathrm{T_{k,i}^{FC}}$. It is worth notifying that the past calendar operating time can be easily obtained by checking the records of server or component purchases.
\begin{figure}[t]
    \centering
    \includegraphics[width=0.9\linewidth]{figures/Fig34.pdf}
    \vspace{-9pt}
    \caption{Relationship between expected calendar lifetime and expected operating lifetime. Expected server’s calendar lifetime $T^{\mathrm{T^{Can}}}$ consists of past calendar operating time $T^{\mathrm{T^{PC}}}$ and future calendar operating time $T^{\mathrm{T^{FC}}}$.  $T^{\mathrm{T^{FC}}}$ is estimated by the expected future operating lifetime $T^{\mathrm{T^{FO}}}$ and operation during the dispatched day.}
    \label{lifetime}
    \vspace{-9pt}
\end{figure}

\begin{equation}
    \begin{split}
    \mathrm{T_{k,i}^{Can}} &= \mathrm{\left( {T_{k,i}^{PC} + T_{k,i}^{FC}} \right) {N_{k,i}}}\\
    &= \mathrm{\left( {T_{k,i}^{PC} + T_{k,i}^{RO}\frac{{{T^{day}}}}{{\Delta {t^{Eq}}}}} \right) {N_{k,i}}}
    \end{split}
    \label{eq:EC4}
\end{equation}
\begin{equation}
    \mathrm{T_{k,i}^{FO} = T_{k,i}^{Life} - T_{k,i}^{PO}}
    \label{eq:EC5}
\end{equation}
where, $\mathrm{T_{k,i}^{FO}}$ is the remaining operation time. By dividing the daily consumed operating time $\mathrm{\Delta t_{k,i}^{Eq}}$ by $\mathrm{T_{\text{day}}}$, the operating time consumed speed can be estimated, further deducing the expected future calendar time based on the remaining operating time $\mathrm{T_{k,i}^{on}}$. The daily equivalent operating time $\mathrm{\Delta t_{k,i}^{Eq}}$ is given by:
\begin{equation}
    \begin{split}
    \mathrm{\Delta {t^{Eq}}} &= \mathrm{\frac{{\sum\nolimits_{t=1}^{24} {N_{k,i}^A(t)} \Delta t}}{{\sum\nolimits_{t=1}^{24} {{N_{k,i}(t)}} \Delta t}}{T^{day}}}=\frac{\sum\nolimits_{t=1}^{24} {N_{k,i}^A(t)}}{24{N_{k,i}}}
    \end{split}
    \label{eq:EC6}
\end{equation}
where, $\mathrm{N_{k,i}^{A}(t)}$ is the number of dispatched servers in the group $\mathrm{k}$ of DC $\mathrm{i}$ at time $\mathrm{t}$ and $\mathrm{N_{k,i}(t)}$ denotes the number of total servers in group $\mathrm{k}$ of DC $\mathrm{i}$ at time $\mathrm{t}$.  On top, $\mathrm{T^{day}}$ denotes the length of the dispatched day, which is 1 day. $\mathrm{\Delta t_{k,i}^{Eq}}$ take 1 day as unit.

Using (3)-(8), the daily embodied carbon emission $\mathrm{C_{i}^{EC}}$ can be given by:
\begin{equation}
    \mathrm{C_i^{EC} = \sum\nolimits_{k=1}^{K} {\frac{{C_{k,i}^{M} {{\left( {\sum\nolimits_{t=1}^{24} \cfrac{N_{k,i}^{A}(t)}{24} } \right)}^2}}}{{T_{k,i}^{PC} \sum\nolimits_{t=1}^{24} {\cfrac{N_{k,i}^{A}(t)}{24}}  + T_{k,i}^{FO} {N_{k,i}}}}}} 
    \label{eq:EC6}
\end{equation}

\subsubsection{Migration cost} This caters to the cost function associated with transferring workloads between DCs, given by:
\begin{equation}
    \mathrm{C_i^{Mig} =  {{\alpha ^{Mig}}{{\left| {\Delta W_{i,t}^I} \right|}}}} ,{\kern 1pt} {\kern 1pt} \ \mathrm{\forall i \in I}
    \label{eq:migracost}
\end{equation}
where, $\mathrm{\alpha ^{Mig}}$ is the coefficient of migration cost with unit of  $\mathrm{\$/requests/s}$. 


\subsection{Workload Migration Model}

\subsubsection{Interactive Workload (IW) Modeling}
IWs refer to computing tasks or applications that require real-time interaction and responses, such as real-time payments and online services, which are \textit{delay-sensitive}. As a result, such workloads have spatial flexibility, which can be routed to another DC immediately as per the availability of computing resources. The migration model of interactive workload between different DCs can be modeled using:
\begin{equation}
    \mathrm{W_{i}^I(t) = W_{i}^{I,ini}(t) - \Delta W_{i}^I(t)	\ni   {W_{i}^I(t) \geq 0}}
    \label{eq:WI1}
\end{equation}
\begin{equation}
    \mathrm{\Delta W_{i}^I(t) = \sum\nolimits_{j \in I,j \ne i} {\Delta W_{i \to j}^I(t)}} \
    \label{eq:WI2}
\end{equation}
where, $\mathrm{W_{i}^{I,ini}(t)}$ and $\mathrm{W_{i}^I(t)} $ denote the interactive workload before and after migration at time $\mathrm{t}$ in DC $\mathrm{i}$, respectively. Furthermore, $\mathrm{\Delta W_{i}^I(t)}$ in (12) denotes the total received or migrated workload at time $\mathrm{t}$ in DC $\mathrm{i}$. It should be noted that $\mathrm{\Delta W_{i}^I(t)}$ is positive, when the workload is offloaded/moved out. To ensure all interactive workloads can be processed immediately, all migrated workloads should be processed such that $\mathrm{\sum\nolimits_{i=1}^{I} {\Delta W_{i}^I(t)} = 0}$. Furthermore, the amount of transferred workload is limited within the upper limit of the transmission fiber $\mathrm{\Delta W_{i \to j}^{I,ub}}$, given by:
\begin{eqnarray}
    \mathrm{| \Delta W_{i \to j}^{I}(t)|\le\Delta W_{i \to j}^{I,ub}} 
    \label{eq:WI4}
\end{eqnarray} 		
\subsubsection{Batch Workload (BW) Modeling}
BWs refer to the \textit{flexible} tasks that do not need to be addressed immediately and are sufficient to be completed before the deadline, such as data analysis and model training. Although this facilitates temporal flexibility for batch workloads while lacking spatial adjustment, they heavily rely on large-scale databases, which will incur significant migration costs. 

Based on Google's batch workload migration strategy \cite{9770383}, the batch workload transfer model is given by:
\begin{equation}
    \mathrm{W_{i}^B(t) = \frac{ \sum\limits_{t=1}^{24}{W_{i}^{B,ini}(t)}} {24} + \Delta W_{i}^B(t)} \ni {\small\begin{cases} \mathrm{W_{i}^B(t) \geq 0} \\ \mathrm{\sum\limits_{t=1}^{24} {\Delta W_{i}^B(t)}  = 0} \end{cases}}
    \label{eq:BI1}
\end{equation}
where, $\mathrm{W_{i}^{B,ini}(t)}$, $\mathrm{W_{i}^B(t)} $ and $\mathrm{\Delta W_{i}^B(t)}$ denote the batch workload before, after migration and the amount of transferred batch workload at time $\mathrm{t}$ in DC $\mathrm{i}$, respectively.

\subsection{Computing Resource Dispatch Strategy}  

Considering server heterogeneity and failure events, it is vital to account for a computing resource dispatch strategy and optimize workload allocation into available servers. To be specific, the server cluster and the number of primary and backup servers in each cluster will be optimized for dispatching decisions.

The workload accommodated by $\mathrm{k}$ server cluster are allocated in a dynamic manner using:
\begin{subequations}
    \begin{equation}
        \mathrm{W_{i}^I(t) = \sum\nolimits_{k=1}^{K} {W_{k,i}^I(t)}} 
   \end{equation}	
    \begin{equation}
        \mathrm{W_{i}^B(t) = \sum\nolimits_{k=1}^{K} {W_{k,i}^B(t)} }  
    \end{equation}	
    \label{eq:N1}
\end{subequations}
where, $\mathrm{W_{k,i}^I(t)}$ and $\mathrm{W_{k,i}^B(t)}$ denote the accommodated interactive and batch workloads in DC $\mathrm{i}$. It should be noted that the primary servers in cluster $\mathrm{k}$ should be sufficient to accommodate the total assigned workloads, as defined in: 
\begin{equation}
    \mathrm{0 \le [W_{k,i}^I(t) + W_{k,i}^B(t)] \le N_{k,i}^P(t) \cdot {S_{k,i}^{rate}} \cdot {u_{k,i}(t)}}
    \label{eq:N2}
\end{equation}
where, $\mathrm{N_{k,i}^P(t)}$, $\mathrm{S_{k,i}^{rate}}$, $\mathrm{u_{k,i}}$ denote the number of dispatched primary servers, the maximum speed of servers to deal with workloads, and the server utilization rate of the server cluster $\mathrm{k}$ in DC $\mathrm{i}$, respectively.

During the operating process of DCs, the dispatched servers should satisfy the relationship defined in Fig. \ref{Server relationship}. In a server cluster with $\mathrm{N_{k,i}}$ servers, except for the deployment of primary servers, backup resources $\mathrm{N_{k,i}^B(t)}$ should be reserved considering the failure events during server operation. To ensure sufficient backup resources under uncertain failure events, a chance-constrained programming is proposed, as follows: 
\begin{equation}
    \mathrm{Pr \left( N_{k,i}^F(t) \leq N_{k,i}^B(t) \right) \geq p^{thr}}
    \label{eq:N3}
\end{equation}
where, $\mathrm{N_{k,i}^F(t)}$ are the failed resources at time $\mathrm{t}$. More details on quantifying $\mathrm{N_{k,i}^F(t)}$ can be found in Section III.  $\mathrm{p^{thr}}$ is the target threshold probability. This constraint ensures that with at least $\mathrm{p^{thr}}$ confidence, the reserved backup servers are sufficient to cover the random failure events.

Hence, the servers with an \textit{active} status $\mathrm{N_{k,i}^A(t)}$ that can be dispatched are given by:
\begin{subequations}
    \begin{alignat}{2}
        \mathrm{N_{k,i}^P(t) + N_{k,i}^B(t) = N_{k,i}^A(t)}\\
        \mathrm{N_{k,i}^P(t) \ge 0, N_{k,i}^B(t)\ge 0}
    \end{alignat}
    \label{eq:N4}
\end{subequations}
Given that there will be failure events, servers that can be fully exploited will decrease with time. Software failures can typically be resolved by restarting the affected servers, leading to only a temporary reduction in the current hour. However, since hardware failures require a complex and time-consuming repair process, affected servers will not be available for the remainder of the dispatch day. Consequently, it results in a reduction in the remaining available servers $\mathrm{N_{k,i}^R}$, as follows:
\begin{equation}
    \mathrm{N_{k,i}^R(t) = N_{k,i} - \sum\nolimits_{\tau  = 1}^t {N_{k,i}^{F,H}(\tau)} }
    \label{eq:N5}
\end{equation}
where, $\mathrm{N_{k,i}^R(t)}$, $\mathrm{N_{k,i}^{F,H}(\tau)}$ denote the remaining available servers in cluster $\mathrm{k}$, and the number of failed servers due to hardware failure at time $\mathrm{\tau}$, respectively. More details on determining $\mathrm{N_{k,i}^{F,H}(\tau)}$ can be found in Section III.

Therefore, the dispatched active servers $\mathrm{N_{k,i}^A(t)}$ should not be above the remaining available servers $\mathrm{N_{k,i}^R(t)}$:
\begin{equation}
    \mathrm{0 \le N_{k,i}^A(t) \le N_{k,i}^R(t)}
    \label{eq:N6}
\end{equation}
