%
%              POLMAT --> TRUNCATED PRODUCT
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Polynomial matrix truncated product}
\label{sec:polmat:TruncatedProduct}

\begin{proposition}
  \label{prop:TruncatedProduct}
  Given \(\mat{F} \in \pmatspace{n}{m}\), \(\mat{G} \in \pmatspace{m}{m}\), and
  \(d = (d_j)_j \in \NN^m\), Algorithm \texttt{TruncatedProduct} uses
  \[
    \bigO{\sum_{0 \le k < \lceil \log_2(m) \rceil} \left\lceil 2^k \frac{n}{m} \right\rceil \timepmm{2^{-k}m}{2^k\left\lceil\frac{D}{m}\right\rceil}}
  \]
  operations in \(\field\) and returns the truncated product \((FG) \rem x^d\)
  that is, \(FG\) with column \(j\) truncated at order \(d_j\). Here, \(D\) is
  the maximum between \(\sumTuple{d}\) and the sum of the degrees of the
  nonzero columns of \(F\).
  If \(m\) is both in \(\bigO{n}\) and \(\bigO{D}\), this cost bound is
  in \(\bigO{m^{\expmm-2} n \timepm{D}}\).
\end{proposition}

\begin{proof}
  For convenience, we denote by \(I_k\) and \(J_k\) the sets \(I\) and \(J\)
  defined at the iteration \(k\) of the main loop of the algorithm. Let also
  \(R^{(k)}\) be the matrix \(R\) at the beginning of iteration \(k\), and
  \(R^{(\ell)}\) be the output \(R\). Let \(F^{(0:k)} = F \rem x^{2^k\delta}\) for
  \(1\le k \le \ell\), with in particular \(F^{(0:\ell)} = F\) since \(\max_j
  d_j \le \sumTuple{d} \le m\delta \le 2^\ell \delta\).

  At the beginning of the first iteration, \(R^{(1)} = (F^{(0)} G) \rem x^{d} =
  (F^{(0:1)} G) \rem x^{d}\). Then, to prove the correctness of the algorithm,
  we let \(k \in \range{\ell}\) and assume \(R^{(k)} = (F^{(0:k)} G) \rem
  x^{d}\), and we show \(R^{(k+1)} = (F^{(0:k+1)}G) \rem x^{d}\).

  First, consider \(j\not\in J_k\). The column \(j\) of \(R^{(k)}\) is not
  modified by iteration \(k\), i.e.\ \(\matcol{R}{j}^{(k)} =
  \matcol{R}{j}^{(k+1)}\). On the other hand, one has \(d_j < 2^k\delta\),
  hence \(F^{(0:k)} \rem x^{d_j} = F^{(0:k+1)} \rem x^{d_j}\). We obtain
  \[
    \matcol{R}{j}^{(k+1)}
    = \matcol{R}{j}^{(k)}
    = (F^{(0:k)}\matcol{G}{j}) \rem x^{d_j}
    = (F^{(0:k+1)}\matcol{G}{j}) \rem x^{d_j}.
  \]
  meaning that the sought equality holds for the columns \(j \not \in J_k\).

%\setcounter{algorithm}{4}
\renewcommand{\thealgorithm}{5}

\begin{algorithm}[t]
  \algoCaptionLabel{TruncatedProduct}{F,G,d}
  \begin{algorithmic}[1]
    \Require \(\mat{F} \in \pmatspace{n}{m}\), \(\mat{G} \in \pmatspace{m}{m}\),
        \(d = (d_1,\ldots,d_m) \in \NN^m\)
    \Ensure the column-truncated product \((FG) \rem x^d \in \pmatspace{n}{m}\)

    \State
    \(\gamma \gets\) sum of the degrees of the nonzero columns of \(F\)

    \State
    \(D \gets \max(\sumTuple{d},\gamma)\); ~~
    \(\delta \gets \lceil D/m\rceil\); ~~
    \(\ell \gets \lceil\log_2(m)\rceil\)

    \State
    write \(\mat{F} = \mat{F}^{(0)} + \sum_{1 \le k < \ell} \mat{F}^{(k)} x^{2^k\delta}\)
    with each \(F^{(k)}\) in \(\pmatspace{n}{m}\),
    \(\deg(F^{(k)}) < 2^k\delta\) for \(1 \le k < \ell\), and \(\deg(F^{(0)}) < 2\delta\)

    \State
    \(R \in \pmatspace{n}{m} \gets (F^{(0)}G) \rem x^d\) \Comment{stores the result}
    \label{step:TruncatedProduct:first_product}

    \For{\(k \gets 1,\ldots, \ell-1\)}
    \State \(I \gets \{i\in\range{m} \mid \cdeg{\matcol{F}{i}} \ge 2^k\delta\}\)
    \State \(J \gets \{j\in\range{m} \mid d_j \ge 2^k\delta\}\)
    \State \(e \gets (d_j - 2^k\delta)_{j \in J}\)
    \State \(\matcols{R}{J} \gets \matcols{R}{J} + \left((\matcols{F}{I}^{(k)}\submat{G}{I}{J}) \rem x^{e}\right) x^{2^k\delta} \)
        \label{step:TruncatedProduct:partial_product}
    \EndFor
    \State \Return \(R\)
  \end{algorithmic}
\end{algorithm}
  Now, consider \(j \in J_k\). For \(i\not\in I_k\), one has
  \(\cdeg{\matcol{F}{i}} < 2^k\delta\), hence \(\matcol{F}{i}^{(k)} = 0\): it
  follows that \(F^{(k)} \matcol{G}{j} =
  \matcols{F}{I}^{(k)}\submat{G}{I}{j}\). Thus
  Line~\ref{step:TruncatedProduct:partial_product} computes
  \begin{align*}
    \matcol{R}{j}^{(k+1)} \gets ~
       & \matcol{R}{j}^{(k)} + \left((\matcols{F}{I}^{(k)}\submat{G}{I}{j}) \rem x^{d_j - 2^k\delta}\right) x^{2^k\delta} \\
       & = (F^{(0:k)} \matcol{G}{j}) \rem x^{d_j} + (x^{2^k\delta}F^{(k)}\matcol{G}{j}) \rem x^{d_j} \\
       & = (F^{(0:k+1)}\matcol{G}{j}) \rem x^{d_j}.
  \end{align*}
  This completes the proof of correctness.

  For complexity, note that the definition of \(D\) gives \(\card{I_k} \le
  2^{-k}m\) and \(\card{J_k} \le 2^{-k}m\); also, only
  Lines~\ref{step:TruncatedProduct:first_product} and \ref{step:TruncatedProduct:partial_product}
  use arithmetic operations.

  At Line~\ref{step:TruncatedProduct:first_product}, we first compute \(F^{(0)}G\),
  then truncate. The left and right matrices in this product are respectively
  \(n\times m\) of degree \(<2\delta\), and \(m\times m\) with sum of column
  degrees \(\le m\delta\). The product can be performed by expanding the
  columns of \(G\) into \(\le 2m\) columns all of degree \(\le\delta\), which leads
  to the complexity \(\bigO{\lceil \frac{n}{m} \rceil \timepmm{m}{\delta}}\).

  At Line~\ref{step:TruncatedProduct:partial_product}, the multiplication by a
  power of \(x\) is free. The sum consists in adding two matrices with \(n\)
  rows and with column degrees strictly less than \((d_j)_{j\in J_k}\)
  entry-wise.
  This costs \(\bigO{n \sumTuple{d}}\) operations in \(\field\) at each
  iteration, hence \(\bigO{\ell n \sumTuple{d}}\) in total. Using the trivial
  lower bound on \(\timepmm{\cdot}{\cdot}\) shows that this is within the
  claimed overall cost bound:
  \begin{align*}
    \ell n \sumTuple{d} \le \sum_{k=0}^{\ell-1} n D
                        & \le \sum_{k=0}^{\ell-1} \left\lceil 2^k \frac{n}{m} \right\rceil (2^{-k}m)^2 2^k \left\lceil \frac{D}{m} \right\rceil \\
                        & \in \bigO{\sum_{k=0}^{\ell-1} \left\lceil 2^k \frac{n}{m} \right\rceil \timepmm{2^{-k}m}{2^k\left\lceil\frac{D}{m}\right\rceil}}.
  \end{align*}

  Finally, for the truncated product, we first multiply
  \(\matcols{F}{I_k}^{(k)}\submat{G}{I_k}{J_k}\) and then truncate. The left
  matrix in this product has \(n\) rows, \(\le 2^{-k}m\) columns, and degree
  \(<2^k\delta\). The right matrix has row and columns dimensions both \(\le
  2^{-k}m\), and sum of column degrees \(\le\sumTuple{d}\). The product can be
  performed by expanding the columns of \(\submat{G}{I_k}{J_k}\) into \(\le
  2^{1-k}m\) columns all of degree \(\le \sumTuple{d}/(2^{-k}m) \le
  2^k\delta\), which leads to the complexity \(\bigO{\lceil 2^k \frac{n}{m}
  \rceil \timepmm{2^{-k}m}{2^k\delta}}\). Summing the latter bound for \(k \in
  \{1,\ldots,\ell-1\}\), and adding the term \(k=0\) for
  Line~\ref{step:TruncatedProduct:first_product}, yields the claimed cost bound.

  The final simplified complexity bound follows from the assumptions mentioned
  in Section~\ref{sec:polmat:timefunc}: \(\timepmm{\mu}{\delta}\) is in
  \(\bigO{\mu^\expmm \timepm{\delta}}\), \(\timepm{\cdot}\) is superlinear, and
  \(\expmm>2\) implies that the sum \(\sum_{0 \le k < \ell}
  2^{k(2-\expmm)}\) is bounded by a constant.
\end{proof}





