\title{Multi-Pass Streaming Lower Bounds for Approximating Max-Cut}
\author{Yumou Fei\thanks{Department of EECS, Massachusetts Institute of Technology.}
\and Dor Minzer\thanks{Department of Mathematics, Massachusetts Institute of Technology. Supported by NSF CCF award 2227876 and NSF CAREER award 2239160.}\and Shuo Wang\thanks{Department of Mathematics, Massachusetts Institute of Technology. Supported by NSF CCF award 2227876.}}
