\noindent {\textbf Dynamic Random Graph.} A \textit{continuous dynamic graph} $\mathcal{G}$ is a family of graphs $\mathcal{G} = \{ G_t = (V_t, E_t) : t \in \mathbb{R}^+\}$, where $V_t$ is the set of nodes and $E_t$ is the set of edges in the system at time $t$.  If $\{ V_t\}_t$ and $\{ E_t\}_t$ are families of random sets we call the corresponding random process a \textit{dynamic random graph}. We call $G_t$ the \textit{snapshot} of the dynamic random graph at time $t$. For a set of nodes $S \subseteq V_t$, we denote with $\delta_{out}^t(S)$ the outer boundary of $S$ in snapshot $G_t$.% A \textit{Discrete} snapshot of $G$ is represented as. $G_n$.  .% A snapshot of $G$ is represented as $G_0, G_1, \ldots G_t, \ldots$. 

Let $G = (V,E)$ be an undirected graph. For any node $v \in V$, its degree is defined as $d(v) = |N(v)|$, where $N(v)$ is the set of neighbors of $v$. For a subset $ S \subseteq V$, the volume of $S$ is defined as $vol(S) = \sum_{v \in S}d(v)$ and the edge cut of $S$ as $E(S, V\backslash S) = \{ (u,v) | (u,v) \in E, u \in S, v \notin S\}$. The conductance of (a non-empty set) $S$, $\phi(S)$, is defined as $\phi(s) = |E(S, V \backslash S)| / \min(vol(S), vol(V \backslash S))$. Finally, the conductance of the entire graph $G$ is $\phi = \min_{S \subseteq V, |S| \leq |V|/2} \phi(S)$. As we define next, graphs with {\em constant} conductance are called {\em expander } graphs.

\begin{definition}[Expander Graph]\label{def:expander-graph}
    A family of graphs $G_n$ on $n$ nodes is an \emph{expander family} if,
    for some constant $\alpha$ with $0 < \alpha < 1$, the conductance
    $\phi_n = \phi(G_n)$ satisfies $\phi_n \geq \alpha$ for all
    $n \geq n_0$ for some $n_0 \in \mathbb{N}$.
\end{definition}

