\begin{definition}[Stochastic Churn Model \cite{PRU01}]\label{def:poisson_node_churn}
    A Poisson node churn is a random process ${V_t : t \in \mathbb{R}}$ such that: 
    \begin{enumerate}
        \item $V_0 = \phi$;
        \item The arrival of new nodes in $V_t$ is a Poisson process with rate $\lambda$.
        %Without loss
        %of generality (cf. Section \ref{sec:model}), we will assume $\lambda = 1$, i.e., the mean number of nodes that arrive per {\em unit of time} is $1$.
        \item Once a node is in $V_t$, its lifetime has exponential distribution with parameter $\mu$. \cite{Becchetti-ICDCS21}
        \end{enumerate} 
\end{definition}


In Definition \ref{def:poisson_node_churn}, the arrival time interval between two consecutive nodes is an exponential random variable of parameter $\lambda$, and the number of nodes joining in a time interval of duration $\tau$ is a Poisson random variable with expectation $ \tau \cdot \lambda$. Further, $\{ V_t : t \in \mathbb{R}^+\}$ is a continuous Markov Process. 

We show that in the long run the network size converges to $\lambda / \mu$ which we denote by $n$, called the {\em stable network size}.

\begin{lemma}[stable network size \cite{PRU01}]\label{lem:sizeofg}
    Consider  the Poisson node churn $\{V_t : t \in \mathbb{R}^+\}$ in Definition \ref{def:poisson_node_churn} with parameters $\lambda$
    and $\mu$. 
    \begin{enumerate}
        \item For any $\log n \leq  t \leq n$, w.h.p, $|V_t| = \Theta(t)$.
        \item For any $t > n$, w.h.p., $|V_t| = \Theta(n)$.
    \end{enumerate}
\end{lemma}

