% \Statex $\text{TTL} = c \log n$ \Comment{Time-to-live (TTL) for each token. Tokens expire after $c \log n$ steps.}
\Statex $\outbox_v$ for each neighbor $v$ \Comment{\textit{FIFO token buffers stored at $u$, one for each neighbor $v$.}}

\Statex
\For{$t = 1, 2, \dots$, for each phase:} \Comment{\textit{After a node joins the network}}

\State $u$ creates $\tot$ tokens, each with value of $\textsc{rwCounter} = 0$.
\Statex \Comment{\textit{Each token has distance ID and stores the source node ID}}

\ForAll{tokens $\tok$ that were created}
	\State Pick a neighbor $v$ uniformly and independently at random.
 	\State Push  $\tok$ into $\outbox_v$.
\EndFor
\For{$\stepNum \gets 1$ to $\rwLength$}
\For{each neighbor $v$}
\State Dequeue up to $\capa$ tokens from $\outbox_v$ (which is a FIFO queue).
\State Record $v$ as the next node in the walk taken by each of those tokens.

% \If{\text{TTL} is greater than 0}
%     \State Send each dequeued token to $u$
% \Else
%     \State Save the token ID and node ID 
%     \State Send the verified token back to $u$ \textit{\Comment{Using the same path}}
% \EndIf
\EndFor
\State Receive up to $\capa$ tokens sent by each neighbor and store them in a set $M$. 
\Statex \Comment{\textit{Any neighbor that sends more than $\capa$ node is blacklisted and heretofore ignored.}}
\For{each $\tok$ in $M$}
	\If{$\tok.\textsc{rwCounter} < \rwLength$}
        \State Increment the \textsc{rwCounter} of each token by 1.
		\State Pick a neighbor $v$ uniformly and independently at random.
		\State Enqueue  $\tok$ into $\outbox_v$. 
	\Else
		\State Save node ID in {\texttt{verifiedList}}

        \State Send the verified token back to source of $\tok$ via the same path (in reverse).
        \Statex \Comment{\textit{Takes additional $\rwLength$ steps.}}
	\EndIf
\EndFor
\EndFor
\EndFor
\end{algorithmic}
\end{algorithm}

