    As mentioned earlier, each edge from a node $ v \in S$ has probability at most $O(|S|/|V_t|)$ to land in $S$ or 
    $\Pr(X_1 = 1) \leq  O(|S|/|V_t|) = aq/n_t$, for some constant $a$ and assuming $|V_t| = n_t$.

    Next, we condition on the event that $X_1 = 1, \ldots , X_{i-1} = 1$, resulting in a decrease in probability for $X_i$ having both end points in $S$, then for all $ i = 2, \ldots , |E|$
    $$ \Pr\left( X_i = 1 \bigg| \bigwedge_{j=1}^{i-1} X_{j} = 1\right) \leq aq/n_t$$

    \noindent Applying chain rule of conditional probability, we have
    \begin{align}\label{eq:chainRule}
        \Pr\left(\bigwedge_{j=1}^{i} X_j = 1\right) &= \Pr\left(X_i = 1 \bigg| \bigwedge_{j=1}^{i-1} X_j = 1\right)\cdot \Pr\left(\bigwedge_{j=1}^{i-1} X_j = 1\right)\nonumber\\ 
        &= \Pr(X_j = 1) \cdot \prod_{j=2}^i \Pr\left( X_j = 1 \bigg| \bigwedge_{k=1}^{j-1}X_k = 1\right)\leq \left( a/n_t\right)^i
    \end{align}

    \noindent Next, we bound the probability of $|E(S,
    S)| \geq (1 -\phi')|E_S|$.  To do so, we consider all subsets $S$ of size $q$ (of size at most $n_t/2$) in the core set $C_{t,t+\eta\log{n}}$.  Then, we have 
    \begin{equation*}
        \Pr\left(\exists S, |S| = q \text{ and } |E(S,S)| \geq (1 - \phi')|E_S|  \right) \leq  {{n_t}\choose{q}} {|E_S| \choose {|E_S|(1 - \phi')}} \left( aq/n_t\right)^{(1 - \phi')|E_S|}
    \end{equation*}

    % $$ \Pr\left(\exists S, |S| = q \text{ and } |E(S,S)| \geq (1 - \phi')|E_S|  \right) \leq  {{n_t}\choose{q}} {|E_S| \choose {|E_S|(1 - \phi')}} \left( aq/n_t\right)^{(1 - \phi')|E_S|}$$
