\subsection{Proof of Lemma \ref{lem:arrival}}
\label{sec:arrivalproof}

\begin{proof}
    In a Poisson process with rate $\lambda = 1$, the number of nodes arriving in any interval of length $t' - t$ is Poisson distributed with mean 
    $ \lambda (t - t') = 1 \cdot (t - t') = t - t'$. Hence, $E[N(t',t)] = (t' - t)  = n'$.



To prove concentration of $N(t',t)$ we use a Chernoff bound for the Poisson distribution \cite{upfal}. 

    The Chernoff bound for the Poisson distribution gives us:
        \begin{align*}
            Pr(|N(t',t) - n'| \geq \delta n') &\leq 2e^{-n' \delta^2 / 3}
        \end{align*}
        for any $0 < \delta < 1$.

        \iffalse
        We want to find $\delta$ such that $2e^{-\mu \delta^2 / 3} \leq \frac{1}{n^2}$. Solving for $\delta$, we get:
        \begin{align*}
            2e^{-\mu \delta^2 / 3} &\leq \frac{1}{n^2} \\
            e^{-\mu \delta^2 / 3} &\leq \frac{1}{2n^2} \\
            -\mu \delta^2 / 3 &\leq \ln\left(\frac{1}{2n^2}\right) \\
            \delta^2 &\geq \frac{3 \ln(2n^2)}{\mu} \\
            \delta &\geq \sqrt{\frac{3 \ln(2n^2)}{\mu}}
        \end{align*}
        \fi
        Plugging  $\delta = \sqrt{\frac{3 \ln(2n^2)}{n'}}$, we have the lemma.
\end{proof}





\subsection{Proof of Lemma \ref{lem:probaInequality}}


\begin{proof}
    Let $p^* = \binom{n}{s} \binom{cs}{(1-\Phi) c s} ((1+\varepsilon)s/n)^{(1-\Phi) c s}$. We give two upper bounds: the first for $s = o(n)$ and the second for $s = \kappa n$ for some constant $0 < \kappa \leq 1/2$.

    To get the first bound, we use the inequality $\binom{y}{x} \leq (ey/x)^x$, that holds for any integers $y \geq x \geq 1$. Then, $p^* \leq (en/s)^s (e/(1-\Phi))^{(1-\Phi) c s} ((1+\varepsilon) s/n)^{(1-\Phi) c s} = 2^{s(\beta + (1-(1-\Phi)c) (\log n - \log s))}$, where $\beta = \log(e) + (1-\Phi)c \log (e (1+\varepsilon) / (1-\Phi)) $. For large enough $n$, the $(1-(1-\Phi) c) \log n$ factor dominates in the exponent. Thus, 
    it suffices to choose $c$ large enough and it holds that $p^* \leq 1/n^2$ for large enough $n$.

    To get the second bound, we need to use a tighter inequality (since $s$ and $n$ are large) to bound the binomial coefficients. More concretely, using Stirling's formula, it holds that $\binom{y}{x} \leq 2^{y H(x/y)}$, for any integers $x, y \geq 0$ and where $H(q) = -q \log(q) - (1-q) \log (1-q)$ is the binary entropy of $q \in (0,1)$. As a result, we get $p^* \leq 2^{n ( H(\kappa) + c \kappa H(1-\Phi) + (1-\Phi) c \kappa \log ((1+\varepsilon) \kappa))}$. 
    First, 
    we take small enough $\varepsilon$ such that for any $\kappa \leq 1/2$, $|\log ((1+\varepsilon) \kappa)| \geq 0.9$. 
    Next, note that 
    $H(1-\Phi) \leq 2 \sqrt{\Phi (1-\Phi)} \leq 0.6$, where the first inequality is a well-known upper bound for binary entropy that holds for any $\Phi \in (0,1)$ and the second one holds because $2 \sqrt{x (1-x)}$ takes value $0.6$ at $x=1/10$ and increases between $x=0$ and $x=1/2$. Then, $H(1-\Phi) \leq |(3/4) (1-\Phi) \log ((1+\varepsilon) \kappa)|$, since the right-hand side is strictly greater than $0.6$ for $\Phi \leq 1/10$.
    Therefore, $p^* \leq 2^{n ( H(\kappa) + (c \kappa/4) (1-\Phi) \log ((1+\varepsilon) \kappa))}$. Next, we take $c$ large enough so that $|(c \kappa/8) (1-\Phi) \log ((1+\varepsilon) \kappa)| \geq 2 |\kappa \log \kappa|$. Then, $p^* \leq 2^{n ( \kappa \log \kappa - (1-\kappa) \log(1-\kappa) + (c \kappa/8) (1-\Phi) \log ((1+\varepsilon) \kappa))}$. Since $\kappa \log \kappa - (1-\kappa) \log(1-\kappa) \leq 0$ for $0 \leq \kappa \leq 1/2$ and the other term in the exponent is negative,  $p^* \leq 2^{n (c \kappa/8) (1-\Phi) \log ((1+\varepsilon) \kappa)}$. Finally, we use again $\log ((1+\varepsilon) \kappa) \leq -0.9$ to obtain $p^* \leq 2^{- b \cdot s }$, where $b = 0.9 c (1-\Phi) / 8$ does not depend on $\kappa$. Since $s = \Omega(n)$, it holds that $p^* \leq 1/n^2$ for large enough $n$. 
\end{proof}

\subsection{Proof of Theorem \ref{thm:ByzSamplingFinal}}

The proof of Theorem \ref{thm:ByzSamplingFinal} is an adaptation of the proof of the Byzantine Random Walk Theorem
of \cite{soda25} to the stochastic churn model with Byzantine nodes. For the sake of completeness, we give the full proof here.

\begin{lemma}[\cite{soda25}]\label{lem: coremixing}
    Fix a phase $P_{t',t}$. Let $\core $ be the core subgraph during this phase. Then, all random walks initiated at the start of $P_{t',t}$, and that walk only on $\core$, will walk at least $c \log n$ steps (whp) and hence will mix in $\core$, where $c$ is a large enough constant (depending on $\phi_{\core}$).
\end{lemma}
\begin{proof}
    Fix a phase $ P_{t',t}$. Consider a random walk that walks only in $\core$, or more precisely, that walks on nodes $u_1, u_2, u_3, \ldots, u_i, \ldots, u_t$ during the phase $P_{t',t}$, with $u_1$ being the node that initiated the random walk and $u_t$ being the node where it terminated. When the walk enters each $u_i$, there are at most $d \cdot \capa$ random walks that are allowed to enter (from all incident edges) because $u_i$ will discard any excess walks and blacklist any neighbor having sent more than $\capa$ tokens. 

    Then, the random walk is placed on $\outbox_{u_{i+1}}$ that was chosen randomly by $u_i$. Of course, every other walk (regardless of whether it was initiated by an honest node or a Byzantine node) is also placed randomly in one of the $d$ outboxes. Therefore, even assuming the full set of $d\cdot \capa$ walks arrived at $u_i$ along with (and including) the random walk, the number walks placed into $\outbox_{u_{i+1}}$ is a binomial random variable with parameters $d.\capa$ and $1/d$, thus having a mean of $\capa$. Importantly, when $\capa$ is $a\log^3n$, the probability that the number of walks placed into $\outbox_{u_{i+1}}$ will exceed $a\log^3n +(a/2b) \log^2 n = (1 + 1 /(2b \log n)) \cdot a\log^3 n$ is at most
    $e^{(a \log^3 n) \cdot (1/(4b^2 \log^2 n))/3} = n^{-1/(12b^2)}$
        by a  Chernoff bound. (Note that since $b \geq 1,1/(2b \log n) \leq 1$ for any $ n \geq 2)$. As a result, with probability at most $n^{-1/(12b^2)}$, the excess number of random walks placed into $\outbox_{u_{i+1}}$ (i.e., in addition to the mean $\capa$) is at most $(a/2b)\log^2 n$ per round. With $\rwLength = 2f = 2b \log n$, the number of such excess walks placed in $\outbox_{u_{i+1}}$ in the whole phase is at most $2b \log n \cdot (a /2b) \log^2 n = \capa$ with probability at most $n^{-a/(12b^2)}$, or in other words, whp for a constant $a$ chosen large enough compared to $b$. 

    With the excess smaller or equal to $\capa$ (whp), the random walk will buffer at $\outbox_{u_{i+1}}$ for at most one round before moving on to $u_{i+1}$. Thus, even if the random walk were unlucky and took two rounds at each node, in $2f$ steps, it would have taken the requisite $f$ random walk steps to ensure mixing. Thus, we can ensure that all random walks that only walked in $\core$ for $2f$ rounds will take at least $f$ random walk steps. 
\end{proof}
In the next lemma, we bound the number of edges in the core subgraph for a given phase. This hinges on the fact that due to the stochastic churn model, the graph does not change drastically over $\Theta(\log n)$ steps. 

\begin{lemma}\label{lem:sizeofcore}
    Fix a phase $P_{t',t}$, where $t' \geq 3n$ and nodes arrivals and departures are accounted for dynamically. Let $\core$ be the core subgraph for this phase. Then, $|{\core}|  = \Theta(n)$.
\end{lemma}
\begin{proof}% Consider vertices instead of edges 
    Fix a phase $P_{t',t}$. We first bound the number of nodes in $G_{t',t}$. Let $V_{t'}$ be the vertex set for graph $G_{t'}$ at time $t'$. Then, from Lemma \ref{lem:sizeofg}, we know that the number of nodes in the network at time $t'$ is $\Theta(n)$ whp. Also,  $t-t' = \Theta(\log n)$ from definition \ref{def:phase}, then from Lemma \ref{lem:arrival}, whp at most $\Theta(\log n)$ nodes depart or join from the network during this phase. Thus, whp,
    $$G_{t',t} = \Theta(n) - \Theta(\log n) .$$ 
    Recall from Definition \ref{def: core} that $\core = G_{t',t} - O(B_t)$. Since $G_{t'}$ is an expander graph, it has strong connectivity properties and high conductance, $\phi$, ensuring that removing a small fraction of nodes does not break expansion whp. Then, using the fact that $|B| = o(n)$ as the number of Byzantine nodes are small relative to the network size, we have 
    \begin{equation*}
        |\core| = \Theta(n) - \Theta(\log n) - o(n) = \Theta(n). \qedhere
    \end{equation*}   
\end{proof}

In the next lemma, we bound the probability that a random walk starting at any given node in the $\core$ ends at another node within the $\core$ after $\Theta (\log n )$ steps.

\begin{lemma}[\cite{soda25}]\label{lem: mean}
    Let $\mu = |B_t|/|\core|$. Then, 

    $$\frac12 |\core| \leq (1 -O(\mu))d \leq |E_\core| \leq \frac 12 d |\core|$$

    where $E_{\core}$ is the set of edges in core subgraph $\core$ in phase $P_{t',t}$.
\end{lemma}
\begin{proof}
    Fix a phase $P_{t',t}$, where $t' \geq 3n $, and let $\core$ denote the core subgraph for this phase. From Definition \ref{def: core} and Lemma \ref{lem:sizeofcore}, we know that $|\core| = \Theta(n)$, and the core consists of all honest nodes that neither joined nor departed during the interval this phase and are not Byzantine. 

    Let $G_{t'}$ be the graph at time $t'$, and assume that it is a $d$-regular graph (as per Algorithm \ref{alg:p2pConstr}). Let $d_{max}$ be the maximum degree of any node, and $d_{avg}$ be the average degree. The algorithm ensures that the bounded degrees, so $d_{max} = O(1)$ and we assume $d_{avg} = \Theta(d_{max})$.

    First, we establish the upper bound for $|E_{\core}|$. Each node $v \in V(\core)$ has $\text{deg}_{C_{t',t}}(v) \leq d_{max}$. The sum of degrees in $\core$ is $2|E_{\core}|$. Thus, $2|E_{\core}| \leq |\core|d_{max}$. Using $d_{max}=O(d)$, we have:

    $$ |E_{\core}| \leq \frac{1}{2}d|\core| $$

    Next, we establish the lower bound for $|E_{\core}|$. Assuming the nodes of the $\core$ have $d_{avg}$ degree, then the number of edges in $\core$ would be $\frac 12 d_{avg} |\core|$. But some these edges might have been affected by Byzantine nodes or some of the nodes might have departed due to the churn during this phase. Therefore, number of such unavailable nodes is $|B_t| + |D_{t',t}|$. This means some of the node's edges would be outside the $\core$ and each such node could have been connected to $d_{max}$ nodes. Each such node could have been connected to at most $d_{max}$ nodes within $V(C_{t',t})$. Thus, the maximum number of edges ``removed'' or not formed with respect to $V(C_{t',t})$ is bounded by $d_{max}(|B_t| + |D_{t',t}|)$. 

    From Lemma \ref{lem:arrival}, $|D_{t',t}| = O(\log n)$. Substituting $d_{avg} = \Theta(d)$ and $d_{max} = O(d)$:
    $$|E_{C_{t',t}}| \geq \frac{1}{2}d|C_{t',t}| - O(d(|B_t| + \log n)).$$Factoring $\frac{1}{2}d|C_{t',t}|$:$$|E_{C_{t',t}}| \geq \frac{1}{2}d|C_{t',t}| \left(1 - O\left(\frac{|B_t|}{|C_{t',t}|} + \frac{\log n}{|C_{t',t}|}\right)\right).$$

    With $\mu = |B_t|/|C_{t',t}|$ and $|C_{t',t}| = \Theta(n)$, the term $\frac{\log n}{|C_{t',t}|} = O\left(\frac{\log n}{n}\right)$. Given that $|B_t|$ is $\omega(\log n)$ and  $O\left(\frac{\log n}{n}\right)$ is $O(\mu)$. Thus, we derive the lower bound:
    $$|E_{C_{t',t}}| \geq \frac{1}{2}d|C_{t',t}|(1 - O(\mu)).$$

    As lemma the states $(1 - O(\mu))d \le |E_{C_{t',t}}|$. Comparing this with the derived lower bound $|E_{C_{t',t}}| \ge \frac{1}{2}d|C_{t',t}|(1 - O(\mu))$, the lemma's inequality $(1 - O(\mu))d \le |E_{C_{t',t}}|$ holds if $(1 - O(\mu))d \le \frac{1}{2}d|C_{t',t}|(1 - O(\mu))$. Assuming $d > 0$ and $(1-O(\mu)) > 0$, this simplifies to $1 \le \frac{1}{2}|C_{t',t}|$, or $|C_{t',t}| \ge 2$, which is true for any non-trivial core.

    Combining the derived bounds on $|E_{C_{t',t}}|$ yields the full statement of the lemma.

\end{proof}

\begin{lemma}[\cite{soda25}]\label{lem: corewalk}
    Fix a phase $P_{t',t}$. Consider, for any core node $v \in \core$, any random walk that starts at $v$ and walks only through the nodes of $\core$ for $\Theta(\log n)$ steps. Then, the probability that the walk is at node $u \in \core$ at the end of the random walk is $\Theta \left(\frac{1}{|\core|} \right) = \Theta \left(\frac1n \right)$.
\end{lemma}
\begin{proof}
    Consider a random walk that starts at a node $v \in \core$ and walks only on nodes in $\core$. Conditioning that the walk only uses edges in $\core$, then it holds that any node in $\core$, the walk chose a \textit{uniform random outgoing edge among edges in } $\core$. Hence, the conditioned random walk is a standard random walk on $\core$. Since $\core$ is an expander, or more precisely $\core $ has constant conductance $\phi_{\core}$, the (conditioned) random walk on $\core$ mixes in $\tau_\core$ steps and reaches close to the \textit{stationary distribution} in $\core$ (up to $1/n^3$ error, as we have defined in Subsection \ref{subsec:defCore}). In particular, the stationary probability of node $u \in \core$ is $deg_{\core}(u/2|E_\core|)$. Now, we can apply Lemma \ref{lem: coremixing} where $\core$ is the honest subset of nodes and $f = \tau_\core = b\log n$ is the mixing time of $\core$. As a result, the probability that the walk ends up at a node $u \in \core$ is proportional to its degree $deg_\core(u)$ (where $1 \leq deg_\core(u) \leq d)$ divided by the number of edges in $\core$ (and up to $1/n^3$ error)  which is $\Theta(d|C|/2) = \Theta(n)$ (by Lemma \ref{lem: mean}, and as $|B_t| - o(n)$ and $|\core| = n - O(|B_t|) = \Theta(n)$. Hence, the probability that the walk ends at $u$ is $\Theta(1/n)$.

\end{proof}

