\paragraph{Execution Phase}
\par During the execution phase, the computational complexity of PPO-LA is $O(M_aN_aT|\theta_\pi|)$. This complexity is primarily due to action selection according to the current policy.

\par The space complexity during the execution phase is $O(|\theta_\pi|)$, since the policy network parameters need to be stored in memory for action selection.





\begin{algorithm}[t]
\caption{PPO-LA Algorithm}
\label{alg:PPO-LA}
\KwIn{Population size $N_{\mathrm{pop}}$, number of maximum iterations $T_{\mathrm{max}}$, objective function $f$.} 
\tcc{\textbf{Initialization stage}}
\textbf{Initialize} policy network parameters $\theta$, actor old network parameters $\theta_{\text{old}}$, value network parameters $\phi$\ and episodic memory $\mathcal{B}$\;
\tcc{\textbf{Data Collection Stage}}
\For{each Episode}{
    Reset the environment and initialize state $s_t$\;

    \tcc{\textbf{Trajectory Generation}}
    \For{each Time slot}{
        Collect trajectory data $\mathcal{D}$;

        Compute advantage estimates $A_t$;

        Calculated $r_t$ according to Eq. (\ref{reward});

        Store transition $(s_t, a_t, r_t, s_{t+1})$ in $\mathcal{B}$\;

    \tcc{\textbf{Policy Optimization Stage}}
    \If{size of buffer $\mathcal{B}$ == batch size}{
        \For{each update step}{
            Sample a batch of transitions from $\mathcal{B}$\;

            \tcp{Update policy with clipping mechanism}
            Update policy network parameters $\theta$ by maximizing $L^{CLIP}(\theta)$\;

            \tcp{Update value function}
            Update value network parameters $\phi$ by minimizing $L^{VF}(\phi)$;

        }
    }
    \tcp{Network synchronization}
    $\theta_{\text{old}} \gets \theta$\;
    Clear buffer $\mathcal{B} \gets \emptyset$\;
    }
    \textbf{Check termination condition}\;
}
\KwOut{Optimized policy parameters $\theta^*$ for deployment.}
\end{algorithm}







