\begin{mainresult}\label{MainDecomp}
    Let $G$ be a 4-connected graph.
    Let $\cT(G)$ denote the mixed-tree-decomposition of $G$ that is uniquely determined by the set $N(G)$ of all totally-nested tetra-separations of~$G$.
    Every torso $\tau$ of $\cT(G)$ satisfies one of the following:
    \begin{enumerate}
        \item\label{MainDecompQuasi5con} $\tau$ is quasi-5-connected;
        \item\label{MainDecompBagel} $\tau$ is a cycle of triangle-torsos and 3-connected torsos on $\le 5$ vertices; 
        \item\label{MainDecompDoubleWheel} $\tau$ is a generalised double-wheel;
        \item\label{MainDecompK4m} $\tau$ is a thickened $K_{4,m}$ with $m\ge 0$, or the entire graph $G$ is a sprinkled $K_{4,m}$ with $m\ge 4$.
    \end{enumerate}
\end{mainresult}

\begin{remark}\label{MainDecompCanonical}
    Both $N(G)$ and $\cT(G)$ in \cref{MainDecomp} are canonical: if $\varphi\colon G\to G'$ is a graph-isomorphism, then $N(\varphi(G))=\varphi(N(G))$ and $\cT(\varphi(G))=\varphi(\cT(G))$.
\end{remark}

\begin{remark}\label{MainDecompInfinite}
    \cref{MainDecomp} includes infinite graphs $G$ with no additional restrictions whatsoever.
    More generally, all graphs in this paper are allowed to be infinite, unless stated otherwise.
\end{remark}


\cref{MainDecomp} implies a new Tutte-type canonical decomposition for 3-connectivity.
A \emph{\trisp } is defined like a tetra-separation, except that the separator is required to have size three instead of four.
A \trisp\ of a graph $G$ is \emph{totally-nested} if it is nested with every \trisp\ of~$G$.
A \emph{generalised wheel} with \emph{centre} $v$ is a 3-connected graph $X$ with a vertex $v$ such that $X-v$ has a cycle-decomposition with all adhesion-sets of size 1 and into $K_2$'s and triangles.

\begin{maincorollary}\label{3Decomp}
    Let $G$ be a 3-connected graph.
    Let $M(G)$ denote the set of all \trisp s of $G$ that are totally-nested (with regard to the \trisp s).
    Let $\cT(G)$ denote the mixed-tree-decomposition of $G$ that is uniquely determined by $M(G)$.
    Every torso $\tau$ of $\cT(G)$ satisfies one of the following:
    \begin{enumerate}
        \item\label{3DecompQuasi4con} $\tau$ is quasi-4-connected;
        \item\label{3DecompWheel} $\tau$ is a generalised wheel;
        \item\label{3DecompK3m} $\tau$ is a thickened $K_{3,m}$ with $m\ge 0$, or the entire graph $G$ is a sprinkled $K_{3,m}$ with $m\ge 4$.
    \end{enumerate}
\end{maincorollary}

Both \cref{MainDecompCanonical,MainDecompInfinite} also apply to \cref{3Decomp}.\medskip








\noindent\textbf{Vertex-transitive graphs.}
It is well known that all vertex-transitive finite connected graphs are either 3-connected, cycles, or $K_2$'s~\cite{infiniteSPQR}.
This fact has then been refined in \cite{Tridecomp} by analysing the 3-connected outcome further; see \cite[Corollary~2]{Tridecomp}.
However, \cite{Tridecomp} leaves it open to gain new insights into vertex-transitive 4-connectivity.
This is where we apply \cref{MainDecomp}: to obtain a characterisation of vertex-transitive 4-connectivity.
Recall that a graph $G$ is \emph{arc-transitive} if for every two ordered pairs $(u_i,v_i)$ with $u_i v_i\in E(G)$ for $i=1,2$ there is an automorphism $\varphi$ of $G$ such that $\varphi(u_1)=u_2$ and $\varphi(v_1)=v_2$.
The \emph{$K_4$-expansion} of a 4-regular graph $G$ is obtained from $G$ by expanding every vertex to a~$K_4$, and adding a perfect matching such that two $K_4$'s are joined by a matching-edge if and only if their original vertices in $G$ are joined by a $G$-edge.
For other definitions related to \cref{mainthm:transitive}, see \cref{sec:vertexTransitive}.

\begin{restatable}{mainresult}{maintransitive}
    \label{mainthm:transitive}
    A 4-connected finite graph $G$ is vertex-transitive if and only if $G$ either is
    \begin{enumerate}
        \item\label{mainitm:transitive-1} a quasi-5-connected vertex-transitive graph,
        \item\label{mainitm:transitive-2} the $K_4$-expansion of a quasi-5-connected arc-transitive graph,
        \item\label{mainitm:transitive-3} a cycle of $K_4$-bags of length $\ge 4$ (\cref{fig:CycleOfK4s}),
        \item\label{mainitm:transitive-4} a cycle alternating between $K_4$-bags and $C_4$-bags of length $\ge 4$ (\cref{fig:CycleAlternating}),
        \item\label{mainitm:transitive-5} a cycle of triangle-bags of length $\ge 6$ (\cref{fig:cycleOfTriangles}),
    \end{enumerate}
    \noindent or $G$ is one of the following graphs or a $K_4$-expansion thereof:
    \begin{enumerate}[resume]
        \item\label{mainitm:transitive-6} a cycle of $K_{2,2}$-bags of length $\ge 3$ (\cref{fig:CycleOfK22s}),
        \item\label{mainitm:transitive-7} the line-graph of the cube (\cref{fig:LineGraphCube}).
    \end{enumerate}
\end{restatable}

\cref{mainthm:transitive} strengthens a classical theorem of Godsil and Royle from geometric group theory in a special case \cite[Theorem 3.4.2]{Godsil}.


