    \caption{A small quasi-5-connected graph with a tetra-separation (red)}
    \label{fig:quasi5conVtetra}
\end{figure}

The mixed-separations\pl\ of a graph come with the usual partial ordering:
\[
    (A,B)\;\defnMath{\le}\; (C,D):\Leftrightarrow A\se C\text{ and }B\supseteq D.
\]
Two mixed-separations\pl{} $(A,B)$ and $(C,D)$ are \defn{nested} if, after possibly switching the name~$A$ with~$B$ or the name~$C$ with~$D$, we have $(A,B)\le (C,D)$. 
Otherwise, they \defn{cross}.
A set of mixed-separations\pl\ is \defn{nested} if all its elements are pairwise nested.
In the context of $(A,B)$ and $(C,D)$ crossing, the \defn{vertex-centre} is the vertex-set $A\cap B\cap C\cap D$.

A tetra-separation of a graph~$G$ is \defn{totally-nested} if it is nested with every tetra-separation of~$G$.


\subsection{Stars, mixed-tree-decompositions and torsos}\label{sec:MixedTdcs}
The following definition is supported by \cref{fig:MixedTDC}.
Let $G$ be a graph.
A pair $\cT=(T,(V_t)_{t\in T})$ of a tree $T$ and a family of vertex sets $V_t\se V(G)$ indexed by the nodes $t\in T$ is a \defn{mixed-tree-decomposition} of~$G$ if it satisfies the following two conditions:
\begin{enumerate}[label=\textnormal{(M\arabic*)}]
    \item $V(G)=\bigcup_{t\in T}V_t$;
    \item\label{M2} the subgraph of $T$ induced by $\{\,t\in T:v\in V_t\,\}$ is connected for every vertex $v\in G$.
\end{enumerate}
We refer to the vertex sets $V_t$ as \defn{bags}.
Mixed-tree-decompositions generalise both tree-decompositions and tree-cut decompositions.
Every oriented edge $(t_1,t_2)$ of $T$ \defn{induces} a mixed-separation\pl\ $(A_1,A_2)$ where $A_i=\bigcup_{t\in V(T_i)}V_t$ for the component $T_i$ of $T-t_1 t_2$ with $t_i\in T_i$.
This defines a map $\defnMath{\alpha_{\cT}(t_1,t_2)}:=(A_1,A_2)$ with domain the set $\defnMath{\vec E(T)}$ of oriented edges of~$T$.
The set of induced mixed-separations\pl\ of $\cT$ is nested.
It is \defn{symmetric}: for each element $(A_1,A_2)$ it also contains $(A_2,A_1)$.
We call $\cT$ \defn{proper} if all its induced mixed-separations\pl\ are proper.
The \defn{adhesion-set} of an edge $t_1 t_2$ of $T$ is the separator of $\alpha_{\cT}(t_1,t_2)$, which is well-defined.


