\subsection{Graph-decompositions}
Let $G$ and $H$ be graphs.
Let $\cG = (G_h : h \in V(H))$ be a family of subgraphs $G_h \subseteq G$ indexed by the nodes of~$H$. 
The pair $(H, \cG)$ is an \defn{$H$-decomposition} or \defn{graph-decomposition} of $G$ if
\begin{enumerate}[label=\rm{(H\arabic*)}]
    \item\label{GraphDec1} $G = \bigcup_{h \in V(H)} G_h$, and
    \item\label{GraphDec2} for every $v \in V(G)$, the subgraph $H_v \subseteq H$ induced on $\{h \in V(H) : v \in V(G) \}$ is connected.
\end{enumerate}
We refer to the $G_h$ as its \defn{parts} and to $H$ as its \defn{decomposition graph}.
When $H$ is a cycle, we call $(H,\cG)$ a \defn{cycle-decomposition}

The \defn{adhesion-graphs} of $(H,\cG)$ are the intersections $G_h\cap G_{h'}$ for the edges $hh'\in E(H)$.
The \defn{adhesion-sets} of $(H,\cG)$ are the vertex-sets of its adhesion-graphs.
The \defn{torso} of a part $G_h$ is obtained from $G_h$ by making every adhesion-graph $G_h\cap G_{h'}$ with $hh'\in E(G)$ into a complete graph by adding all possible edges.
An edge of a torso with both ends contained in the same adhesion-set is a \defn{torso-edge}, even if it already exists in~$G$.
The \defn{interior} $\defnMath{\mathring{G}_h}$ of $G_h$ is the graph $G_h-\bigcup_{h'\in H-h}G_{h'}$.
The \defn{interior} of a torso is defined similarly.
The \defn{interior} vertices of $G_h$ are the vertices of the interior of $G_h$, and the \defn{interior} vertices of a torso are defined similarly.


Let $X$ be a graph.
We call $X$ a \defn{generalised wheel} with \defn{centre $v$} if $X$ is 3-connected with $v\in V(X)$ such that $X-v$ has a cycle-decomposition with all adhesion-sets of size 1 and into $K_2$'s and triangles.
We call $X$ a \defn{generalised double-wheel} with \defn{centre $\{u,v\}$} if $X$ is 4-connected and $u,v$ are distinct vertices of $X$ such that $X-u-v$ has a cycle-decomposition with all adhesion-sets of size 1 and into $K_2$'s and triangles.
We call $X$ a \defn{cycle of $X_1$-torsos, \dots, $X_k$-torsos} where the $X_i$ are graphs, if $X$ is 4-connected and has a cycle-decomposition with all adhesion-sets of size two such that every torso is isomorphic to some~$X_i$.
A \defn{thickened $K_{4,m}$} is obtained from a $K_{4,m}$ by turning the left side into a $K_4$.
A \defn{sprinkled $K_{4,m}$} is obtained from a $K_{4,m}$ by adding any number of edges to the left side.


\section{Proofs of \texorpdfstring{\cref{MainDecomp} and \cref{3Decomp}}{the decomposition theorems} and strengthenings thereof}
\label{sec:ProofsStrengthenings}

Instead of proving \cref{MainDecomp} and \cref{3Decomp} directly, we will first prove stronger but slightly more technical versions of them, \cref{MainDecompStrengthening} and \cref{3DecompStrengthening} below, and then immediately obtain \cref{MainDecomp} and \cref{3Decomp} from their strengthenings.
The proof of \cref{MainDecompStrengthening} uses a number of lemmas that have not yet been introduced.
Stating and proving these lemmas will be the main objectives of later sections.


\begin{theorem}[Technical strengthening of \cref{MainDecomp}]\label{MainDecompStrengthening}
    Let $G$ be a 4-connected graph.
    Let $N$ denote the set of all totally-nested tetra-separations of~$G$.
    Let $\sigma$ be a splitting star of $N$ with torso $\tau$.
    \begin{enumerate}
        \item\label{MainDecompStrengtheningQuasi5con} If $\sigma$ is not interlaced by any tetra-separation, then $\tau$ is quasi-5-connected.
    \end{enumerate}
    Assume now that $\sigma$ is interlaced by a tetra-separation $(A,B)$, which is crossed by another tetra-separation $(C,D)$ with vertex-centre~$Z$.
    Then $|Z|\in\{0,2,4\}$.
    \begin{enumerate}[resume]
        \item\label{MainDecompStrengtheningBagel} If $|Z|=0$, then $\tau$ is a cycle of triangle-torsos and 3-connected torsos on $\le 5$ vertices.
        \item\label{MainDecompStrengtheningDoubleWheel} If $|Z|=2$, then $\tau$ is a generalised double-wheel with centre $Z$.
        \item\label{MainDecompStrengtheningK4m} If $|Z|=4$, then $\tau$ is a thickened $K_{4,m}$ with $Z$ as the left side and $m\ge 0$, or the entire graph $G$ is a sprinkled $K_{4,m}$ with $Z$ as the left side and $m\ge 4$.
    \end{enumerate}
\end{theorem}

\begin{proof}
    If no tetra-separation of $G$ interlaces $\sigma$, then $\tau$ is quasi-5-connected by \cref{Quasi5conSummary}.
    So we may assume that some tetra-separation $(A,B)$ of $G$ interlaces~$\sigma$.
    Then $(A,B)$ is crossed by some tetra-separation $(C,D)$, with $Z$ denoting the vertex-centre.
    By the \allref{keylem:crossing}, we have $|Z|\in\{0,2,4\}$.

    \cref{MainDecompStrengtheningBagel}.
    Assume $|Z|=0$.
    Then $\tau$ is a cycle of triangle-torsos and 3-connected torsos on $\le 5$ vertices by \cref{bagelTorso}.

    \cref{MainDecompStrengtheningDoubleWheel}.
    Assume $|Z|=2$.
    Then $\tau$ is a generalised double-wheel with centre $Z$ by \cref{wheelTorso}.

    \cref{MainDecompStrengtheningK4m}.
    Assume $|Z|=4$.
    If $\sigma$ is non-empty, then $\tau$ is a thickened $K_{4,m}$ with $Z$ as left side and $m\ge 0$ by \cref{SprinkledK4mSummary}.
    Otherwise the entire graph $G$ is a sprinkled $K_{4,m}$ with $Z$ as left side and $m\ge 4$, also by \cref{SprinkledK4mSummary}.
\end{proof}

\begin{proof}[Proof of \cref{MainDecomp}]
    Immediate from \cref{MainDecompStrengthening}.
\end{proof}


\begin{corollary}[Technical strengthening of \cref{3Decomp}]\label{3DecompStrengthening}
    Let $G$ be a 3-connected graph.
    Let $N$ be the set of all \trisp s of~$G$ that are totally-nested (with regard to the \trisp s of~$G$).
    Let $\sigma$ be a splitting star of $N$ with torso~$\tau$.
    \begin{enumerate}
        \item\label{3DecompStrengtheningQuasi4con} If $\sigma$ is not interlaced by any \trisp , then $\tau$ is quasi-4-connected.
    \end{enumerate}
    Assume now that $\sigma$ is interlaced by a \trisp\ $(A,B)$, which is crossed by another \trisp\ $(C,D)$ with vertex-centre~$Z$.
    \begin{enumerate}[resume]
        \item\label{3DecompStrengtheningWheel} If $Z$ consists of exactly one vertex~$v$, then $\tau$ is a generalised wheel with centre~$v$.
        \item\label{3DecompStrengtheningK3m} Otherwise $Z$ has size three.
        If $\sigma\neq\emptyset$, then $\tau$ is a thickened $K_{3,m}$ with $m\ge 0$, and otherwise $G$ is a sprinkled $K_{3,m}$ with $m\ge 4$.
    \end{enumerate}
\end{corollary}

\begin{proof}
    Let $\hat G$ be the graph obtained from $G$ by adding an apex-vertex~$\alpha$.
    Every tetra-separation of $\hat G$ contains $\alpha$ in its separator.
    Hence the map $\varphi$ that sends $(A,B)$ to $(A\cup\{\alpha\},B\cup\{\alpha\})$ is a bijection between the set of \trisp s of $G$ and the set of tetra-separations of~$\hat G$.
    Two \trisp s of $G$ are nested if and only if their images under $\varphi$ are nested.
    Hence $\varphi$ restricts to a bijection between the set $N$ of totally-nested \trisp s of $G$ and the set $\hat N$ of totally-nested tetra-separations of~$\hat G$.
    Let $\hat\sigma:=\varphi(\sigma)$, which is a splitting star of $\hat N$.
    Let $\hat\tau$ denote the torso of $\hat\sigma$.
    Since $\alpha$ lies in all separators of tetra-separations of $\hat G$, no edge incident to $\alpha$ is contracted in the definition of the torso~$\hat\tau$.
    Thus $\tau=\hat\tau-\alpha$.

    \cref{3DecompStrengtheningQuasi4con}. 
    Assume that $\sigma$ is not interlaced by any \trisp .
    Then $\hat\sigma$ is not interlaced by any tetra-separation, so $\hat\tau$ is quasi-5-connected by \cref{MainDecompStrengthening}~\cref{MainDecompStrengtheningQuasi5con}.
    If $\tau$ is not quasi-4-connected, this is witnessed by some separation $(X,Y)$ of $\tau$, and then $(X\cup\{\alpha\},Y\cup\{\alpha\})$ witnesses that $\hat\tau$ is not quasi-5-connected.
    Hence $\tau$ is quasi-4-connected.

    So we may assume next that $\sigma$ is interlaced by a \trisp\ $(A,B)$, which is crossed by another \trisp\ $(C,D)$ with $Z$ denoting the centre.
    Then $\varphi(A,B)$ interlaces $\sigma$ and is crossed by $\varphi(C,D)$ with vertex-centre $\hat Z:=Z\cup\{\alpha\}$.

    \cref{3DecompStrengtheningWheel}.
    Assume that $Z$ consists of exactly one vertex~$v$.
    Then $\hat\tau$ is a generalised double-wheel with centre $\{v,\alpha\}$ by \cref{MainDecompStrengthening}~\cref{MainDecompStrengtheningDoubleWheel}.
    Hence $\hat\tau$ is a generalised wheel with centre~$v$.

    \cref{3DecompStrengtheningK3m}. The vertex-centre $Z$ cannot have sizes 0 or 2, since then $\hat Z$ would have size 1 or 3, which is excluded in \cref{MainDecompStrengthening}.
    Thus $|Z|=3$, so $|\hat Z|=4$.
    Since $\alpha\in\hat Z$, both outcomes of \cref{MainDecompStrengthening}~\cref{MainDecompStrengtheningK4m} translate to the two outcomes of~\cref{3DecompStrengtheningK3m}.
\end{proof}

\begin{proof}[Proof of \cref{3Decomp}]
    Immediate from \cref{3DecompStrengthening}.
\end{proof}

\begin{example}
    The outcome in \cref{MainDecompStrengthening} is not in general unique.
    For example, consider the graph $G$ depicted in \cref{fig:TwoWayCrossingLaugen} on the left.
    Every tetra-separation of $G$ is crossed, hence $\sigma=\emptyset$ is a splitting star of the set $N(G)$ of all totally-nested tetra-separations of~$G$.
    On the left of \cref{fig:TwoWayCrossingLaugen}, we see two tetra-separations that interlace $\sigma$ and cross with empty vertex-centre.
    From their perspective, $G$ is a cycle of $K_4$-torsos and $4$-wheel torsos, see \cref{MainDecompStrengthening}~\cref{MainDecompStrengtheningBagel}.
    On the right of \cref{fig:TwoWayCrossingLaugen}, we see two tetra-separations that interlace $\sigma$ and cross with a vertex-centre of size~2.
    From their perspective, $G$ is a generalised wheel, see \cref{MainDecompStrengthening}~\cref{MainDecompStrengtheningDoubleWheel}.

    For another example, consider the graph $G$ depicted in \cref{fig:TwoWayCrossingK4m} on the left.
    Again, $\sigma=\emptyset$ is a splitting star of~$N(G)$.
    On the left of \cref{fig:TwoWayCrossingLaugen}, we see two tetra-separations that interlace $\sigma$ and cross with empty vertex-centre.
    From their perspective, $G$ is a cycle of $K_4$-torsos, see \cref{MainDecompStrengthening}~\cref{MainDecompStrengtheningBagel}.
    On the right of \cref{fig:TwoWayCrossingLaugen}, we see two tetra-separations that interlace $\sigma$ and cross with a vertex-centre of size~4.
    From their perspective, $G$ is a $K_{4,4}$, see \cref{MainDecompStrengthening}~\cref{MainDecompStrengtheningK4m}.
\end{example}


