\end{figure}


\section{How tetra-separations cross}\label{sec:crossingAnalysis}

In this section, we characterise the ways in which tetra-separations can cross.
The main result here is the \allref{keylem:crossing}.

We require the following terminology for corner diagrams from \cite[§1.3]{Tridecomp}, which is supported by \cref{fig:crossingDiagram}.
Let $(A,B)$ and $(C,D)$ be mixed-separations\pl{} of a graph~$G$.
All of the following definitions depend on $(A,B)$ and $(C,D)$ being clear from context.
The \defn{corner for $\{A,C\}$}, or the \defn{corner $AC$} for short, is the vertex $(A\sm B)\cap (C\sm D)$.
The corners for the other three combinations of one side from $(A,B)$ and one side from $(C,D)$ are defined analogously.
Two corners are \defn{adjacent} when their pair share a side, and \defn{opposite} otherwise.
An edge of $G$ is \defn{diagonal} if its endvertices lie in opposite corners.
The \defn{centre} consists of all vertices in the vertex-centre and all diagonal edges.

The \defn{link for~$C$}, or \defn{$C$-link} for short, consists of
\begin{itemize}
    \item all non-diagonal edges $f$ that have an end in the corner for a pair containing $C$ (these being the corners $AC$ or $BC$) and satisfy $f\in S(A,B)$, and
    \item all vertices in $(C\sm D)\cap S(A,B)$.
\end{itemize}
The links for the other three sides $A,B,D$ are defined analogously.
Each $L$-link is \defn{adjacent} to the two corners for the pairs containing $L$.
Two links are \defn{adjacent} if they are adjacent to the same corner, and \defn{opposite} otherwise.
An edge of $G$ is \defn{jumping} if its endvertices lie in opposite links.

Let $X \in \{A,B\}$ and $Y \in \{C,D\}$.
An edge $e$ of $G$ \defn{dangles from the $Y$-link through the $X$-link} if $e$ has an endvertex in the $Y$-link and $e$ is contained in the $X$-link.
We then call $e$ \defn{dangling} for short.

\begin{figure}[ht]
    \centering
    \includegraphics[height=8\baselineskip]{Figures/CrossingDiagramAreas.pdf}
    \caption{A crossing-diagram. Corners are yellow. Links are blue. The centre is red. The red edge is diagonal. The purple edge is jumping. The left blue edge dangles from the $A$-link through the $C$-link.}
    \label{fig:crossingDiagram}
\end{figure}

The following definition is supported by \cref{fig:PotterDef}.
The corner for $AC$ is \defn{potter} if it is empty and its adjacent links have size two and there exists a path $u_1u_2u_3u_4$ in $G$ such that $u_1u_2$ dangles from the vertex~$u_2$ in the $C$-link through the $A$-link, and $u_3u_4$ dangles from the vertex~$u_3$ in the $A$-link through the $C$-link.

\begin{figure}[ht]
    \centering
    \includegraphics[height=8\baselineskip]{Figures/PotterDef.pdf}
    \caption{The corner $AC$ is potter.}
    \label{fig:PotterDef}
\end{figure}

In the remainder of this section, we prove the following:

\begin{keylemma}[Crossing Lemma]
\label{keylem:crossing}
    Let $(A,B)$ and $(C,D)$ be crossing tetra-separations in a 4-connected graph~$G$.
    Then exactly one of the following assertions holds.
    \begin{enumerate}
        \item\label{itm:crossing-0} All links are empty and the centre has size four.
        \item\label{itm:crossing-1} All links have size one and the centre has size two.
        \item\label{itm:crossing-2} All links have size two and the centre is empty.
    \end{enumerate}
    Moreover, there are no diagonal edges and no jumping edges. 
    If there is an edge that dangles from one link through another, then we are in case~\ref{itm:crossing-2} and the corner in between the two links is potter.
\end{keylemma}

A mixed-separation $(A,B)$ is an \defn{edge-cut} if $S(A \cap B)\se E(G)$. An edge-cut $(A,B)$ is \defn{atomic} if $|A|=1$ or $|B|=1$.
\begin{lemma}
\label{lem:trivial-tetra-separations}
    Let $(A,B)$ be a mixed-4-separation of a 4-connected graph~$G$ that satisfies the degree-condition. Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{itm:trivial-tetra-separations-1} $(A,B)$ is not a tetra-separation;
        \item\label{itm:trivial-tetra-separations-2} $(A,B)$ is an atomic cut in~$G$;
        \item\label{itm:trivial-tetra-separations-3} $|A \sm B| = 1$ or $|B \sm A| = 1$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    \ref{itm:trivial-tetra-separations-2} $\Rightarrow$ \ref{itm:trivial-tetra-separations-1} is trivial.

    \ref{itm:trivial-tetra-separations-1} $\Rightarrow$ \ref{itm:trivial-tetra-separations-3}. If $(A,B)$ is not a tetra-separation, then there exist two edges in $S(A,B)$ that share an endvertex~$u$, say $u \in A \sm B$. Since $G$ is 4-connected and since $(A,B \cup \{u\})$ is a mixed-separation\pl{} of order at most~3, $(A,B)$ cannot be proper. Hence, $A \sm (B \cup \{u\}) = \emptyset$ and $A \sm B = \{u\}$.

    \ref{itm:trivial-tetra-separations-3} $\Rightarrow$ \ref{itm:trivial-tetra-separations-2}. If say $|A \sm B| = 1$ then $A \cap B = \emptyset$ by the degree-condition. It follows that $(A,B)$ is an atomic cut in $G$.
\end{proof}

Let $(A,B)$ and $(C,D)$ be mixed-separations\pl{} of a graph~$G$.
The \defn{corner-separator $L(A, C)$} for the corner $AC$ is the union of the $A$-link, the $C$-link, the vertex-centre, and the diagonal edges that have an end in the corner $AC$.
The corner-separators for the other three corners are defined analogously.

\begin{lemma}\emph{\cite[Lemma 1.3.4]{Tridecomp}}
\label{lem:submodularity-crossing}
    For two mixed-separations $(A, B)$ and $(C, D)$ of $G$, we have
    \[|L(A, C)| + |L(B,D)| \le |S(A, B)| + |S(C, D)|~.\]
    Moreover, if we have equality, there are no jumping edges, and every diagonal edge has its endvertices in the corners for~$AC$ and~$BD$.
\end{lemma}

\begin{lemma}
\label{lem:crossing-opposite-corners}
    Let two tetra-separations $(A,B)$ and $(C,D)$ cross in a 4-connected graph~$G$.
    Then there exist two opposite corner-separators of size at least~4.
\end{lemma}
\begin{proof}
    Otherwise, two adjacent corner-separators have size at most~3, say the corner-separator for~$AC$ and the corner-separator for~$BC$. By 4-connectivity, the corners for~$AC$ and~$BC$ are empty. Since $C \sm D \neq \emptyset$, the link~$L$ for~$C$ is nonempty. 
    The link $L$ only contains vertices since its adjacent corners are empty, so $L = (A \cap B) \sm D$. If $|L| \geq 2$ then the vertices in~$L$ have at most one neighbour in $A \sm B$ (and $B \sm A$), contradicting the degree-condition for $(A,B)$. Otherwise, if $|L| = 1$ then $(C,D)$ is not a tetra-separation by \cref{lem:trivial-tetra-separations}, a contradiction.
\end{proof}

The following lemma may be regarded as an analogue of \cite[Lemma 1.3.5]{Tridecomp}.

\begin{lemma}\label{lem:crossing-mixed-separations}
    Let $(A,B)$ and $(C,D)$ be two mixed-$k$-separations in a $k$-connected graph $G$ that cross so that two opposite corner-separators have size at least~$k$. Then either
    \begin{enumerate}
        \item\label{itm:crossing-mixed-separations-1} all links have the same size $\ell$ and the centre has size $k-2\ell$ for some $\ell \le \lfloor k/2 \rfloor$; or
        \item\label{itm:crossing-mixed-separations-2} two adjacent links have size~$i$, the other two links have size~$j$, and the centre has size $k-i-j$, where $1\le i \le \lfloor (k-1)/2 \rfloor$ and $i < j \leq k-i$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    By \cref{lem:submodularity-crossing}, two opposite corner-separators have size exactly~$k$, say the corner-separators for~$AC$ and~$BD$.
    Let $a, b, c, d$ denote the sizes of the links for $A, B, C, D$, respectively. Let $x$ denote the size of the centre. 
    By \cref{lem:submodularity-crossing}, every diagonal edge has its endvertices in the corners for~$AC$ and~$BD$; and there are no jumping edges. 
    We get $a + c + x = k$ and $b + d + x = k$ and $a + b + x = k$ and $c + d + x = k$. It follows that $b=c$ and $a=d$. Without loss of generality $a=d \leq b=c$.

    Since $a+c \leq k$ and $a \leq c$ we have $a=d \in \{0,1,\ldots,\lfloor k/2 \rfloor\}$. If $a=d=0$ then the corner for~$AD$ must be nonempty, and hence $x=k$ since $G$ is $k$-connected. Then $b=c=0$ and we get outcome~\ref{itm:crossing-mixed-separations-1}.

    Otherwise $1 \leq a=d \leq \lfloor k/2 \rfloor$. If $a=b=c=d=:\ell$ then we get $x=k-a-c = k-2 \ell$ and so get outcome~\ref{itm:crossing-mixed-separations-1}. Otherwise $i := a=d < b=c =: j$. Note that $i \leq \lfloor (k-1)/2 \rfloor$. With $x=k-a-c=k-i-j$, we get outcome~\ref{itm:crossing-mixed-separations-2}.
\end{proof}

\begin{lemma}
\label{lem:links-of-crossing-tetra-separations}
    Let $(A,B)$ and $(C,D)$ be two crossing tetra-separations in a 4-connected graph~$G$. Then all links have the same size~$\ell$ and the centre has size $4-2\ell$, for some $\ell \in \{0,1,2\}$.
\end{lemma}
\begin{proof}
    Suppose that not all links have size $\ell$, for some $\ell \in \{0,1,2\}$. 
    By \cref{lem:crossing-opposite-corners} and \cref{lem:crossing-mixed-separations}, we get that two adjacent links have size one, the other two links have size at least two and the centre has size at most one. 
    Without loss of generality, the corner~$K$ of~$AC$ is the corner whose adjacent links have size one. 
    The corner-separator of $K$ has size at most~3, so~$K$ is empty since~$G$ is 4-connected. 
    Then one of the links of size one contains a vertex~$u$, say $u \in (A \cap B) \sm D$. 
    But then $u$ has at most one neighbour in $A \sm B$, contradicting the degree-condition for~$(A,B)$.
    Hence all links have the same size~$\ell$ for some $\ell\in\{0,1,2\}$, and then the centre has size $4-2\ell$ by \cref{lem:crossing-opposite-corners} and \cref{lem:crossing-mixed-separations}.
\end{proof}




\begin{observation}
\label{obs:potter-adjacent-corner}
    Let $(A,B)$ and $(C,D)$ be crossing tetra-separations in a 4-connected graph~$G$.
    If a corner is potter, then its two adjacent corners are nonempty.
    In particular, no two adjacent corners are potter. \qed
\end{observation}

\begin{lemma}
\label{lem:crossing-edges}
    Let $(A,B)$ and $(C,D)$ be two crossing tetra-separations in a 4-connected graph~$G$. 
    \begin{enumerate}
        \item\label{itm:crossing-edges-1} There are no jumping edges and no diagonal edges.
        \item\label{itm:crossing-edges-2} Let $X,Y \in \{A,B,C,D\}$. 
        If some edge dangles from the $Y$-link through the $X$-link, then the corner for $XY$ is potter.
    \end{enumerate}
\end{lemma}
\begin{proof}
    \ref{itm:crossing-edges-1} By \cref{lem:links-of-crossing-tetra-separations}, all links have the same size $\ell$ and the centre has size $4-2\ell$. 
    By \cref{lem:submodularity-crossing}, there do not exist jumping edges nor diagonal edges.

    \ref{itm:crossing-edges-2} 
    Without loss of generality, $X=A$ and $Y=C$.
    Let $e=u_1u_2$ be a dangling edge such that $u_2$ lies in the $C$-link and $e$ lies in the $A$-link.
    We first show that the corner~$K$ for~$AC$ is empty. 
    Assume for contradiction that $K \neq \emptyset$. 
    By \cref{lem:links-of-crossing-tetra-separations} and 4-connectivity, $|L(A,C)| = 4$. 
    Then $L(A,C)-e$ is a mixed-3-separator separating the vertices in the corner for~$AC$ from~$u_1$.
    This contradicts 4-connectivity by \cref{kConMixed}.

    By the degree-condition of $(A,B)$ and since $K$ is empty, the vertex $u_2$ in the $C$-link has a neighbour~$u_3$ in the $A$-link. 
    By the degree-condition of $(C,D)$ and since $K$ is empty, the vertex~$u_3$ has a neighbour~$u_4$ in $(C \sm D) \cap B$. 
    It remains to show that~$u_4$ is in the corner for~$BC$. 
    Otherwise, $u_4$ is in the $C$-link.
    By the degree-condition of $(A,B)$ and since $K$ is empty, the vertex $u_4$ has a neighbour in $A\cap D$ besides $u_3$, and therefore the $A$-link contains a third vertex or edge besides $e$ and~$u_3$.
    This contradicts \cref{lem:links-of-crossing-tetra-separations}.
\end{proof}

\begin{proof}[Proof of the \allref{keylem:crossing}]
    We combine \cref{lem:links-of-crossing-tetra-separations} and \cref{lem:crossing-edges}.
\end{proof}


\section{Shifts: a tool for finding tetra-separations}\label{sec:shifts}

This section provides a `shifting' method for obtaining tetra-separations from genuine 4-separations, and from mixed-4-separations more generally.
There are `small' mixed-4-separations that fail to yield tetra-separations via the shifting method.
We characterise these in \cref{leftrightTetra}.

\subsection{Left-shifts and right-shifts}

\begin{definition}[Left-shift, right-shift]
    Let $(A,B)$ be a mixed-separation\pl\ in a graph. Let $L$ be the set of vertices in $A \cap B$ with at most one neighbour in $A \sm B$, and let $R$ be the set of vertices in $A \cap B$ with at most one neighbour in $B \sm A$.
    The \defn{left-shift} of $(A,B)$ is $(A \sm L, B)$.
    The \defn{right-shift} of $(A,B)$ is $(A,B \sm R)$.
\end{definition}

In the following, we prove lemmas for the left-shift.
All results have analogues for right-shifts by symmetry.

\begin{observation}\label{obs:shift-maintains-proper-sides}
    The left-shift $(A',B')$ of a mixed-separation\pl\ $(A,B)$ satisfies $A'\sm B'=A\sm B$ and $B'\sm A'\supseteq B\sm A$.\qed
\end{observation}

\begin{lemma}
\label{lem:left-shift}
    Let $(A,B)$ be a mixed-$k$-separation\pl\ of a graph~$G$ with left-shift $(A',B')$.
    \begin{enumerate}
        \item\label{lem:left-shift1} $(A',B')$ is a mixed-$\ell$-separation\pl\ with $\ell\le k$. We have $\ell=k$ if every vertex in $S(A,B)$ has a neighbour in $A\sm B$.
        \item\label{lem:left-shift2} Every vertex in $S(A',B')$ has $\ge 2$ neighbours in $A'\sm B'$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    \cref{lem:left-shift1}.
    By definition, the left-shift $(A',B')$ is a mixed-separation\pl{}. 
    The separator of $(A',B')$ is obtained from the separator of $(A,B)$ by replacing every vertex $v\in S(A,B)$ that has exactly one neighbour $u\in A\sm B$ with the edge $uv$ and by removing every vertex in $S(A,B)$ that has no neighbour in $A\sm B$.
    Hence the order of $(A',B')$ is at most that of $(A,B)$, with equality if every vertex in $S(A,B)$ has a neighbour in $A\sm B$.

    \cref{lem:left-shift2}.
    Assume for a contradiction that there is a vertex $v \in S(A',B')$ with at most one neighbour in $A' \sm B'$.
    Since $A'\sm B'=A\sm B$ by \cref{obs:shift-maintains-proper-sides}, the vertex $v$ also has at most one neighbour in $A \sm B$. 
    But then, by the definition of left-shift, we have $v \notin A'$, contradicting $v \in S(A',B')$.
\end{proof}






\begin{lemma}\label{leftMatching}
    Let $(A,B)$ be a mixed-4-separation\pl\ in a 4-connected graph~$G$.
    Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{leftMatching1} no two edges in $S(A,B)$ share an endvertex in $A\sm B$;
        \item\label{leftMatching2} $|A\sm B|\ge 2$ or $|S(A,B)\cap E(G)|\le 1$.
    \end{enumerate} 
\end{lemma}
\begin{proof}
    \cref{leftMatching1} $\Rightarrow$ \cref{leftMatching2} is immediate.

    \cref{leftMatching2} $\Rightarrow$ \cref{leftMatching1}.
    Assume that \cref{leftMatching1} fails, so there are two edges $ab_1,ab_2\in S(A,B)$ with $a\in A\sm B$ and both $b_i\in B\sm A$.
    Let $X$ be the vertex-set that consists of $a$ together with all vertices in $S(A,B)$ and all endvertices in $B$ of edges in $S(A,B)$ other than the $ab_i$.
    Since $|A\sm B|\ge 2$ by \cref{leftMatching2}, there is $\alpha\in A\sm B$ distinct from~$a$.
    If some $b_i$ is not in $X$, we let $\beta:=b_i$.
    Otherwise both $b_i$ are in $X$, each has exactly two neighbours in $A\sm B$, and $S(A,B)$ contains only edges.
    Since $b_1$ has degree four, it has a neighbour $\beta$ in $B\sm A$ that is distinct from~$b_2$.
    In either case, $X$ is a 3-separator that separates $\alpha$ from~$\beta$, contradicting that $G$ is 4-connected.
\end{proof}

\begin{lemma}\label{leftDegreeStrongerMatching}
    Let $(A,B)$ be a mixed-4-separation\pl\ in a 4-connected graph~$G$ such that every vertex in $S(A,B)$ has $\ge 2$ neighbours in $A\sm B$.
    Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{leftDegreeStrongerMatching1} no two edges in $S(A,B)$ share an end in $A\sm B$;
        \item\label{leftDegreeStrongerMatching2} $(A,B)$ is not an atomic edge-cut with $|A|=1$;
        \item\label{leftDegreeStrongerMatching3} $|A\sm B|\ge 2$.
    \end{enumerate} 
\end{lemma}
\begin{proof}
    \cref{leftDegreeStrongerMatching1} $\Rightarrow$ \cref{leftDegreeStrongerMatching2} is immediate.

    \cref{leftDegreeStrongerMatching2} $\Rightarrow$ \cref{leftDegreeStrongerMatching3}.
    Assume $|A\sm B|\le 1$.
    Since every vertex in $S(A,B)$ has $\ge 2$ neighbours in $A\sm B$, we get that $S(A,B)$ is an edge-cut.
    Since $S(A,B)$ is nonempty, $|A|=1$ follows.

    \cref{leftDegreeStrongerMatching3} $\Rightarrow$ \cref{leftDegreeStrongerMatching1}.
    This follows from \cref{leftMatching} \cref{leftMatching2} $\Rightarrow$ \cref{leftMatching1}.
\end{proof}

\begin{lemma}\label{leftMatchingMedium}
    Let $(A,B)$ be a mixed-4-separation\pl\ in a 4-connected graph $G$
    with $A\sm B\neq\emptyset$ and
    such that no two edges in $S(A,B)$ share an end in $B\sm A$.
    Let $(A',B')$ denote the left-shift of $(A,B)$.
    Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{leftMatchingMedium1} $(A',B')$ satisfies the matching-condition;
        \item\label{leftMatchingMedium2} $|A\sm B|\ge 2$.
    \end{enumerate} 
\end{lemma}
\begin{proof}
    By \cref{lem:left-shift}, every vertex in $S(A',B')$ has $\ge 2$ neighbours in $A'\sm B'$.

    \cref{leftMatchingMedium1} $\Rightarrow$ \cref{leftMatching2}.
    Suppose $|A\sm B|\le 1$.
    So $|A\sm B|=1$ since $A\sm B\neq\emptyset$.
    Then $|A'\sm B'|=1$ since $A\sm B=A'\sm B'$.
    Applying \cref{leftDegreeStrongerMatching} to $(A',B')$ yields that $(A',B')$ is an atomic edge-cut.

    \cref{leftMatching2} $\Rightarrow$ \cref{leftMatching1}.
    From $A\sm B= A'\sm B'$ we get $|A'\sm B'|\ge 2$.
    So no two edges in $S(A',B')$ share an end in $A'\sm B'$ by \cref{leftDegreeStrongerMatching} applied to $(A',B')$.
    So suppose for a contradiction that there are two distinct edges $a_1 b,a_2 b$ in $S(A',B')$ with $a_i\in A'\sm B'$ and $b \in B' \sm A'$.
    Then $a_i\in A'\sm B'= A\sm B$ and $b\in B\cap A$.
    Hence $b$ has $\ge 2$ neighbours in $A\sm B$, contradicting that~$b$ was replaced with edges when taking the left-shift.
\end{proof}

\begin{lemma}\label{Righty}
    Let $G$ be a 4-connected graph.
    Let $(A,B)$ be a mixed-4-separation of~$G$.
    Let $(C,D)$ be a 4-separation of $G$ with right-shift $(C',D')$.
    Assume $A\se C$.
    Then $(A,B)\le (C',D')$.
\end{lemma}
\begin{proof}
    We obtain $A\se C'$ from $A\se C=C'$.
    Let $X$ consist of all endvertices in $A$ of edges in $S(A,B)$.
    Then $N(B\sm A)=(A\cap B)\cup X$.
    From $A\se C$ we obtain $D\sm C\se B\sm A$.
    Hence $D\se (B\sm A)\cup N(B\sm A)=B\cup X$.
    Recall that $D'\se D$.
    Let $v\in D'$.
    It suffices to show that $v\notin X$.
    If $v\in X$, then $v$ has exactly one neighbour in $B\sm A$.
    Since $B\sm A\supseteq D\sm C$, the definition of right-shift yields $v\notin D'$, a contradiction.
    So $v\notin X$.
\end{proof}


\subsection{Left-right-shifts and right-left-shifts}\label{sec:LeftRightShift}


\begin{definition}
    Let $(A,B)$ be a mixed-separation\pl . 
    The \defn{left-right-shift} of $(A,B)$ is obtained from $(A,B)$ by first taking the left-shift and then the right-shift.
    The \defn{right-left-shift} of $(A,B)$ is obtained from $(A,B)$ by first taking the right-shift and then the left-shift.
\end{definition}


\begin{observation}
\label{obs:reduction-maintains-proper-sides}
    Let $(A',B')$ be the left-right-shift of a mixed-4-separation\pl\ $(A,B)$ in a graph~$G$. 
    Then $A' \sm B' \supseteq A \sm B$ and $B' \sm A' \supseteq B \sm A$.
\end{observation}
\begin{proof}
    We perform the two shifts one after the other, applying \cref{obs:shift-maintains-proper-sides} after each shift.
\end{proof}

\begin{keylemma}\label{leftrightTetra}
    Let $(A,B)$ be a mixed-4-separation\pl\ in a 4-connected graph $G$.
    The left-right-shift $(A'',B'')$ of $(A,B)$ is a tetra-separation if and only if the following three conditions are satisfied:
    \begin{enumerate}
        \item\label{leftrightTetra1} $|A\sm B|\ge 2$;
        \item\label{leftrightTetra2} the number of vertices in $S(A,B)$ with $\le 1$ neighbour in $A\sm B$ is $\ge 2- |B\sm A|$;
        \item\label{leftrightTetra3} $|B\sm A|\ge 2$ or $|S(A,B)\cap E(G)|\le 1$.
    \end{enumerate}
\end{keylemma} 
\begin{proof}
    Let $(A',B')$ denote the left-shift of $(A,B)$.

    \casen{Backward implication.}
    Assume \cref{leftrightTetra1}--\cref{leftrightTetra3}.
    By \cref{leftrightTetra3} and \cref{leftMatching} (applied to $(B,A)$ instead of $(A,B)$), no two edges in $S(A,B)$ share an endvertex in $B\sm A$.
    By \cref{leftrightTetra1} and \cref{leftMatchingMedium}, $(A',B')$ satisfies the matching-condition.
    By \cref{lem:left-shift}, every vertex in $S(A',B')$ has $\ge 2$ neighbours in $A'\sm B'$.
    By \cref{leftrightTetra1} and since $G$ is 4-connected, every vertex in $S(A,B)$ has a neighbour in $A\sm B$.
    Hence $(A',B')$ has order four by \cref{lem:left-shift}.
    We further have $|A'\sm B'|=|A\sm B|\ge 2$ by \cref{obs:reduction-maintains-proper-sides} and we have $|B'\sm A'|\ge 2$ by~\cref{leftrightTetra2}.

    By \cref{leftMatchingMedium} (applied for the right-shift), $(A'',B'')$ satisfies the matching-condition.
    By \cref{lem:left-shift} (applied for the right-shift), every vertex in $S(A'',B'')$ has $\ge 2$ neighbours in $B''\sm A''$.
    Every vertex in $S(A'',B'')$ has $\ge 2$ neighbours in $A''\sm B''$ since $A''\sm B''=A'\sm B'$ by \cref{obs:reduction-maintains-proper-sides} (applied for the right-shift).
    Hence $(A'',B'')$ satisfies the degree-condition.
    Since $B'\sm A'$ is nonempty and $G$ is 4-connected, every vertex in $S(A',B')$ has a neighbour in $B'\sm A'$, so $(A'',B'')$ has order four by \cref{lem:left-shift} (applied for the right-shift).
    Finally, $A''\sm B''=A'\sm B'$ and $B''\sm A''\supseteq B'\sm A'$ by \cref{obs:reduction-maintains-proper-sides}, so $(A'',B'')$ is proper.

    \casen{Forward implication.}
    Suppose first that \cref{leftrightTetra3} fails.
    Then, by \cref{leftMatching} for $(B,A)$, there are two edges $a b_1, a b_2$ in $S(A,B)$ with $a\in A\sm B$ and $b_i\in B\sm A$.
    Then $a\in A''\sm B''$ and $b_i\in B''\sm A''$ by \cref{obs:reduction-maintains-proper-sides}.
    Hence $(A'',B'')$ fails the matching-condition.

    Suppose next that \cref{leftrightTetra3} holds, but \cref{leftrightTetra1} or \cref{leftrightTetra2} fails.
    By \cref{leftrightTetra3} and \cref{leftMatching} for $(B,A)$, no two edges in $S(A',B')$ share an endvertex in~$B'\sm A'$.
    If \cref{leftrightTetra1} fails, we have $|A\sm B|\le 1$, so \cref{leftMatchingMedium} gives that $(A',B')$ violates the matching-condition, and hence $(A'',B'')$ also violates the matching-condition.
    Next, assume that \cref{leftrightTetra1} holds, but \cref{leftrightTetra2} fails.
    As $|A\sm B|\ge 2$, \cref{leftMatchingMedium} gives that $(A',B')$ satisfies the matching-condition.
    The failure of \cref{leftrightTetra2} yields $|B'\sm A'|\le 1$.
    Hence applying \cref{leftMatchingMedium} to $(B',A')$ (instead of $(A,B)$) yields that $(A'',B'')$ violates the matching-condition.
\end{proof}



\begin{proof}[Proof of \cref{quasi5conVtetra}.]
    \cref{quasi5conVtetra1}.
    If $G$ is not quasi-5-connected, it has a 4-separation $(A,B)$ with $|A\sm B|\ge 2$ and $|B\sm A|\ge 2$.
    Hence the right-left-shift of $(A,B)$ is a tetra-separation of $G$ by \cref{leftrightTetra}.

    \cref{quasi5conVtetra2}.
    Let $(A,B)$ be a tetra-separation of $G$.
    Let $X:=A\sm B$ and $Y:=B\sm A$.
    Let $F$ denote the set of edges in $S(A,B)$.
    We have
    \[
        8\le |G| =|X|+|Y|+4-|F|
    \]
    and therefore
    \[
        |F| \le (\,|X|-2)+(\,|Y|-2).
    \]
    Both $X$ and $Y$ have size $\ge 2$ by \cref{lem:trivial-tetra-separations} since $(A,B)$ is a tetra-separation.
    Hence both terms $|X|-2$ and $|Y|-2$ are $\ge 0$.
    We may therefore bipartition $F$ into classes $F_X$ and $F_Y$ of $\le |X|-2$ and $\le |Y|-2$ edges, respectively.
    We obtain $X'$ from $X$ by adding for each edge in $F_X$ its endvertex in $A$ to $X$, and we obtain $Y'$ similarly.
    Then $(X',Y')$ is a 4-separation of $G$.
    We have $|X'\sm Y'|\ge |X|-|F_X|\ge 2$, and similarly $|Y'\sm X'|\ge 2$.
    Thus $G$ is not quasi-5-connected.
\end{proof}













\section{Understanding nestedness through connectivity}\label{sec:ExternalConnectivity}

The purpose of this section is to characterise the property of total-nestedness for tetra-separations $(A,B)$ in terms of connectivity-properties of their separators~$S(A,B)$; see \cref{keylem:nestedness-external-connectivity}.
This translates the problem of proving total-nestedness of $(A,B)$ to a problem about constructing various families of paths that link up the vertices and edges in the separator $S(A,B)$ in different ways.


For an element $x\in V(G)\cup E(G)$ we let \defnMath{$\hat x$} denote the singleton $\{x\}$ if $x$ is a vertex, and the set of endvertices of $x$ if $x$ is an edge.
For a set $X\se V(G)\cup E(G)$ we write $\defnMath{\hat X}:=\bigcup_{x\in X}\hat x$.

A bipartition of a set is \defn{balanced} if its two classes have the same size.

\begin{lemma}\label{kConMixed}
    Let $G$ be a $k$-connected graph.
    Then $G$ has no mixed-$\ell$-separation for any $\ell<k$.
\end{lemma}
\begin{proof}
    Assume for a contradiction that $(A,B)$ is a mixed-$\ell$-separation of $G$ with $\ell<k$.
    Then $S(A,B)$ contains an edge $ab$ with $a\in A\sm B$ and $b\in B\sm A$.
    We claim that $A\sm (B\cup\{a\})$ or $B\sm (A\cup\{b\})$ is non-empty.
    Indeed, otherwise $V(G)=(A\cap B)\cup\{a,b\}$, so $|G|=\ell+1\le k$, contradicting that $k$-connected graphs such as $G$ have $>k$ vertices by definition.
    So suppose that there is a vertex $v\in A\sm (B\cup\{a\})$.
    Let $X$ be obtained from $S(A,B)$ by keeping all vertices, replacing $ab$ with $a$,  and replacing each other edge with its endvertex in $B\sm A$.
    Then $X$ is an $\ell$-separator of $G$ that separates $v$ from~$b$, contradicting that $G$ is $k$-connected.
\end{proof}

Let $X,Y$ be two vertex-sets in a graph~$G$.
A mixed-separation $(A,B)$ of $G$ \defn{strongly separates} $X$ and $Y$ if $X\se A\sm B$ and $Y\se B\sm A$.
Note that if $(A,B)$ strongly separates $X$ and $Y$, then $X$ and $Y$ are disjoint.
The following lemma is folklore; we include a proof for convenience.

\begin{lemma}[Menger for independent paths]\label{Menger}
Let $X,Y$ be two disjoint vertex-sets in a graph~$G$. Then the following two numbers are equal:
\begin{enumerate}
    \item\label{MengerPaths} the maximum number of independent $X$--$Y$ paths in~$G$;
    \item\label{MengerSep} the minimum order of a mixed-separation in $G$ that strongly separates $X$ and~$Y$.
\end{enumerate}
Moreover, if $G$ is $k$-connected, then \ref{MengerPaths}, \ref{MengerSep}${}\ge k$.
\end{lemma}

\begin{proof}
    As usual, \ref{MengerPaths} $\le$ \ref{MengerSep}, so it remains to show \ref{MengerPaths} $\ge$ \ref{MengerSep}.
    Since every $X$--$Y$ edge forms a path in every maximum set of independent $X$--$Y$ paths in $G$, we may assume without loss of generality that $G$ contains no $X$--$Y$ edges.
    Let $X':=N_G(X)$ and $Y':=N_G(Y)$.
    Note that $X'\cup Y'$ is disjoint from $X\cup Y$.
    Let $G':=G-(X\cup Y)$.

    Now let $\cP$ be a maximum-size set of independent $X$--$Y$ paths in~$G$.
    Then $\cP$ determines a set $\cP'$ of $|\cP|$ pairwise disjoint $X'$--$Y'$ paths in~$G'$.
    Hence $G'$ contains an $X'$--$Y'$ separator $S'$ of size $|\cP|$, by Menger's theorem applied in $G'$ to $X',Y'$ and $\cP'$.
    Then $S'$ is the separator of a mixed-separation of $G$ that strongly separates $X$ and~$Y$, and which has order $|S'|=|\cP|$.

    The `moreover'-part follows from \cref{kConMixed}.
\end{proof}


\subsection{Half-connected}

A mixed-separation $(A,B)$ of a graph $G$ is \defn{half-connected} if $G[A\sm B]$ or $G[B\sm A]$ is connected~\cite{Tridecomp}.

\begin{lemma}
\label{lem:nestedness-half-connected}
    Let $(A,B)$ be a tetra-separation of a 4-connected graph~$G$. Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{itm:nestedness-half-connected-1} $(A,B)$ is half-connected;
        \item\label{itm:nestedness-half-connected-2} no tetra-separation of $G$ crosses $(A,B)$ so that all links are empty.
    \end{enumerate}
\end{lemma}
\begin{proof}
    $\neg$ \ref{itm:nestedness-half-connected-2}~$\Rightarrow$~$\neg$ \ref{itm:nestedness-half-connected-1}. 
    If a tetra-separation of $G$ crosses $(A,B)$ so that all links are empty, then all corners are nonempty. Hence, neither $G[A \sm B]$ nor $G[B \sm A]$ is connected.

    $\neg$ \ref{itm:nestedness-half-connected-1}~$\Rightarrow$~$\neg$ \ref{itm:nestedness-half-connected-2}. Assume that $(A,B)$ is not half-connected; that is, $G[A \sm B]$ and $G[B \sm A]$ are not connected.
    Then $S(A,B)$ consists of vertices only.
    Let $C_A$ be a component of $G[A \sm B]$ and let $C_B$ be a component of $G[B \sm A]$. 
    Let $C := V(C_A)\cup V(C_B) \cup S(A,B)$ and $D := V(G-C_A-C_B)$. 
    Then $(C,D)$ is a genuine 4-separation with $S(C,D)=S(A,B)$ that crosses $(A,B)$ with all links empty.
    To see that $(C,D)$ is a tetra-separation, note first that both $G[C \sm D]$ and $G[D \sm C]$ are disconnected. 
    Since $G$ is 4-connected, every vertex in $S(A,B)$ has a neighbour in every component of $G-S(A,B)$.
    So $(C,D)$ satisfies the degree-condition, and it trivially satisfies the matching-condition.
\end{proof}




\subsection{3-linked}

\begin{definition}[3-linked]
\label{dfn:3-linked}
Let $X=\{x_1,x_2,x_3,x_4\}$ be the separator of a tetra-separation $(A,B)$ of a graph~$G$.
We say that $\{x_1,x_2\}$ is \defn{3-linked around~$X$} if at least one of the following holds:
\begin{defenum}
    \item\label{itm:3-linked-1} $x_3$ or $x_4$ is an edge;
    \item\label{itm:3-linked-2} $x_1$ or $x_2$ is a vertex and there is an $\hat x_1$--$\hat x_2$ edge;
    \item\label{itm:3-linked-3} there are three independent $\hat x_1$--$\hat x_2$ paths in $G-x_3-x_4$.
\end{defenum}
Similarly, we define that $\{x_i,x_j\}$ is \defn{3-linked around~$X$} for other choices of distinct indices $i,j\in [4]$.
We say that $(A,B)$ is \defn{3-linked} if every pair of distinct elements in $S(A,B)$ is 3-linked around~$X$.
\end{definition}

\begin{lemma}
\label{lem:nestedness-3-linked}
    Let $X=\{x_1,x_2,x_3,x_4\}$ be the separator of a tetra-separation $(A,B)$ in a 4-connected graph~$G$. 
    The following assertions are equivalent:
    \begin{enumerate}
        \item\label{itm:nestedness-3-linked-1} $\{x_1,x_2\}$ is 3-linked around~$X$;
        \item\label{itm:nestedness-3-linked-2} no tetra-separation of $G$ crosses $(A,B)$ so that $x_1$ and $x_2$ are in opposite links while the centre has size~2.
    \end{enumerate}
\end{lemma}
\begin{proof}
    $\neg$ \ref{itm:nestedness-3-linked-2} $\Rightarrow$ $\neg$ \ref{itm:nestedness-3-linked-1}. 
    Assume that a tetra-separation $(C,D)$ crosses $(A,B)$ so that~$x_1$ and~$x_2$ are in opposite links while the centre has size~2. 
    By the \allref{keylem:crossing}, all links have size~1 and there are no jumping edges, no diagonal edges and no dangling edges.
    So,~$x_3$ and~$x_4$ are both vertices, which shows that~\ref{itm:3-linked-1} does not hold. 
    Since there are no dangling edges and no jumping edges, if there exists an $\hat x_1$--$\hat x_2$ edge then both~$x_1$ and~$x_2$ are edges. 
    This shows that~\ref{itm:3-linked-2} does not hold.
    Since there are no diagonal edges, no jumping edges and no dangling edges, every $\hat x_1$--$\hat x_2$ path that avoids~$x_3$ and~$x_4$ has an inner vertex or an edge in the link for~$A$ or the link for~$B$. Hence, there are at most two independent $\hat x_1$--$\hat x_2$ paths in $G-x_3-x_4$. This shows that~\ref{itm:3-linked-3} does not hold. So, $\{x_1,x_2\}$ is not 3-linked around~$X$.

    $\neg$ \ref{itm:nestedness-3-linked-1} $\Rightarrow$ $\neg$ \ref{itm:nestedness-3-linked-2}. 
    Assume that $\{x_1,x_2\}$ is not 3-linked around~$X$. 
    Then $x_3$ and $x_4$ are both vertices and there are at most two independent $\hat x_1$--$\hat x_2$ paths in $G-x_3-x_4$.
    By \allref{Menger}, there is a mixed-2-separation~$(C,D)$ of~$G-x_3-x_4$ that strongly separates~$\hat x_1$ from~$\hat x_2$, say with~$\hat x_1 \subseteq C \sm D$ and $\hat x_2 \subseteq D \sm C$.
    Let~$(C',D'):=(C \cup \{x_3,x_4\}, D \cup \{x_3,x_4\})$, which is a mixed-4-separation.
    Observe that~$(C',D')$ crosses~$(A,B)$ since the $C'$-link and the $D'$-link are non-empty.

    We claim that both~$C' \sm D'$ and~$D' \sm C'$ have size~$\geq 2$.
    Assume otherwise, say~$x_1$ is a vertex and it is the only vertex in~$C' \sm D'$.
    By the degree-condition for~$x_1 \in S(A,B)$, it has at least four neighbours in $V(G) \sm (A \cap B)$. This, however, contradicts that~$(C,D)$ has order two.

    Let~$(C'',D'')$ be the left-right-shift of~$(C',D')$, which is a tetra-separation by \cref{leftrightTetra}.
    First, note that~$\hat x_1 \subseteq C' \sm D' \subseteq C'' \sm D''$ and $\hat x_2 \subseteq D' \sm C' \subseteq D'' \sm C''$ by \cref{obs:reduction-maintains-proper-sides}.
    So,~$x_1$ and~$x_2$ are in the $C''$-link and the $D''$-link, respectively.
    In particular, $(C'',D'')$ crosses $(A,B)$.

    We claim that $x_3,x_4 \in S(C'',D'')$.
    Assume not, say~$x_3 \in C'' \sm D''$. 
    Let $e\in S(C'',D'')$ be the edge that $x_3$ sends to $D''\sm C''$.
    By the \allref{keylem:crossing},~$e$ is not a jumping edge. 
    So there is an~$X \in \{A,B\}$ such that~$e$ dangles from the $C''$-link through the $X$-link, say $X=A$.
    By the \allref{keylem:crossing}, the corner~$AC''$ is potter. 
    In particular,~$x_1$ is an edge that dangles from the $A$-link through the $C''$-link. 
    Then, however, $\hat x_1 \nsubseteq C'' \sm D''$, a contradiction.
    Hence,~$(C'',D'')$ crosses~$(A,B)$ so that~$x_1$ and~$x_2$ are in opposite links while the centre has size~2.
\end{proof}





\subsection{Potter-linked}

Let $(A,B)$ be a mixed-separation of a graph~$G$.
Let $\{x_1,x_2\}\se S(A,B)$ consist of an edge and a vertex, say $x_1$ is the edge and $x_2$ is the vertex.
Write $x_1=ab$ with $a\in A\sm B$ and $b\in B\sm A$.
In the context of $(A,B)$, we say that $\{x_1,x_2\}$ is \defn{$A$-weird} if $x_2$ has exactly one neighbour in $A \sm \{a\}$.
If $(A,B)$ is a tetra-separation, this is equivalent to saying that $x_2$ has exactly two neighbours in $A$ and $a$ is one of them.

\begin{example}
\label{obs:potter-implies-weird}
    Let $(A,B)$ and $(C,D)$ be crossing tetra-separations in a graph~$G$.
    Assume that the corner for $AC$ is potter, witnessed by an edge $u_1 u_2$ that dangles from the vertex $u_2$ in the $C$-link through the $A$-link, and by an edge $u_3 u_4$ that dangles from the vertex $u_3$ in the $A$-link through the $C$-link; see \cref{fig:PotterDef}.
    Then $\{u_2,u_3u_4\}$ is $A$-weird and $\{u_3,u_1u_2\}$ is $C$-weird.
\end{example}




Let $X,Y\se V(G)\cup E(G)$.
An \defn{$X$--$Y$ edge} means an edge $xy$ with $x\in X$ and $y\in Y$.

\begin{definition}[0-potter-linked]
\label{dfn:0-potter-linked}
Let~$\{\pi_1,\pi_2\}$ be a balanced bipartition of the separator of a tetra-separation~$(A,B)$ in a graph~$G$.
We say that $\{\pi_1,\pi_2\}$ is \defn{0-potter-linked} with respect to~$(A,B)$ if at least one of the following assertions holds:
\begin{defenum}
    \item\label{itm:0-potter-linked-1} there is a $\pi_1$--$\hat \pi_2$ edge or a $\hat \pi_1$--$\pi_2$ edge;
    \item\label{itm:0-potter-linked-2} there are five independent $\hat \pi_1$--$\hat \pi_2$ paths in~$G$.
\end{defenum}
Note that this is symmetric in~$\pi_1$ and $\pi_2$.
A~tetra-separation $(A,B)$ is \defn{0-potter-linked} if $\{\pi_1,\pi_2\}$ is 0-potter-linked for every balanced bipartition $\{\pi_1,\pi_2\}$ of $S(A,B)$. 
\end{definition}




\begin{lemma}
\label{lem:nestedness-0-potter-linked}
    Let $(A,B)$ be a tetra-separation of a 4-connected graph~$G$.
    Let $\{\pi_1,\pi_2\}$ be a balanced bipartition of $S(A,B)$. 
    Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{itm:nestedness-0-potter-linked-1} $\{\pi_1,\pi_2\}$ is 0-potter-linked;
        \item\label{itm:nestedness-0-potter-linked-2} no tetra-separation of $G$ crosses $(A,B)$ so that $\pi_1$ and $\pi_2$ form opposite links and no corner is potter.
    \end{enumerate}
\end{lemma}
\begin{proof}
    $\neg$ \ref{itm:nestedness-0-potter-linked-2} $\Rightarrow$ $\neg$ \ref{itm:nestedness-0-potter-linked-1}.
    Assume that a tetra-separation $(C,D)$ of $G$ crosses $(A,B)$ so that $\pi_1$ and $\pi_2$ form opposite links and no corner is potter.
    Hence by the \allref{keylem:crossing}, no edge is dangling, jumping, or diagonal.
    It follows that if there exists a $\hat \pi_1$--$\hat \pi_2$ edge~$uv$, then both~$u$ and~$v$ are endvertices of edges in~$S(A,B)$. This shows that~\ref{itm:0-potter-linked-1} fails.

    It remains to show that there are at most four $\hat\pi_1$--$\hat\pi_2$ paths in~$G$.
    As no edge is dangling, jumping, or diagonal, every $\hat\pi_1$--$\hat\pi_2$ path in $G$ must have an internal vertex or an edge in the $A$-link or in the $B$-link. 
    The sum of the sizes of the $A$-link and the $B$-link is at most~4 since the size of $S(C,D)$ is at most~4.
    Hence \ref{itm:0-potter-linked-2} fails.

    $\neg$ \ref{itm:nestedness-0-potter-linked-1} $\Rightarrow$ $\neg$ \ref{itm:nestedness-0-potter-linked-2}. 
    Assume that $\{\pi_1,\pi_2\}$ is not 0-potter-linked.
    Then there are at most four independent $\hat\pi_1$--$\hat\pi_2$ paths in $G$.
    By \allref{Menger}, there is a mixed-4-separation $(C,D)$ of $G$ that strongly separates $\hat\pi_1$ from $\hat\pi_2$, say with~$\hat \pi_1 \subseteq C \sm D$ and~$\hat \pi_2 \subseteq D \sm C$.
    In particular, $|C \sm D| \geq 2$ and $|D \sm C| \geq 2$.
    Observe that $(C,D)$ crosses $(A,B)$ since the $C$-link and the $D$-link are non-empty. 
    Let $(C',D')$ be the left-right-shift of $(C,D)$, which is a tetra-separation by \cref{leftrightTetra}.

    We claim that~$(C',D')$ crosses~$(A,B)$ so that~$\pi_1$ and~$\pi_2$ form opposite links and no corner is potter.
    Since $\hat \pi_1 \subseteq C \sm D \subseteq C' \sm D'$ and $\hat \pi_2 \subseteq D \sm C \subseteq D' \sm C'$ by \cref{obs:reduction-maintains-proper-sides},~$\pi_1$ forms the $C'$-link while~$\pi_2$ forms the $D'$-link.
    In particular,~$(C',D')$ crosses~$(A,B)$.
    Assume for contradiction that some corner is potter, say the corner $AC'$. 
    Then~$\pi_1$ is $A$-weird and hence contains an edge~$e$.
    Let~$a$ be the endvertex of~$e$ in~$A \sm B$. So,~$a \in \hat \pi_1 \subseteq C' \sm D'$. Therefore,~$a$ is contained in the corner~$AC'$.
    In particular, the corner $AC'$ is not empty, and so it is not potter, a contradiction.
\end{proof}




The following definition is supported by \cref{fig:1potterLinkedDef}.

\begin{definition}[1-potter-linked]
\label{dfn:1-potter-linked}
    Let~$\{\pi_1,\pi_2\}$ be a balanced bipartition of the separator of a tetra-separation~$(A,B)$ of a graph~$G$.
    Let~$(X,Y)=(A,B)$ or~$(X,Y)=(B,A)$.
    We say that \defn{$\pi_1$ is 1-potter-linked to~$\pi_2$ around~$X$} with respect to $(A,B)$ if at least one of the following holds:
    \begin{defenum}
        \item\label{itm:1-potter-linked-1} $\pi_1$ is not $X$-weird;
        \item\label{itm:1-potter-linked-2} there is a $\pi_1$--$(\hat \pi_2 \cap Y)$ edge or a $(\hat \pi_1 \cap Y)$--$\pi_2$ edge;
        \item\label{itm:1-potter-linked-3} there are three independent $\hat \pi_1$--$\hat \pi_2$ paths in~$G[Y]$.
    \end{defenum}
    Note that this is \emph{not} symmetric in~$\pi_1,\pi_2$.
    We say that~$\{\pi_1,\pi_2\}$ is \defn{1-potter-linked} with respect to~$(A,B)$ if for both $X \in \{A,B\}$,~$\pi_1$ is 1-potter-linked to~$\pi_2$ around~$X$ and~$\pi_2$ is 1-potter-linked to~$\pi_1$ around~$X$ with respect to~$(A,B)$.
    A~tetra-separation $(A,B)$ is \defn{1-potter-linked} if $\{\pi_1,\pi_2\}$ is 1-potter-linked for every balanced bipartition $\{\pi_1,\pi_2\}$ of $S(A,B)$.
\end{definition}

\begin{figure}[ht]
    \centering
    \includegraphics[height=8\baselineskip]{Figures/1potterLinkedDef.pdf}
    \caption{$\pi_1$ is red and $X$-weird. $\pi_2$ is blue.
    Both pictures include how a mixed-separation $(C,D)$ might exploit the weirdness of $\pi_1$ to cross $(A,B)$.
    Left: the yellow edges satisfy \ref{itm:1-potter-linked-2}. Right: the yellow paths satisfy \ref{itm:1-potter-linked-3}.}
    \label{fig:1potterLinkedDef}
\end{figure}


\begin{lemma}\label{lem:nestedness-1-potter-linked}
    Let $(A,B)$ be a tetra-separation of a 4-connected graph~$G$ and let $\{\pi_1,\pi_2\}$ be a balanced bipartition of $S(A,B)$. 
    Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{itm:nestedness-1-potter-linked-1} $\{\pi_1,\pi_2\}$ is 1-potter-linked with respect to $(A,B)$;
        \item\label{itm:nestedness-1-potter-linked-2} no tetra-separation of $G$ crosses $(A,B)$ so that $\pi_1$ and $\pi_2$ form opposite links and exactly one corner is potter.
    \end{enumerate}
\end{lemma}
\begin{proof}
    $\neg$ \ref{itm:nestedness-1-potter-linked-2} $\Rightarrow$ $\neg$ \ref{itm:nestedness-1-potter-linked-1}. 
    Assume that a tetra-separation $(C,D)$ crosses $(A,B)$ so that $\pi_1$ and $\pi_2$ form opposite links, say $\pi_1$ is the $C$-link and~$\pi_2$ is the $D$-link, and so that exactly one corner is potter, say the $AC$-corner.
    We show that~$\pi_1$ is \emph{not} 1-potter-linked to~$\pi_2$ with respect to~$(A,B)$.
    For this, we show that for~$(X,Y)=(A,B)$ in \cref{dfn:1-potter-linked}, all of \ref{itm:1-potter-linked-1}--\ref{itm:1-potter-linked-3} fail.

    Observe that $\pi_1$ is $A$-weird by \cref{obs:potter-implies-weird}, so \ref{itm:1-potter-linked-1} fails.
    By assumption, the corner $AC$ is the only corner that is potter.
    By the \allref{keylem:crossing}, every link has size two while the centre is empty.
    Moreover, there do not exist jumping or diagonal edges, and the $B$-link contains no dangling edge.
    It follows that there is no $\pi_1$--$(\hat \pi_2 \cap B)$ edge and no $(\hat \pi_1 \cap B)$--$\pi_2$ edge, so \ref{itm:1-potter-linked-2} fails.
    Moreover, every $\hat\pi_1$--$\hat\pi_2$ path in $G[B]$ has an internal vertex or an edge in the $B$-link. 
    Thus, there are at most two independent $\hat\pi_1$--$\hat\pi_2$ paths in $G[B]$, so \ref{itm:1-potter-linked-3} fails.

    $\neg$ \ref{itm:nestedness-1-potter-linked-1} $\Rightarrow$ $\neg$ \ref{itm:nestedness-1-potter-linked-2}.
    Assume that $\{\pi_1,\pi_2\}$ is not 1-potter-linked with respect to $(A,B)$. 
    Without loss of generality,~$\pi_1$ is not 1-potter-linked to~$\pi_2$ and \ref{itm:1-potter-linked-1}--\ref{itm:1-potter-linked-3} fail for~$(X,Y)=(A,B)$.
    By $\neg$~\ref{itm:1-potter-linked-1}, $\pi_1$ is $A$-weird.
    Write $\pi_1=:\{v_1,e_1\}$ where $v_1$ is a vertex and $e_1=a_1 b_1$ is an edge with $a_1\in A\sm B$ and $b_1\in B\sm A$.
    Let $a'_1$ be the unique neighbour of $v_1$ in $A$ besides~$a_1$.
    Note that $a'_1$ lies in $A\sm B$ by the degree-condition for~$v_1$.

    By $\neg$~\ref{itm:1-potter-linked-3}, there are at most two independent $\hat\pi_1$--$\hat\pi_2$ paths in $G[B]$. 
    By \allref{Menger}, there is a mixed-separation $(C_1,D_1)$ of $G[B]$ of order $\le 2$ that strongly separates $\hat\pi_1$ from $\hat\pi_2$, say with $\hat\pi_1 \cap B \subseteq C_1 \sm D_1$ and $\hat\pi_2 \cap B \subseteq D_1\sm C_1$.
    In particular, $|C_1\sm D_1|\ge 2$ and $|D_1\sm C_1|\ge 2$.
    See \cref{fig:PotterMenger} for the next definition.
    We define $(C_2,D_2):=(C_1 \cup a_1, (D_1 \cup A) \sm \{v_1\})$. 
    We have $S(C_2,D_2) = S(C_1,D_1) \cup \{a'_1 v_1,a_1\}$ since $v_1$ does not have a neighbour in~$A$ besides~$a_1'$. 
    By 4-connectivity of~$G$ and \cref{kConMixed}, $(C_2,D_2)$ has order exactly~4.
    Let $(C,D)$ be the left-right-shift of $(C_2,D_2)$.
    Since $C_1\sm D_1\se C_2\sm D_2$ we have $|C_2\sm D_2|\ge 2$, and similarly $|D_2\sm C_2|\ge 2$.
    Hence $(C,D)$ is a tetra-separation by \cref{leftrightTetra}.

    Consider the crossing-diagram for $(A,B)$ and $(C,D)$.
    We claim that the $C$-link includes~$\pi_1$.
    The $C$-link clearly contains~$v_1$.
    The vertex $a_1\in S(C_2,D_2)$ has two neighbours $v_1,b_1$ in $C_2\sm D_2$, so $a_1\in S(C,D)$.
    Hence $e_1\notin S(C,D)$.
    Since the end $b_1$ of $e_1$ lies in $C_1\sm D_1\se C\sm D$ by \cref{obs:reduction-maintains-proper-sides}, the edge $e_1$ lies in the $C$-link.
    Next, we claim that the $D$-link includes~$\pi_2$.
    Every vertex in $\pi_2$ clearly lies in the $D$-link.
    Now let $f$ be an edge in $\pi_2$.
    The endvertex of $f$ in $B\sm A$ lies in $\hat \pi_2\cap B\se D_1\sm C_1\se D\sm C$ by \cref{obs:reduction-maintains-proper-sides}.
    The endvertex of $f$ in $A\sm B$ must be distinct from $a_1$ by the matching-condition, and hence is contained in $D_2\sm C_2\se D\sm C$ by \cref{obs:reduction-maintains-proper-sides}.
    Therefore, both ends of $f$ lie in $D\sm C$ while $f\in S(A,B)$, so $f$ lies in the $D$-link.

    Since the $C$-link includes $\pi_1$ and the $D$-link includes $\pi_2$, the two tetra-separations $(A,B)$ and $(C,D)$ cross, and the inclusions are equalities by the \allref{keylem:crossing}.
    It remains to show that the $AC$-corner is the only corner that is potter.
    The edge~$v_1 a_1'$ dangles from the $C$-link through the $A$-link, so the corner~$AC$ is potter by the \allref{keylem:crossing}.
    By \cref{obs:potter-adjacent-corner}, the corners for~$AD$ and~$BC$ are not potter. 
    Assume for contradiction that the $BD$-corner is potter.
    Then~$\pi_2$ is $B$-weird and hence contains an edge~$f$.
    But then the endvertex of $f$ in $B\sm A$ is contained in $D\sm C$ as shown above.
    In particular, the corner for $BD$ is not empty, contradicting that $BD$ is potter.
\end{proof}

