\begin{definition}[2-potter-linked]
\label{dfn:2-potter-linked}
    Let~$\{\pi_1,\pi_2\}$ be a balanced bipartition of the separator of a tetra-separation~$(A,B)$ of a graph~$G$.
    We say that $\{\pi_1,\pi_2\}$ is \defn{2-potter-linked} with respect to $(A,B)$ if for both~$(X,Y)=(A,B)$ and~$(X,Y)=(B,A)$, at least one of the following holds:
    \begin{defenum}
        \item\label{itm:2-potter-linked-1} $\pi_1$ is not $X$-weird;
        \item\label{itm:2-potter-linked-2} $\pi_2$ is not $Y$-weird.
    \end{defenum}
    A~tetra-separation $(A,B)$ is \defn{2-potter-linked} if $\{\pi_1,\pi_2\}$ is 2-potter-linked for every balanced bipartition $\{\pi_1,\pi_2\}$ of $S(A,B)$.
\end{definition}

\begin{observation}
\label{obs:weird-no-edges-in-separator}
    Let~$(A,B)$ be a tetra-separation of a graph~$G$.
    Let $\{\pi_1,\pi_2\}$ be a balanced bipartition of $S(A,B)$.
    Assume that~$\pi_1$ is $A$-weird.
    Then there is no $\pi_1$--$\pi_2$ edge.
\end{observation}
\begin{proof}
    Assume that there is a $\pi_1$--$\pi_2$ edge~$uv$ with $u \in \pi_1$ and $v \in \pi_2$.
    Let~$u'$ be the endvertex in $A\sm B$ of the edge in~$\pi_1$.
    Then~$v$ is the only neighbour of~$u$ in~$A \sm \{u'\}$ by definition of $A$-weird.
    Hence,~$u \in S(A,B)$ has at most one neighbour in~$A \sm B$, contradicting the degree-condition.
\end{proof}

\begin{lemma}\label{lem:nestedness-2-potter-linked}
    Let $(A,B)$ be a tetra-separation of a 4-connected graph~$G$ and let $\{\pi_1,\pi_2\}$ be a balanced bipartition of $S(A,B)$. 
    Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{itm:nestedness-2-potter-linked-1} $\{\pi_1,\pi_2\}$ is 2-potter-linked with respect to $(A,B)$;
        \item\label{itm:nestedness-2-potter-linked-2} no tetra-separation of $G$ crosses $(A,B)$ so that $\pi_1$ and $\pi_2$ form opposite links and exactly two corners are potter.
    \end{enumerate}
\end{lemma}
\begin{proof}
    $\neg$~\ref{itm:nestedness-2-potter-linked-2} $\Rightarrow$ $\neg$~\ref{itm:nestedness-2-potter-linked-1}. 
    Assume that a tetra-separation $(C,D)$ crosses $(A,B)$ so that $\pi_1$ and $\pi_2$ form opposite links, say $\pi_1$ is the $C$-link and~$\pi_2$ is the $D$-link, and so that exactly two corners are potter.
    By \cref{obs:potter-adjacent-corner}, no two adjacent corners are potter. 
    So we can assume without loss of generality that the $AC$-corner and the $BD$-corner are potter while the other two corners are not potter.
    Then~$\pi_1$ is $A$-weird and~$\pi_2$ is $B$-weird by \cref{obs:potter-implies-weird}. So,~\ref{itm:2-potter-linked-1} and~\ref{itm:2-potter-linked-2} fail for $(X,Y)=(A,B)$.

    $\neg$~\ref{itm:nestedness-2-potter-linked-1} $\Rightarrow$ $\neg$~\ref{itm:nestedness-2-potter-linked-2}.
    Assume that $\{\pi_1,\pi_2\}$ is not 2-potter-linked with respect to $(A,B)$.
    Say~\ref{itm:2-potter-linked-1} and~\ref{itm:2-potter-linked-2} fail for~$(X,Y)=(A,B)$; that is to say, $\pi_1$ is $A$-weird and~$\pi_2$ is $B$-weird.
    For $i \in \{1,2\}$, write $\pi_i=:\{v_i,e_i\}$ where~$v_i$ is a vertex and $e_i=a_i b_i$ is an edge with $a_i\in A\sm B$ and $b_i\in B\sm A$; see \cref{fig:PotterWiggle}.
    Let~$a'_1$ be the unique neighbour of~$v_1$ in~$A \sm \{a_1\}$, and let~$b_2'$ be the unique neighbour of~$v_2$ in~$B \sm \{b_1\}$.
    By the degree-condition, we have $a'_1\in A\sm B$ and $b'_1\in B\sm A$.

    Let $C:=B \sm \{v_2\}) \cup \{a_1\}$ and $D:=(A\sm \{v_1\})\cup \{b_2\}$.
    Since $\pi_1$ is $A$-weird, $\pi_2$ is $B$-weird, and $v_1 v_2\notin E(G)$ by \cref{obs:weird-no-edges-in-separator}, we have
    $S(C,D)=\{a'_1 v_1,a_1,b_2,v_2 b'_2\}$.
    Note that~$(C,D)$ crosses~$(A,B)$ since~$v_1$ is in the $C$-link and~$v_2$ is in the $D$-link.
    The vertex $a_1$ has two neighbours in $C \sm D$, namely~$v_1$ and~$b_1$.
    Since~$a_1$ has degree at least four and it is not adjacent to~$b_2$, the only other vertex in $S(C,D)$, it follows that~$a_1$ also has at least two neighbours in~$D \sm C$.
    Similarly,~$b_2$ also has two neighbours in both~$C \sm D$ and~$D \sm C$. 
    Hence $(C,D)$ satisfies the degree-condition.
    It satisfies the matching-condition since $v_1\neq v_2$ means that $a'_1 v_1$ and $v_2 b'_2$ do not share endvertices. 
    Hence,~$(C,D)$ is a tetra-separation that crosses $(A,B)$ with $\pi_1$ and $\pi_2$ as opposite links.
    The corners $AC$ and $BD$ are potter by construction.
    By \cref{obs:potter-adjacent-corner}, no other corner is potter.
\end{proof}

