\begin{corollary}
\label{cor:nestedness-potter-linked}
    Let $(A,B)$ be a tetra-separation of a 4-connected graph~$G$ and let $\{\pi_1,\pi_2\}$ be a balanced bipartition of $S(A,B)$. 
    Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{itm:nestedness-potter-linked-1} $\{\pi_1,\pi_2\}$ is $h$-potter-linked with respect to $(A,B)$ for every $h \in \{0,1,2\}$;
        \item\label{itm:nestedness-potter-linked-2} no tetra-separation of $G$ crosses $(A,B)$ so that $\pi_1$ and $\pi_2$ form opposite links.
    \end{enumerate}
\end{corollary}
\begin{proof}
    By \cref{obs:potter-adjacent-corner}, every crossing pair of tetra-separations has at most two corners that are potter.
    So the corollary immediately follows from \cref{lem:nestedness-0-potter-linked}, \cref{lem:nestedness-1-potter-linked} and \cref{lem:nestedness-2-potter-linked}.
\end{proof}



\noindent\textbf{Summary.}

\begin{definition}
\label{dfn:externally-connected}
    A tetra-separation $(A,B)$ is \defn{externally 5-connected} if it is half-connected, 3-linked and $h$-potter-linked for every $h \in \{0,1,2\}$.
\end{definition}


\begin{keylemma}
\label{keylem:nestedness-external-connectivity}
    For every tetra-separation $(A,B)$ of a 4-connected graph~$G$, the following assertions are equivalent:
    \begin{enumerate}
        \item $(A,B)$ is totally-nested;
        \item $(A,B)$ is externally 5-connected.
    \end{enumerate}
\end{keylemma}

\begin{proof}
    We combine \cref{lem:nestedness-half-connected}, \cref{lem:nestedness-3-linked} and \cref{cor:nestedness-potter-linked} with the \allref{keylem:crossing}.
\end{proof}





\section{Thickened \texorpdfstring{$K_{4,m}$}{K4m}'s}
\label{sec:K4m}

This section deals with the thickened $K_{4,m}$ outcome of \cref{MainDecomp}; see \cref{keylem:K4m}.

A \defn{sprinkled $K_{4,m}$} is a graph obtained from a $K_{4,m}$ with a side $X$ of size four by possibly adding edges between vertices in~$X$.
We refer to $X$ as a \defn{sprinkled side}.


Let $Z\se V(G)$ and $K$ a component of $G-Z$.
When $Z$ and $K$ are clear from context, we write $(U'_K,W'_K):=(V(K)\cup Z,V(G-K))$.
Let $Z$ be a set of four vertices in a 4-connected graph $G$ such that $G-Z$ has $\ge 4$ components.
For each component $K$ of $G-Z$, let $(U_K,W_K)$ denote the left-right-shift of $(U'_K,W'_K)$.

\begin{lemma}\label{K4mMonotoneShift}
    Let $Z$ be a set of four vertices in a 4-connected graph~$G$, such that $G-Z$ has $\ge 4$ components.
    Let $K$ be a component of $G-Z$.
    Then $(U_K,W_K)$ equals the left-shift of $(U'_K,W'_K)$.
    In particular, $(U_K,W_K)\le (U'_K,W'_K)$ and $W_K=W'_K$.
\end{lemma}
\begin{proof}
    Let $(A,B)$ denote the left-shift of $(U'_K,W'_K)$.
    Since every vertex in $S(U'_K,W'_K)$ has $\ge 2$ neighbours in $W'_K\sm U'_K$, and since $W'_K\sm U'_K\se B\sm A$ by \cref{obs:shift-maintains-proper-sides}, it follows that every vertex in $S(A,B)$ has $\ge 2$ neighbours in $B\sm A$.
    Hence $(A,B)=(U_K,W_K)$ and $W'_K=B=W_K$.
\end{proof}

\begin{lemma}\label{K4mTotallyNestedChar}
    Let $Z$ be a set of four vertices in a 4-connected graph $G$ such that $G-Z$ has $\ge 4$ components.
    Let $K$ be a component of $G-Z$.
    Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{K4mTotallyNestedChar1} $K$ has $\ge 2$ vertices;
        \item\label{K4mTotallyNestedChar2} the left-right-shift of $(U'_K,W'_K)$ is a totally-nested tetra-separation.
    \end{enumerate}
\end{lemma}

\begin{proof}
    $\neg$~\cref{K4mTotallyNestedChar1} $\Rightarrow$ $\neg$~\cref{K4mTotallyNestedChar2}.
    If $K$ has only one vertex, then $|U_K\sm W_K|=1$, so $(U'_K,W'_K)$ fails to be a tetra-separation by \cref{leftrightTetra}.

    \cref{K4mTotallyNestedChar1} $\Rightarrow$ \cref{K4mTotallyNestedChar2}.
    We abbreviate $(U,W):=(U_K,W_K)$ and $(U',W'):=(U'_K,W'_K)$.
    Since $K$ has $\ge 2$ vertices, $(U,W)$ is a tetra-separation by \cref{leftrightTetra}.
    To show that $(U,W)$ is totally-nested, by \cref{keylem:nestedness-external-connectivity} it suffices to show that $(U,W)$ is externally 5-connected.

    \casen{Half-connected:} 
    We have $G[U\sm W]=K$ by \cref{K4mMonotoneShift}.


    To check the remaining aspects of external 5-connectivity,
    for each $z\in Z$ we denote by $z^*$ the element of $S(U,W)$ that equal or incident to~$z$.
    By \cref{K4mMonotoneShift}, $z^*$ is either equal to $z$ or $z^*$ is an edge between $K$ and~$z$.
    Denote by $z^U$ the vertex in $\hat z\cap U$.
    We can use the three components of $G-Z$ besides~$K$ to find paths:
    \begin{enumerate}[label={($\dagger$)}]
        \item\label{lem:K4m-three-paths} There are three independent $z_1$--$z_2$ paths in $G$ with all internal vertices outside~$K$, for every two distinct vertices $z_1,z_2\in Z$.
    \end{enumerate}

    \casen{3-linked:} follows from \cref{lem:K4m-three-paths}.

    \casen{0-potter-linked:}
    Let $\{\pi_1,\pi_2\}$ be a balanced bipartition of~$S(U,W)$. 
    We find three independent $\hat\pi_1$--$\hat\pi_2$ paths through $W\sm U$ by~\cref{lem:K4m-three-paths}.
    We claim that there are two independent $\hat\pi_1$--$\hat\pi_2$ paths through~$K$.
    Let $\{\pi'_1,\pi'_2\}$ denote the bipartition of~$Z$ that corresponds to $\{\pi_1,\pi_2\}$.
    For both~$i$, let $\pi_i^K$ denote the set of neighbours of $\pi'_i$ in~$K$.
    Then $|\pi_i^K|\ge 2$, since otherwise $\pi_i^K\cup \pi'_{3-i}$ is a 3-separator of~$G$ as $|K|\ge 2$, contradicting 4-connectivity.
    So it suffices to find two disjoint $\pi_1^K$--$\pi_2^K$ paths in~$K$.
    If these are missing, then by Menger's theorem $\pi_1^K$ and $\pi_2^K$ are separated by a single vertex~$v$, and then $\pi'_1\cup\{v\}$ is a 3-separator of~$G$, contradicting 4-connectivity.

    \casen{1-potter-linked:} Let $\{\pi_1,\pi_2\}$ be a balanced bipartition of~$S(U,W)$. 
    Assume that~$\pi_1$ is weird, say.
    Then~$\pi_1$ is $U$-weird since each vertex in~$Z$ has $\ge 3$ neighbours in~$W \sm U$. 
    By \cref{lem:K4m-three-paths}, there exist three independent $\hat \pi_1$--$\hat \pi_2$ paths in~$G[W]$.
    Hence $\{\pi_1,\pi_2\}$ is 1-potter-linked with respect to~$(U,W)$.

    \casen{2-potter-linked:} Let $\{\pi_1,\pi_2\}$ be a balanced bipartition of~$S(U,W)$.
    No~$\pi_i$ is $W$-weird, since each vertex in~$Z$ has $\ge 3$ neighbours in~$W \sm U$. So,~\ref{itm:2-potter-linked-1} or \ref{itm:2-potter-linked-2} always holds.
\end{proof}


We write $\defnMath{\sigma(Z)}$ for the star $\{\,(U_K,W_K):K$ is a component of $G-Z$ with $|K|\ge 2\,\}$.

\begin{corollary}\label{ZgivesStarInN}
    Let $Z$ be a set of four vertices in a 4-connected graph $G$ such that $G-Z$ has $\ge 4$ components.
    Then $\sigma(Z)$ is a star of totally-nested tetra-separations.
\end{corollary}
\begin{proof}
    By \cref{K4mTotallyNestedChar}, every element in~$\sigma(Z)$ is a totally-nested  tetra-separation. 
    Let~$K \neq L$ be components of $G-Z$, each of size~$\geq 2$.
    By \cref{K4mMonotoneShift}, $(U_K,W_K) \leq (U_K',W_K')$ and $(U_L,W_L) \leq (U_L',W_L')$. With $(U_K',W_K') \leq (W_L',U_L')$, it follows that $(U_K,W_K) \leq (W_L,U_L)$.
    So,~$\sigma(Z)$ is a star.
\end{proof}


\begin{lemma}\label{squeezingTetra}
    Let $(A,B)$ be a 4-separation in a 4-connected graph~$G$ such that $|A\sm B|\ge 2$ and every vertex in $S(A,B)$ has $\ge 2$ neighbours in $B\sm A$.
    Let $(A'',B'')$ be the left-right-shift of $(A,B)$.
    Then no tetra-separation $(C,D)$ of $G$ satisfies $(A'',B'')<(C,D)\le (A,B)$.
\end{lemma}

\begin{proof}
    Suppose for a contradiction that there is a tetra-separation $(C,D)$ with $(A'',B'')<(C,D)\le (A,B)$.
    By \cref{leftrightTetra}, $(A'',B'')$ is a tetra-separation.
    By \cref{K4mMonotoneShift}, we have $B=B''$.
    So both inclusions $B''\supseteq D\supseteq B$ are actually equalities.
    We therefore have $A''\subsetneq C\se A$.
    Let $v\in C\sm A''$.
    Then $v$ is a vertex in $S(A,B)$ with at most one neighbour in $A\sm B$.
    But since $D=B$ we have $C\sm D\se A\sm B$, so $v$ also has at most one neighbour in $C\sm D$, contradicting that $(C,D)$ is a tetra-separation.
\end{proof}

\begin{lemma}
\label{lem:not-half-conntected-is-tetra}
    Let~$G$ be a 4-connected graph.
    Let~$(A,B)$ be a mixed-4-separation in~$G$ that is not half-connected.
    Then~$(A,B)$ is a tetra-separation.
\end{lemma}
\begin{proof}
    By assumption, both $G[A\sm B]$ and $G[B\sm A]$ have two components.
    In particular, $|A \sm B|\ge 2$ and $|B \sm A| \geq 2$.
    Then by \cref{leftMatching},~$(A,B)$ satisfies the matching-condition.
    Let~$v$ be a vertex in~$S(A,B)$.
    By 4-connectivity of~$G$ and by \cref{kConMixed}, $v$~has a neighbour in every component of $G-S(A,B)$.
    In particular, $v$~satisfies the degree-condition.
    Hence,~$(A,B)$ is a tetra-separation.
\end{proof}

\begin{lemma}\label{K4mInterlacingVsComponent}
    Let~$Z$ be a set of four vertices in a 4-connected graph~$G$ such that $G-Z$ has~$\ge 4$ components.
    Let~$(E,F)$ be a totally-nested tetra-separation of~$G$.
    Then there exists a component~$K$ of $G-Z$ with $|K| \geq 2$ such that
    $(E,F)\le (U'_K,W'_K)$ or $(F,E)\le (U'_K,W'_K)$.
\end{lemma}
\begin{proof}
    We denote by $\cK$ the set of components of $G-Z$.
    First, we show that there is a component~$K \in \cK$ such that either $E \sm Z \subseteq V(K)$ or $F \sm Z \subseteq V(K)$.
    Assume otherwise.
    Then we can bipartition~$\cK$ into two sets~$\cK_1$ and~$\cK_2$ such that for both $i \in \{1,2\}$, $|\cK_i| \geq 2$ and $\bigcup_{K \in \cK_i} K$ intersects both~$E$ and~$F$.
    We define $A_i := Z \cup \bigcup_{K \in \cK_i} V(K)$.
    Then~$(A_1,A_2)$ is a tetra-separation by \cref{lem:not-half-conntected-is-tetra}.
    Now $E \nsubseteq A_i$ and $F \nsubseteq A_i$ for both $i \in \{1,2\}$ implies that $(A_1,A_2)$ crosses~$(E,F)$, contradicting that~$(E,F)$ is totally-nested.

    Hence we have~$E \subseteq V(K) \cup Z$, say, for a component~$K \in \cK$.
    Since every vertex in $Z$ has $\ge 2$ neighbours outside $V(K)\cup Z$, it follows that $(U'_K,W'_K)$ equals its right-shift.
    Hence $(E,F)\le (U'_K,W'_K)$ by \cref{Righty}.
    Since $(E,F)$ is a tetra-separation, we have $|E\sm F|\ge 2$ by \cref{leftDegreeStrongerMatching}.
    Therefore, $|K|\ge 2$.
\end{proof}

\begin{keylemma}\label{SprinkledK4mSummary}
    Let $G$ be a 4-connected graph, and let $N$ denote the set of totally-nested tetra-separations of~$G$.
    Assume that two tetra-separations $(A,B)$ and $(C,D)$ of $G$ cross so that the vertex-centre $Z$ has size four.
    Let $m$ denote the number of trivial components of $G-Z$.
    Then:
    \begin{enumerate}
        \item\label{SprinkledK4mSummary1} $\sigma(Z)$ is a splitting star of $N$.
        \item\label{SprinkledK4mSummary2} $\sigma(Z)$ is interlaced by both $(A,B)$ and $(C,D)$.
        \item\label{SprinkledK4mSummary4} If $\sigma(Z)\neq\emptyset$, then $G-Z$ has a component with $\ge 2$ vertices, and the torso of $\sigma(Z)$ is a thickened $K_{4,m}$ where $Z$ is the left side.
        \item\label{SprinkledK4mSummary5} If $\sigma(Z)=\emptyset$, then every component of $G-Z$ is trivial, and $G=\tau$ is a sprinkled $K_{4,m}$ with $Z$ as left side and $m\ge 4$.
    \end{enumerate}
\end{keylemma}
\begin{proof}
    \cref{SprinkledK4mSummary1}.
    By \cref{ZgivesStarInN}, $\sigma(Z)$ is a star in~$N$.
    To show that $\sigma(Z)$ is splitting, assume for a contradiction that it is interlaced by a totally-nested tetra-separation $(E,F)$.
    By \cref{K4mInterlacingVsComponent}, there is a component $K$ of $G-Z$ with $|K| \geq 2$ and $(E,F)\le (U'_K,W'_K)$, say.
    Since $K$ has at least two vertices, we have $(U_K,W_K)\in\sigma(Z)$.
    Note that $(U_K,W_K)\le (U'_K,W'_K)$ by \cref{K4mMonotoneShift}, which implies $(U_K,W_K)\not < (F,E)$.
    By \cref{squeezingTetra}, we cannot have $(U_K,W_K)<(E,F)$.
    Since $(U_K,W_K)\in N$, we therefore have $(E,F)\le (U_K,W_K)$ or $(F,E)\le (U_K,W_K)$, contradicting that $(E,F)$ interlaces~$\sigma(Z)$.

    \cref{SprinkledK4mSummary2}. We denote by $\sigma'(Z)$ the star $\{\,(U'_K,W'_K):K$ is a component of $G-Z$ with $|K|\geq 2\,\}$. Both $(A,B)$ and $(C,D)$ interlace $\sigma'(Z)$, hence they also interlace $\sigma(Z)$ by \cref{K4mMonotoneShift}.

    \cref{SprinkledK4mSummary4} and \cref{SprinkledK4mSummary5} are straightforward.
\end{proof}


A graph $G$ is \defn{4-angry} if it is 4-connected and every tetra-separation of $G$ is crossed by a tetra-separation.

\begin{keylemma}
\label{keylem:K4m}
    Let $G$ be a 4-angry graph. Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{itm:keylem-K4m-1} two tetra-separations of~$G$ cross with all links empty;
        \item\label{itm:keylem-K4m-2} $G$ is a sprinkled $K_{4,m}$ with $m \geq 4$.
    \end{enumerate}
\end{keylemma}

\begin{proof}
    \ref{itm:keylem-K4m-2} $\Rightarrow$ \ref{itm:keylem-K4m-1}.
    Let $X$ be a sprinkled side of~$G$.
    Let $\{P_1,\ldots,P_4\}$ be a partition of the other side $V(G-X)$.
    Let $(A,B)$ be the mixed-4-separation $(P_1\cup P_2\cup X,X\cup P_3\cup P_4)$ and let $(C,D)$ be the mixed-4-separation $(P_1\cup P_3\cup X,X\cup P_2\cup P_4)$.
    Then $(A,B)$ and $(C,D)$ are tetra-separations with separators equal to~$X$, and they cross.

    \ref{itm:keylem-K4m-1} $\Rightarrow$ \ref{itm:keylem-K4m-2} follows from \cref{SprinkledK4mSummary} \cref{SprinkledK4mSummary4} and \cref{SprinkledK4mSummary5}.
\end{proof}




\section{Generalised double-wheels}\label{sec:DoubleWheel}

To deal with the generalised double-wheel outcome of \cref{MainDecomp}, we first introduce a particular cycle-decomposition in \cref{sec:WheelBlockBagel} for analysing the wheel-structure obtained from two tetra-separations that cross with vertex-centre of size two.
\cref{sec:WheelNpathsLemmata} introduces machinery that exploits the structure of this cycle-decomposition to find independent paths.
\cref{sec:WheelTotallyNested} employs this machinery to show that all non-trivial bags of the cycle-decomposition give rise to totally-nested tetra-separations (\cref{cor:double-wheel-totally-nested}).
\cref{sec:WheelSplitting} shows that these totally-nested tetra-separations form a splitting star as in \cref{MainDecomp} and deduces that its torso is a generalised double-wheel (\cref{wheelTorso}).
Finally, \cref{sec:WheelAngry} characterises the special case where additionally all tetra-separations of the graph are crossed (\cref{keylem:double-wheel-angry}).

\subsection{Block-bagel}\label{sec:WheelBlockBagel}

Let $G$ be a 2-connected graph.
A \defn{Block-bagel} of $G$ is a cycle-decomposition $\cO = (O,\cG)$ of~$G$ with $\cG=(G_t:t \in V(O))$ such that
\begin{enumerate}
    \item every bag $G_t$ of $\cO$ is either 2-connected or a $K_2$, and
    \item all adhesion sets have size one.
\end{enumerate}
The vertex in the adhesion-set of an edge $e$ of $O$ is the \defn{adhesion-vertex} of~$e$.
When $\cO$ as introduced as $(O,\cG)$, we tacitly assume that $\cG=(G_t:t\in V(O))$.

\begin{observation}
\label{obs:block-bagel-disjoint-adhesion}
    Let~$G$ be a 2-connected graph with a block-bagel $\cO=(O,\cG)$.
    Then every two edges of $O$ have distinct adhesion-vertices.
\end{observation}
\begin{proof}
    Otherwise, two edges~$rs$ and~$st$ have the same adhesion-vertex~$v$. But then $v$ is a cutvertex of~$G$ that separates $V(G_s - v)$ from $V(G-G_s)$.
\end{proof}

Assume now that $G$ is a 4-connected graph with two tetra-separations $(A,B)$ and $(C,D)$ that cross with all links of size one.
Then the centre $Z'$ consists of two vertices by the \allref{keylem:crossing}.
We will construct a block-bagel of $G-Z'$.
The \defn{$AC$-shrimp} is obtained from $G[A\cap C]-Z'$ by adding any edges in the $A$-link or the $C$-link (including the endvertices of these edges).
Note that the $AC$-shrimp is connected because $G-Z'$ is 2-connected.
The \defn{$AC$-block-decomposition} means the block-decomposition of the $AC$-shrimp.
Note that the $AC$-block-decomposition is a path-decomposition because $G$ is 4-connected.
Its decomposition-path is called the \defn{$AC$-block-path}.
We obtain similarly definitions for the other three corners.

\begin{lemma}\label{wheelLinksVsCorners}
    Let $G$ be a 4-connected graph with two tetra-separations $(A,B)$ and $(C,D)$ that cross with all links of size one.
    Let $K$ be one of the four corners, and consider an adjacent $L$-link~$\Lambda$.
    \begin{enumerate}
        \item\label{wheelLinksVsCorners1} If $\Lambda$ consists of a vertex, then this vertex is contained in a unique bag $V_t$ of the $K$-block-decomposition, and $G[V_t]$ is 2-connected.
        \item\label{wheelLinksVsCorners2} If $\Lambda$ consists of an edge $e=uv$, then there is a unique bag $V_t$ of the $K$-block-decomposition with $V_t=\{u,v\}$ and $G[V_t]=K_2$. Moreover, $u$ and $v$ lie in the two corners adjacent to the $L$-link.
    \end{enumerate}
\end{lemma}
\begin{proof}
    \cref{wheelLinksVsCorners1}. The bag $V_t$ is unique since $G$ is 4-connected. It follows from the degree-condition that $G[V_t]$ must be 2-connected.

    \cref{wheelLinksVsCorners2}. The first part is immediate. For the `moreover'-part we use that $e$ is not dangling by the \allref{keylem:crossing}.
\end{proof}

\begin{corollary}\label{wheelCornersNonempty}
    Let $G$ be a 4-connected graph with two tetra-separations $(A,B)$ and $(C,D)$ that cross with all links of size one.
    Then all four corners are non-empty.\qed
\end{corollary}

The bag $V_t$ and node $t$ in \cref{wheelLinksVsCorners} are said to \defn{represent} the $L$-link in the $K$-block-decomposition and in the $K$-block-path.

For each corner $K$ let $\cT^K=(T^K,\cV^K)$ denote the $K$-block-decomposition.
We obtain $O$ from the disjoint union $\bigsqcup_K T^K$, where $K$ ranges over the four corners, by doing the following for each link $L$:
for both corners $K$ and $K'$ adjacent to $L$ we consider the nodes $t$ and $t'$ that represent the $L$-link in $T^K$ and $T^{K'}$, respectively, and
\begin{itemize}
    \item we join the nodes $t$ and $t'$ by an edge $\defnMath{o(L)}$ in $O$ if their bags $G[V_t]$ and $G[V_{t'}]$ are 2-connected;
    \item we otherwise identify the nodes $t$ and $t'$ to a single node $\defnMath{o(L)}$ of~$O$.
\end{itemize}
We say that $o(L)$ \defn{represents} the $L$-link in~$O$.
For each node $t$ of $O$ that is not of the form $o(L)$, we define $G_t:=G[V^K_t]$ where $K$ is the unique corner with $t\in T^K$.
For each node $t$ of $O$ with $t=o(L)$ for some link~$L$,
we let $G_t$ be the $K_2$-subgraph of $G$ from \cref{wheelLinksVsCorners}~\cref{wheelLinksVsCorners2} that represents the $L$-link in the $K$-block-decompositions for the two corners $K$ adjacent to~$L$.
The pair $(O,(G_t)_{t\in V(O)})$ is the \defn{block-bagel induced by $(A,B)$ and $(C,D)$.}
It really is a block-bagel of $G-Z'$.

The following setting is supported by \cref{fig:BlockBagelBag}.

\begin{setting}[Block-bagel setting]
\label{set:block-bagel}
    Let $(A,B)$ and~$(C,D)$ be two tetra-separations of a 4-connected graph~$G$ that cross with all links of size one.
    Let~$Z'$ be the centre, which consists of two vertices $z'_1,z'_2$.
    Let~$\cO = (O, (G_t)_{t \in V(O)})$ be the Block-bagel induced by~$(A,B)$ and~$(C,D)$.
    Write~$O = t(0),t(1),\ldots ,t(m),t(0)$ where indices are treated as elements of $\Z_{m+1}$.
    For every node $t \in V(O)$, we let~$U_t' := V(G_t)\cup Z'$ and $W_t' := Z' \cup \bigcup_{s \in V(O -t)} V(G_s)$, and we let $(U_t,W_t)$ be the right-left-shift of~$(U_t',W_t')$.
\end{setting}

Note that $(U_t',W_t')$ is a mixed-4-separation\pl{}.

