\subsection{N-Paths lemmata}\label{sec:WheelNpathsLemmata}

\begin{definition}[Helpful]
    Let~$\cO=(O,\cG)$ be a block-bagel of a graph~$G$.
    An element $x \in V(O) \cup E(O)$ is \defn{helpful} if
    \begin{itemize}
        \item $x$ is an edge with $K_2$-bags at both ends, or
        \item $x$ is a node with a 2-connected bag.
    \end{itemize}
    We define $\defnMath{h(\cO)}$ to be the number of helpful elements of the decomposition-cycle~$O$.

    For every helpful $x$ there is a unique corner $K$ such that $x$ stems from the $K$-block-path.
    We then say that $x$ \defn{belongs} to the corner~$K$.
\end{definition}



\begin{lemma}[Helpful Lemma]
\label{lem:helpful-lemma}
    Assume the \allref{set:block-bagel}.
    Then for every corner there is a helpful element that belongs to that corner. 
    In particular,~$h(\cO) \geq 4$. 
\end{lemma}
\begin{proof}
    Let $K$ be an arbitrary corner.
    If the $K$-block-decomposition has a 2-connected bag, then we are done. 
    Otherwise, the $K$-shrimp is a path.
    The corner $K$ contains a vertex $v$ by \cref{wheelCornersNonempty}.
    Then~$v$ is the adhesion-vertex of a helpful edge that belongs to the corner~$K$.
\end{proof}



\begin{lemma}
\label{lem:path-from-helpful-edge}
    Assume the~\allref{set:block-bagel}.
    The adhesion-vertex of a helpful edge of $O$ sends edges to both vertices $z'_1,z'_2$ in the centre.
\end{lemma}
\begin{proof}
    Otherwise the adhesion-vertex has degree $\le 3$, contradicting 4-connectivity.
\end{proof}

The following two lemmata are supported by \cref{fig:path-from-helpful-vertex}.

\begin{lemma}
    \label{lem:path-from-helpful-vertex}
    Assume the~\allref{set:block-bagel}.
    Assume that $t$ is a helpful node of~$O$.
    Then each vertex $z'_i$ in the centre has a neighbour $w_i$ in the interior of the bag~$G_t$.
    Moreover, if $|G_t|\ge 4$, then we can find the $w_i$ so that $w_1\neq w_2$.
\end{lemma}
\begin{proof}   
    Since $t$ is helpful, its bag $G_t$ is 2-connected.
    Hence $G_t$ has non-empty interior.
    Each $z'_i$ in the centre has a neighbour $w_i$ in this interior, since otherwise $z'_{3-i}$ together with the two adhesion-vertices of $G_t$ forms a 3-separator of $G$, contradicting 4-connectivity.

    Assume now that $G_{t_1}$ contains at least four vertices.
    If $w_1=w_2$ is the only possibility, then $w_1$ together with the two adhesion-vertices of $G_t$ forms a 3-separator, contradicting 4-connectivity.
\end{proof}

