\begin{lemma}[Bag-Path Lemma]
\label{lem:bag-path}
    Assume the~\allref{set:block-bagel}.
    Let $t$ be a helpful node of~$O$.
    Then there is a $z'_1$--$z'_2$ path in $G-z'_1 z'_2$ with interior in $\mathring{G}_t$.
\end{lemma}
\begin{proof}
    Otherwise the two adhesion-vertices of $G_t$ together with one of the $z'_i$ forms a 3-separator of~$G$, contradicting 4-connectivity.
\end{proof}



\begin{lemma}[One-Path Lemma]
\label{lem:double-wheel-one-path}
    Assume the~\allref{set:block-bagel}.
    Let~$P \subseteq O$ be a path of length~$\ge 2$ with end-nodes~$r$ and~$s$.
    Let $u \in V(G_r)$ and $v \in V(G_s)$.
    Then there is a $u$--$v$ path in $\bigcup_{t \in V(P)} G_{t}$ that internally avoids the adhesion-vertices of the edges not in~$P$.
\end{lemma}
\begin{proof}
    Let~$u_i$ denote the adhesion-vertex of $t(i)\, t(i+1)$.
    We assume without loss of generality that $P=t(1)\, t(2) \ldots t(k)$. 
    For each~$i \in \{1,2,\ldots,k\}$, we construct a path~$P_i$ in~$G_{t(i)}$, as follows.
    For $i=1$ we claim that $P_i$ can be chosen to be a $u$--$u_1$ path with interior in~$G_{t(1)} - u_0$. 
    This is clearly possible if the bag $G_{t(1)}$ is a~$K_2$.
    Otherwise~$G_{t(1)}$ is 2-connected.
    Then we find two independent $u$--$u_1$ paths in~$G_{t(1)}$, and at least one of them internally avoids~$u_0$.
    Similarly, if~$i=k$ then we let~$P_i$ be a $u_{k-1}$--$v$ path with interior in~$G_{t(k)}-u_k$.
    Otherwise, if $2 \leq i \leq k$, then we let~$P_i$ be a $u_{i-1}$--$u_i$ path in~$G_{t(i)}$.
    Then the concatenation $P:=P_1 P_2 \ldots P_k$ is a desired $u$--$v$ path.
\end{proof}

\begin{lemma}[Two-Fan Lemma]
\label{lem:double-wheel-two-fan}
    Assume the~\allref{set:block-bagel}.
    Let~$u$ and~$v$ be the two adhesion-vertices in a bag~$G_t$.
    Assume that either~$t$ is helpful or~$u$ is the adhesion-vertex of a helpful edge.
    Then there exist two independent paths~$P_1, P_2$ with all internal vertices in $\mathring{G}_{t}$ such that~$P_1$ is a $u$--$z_1'$ path and~$P_2$ is a $u$--$v$ path.
\end{lemma}
\begin{proof}
    If~$u$ is the adhesion-vertex of a helpful edge, then~$u z_1' \in E(G)$ by \cref{lem:path-from-helpful-edge}, and~$u v \in E(G)$ since~$G_t$ is a~$K_2$. Then we let~$P_1 := u z_1'$ and~$P_2 := u v$.
    Otherwise,~$t$ is helpful. 
    By \cref{lem:path-from-helpful-vertex}, $z'_1$ has a neighbour~$w$ in $\mathring{G}_{t}$.
    Since~$G_{t}$ is 2-connected, it contains two independent paths~$Q_1,Q_2$ such that~$Q_1$ is a $u$--$w$ path and~$Q_2$ is a $u$--$v$ path. 
    Then we obtain $P_1$ from $Q_1$ by appending~$z'_1$, and we let $P_2 := Q_2$.
\end{proof}

The following lemma is supported by \cref{fig:block-bagel-2-paths}.

\begin{lemma}[Two-Paths Lemma]
\label{lem:double-wheel-two-paths}
    Assume the~\allref{set:block-bagel}.
    Let~$P$ be an $r$--$s$ path in~$O$. 
    Assume that either the first edge $e$ or the second node of~$P$ is helpful.
    Assume that~$P$ contains at least two helpful elements distinct from~$r$.
    Let~$u$ be the adhesion-vertex of the edge~$e$.
    Then there exist two independent $u$--$z_1'$ paths in $G$ with all interior vertices in~$\bigcup_{t \in V(\mathring P)} G_t\cup \mathring G_s$.
\end{lemma}
\begin{proof}
    Without loss of generality,~$P=t(0)\, t(1) \ldots t(k)$ with $r=t(0)$ and $s=t(k)$.
    By assumption, either the edge $e=t(0)\,t(1)$ or the second node~$t(1)$ is helpful.
    Let~$u_i$ denote the adhesion-vertex of $t(i)\, t(i+1)$. In particular, $u=u_0$.
    By the \allref{lem:double-wheel-two-fan}, there are two independent paths~$P_1,Q_1$ with interior in~$\mathring{G}_{t(1)}$ such that~$P_1$ is a $u_0$--$z_1'$ path and~$Q_1$ is a $u_0$--$u_1$ path.

    If~$t(1) t(2)$ or~$t(2)$ is helpful, then~$k=2$. 
    In this case, we find a $u_1$--$z_1'$ path~$Q_2$ with interior in~$\mathring{G}_{t(2)}$ by the \allref{lem:double-wheel-two-fan}. 
    Then the two paths $P_1$ and~$u_0 Q_1 u_1 Q_2 z_1'$ are as desired.
    Otherwise,~$t(1)$ is helpful,~$t(2)$ has a $K_2$-bag and at least one of~$t(2) t(3)$ or~$t(3)$ is helpful. 
    So~$k=3$ in this case. 
    Then~$u_1 u_2 \in E(G)$ since~$t(2)$ has a $K_2$-bag. 
    We find a $u_2$--$z_1'$ path~$Q_2$ with interior in~$\mathring{G}_{t(3)}$ by the \allref{lem:double-wheel-two-fan}. 
    Then the paths~$P_1$ and~$u_0 Q_1 u_1 u_2 Q_2 z_1'$ are as desired.
\end{proof}

