\subsection{Totally-nested tetra-separations from good bags}\label{sec:WheelTotallyNested}

\begin{definition}[Good bag, bad bag]
    Assume the \allref{set:block-bagel}.
    A bag $G_t$ of $\cO$ is \defn{good} if $G_t$ is 2-connected and either
    \begin{itemize}
        \item $|G_t|\ge 4$, or
        \item $G_t$ is a triangle and a neighbouring bag is a~$K_2$.
    \end{itemize}
    Otherwise, $G_t$ is \defn{bad}.
    We also call $t$ \defn{good} or \defn{bad}, respectively.
\end{definition}

Note that $G_t$ is bad if and only if either $G_t$ is a $K_2$ or $G_t$ is a triangle and both neighbouring bags are 2-connected.



The following setting is supported by \cref{fig:bag-setting}.

\begin{setting}[Block-bagel bag setting]
\label{set:bag-setting}
    Assume the \allref{set:block-bagel}.
    Let~$U' := U_{t(0)}'$ and~$W' := W_{t(0)}'$.
    Let $x'$ be the adhesion-vertex of~$t(-1)\,t(0)$ and let $y'$ be the adhesion-vertex of~$t(0)\, t(1)$.
    Observe that $S(U',W')=\{x',y',z_1',z_2'\}$.
    Let $(U,W)$ be the right-left-shift of~$(U',W')$.
    Let $x,y,z_1,z_2\in S(U,W)$ correspond to $x',y',z'_1,z'_2$, respectively.\footnote{So $x$ is incident or equal to $x'$, and so on.}
    Let $x^W$ denote the unique vertex in $\hat x\cap W$, and define $y^W$ and $z_i^W$ similarly.
\end{setting}


\begin{figure}[ht]
    \centering
    \includegraphics[height=12\baselineskip]{Figures/WheelBag.pdf}
    \caption{The \allref{set:block-bagel}. $S(U',W')$ is blue, $S(U,W)$ is red. We have $y^W=y'$ and $z^W_i=z'_i$, so these three vertices are blue. The vertex $x^W$ is green.}
    \label{fig:bag-setting}
\end{figure}

\begin{observation}
\label{obs:double-wheel-out-reduction}
    Assume the~\allref{set:bag-setting}. 
    If $G_{t(1)}$ is a~$K_2$, then~$y$ is the edge in~$G_{t(1)}$.
    Symmetrically, if~$G_{t(-1)}$ is a~$K_2$, then~$x$ is the edge in~$G_{t(-1)}$.\qed
\end{observation}

\begin{lemma}
\label{cor:double-wheel-reduced-edges}
    Assume the~\allref{set:bag-setting}. 
    Then each vertex $z'_i$ in the centre has $\ge 3$ neighbours outside $Z'$ contained in $W'\sm U'$ , and in particular in $W\sm U$.
    In particular, $z_i^W = z_i'$.
\end{lemma}
\begin{proof}
    We combine the \allref{lem:helpful-lemma} with \cref{lem:path-from-helpful-edge} and \cref{lem:path-from-helpful-vertex}, and we use \cref{obs:reduction-maintains-proper-sides} for $W' \sm U' \subseteq W \sm U$.
\end{proof}

\begin{lemma}
\label{lem:double-wheel-UW-is-tetra}
    Assume the~\allref{set:bag-setting}.
    Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{lem:double-wheel-UW-is-tetra1} $G_{t(0)}$ is good, or all three bags $G_{t(-1)},G_{t(0)},G_{t(1)}$ are $K_2$'s;
        \item\label{lem:double-wheel-UW-is-tetra2} $(U,W)$ is a tetra-separation.
    \end{enumerate}
\end{lemma}
\begin{proof}
    \cref{lem:double-wheel-UW-is-tetra1} $\Rightarrow$ \cref{lem:double-wheel-UW-is-tetra2}.
    Suppose first that $G_{t(0)}$ is good.
    By \cref{wheelCornersNonempty}, each of the four corners contains a vertex.
    Since $G_{t(0)}$ is 2-connected, it is included in $A\cap C$, say, so every corner except $AC$ has its vertex contained in $W'\sm U'$.
    Hence $|W'\sm U'|\ge 3$.
    The 4-separation $(U',W')$ trivially satisfies the matching-condition.
    If the bag~$G_{t(0)}$ is not a triangle, then it has $\ge 4$ vertices, so $|U'\sm W'|\ge 2$.
    In this case, $(U,W)$ is a tetra-separation by \cref{leftrightTetra}.
    Otherwise, $G_{t(0)}$ is a triangle.
    Then some neighbouring bag, say $G_{t(1)}$, is a $K_2$.
    Hence $|U' \sm W'| = 1$ and the vertex~$y'$ has exactly one neighbour in~$W' \sm U'$. 
    Again by \cref{leftrightTetra}, $(U,W)$ is a tetra-separation.

    Suppose now that all three bags $G_{t(-1)},G_{t(0)},G_{t(1)}$ are $K_2$'s.
    Then $G_{t(0)}$ meets at most two corners, so the vertices in the other two corners lie in $W'\sm U'$, giving $|U'\sm W'|\ge 2$.
    Both $x'$ and $y'$ have exactly one neighbour in $W'\sm U'$ since both $G_{t(-1)}$ and $G_{t(1)}$ are $K_2$'s.
    Hence $(U,W)$ is a tetra-separation by \cref{leftrightTetra}.

    $\neg$ \cref{lem:double-wheel-UW-is-tetra1} $\Rightarrow$ $\neg$ \cref{lem:double-wheel-UW-is-tetra2}.
    As \cref{lem:double-wheel-UW-is-tetra1} fails, $G_{t(0)}$ either is a $K_2$ neighboured by at least one 2-connected bag, or $G_{t(0)}$ is a triangle neighboured by 2-connected bags.
    Suppose first that $G_{t(0)}$ is a $K_2$ neighboured by a 2-connected bag, say $G_{t(1)}$.
    Then $y'$ has two neighbours in $G_{t(1)}$, which are also contained in $W'\sm U'$.
    The two vertices $z'_i$ in the centre have $\ge 3$ neighbours in $W'\sm U'$ by \cref{cor:double-wheel-reduced-edges}.
    So only $x'$ might have $\le 1$ neighbours in $W'\sm U'$.
    But $|U'\sm W'|=0$, so $(U,W)$ is no tetra-separation by \cref{leftrightTetra}.

    Suppose now that $G_{t(0)}$ is a triangle with both neighbouring bags 2-connected.
    Then, as above, all vertices in $S(U',W')$ have $\ge 2$ neighbours in $W'\sm U'$.
    But $|U'\sm W'|=1$, so $(U,W)$ is no tetra-separation by \cref{leftrightTetra}.
\end{proof}



\begin{observation}
    \label{obs:double-wheel-helpful-is-next}
    Assume the~\allref{set:bag-setting}. 
    Let~$t(i)\, t(i+1)$ be the edge of~$O$ that has $y^W$ as adhesion-vertex.
    Then either the edge $t(i)\, t(i+1)$ or the node $t(i+1)$ is helpful.\qed
\end{observation}



\begin{lemma}
    \label{lem:three-y1-y2-paths}
    Assume the~\allref{set:bag-setting}. 
    Then there exist three independent $z_1'$--$z_2'$ paths in~$G[W]-\{x',y'\}-z'_1 z'_2$.
\end{lemma}
\begin{proof}
    For each helpful $h\in V(O)\cup E(O)$ we construct a $z'_1$--$z'_2$ path~$P_h$, as follows.
    If $h$ is an edge, then its adhesion-vertex send edges to both $z'_i$ by \cref{lem:path-from-helpful-edge}, and we let $P_h$ be the path defined by these two edges; see \cref{fig:three-y1-y2-paths}.
    If $h$ is a helpful node, then we use the \allref{lem:bag-path} to let $P_h$ by a $z'_1$--$z'_2$ path avoiding the edge $z'_1 z'_2$ (if it exists) and with interior in $\mathring{G}_h$.

    All paths $P_h$ are independent.
    By the \allref{lem:helpful-lemma}, there are at least four of them.
    At most one of them meets the bag $G_{t(0)}$.
    By \cref{cor:double-wheel-reduced-edges}, both vertices $z'_i$ in the centre are contained in~$W$.
    Hence at least three of the paths $P_h$ are independent $z'_1$--$z'_2$ paths in $G[W]-\{x',y'\}-z'_1 z'_2$.
\end{proof}

