The following lemma is supported by \cref{fig:double-wheel-three-paths}.
\begin{lemma}
\label{lem:double-wheel-applied-three-paths}
    Assume the~\allref{set:bag-setting} with $G_{t(0)}$ 2-connected. 
    Then there are three independent $\{x^W,y^W\}$--$z_1'$ paths $P_1,P_2,P_3$ in~$G[W]$, such that:
    \begin{enumerate}
        \item both $P_1$ and $P_2$ are $y^W$--$z_1'$ paths, and
        \item $P_3$ is an $x^W$--$z_1'$ path.
    \end{enumerate}
\end{lemma}

\begin{proof}
    Since $t(0)$ is helpful, \allref{lem:helpful-lemma} implies that
    \begin{equation}\label{lem:double-wheel-applied-three-paths-eq}
        \text{$\ge 3$ elements of $O-t(0)$ are helpful.}
    \end{equation}

    Let $f=t(j)\,t(j+1)$ be the edge on $O$ that has $y^W$ as adhesion-vertex.
    Then $f$ or $t(j+1)$ is helpful by \cref{obs:double-wheel-helpful-is-next}.
    If $t(j)$ is helpful, then $j=0$, and $j=1$ otherwise.
    Let $P$ be the path in $O$ that starts with $t(j),t(j+1)$ and has two helpful elements distinct from $t(j)$ and is minimal with these properties.
    The path $P$ is well-defined since $O-t(0)$ has $\ge 3$ helpful elements by \cref{lem:double-wheel-applied-three-paths-eq}.
    Moreover, the end $s$ of~$P$ is distinct from~$t(0)$.
    By the \allref{lem:double-wheel-two-paths}, we find two independent $y^W$--$z_1'$ paths~$Q_1, Q_2$ with all interior vertices in $\bigcup_{t \in V(\mathring P)} G_{t} \cup \mathring G_{s}$.
    By construction, the paths $Q_1$ and $Q_2$ are contained in~$G[W]$.

    Now let $e=t(i)\,t(i-1)$ be the edge on $O$ that has $x^W$ as adhesion-vertex.
    Then $e$ or $t(i-1)$ is helpful by \cref{obs:double-wheel-helpful-is-next}.
    And if $t(i)$ is helpful, then $i=0$.
    By the \allref{lem:double-wheel-one-path}, we find an $x^W$--$z_1'$ path~$Q_3$ with interior in~$\mathring{G}_{t(i-1)}$.
    Once more, $Q_3\se G[W]$ by construction.

    It remains to show that the three paths $Q_i$ are independent.
    We already know that $Q_1$ and $Q_2$ are independent, so it remains to show that $Q_3$ is independent from $Q_1$ and~$Q_2$.
    If the edge $e$ is helpful, then it is the first helpful element on $O$ following $t(0)$ in the direction of~$e$.
    In particular, $e$ does not lie on~$P$ by~\cref{lem:double-wheel-applied-three-paths-eq}.
    Since the bag $G_{t(i-1)}$ is a~$K_2$, it has empty interior.
    So $Q_3=x^W z'_1$ avoids $\mathring G_s$, even if $s=t(i-1)$, so $Q_3$ is independent from $Q_1$ and $Q_2$.
    Otherwise $t(i-1)$ is helpful.
    Then $t(i-1)$ is the first helpful element on $O$ following $t(0)$ in the direction of~$e$.
    In particular, both edges on $O$ incident to $t(i-1)$ are unhelpful.
    So $t(i-1)$ does not lie on $P$ by \cref{lem:double-wheel-applied-three-paths-eq}.
    Hence $Q_3$ is independent from $Q_1$ and~$Q_2$.
\end{proof}



