\begin{lemma}
\label{lem:double-wheel-path-shortening}
    Let~$G$ be a graph, let~$u \in U \subseteq V(G)$ and $v \in V \subseteq V(G)$.
    Every $u$--$v$ path in~$G$ contains a $U$--$V$ path.\qed
\end{lemma}

In the following, we characterise when $(U,W)$ is a totally-nested tetra-separation.\medskip

\begin{center}
    \textbf{Half-connected}
\end{center}

\begin{lemma}
    \label{lem:double-wheel-half-connected}
    Assume the~\allref{set:bag-setting}. Then $(U,W)$ is half-connected.
\end{lemma}
\begin{proof}
    We show that~$G[W \sm U]$ is connected.
    Without loss of generality, assume that the interior of~$G_{t(0)}$ is contained in the corner~$AC$. 
    Let~$v$ be a vertex in the corner~$BD$, which exists by \cref{wheelCornersNonempty}.
    Let $t(i)$ be a node of $O$ with $v\in G_{t(i)}$.


    We claim that every vertex $w$ in $W$ is connected to~$v$ in~$G[W \sm U]$.
    Since~$G_{t(i)} \subseteq G[W \sm U]$, every vertex in~$G_{t(i)}$ is connected to~$v$ in~$G[W \sm U]$.
    If $w$ does not lie in the centre~$Z'$, then we are done by the \allref{lem:double-wheel-one-path}.
    Otherwise $w=z'_1$, say.
    Then $w$ has a neighbour in $W\sm Z'$ by \cref{lem:three-y1-y2-paths}, which we already know is linked to $v$ in $G[W\sm U]$.     
    Hence $(U,W)$ is half-connected.
\end{proof}

\begin{center}
    \textbf{3-linked}
\end{center}

\begin{lemma}
\label{lem:double-wheel-3-linked}
    Assume the~\allref{set:bag-setting} with $G_{t(0)}$ 2-connected. 
    Then $(U,W)$ is 3-linked.
\end{lemma}
\begin{proof}
    Let $\pi$ consist of two elements of $S(U,W)$.
    We show that $\pi$ is 3-linked around $S(U,W)$.

    \casen{Case $\pi=\{x,y\}$.}
    We may assume that both $z_1,z_2$ are vertices, by \ref{itm:3-linked-1}.
    Since the bag $G_{t(0)}$ is 2-connected, it contains two independent $x'$--$y'$ paths.
    By \cref{lem:double-wheel-path-shortening}, these paths contain two independent $\hat x$--$\hat y$ paths which are also included in the bag~$G_{t(0)}$.
    We find a third $\hat x$--$\hat y$ path $G$ that avoids both the bag $G_{t(0)}$ and the centre, by the \allref{lem:double-wheel-one-path}.
    So we are done by \ref{itm:3-linked-3}.

    \casen{Case $\pi=\{z_1,z_2\}$.}
    We find three independent $z'_1$--$z'_2$ paths in $G-x-y$ by \cref{lem:three-y1-y2-paths}.
    These contain three independent $\hat z_1$--$\hat z_2$ paths by \cref{lem:double-wheel-path-shortening}.
    So we are done by \ref{itm:3-linked-3}.

    \casen{Case $\pi=\{x,z_1\}$.}
    We find an $x'$--$z'_1$ path with interior in $\mathring{G}_{t(0)}$, by the \allref{lem:double-wheel-two-fan}.
    This path contains a $\hat x$--$\hat z_1$ path~$P_1$, by \cref{lem:double-wheel-path-shortening}.
    Next, we find two independent $x^W$--$z'_1$ paths $P_2$ and $P_3$ in $G$ that internally avoid $G_{t(0)}$, by \cref{lem:double-wheel-applied-three-paths}.
    Both paths $P_2$ and $P_3$ are $\hat x$--$\hat z_1$ paths by \cref{cor:double-wheel-reduced-edges}.
    Hence the $P_i$ witness \ref{itm:3-linked-3}.

    All remaining cases are symmetric to the case $\pi=\{x,z_1\}$.
\end{proof}

\begin{center}
    \textbf{0-potter-linked}
\end{center}

\begin{lemma}
\label{lem:double-wheel-0-potter-linked}
    Assume the~\allref{set:bag-setting} with $G_{t(0)}$ good.
    Then $(U,W)$ is 0-potter-linked.
\end{lemma}
\begin{proof}
    Let $\{\pi_1,\pi_2\}$ be a balanced bipartition of $S(U,W)$.

    \casen{Case $\pi_1 = \{x,y\}$ and $\pi_2=\{z_1,z_2\}$}.
    Suppose first that~$G_{t(0)}$ is a triangle with a neighbouring bag that is a~$K_2$; say $G_{t(1)}$ is a $K_2$.
    Let $v$ denote the vertex of the triangle $G_{t(0)}$ besides $x'$ and~$y'$.
    Since $G$ is 4-connected, $v$ sends edges to both vertices $z'_i$ in the centre.
    Similarly, the adhesion-vertex $y'$ in between the triangle-bag $G_{t(0)}$ and the $K_2$-bag $G_{t(1)}$ sends at least one edge to some vertex in the centre, say to~$z'_1$.

    We claim that $z'_1=z_1$.
    On the one hand, $z'_1$ has $\ge 3$ neighbours in $W'\sm U'$ by \cref{cor:double-wheel-reduced-edges}, so $z'_1$ remains in the separator when taking the right-shift $(U'',W'')$ of $(U',W')$.
    However, $y'$ becomes the edge $y$ of the $K_2$-bag $G_{t(1)}$ in the separator $S(U'',W'')$ by \cref{obs:double-wheel-out-reduction}.
    Hence $z'_1$ has two neighbours $y'$ and $v$ in $U''\sm W''$.
    Thus $z'_1$ also remains in the separator when taking the left-shift $(U,W)$ of $(U'',W'')$.
    In particular, $z'_1=z_1$.

    So $z_1$ is a vertex.
    Recall that $z_1$ sends an edge to $y'\in\hat\pi_1$.
    Hence we have~\ref{itm:0-potter-linked-1}.

    Suppose otherwise that $G_{t(0)}$ is 2-connected and has at least four vertices.
    We will find five independent $\hat \pi_1$--$\hat \pi_2$ paths in~$G$ for \ref{itm:0-potter-linked-2}.
    There exist two disjoint $\{z'_1,z'_2\}$--$\mathring G_{t(0)}$ paths $P_1,P_2$ by \cref{lem:path-from-helpful-vertex}.
    Since $G_{t(0)}$ is 2-connected, we can extend the paths $P_1,P_2$ to two disjoint $\{z'_1,z'_2\}$--$\{x',y'\}$ paths with interior in $\mathring G_{t(0)}$.
    We find three independent $\{x_1^W,x_2^W\}$--$\{z_1',z_2'\}$ paths in $G[W]$ by \cref{lem:double-wheel-applied-three-paths}.
    The five paths are independent, and they contain five $\hat\pi_1$--$\hat\pi_2$ paths by \cref{lem:double-wheel-path-shortening}.

    \casen{Case $\pi_1=\{x,z_1\}$ and $\pi_2=\{y,z_2\}$}.
    Here it suffices to find five independent $\hat\pi_1$--$\hat\pi_2$ paths in $G$ for \ref{itm:0-potter-linked-2}.
    There are two independent $x'$--$y'$ paths in $G_{t(0)}$ by 2-connectivity.
    We find three independent $z'_1$--$z'_2$ paths in $G[W]-\{x',y'\}$ by \cref{lem:three-y1-y2-paths}.
    The latter three paths are internally disjoint from the former two.
    By \cref{lem:double-wheel-path-shortening}, the five paths contain five independent $\hat\pi_1$--$\hat\pi_2$ paths.

    All remaining cases are symmetric to one of the two cases above.
\end{proof}

\begin{center}
    \textbf{1-potter-linked and 2-potter-linked}
\end{center}

\begin{lemma}
\label{lem:double-wheel-weird}
    Assume the~\allref{set:bag-setting}. 
    Then no pair of two elements of $S(U,W)$ is $W$-weird.
\end{lemma}
\begin{proof}
    Let $\pi$ consist of two elements of $S(U,W)$.
    Assume for a contradiction that $\pi$ is $W$-weird.

    \casen{Assume $\pi=\{x,z_1\}$.}
    The vertex $z'_1$ in the centre has $\ge 3$ neighbours in $W'\sm U'$ by \cref{cor:double-wheel-reduced-edges}.
    Hence $z^W_1=z'_1$.
    Since the $\ge 3$ neighbours also lie in $W\sm U$ by \cref{obs:reduction-maintains-proper-sides}, we further get that $z_1$ must be the edge in~$\pi$.
    Since $z_1$ is an edge, $x$ is a vertex which has exactly one neighbour in $G[W]-z_1^W$.
    Hence $G_{t(-1)}$ is a~$K_2$.
    But then $x$ is the edge of $G_{t(-1)}$ by \cref{obs:double-wheel-out-reduction}, a contradiction.

    \casen{Assume $\pi=\{x,y\}$.}
    Say $x$ is a vertex and $y$ is an edge.
    Then $x=x'$, so $G_{t(-1)}$ is 2-connected by \cref{obs:double-wheel-out-reduction}.
    Hence $x$ has two neighbours $u,v$ in $G_{t(-1)}$.
    By the \allref{lem:helpful-lemma}, neither $u$ nor $v$ is an endvertex of the edge~$y$.
    Hence $\{x,y\}$ is not $W$-weird, a contradiction.

    All other cases are covered by symmetry.
\end{proof}


\begin{lemma}
    \label{lem:double-wheel-potter-linked}
    Assume the~\allref{set:bag-setting} with $G_{t(0)}$ 2-connected. Then $(U,W)$ is 1-potter-linked and 2-potter-linked.
\end{lemma}
\begin{proof}
    Let $\{\pi_1,\pi_2\}$ be a balanced bipartition of $S(U,W)$. 
    Neither~$\pi_i$ is $W$-weird by \cref{lem:double-wheel-weird}.
    In particular, $\{\pi_1,\pi_2\}$ is 2-potter-linked.

    To show that $\{\pi_1,\pi_2\}$ is 1-potter-linked, it suffices to find three independent $\hat \pi_1$--$\hat \pi_2$ paths in~$G[W]$.
    If one of the $\pi_i$ is of the form $\{x,y\}$, then we find three such paths by \cref{lem:double-wheel-applied-three-paths} and \cref{lem:double-wheel-path-shortening}.
    Otherwise $z_1\in\pi_1$ and $z_2\in\pi_2$, say.
    Then we find three desired paths by \cref{lem:three-y1-y2-paths} and \cref{lem:double-wheel-path-shortening}.
\end{proof}



\begin{center}
    \textbf{Summary}
\end{center}

\begin{keylemma}
    \label{cor:double-wheel-totally-nested}
    Assume the~\allref{set:block-bagel}.
    Let $t$ be a node of~$O$.
    If the bag $G_t$ is good, then $(U_t,W_t)$ is a totally-nested tetra-separation.
\end{keylemma}
\begin{proof}
    We may assume the \allref{set:bag-setting} with~$t=t(0)$.
    Then $(U_t,W_t)$ is a tetra-separation by \cref{lem:double-wheel-UW-is-tetra}.
    It suffices to show that $(U_t,W_t)$ is externally 5-connected, by \cref{keylem:nestedness-external-connectivity}.
    This follows from \cref{lem:double-wheel-half-connected} (half-connected), \cref{lem:double-wheel-3-linked} (3-linked), \cref{lem:double-wheel-0-potter-linked} (0-potter-linked) and \cref{lem:double-wheel-potter-linked} (1-potter-linked and 2-potter-linked).
\end{proof}



\subsection{Splitting stars and torsos}\label{sec:WheelSplitting}

\begin{definition}[Tetra-star $\sigma(\cO)$]
    Assume the \allref{set:block-bagel}.
    The \defn{tetra-star} of~$\cO$ is the set of all $(U_t,W_t)$ for good bags~$G_t$ of~$\cO$.
    We denote the tetra-star of~$\cO$ by $\defnMath{\sigma(\cO)}$.
\end{definition}

\begin{lemma}
\label{lem:double-wheel-star}
    Assume the \allref{set:block-bagel}.
    Then $\sigma(\cO)$ is a star of totally-nested tetra-separations.
\end{lemma}
\begin{proof}
    By \cref{cor:double-wheel-totally-nested},~$\sigma(\cO)$ is a set of totally-nested tetra-separations.
    It remains to show that for all good nodes $s\neq t$, we have $(U_s,W_s) \leq (W_t,U_t)$.
    We have $U_s \subseteq V(G_s)$ and $U_t \subseteq V(G_t)$.
    Moreover, by \cref{obs:double-wheel-out-reduction}, for all nodes~$r \in V(O-s)$ that have a 2-connected bag, we have $V(G_r) \subseteq W_s$.
    Therefore, $U_t \subseteq V(G_t) \subseteq W_s$.
    Similarly, $U_s \subseteq V(G_s) \subseteq W_t$.
    It follows that~$(U_s,W_s) \leq (W_t,U_t)$.
\end{proof}



The following two lemmata are supported by \cref{fig:double-wheel-moving-links}.

\begin{lemma}[Link-Moving Lemma for $K_2$-bags]
\label{lem:double-wheel-moving-link-1}
    Assume the \allref{set:block-bagel}.
    Let~$P$ and~$Q$ be the two paths that are the components of~$O - o(C) - o(D)$.
    Assume $o(A) \in P$ and $o(B) \in Q$.
    Let~$c$ denote the end of~$P$ that is adjacent or incident to~$o(C)$ in~$O$.
    Define~$d$ similarly.
    %
    Let~$s$ be a node in the same component of $P-o(A)$ as~$c$ such that $G_s=K_2$.
    Let $P' := dP\mathring{s}$ and $Q':= \mathring{s} P c \cup Q$.
    \begin{enumerate}
        \item\label{itm:double-wheel-moving-link-1-1} $A' := \bigcup_{t \in V(P')} V(G_t)\cup Z'$ and $B':= \bigcup_{t \in V(Q')} V(G_t)\cup Z'$ are the two sides of a tetra-separation of~$G$.
        \item\label{itm:double-wheel-moving-link-1-2} $S(A',B') = Z' \cup (D\text{-link}) \cup \{e\}$, where~$e$ is the edge in~$G_s$.
        \item\label{itm:double-wheel-moving-link-1-3} $(A',B')$ separates some two vertices in $B \cup D$.
        \item\label{itm:double-wheel-moving-link-1-4} $(A',B')$ and~$(C,D)$ cross with all links of size one, and the block-bagel induced by~$(A',B')$ and~$(C,D)$ is equal to~$\cO$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    The pair $(A',B')$ is a mixed-separation by construction.
    Moreover,~\ref{itm:double-wheel-moving-link-1-2} also holds by construction. We show~\ref{itm:double-wheel-moving-link-1-1} next. Let~$d$ be the element in the $D$-link.

    \casen{Matching-condition:} We have to show that, if~$d$ in an edge, then it does not share an endvertex with~$e$.
    The endvertices of~$d$ lie in the corners for~$AD$ and~$BD$ since there do not exist dangling edges in the crossing-diagram of~$(A,B)$ and~$(C,D)$ by the \allref{keylem:crossing}. 
    Both endvertices of~$e$ lie in the corner for~$AC$ by \cref{wheelLinksVsCorners}~\ref{wheelLinksVsCorners1}.
    Hence $d$ and $e$ share no ends.

    \casen{Degree-condition:} 
    All vertices in~$S(A',B')$ are also contained in~$S(A,B)$.
    Since $B \sm A \subseteq B' \sm A'$, every vertex in~$S(A',B')$ has at least two neighbours in~$B' \sm A'$.

    If~$d$ is a vertex, then we claim that every neighbour~$u$ of~$d$ in~$A \sm B$ also also lies in~$A' \sm B'$.
    Indeed, since $ud$ is not a dangling edge,~$u$ is contained in the corner~$AD$ or the $A$-link with respect to~$(A,B),(C,D)$. 
    By \cref{wheelLinksVsCorners}~\ref{wheelLinksVsCorners1}, no endvertex of~$e$ lies in the $A$-link with respect to $(A,B),(C,D)$.
    So, we have $u \in A' \sm B'$.

    It remains to show that both vertices~$z_1'$ and~$z_2'$ in the centre have at least two neighbours in~$A' \sm B'$.
    Let~$s'$ be the neighbour of~$s$ on~$P'$.
    Observe that either~$s'$ or~$ss'$ is helpful and belongs to the corner~$AC$.
    Moreover, by the \allref{lem:helpful-lemma} there is a helpful element that belongs to the $AD$-corner.
    Hence, there are at least two helpful elements that belong to~$(ss') \cup T_{AD}$, where $T_{AD}$ is the $AD$-block-path.
    By \cref{lem:path-from-helpful-edge,lem:path-from-helpful-vertex}, we are done.

    \medskip

    We also have~\ref{itm:double-wheel-moving-link-1-3} since there is a vertex in $A \cap (D \sm C) \subseteq A' \sm B'$ that is separated from every vertex in $B \sm A \subseteq B' \sm A'$ by $(A',B')$.
    Next, we show~\ref{itm:double-wheel-moving-link-1-4}.
    Clearly,~$Z'$ is the centre of the crossing-diagram of~$(A',B')$ with~$(C,D)$. 
    So, $(A',B')$ and $(C,D)$ cross with all links of size one.
    It is straightforward to check that the block-bagel induced by~$(A',B')$ and~$(C,D)$ is equal to~$\cO$.
\end{proof}

Let $P$ be a path.
Let $u$ be a vertex on~$P$, and let $e$ be an edge on~$P$.
Then $uP\mathring e$ denotes the subpath of $P$ that starts in~$u$ and ends in the first end of~$e$ it encounters.
In particular, $e$ is not an edge of $uP\mathring e$.

\begin{lemma}[Link-Moving Lemma for adhesion-vertices]
\label{lem:double-wheel-moving-link-2}
    Assume the \allref{set:block-bagel}.
    Let~$P$ and~$Q$ be the two paths that are the components of~$O - o(C) - o(D)$.
    Assume $o(A) \in P$ and $o(B) \in Q$.
    Let~$c$ denote the end of~$P$ that is adjacent or incident to~$o(C)$ in~$O$.
    Define~$d$ similarly.
    %
    Let~$e$ be an edge of~$O$ with 2-connected bags at both ends.
    Assume that~$e$ stems from the $AC$-block-path.
    Let $P':=dP\mathring{e}$ and $Q':=\mathring e P c \cup Q$.
    Then:
    \begin{enumerate}
        \item\label{itm:double-wheel-moving-link-2-1} $A' := \bigcup_{t \in V(P')} V(G_t)\cup Z'$ and $B':= \bigcup_{t \in V(Q')} V(G_t)\cup Z'$ are the two sides of a tetra-separation of~$G$.
        \item\label{itm:double-wheel-moving-link-2-2} $S(A',B') = Z' \cup (D\text{-link}) \cup \{v\}$, where~$v$ is the adhesion-vertex of the edge~$e$.
        \item\label{itm:double-wheel-moving-link-2-3} $(A',B')$ separates some two vertices in $B \cup D$.
        \item\label{itm:double-wheel-moving-link-2-4} $(A',B')$ and~$(C,D)$ cross with all links of size one, and the block-bagel induced by~$(A',B')$ and~$(C,D)$ is equal to~$\cO$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    The proof is analogous to the proof of the \allref{lem:double-wheel-moving-link-1}, except that the matching-condition is trivially fulfilled, and that the vertex~$v$ satisfies the degree condition since it is contained in two 2-connected bags $G_s,G_{s'}$ with $V(G_s - v) \subseteq A' \sm B'$ and $V(G_{s'} - v) \subseteq B' \sm A'$.
\end{proof}


