\begin{lemma}\label{wheelBlockPathInteriorVertex}
    Assume the \allref{set:block-bagel}.
    Let~$T$ denote the $AC$-block-path.
    Let~$T':=T-o(A)-o(C)$.
    Then either~$T'$ is non-empty or $|A \cap C| \leq 3$.
\end{lemma}
\begin{proof}
    If the $A$-link or the $C$-link contains a vertex, then this vertex is contained in a 2-connected bag $G_t$ with $t\in V(T')$, by \cref{wheelLinksVsCorners}.
    Otherwise both the $A$-link and the $C$-link consist of edges.
    Then $G_{o(A)}$ and $G_{o(C)}$ are $K_2$-bags.
    Each of the two bags $G_{o(A)},G_{o(C)}$ has exactly one endvertex $v_A,v_C$ in the corner for~$AC$ by \cref{wheelLinksVsCorners}, respectively.
    If~$T'$ is empty, then $v_A=v_C$, and $A\cap C=\{v_A\}\cup Z'$ has size three.
\end{proof}

\begin{lemma}
\label{lem:double-wheel-E-in-bag}
    Assume the \allref{set:block-bagel}.
    Let $(E,F)$ be a tetra-separation of $G$ that interlaces the tetra-star $\sigma(\cO)$. 
    Then~$(E,F)$ is crossed by another tetra-separation of~$G$, or there is a 2-connected bag~$G_t$ of~$\cO$ such that~$E \subseteq U'_t$ or~$F \subseteq U'_t$.
\end{lemma}
\begin{proof}
    Assume that~$(E,F)$ is totally-nested. Then~$(E,F) \leq (A,B)$ and~$(E,F) \leq (C,D)$, say. 
    We choose two tetra-separations~$(A',B')$ and~$(C',D')$ with $|A' \cap C'|$ minimum such that
    \begin{enumerate}
        \item\label{itm:double-wheel-min-1} $(A',B')$ and~$(C',D')$ cross with all links of size one; and
        \item\label{itm:double-wheel-min-2} the block-bagel induced by~$(A',B')$ and~$(C',D')$ is equal to~$\cO$; and
        \item\label{itm:double-wheel-min-3} $(E,F) \leq (A',B')$ and $(E,F) \leq (C',D')$.
    \end{enumerate}
    Note that the existence of~$(A',B')$ and~$(C',D')$ follows from~$(A,B)$ and~$(C,D)$ exhibiting properties~\ref{itm:double-wheel-min-1}--\ref{itm:double-wheel-min-3}.
    Let $T$ denote the $A'C'$-block-path, and let~$T':=T-o(A')-o(C')$.
    By \cref{wheelBlockPathInteriorVertex}, $T'$ is non-empty.
    Let~$\cO' = \cO$ be the block-bagel induced by~$(A',B')$ and~$(C',D')$. 

    We claim that every bag $G_t$ with $t\in T'$ is 2-connected.
    Assume otherwise that $G_t=K_2$ for some $t\in T'$, and let $e$ denote the edge of~$G_t$.
    In the context of $(A',B')$ and $(C',D')$, we apply the \allref{lem:double-wheel-moving-link-1} to~$t$ and obtain a tetra-separation $(A'',B'')$ such that
    \begin{itemize}
        \item $S(A'',B'')=\{e\}\cup Z'\cup\text{($D'$-link)}$, and
        \item $(A'',B'')$ separates two vertices of~$B' \cup D'$. 
    \end{itemize}
    Since $B'\cup D'\se F$, the tetra-separation $(A'',B'')$ separates two vertices in~$F$.
    If $(A'',B'')$ also separates two vertices in~$E$, then it crosses~$(E,F)$, a contradiction.
    Hence we have either $(E,F) \leq (A'',B'')$ or $(E,F) \leq (B'',A'')$. 
    In the former case, we have that~$(A'',B'')$ and~$(C',D')$ satisfy all of~\ref{itm:double-wheel-min-1}-\ref{itm:double-wheel-min-3}, but have~$|A'' \cap C'| < |A' \cap C'|$, contradicting the minimality of $|A' \cap C'|$. 
    In the latter case, we apply the \allref{lem:double-wheel-moving-link-1} to~$t$ and obtain a tetra-separation $(C'',D'')$ such that
    \begin{itemize}
        \item $S(C'',D'')=\{e\}\cup Z'\cup\text{($B'$-link)}$, and
        \item $(C'',D'')$ separates two vertices of~$B' \cup D'$. 
    \end{itemize}
    Moreover, we have
    \[
        E\se B''\cap A'\cap C'\se C'' \quad\text{and}\quad F\supseteq A''\cup D'\cup B'\supseteq D''.
    \]
    Hence $(E,F)\le (C'',D'')$.
    Therefore, we have that~$(A',B')$ and~$(C'',D'')$ satisfy all of~\ref{itm:double-wheel-min-1}-\ref{itm:double-wheel-min-3}, but have~$|A' \cap C''| < |A' \cap C'|$, contradicting the minimality of $|A' \cap C'|$.

    We claim that $T'$ has no edge.
    Assume otherwise that $tt'$ is an edge of~$T'$.
    Then both bags $G_t,G_{t'}$ at its ends are 2-connected by the above claim.
    In the context of $(A',B')$ and $(C',D')$, we apply the \allref{lem:double-wheel-moving-link-2} to the edge~$tt'$ and obtain a tetra-separation $(A'',B'')$ with the properties stated in the lemma.
    Then we derive a contradiction in the same way as in the previous claim.

    By the above, every bag $G_t$ with $t\in T'$ is 2-connected, and $T'$ has no edge.
    Since $T'$ is non-empty, it has a unique node~$t$, and $G_t$ is 2-connected.
    Then~$A' \cap C' = V(G_t) \cup Z'$. 
    By \ref{itm:double-wheel-min-3}, $E\se U'_t$. 
\end{proof}

\begin{lemma}
\label{lem:double-wheel-interlaced-crossed}
    Assume the \allref{set:block-bagel}.
    Every tetra-separation of~$G$ that interlaces the tetra-star $\sigma(\cO)$ is crossed by another tetra-separation of~$G$.
\end{lemma}
\begin{proof}
    Assume for contradiction that~$\sigma(\cO)$ is interlaced by a totally-nested tetra-separation~$(E,F)$ of~$G$. 
    By \cref{lem:double-wheel-E-in-bag}, there is a 2-connected bag~$G_t$ of~$\cO$ with $E \subseteq U_t'$, say. 
    By \cref{Righty}, we have~$(E,F) \leq (U_t'',W_t'')$ where $(U''_t,W''_t)$ is the right-shift of $(U'_t,W'_t)$.

    Assume first that~$G_t$ is good.
    Then~$(U_t,W_t) \in \sigma(\cO)$ by definition of~$\sigma(\cO)$. 
    Since~$(E,F)$ interlaces~$\sigma(\cO)$, we have $(U_t,W_t) < (E,F)$ or $(U_t,W_t) < (F,E)$. 
    We cannot have~$(U_t,W_t) < (F,E)$ since otherwise $\emptyset \neq E \sm F \subseteq (W_t \sm U_t) \cap (U_t'' \sm W_t'')$ contradicts that $U''_t\sm W''_t \se U_t \sm W_t$ by \cref{obs:shift-maintains-proper-sides}.
    So~$(U_t,W_t) < (E,F) \leq (U_t'',W_t'')$. 
    Since $(U_t,W_t)$ is the left-shift of $(U''_t,W''_t)$, some vertex in $S(E,F)$ must have $\le 1$ neighbour in $E\sm F$, contradicting the degree-condition. 

    Otherwise,~$G_t$ is bad.
    Since $G_t$ is 2-connected, it is a triangle, and since $G_t$ is bad, both neighbouring bags in $\cO$ are 2-connected.
    Hence both adhesion-vertices of $G_t$ are contained in the separator of $(U''_t,W''_t)$.
    Therefore, the unique interior vertex of the triangle-bag $G_t$ is the only vertex of $U''_t\sm W''_t$.
    Since $(E,F) \leq (U_t'',W_t'')$, we have~$E \sm F \subseteq U_t'' \sm W_t''$. 
    Hence $|E \sm F| \leq 1$, which by \cref{lem:trivial-tetra-separations} contradicts that~$(E,F)$ is a tetra-separation.
\end{proof}

\begin{corollary}\label{wheelGoodChar}
    Assume the \allref{set:block-bagel}.
    Let $t$ be a node of~$O$.
    Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{wheelGoodChar1} the bag $G_t$ is good;
        \item\label{wheelGoodChar2} $(U_t,W_t)$ is a totally-nested tetra-separation of~$G$.
    \end{enumerate}
\end{corollary}
\begin{proof}
    \cref{wheelGoodChar1} $\Rightarrow$ \cref{wheelGoodChar2}: this is \cref{cor:double-wheel-totally-nested}.

    $\neg$ \cref{wheelGoodChar1} $\Rightarrow$ $\neg$ \cref{wheelGoodChar2}.
    Assume that $G_t$ is bad.
    Then $(U_t,W_t)$ fails to be a tetra-separation, unless $G_t$ and both neighbouring bags are $K_2$'s, by \cref{cor:double-wheel-totally-nested}.
    In this case, both vertices of $G_t$ lie in $U_t\sm W_t$, so $(U_t,W_t)$ is distinct from all tetra-separations in the tetra-star~$\sigma(\cO)$.
    Therefore, $(U_t,W_t)$ interlaces $\sigma(\cO)$, and so $(U_t,W_t)$ is crossed by another tetra-separation, by \cref{lem:double-wheel-interlaced-crossed}.
\end{proof}



\begin{lemma}\label{dotTorso4con}
    Let $G$ be a 4-connected graph.
    Let $\sigma$ be a star of mixed-4-separations of~$G$.
    Then the torso of $\sigma$ is 4-connected or a~$K_4$.
\end{lemma}
\begin{proof}
    We combine Lemmas 2.6.3 and 2.6.4 from~\cite{Tridecomp}.
\end{proof}



\begin{keylemma}\label{wheelTorso}
    Let $G$ be a 4-connected graph, and let $N$ denote the set of totally-nested tetra-separations of~$G$.
    Let $\sigma$ be a splitting star of~$N$ that is interlaced by two tetra-separations $(A,B)$ and $(C,D)$ of $G$ that cross with vertex-centre $Z$ of size two.
    Then the torso $\tau$ of $\sigma$ is a generalised double-wheel with centre~$Z$.
\end{keylemma}

\begin{proof}
    By the \allref{keylem:crossing}, the centre~$Z$ equals the vertex-centre and all links have size one.
    Let~$\cO$ be the Block-bagel induced by~$(A,B)$ and~$(C,D)$, which has centre~$Z$.
    By \cref{lem:double-wheel-star}, the tetra-star~$\sigma(\cO)$ is a star of totally-nested tetra-separations of~$G$.
    By \cref{lem:double-wheel-interlaced-crossed}, the tetra-star~$\sigma(\cO)$ is a splitting star of~$N$.
    Since both~$(A,B)$ and~$(C,D)$ interlace both~$\sigma$ and~$\sigma(\cO)$, we obtain $\sigma=\sigma(\cO)$.
    Hence it remains to compute the torso~$\tau$ of~$\sigma(\cO)$.
    The torso~$\tau$ is 4-connected by \cref{dotTorso4con}.
    We can obtain~$\tau$ from~$\cO$ by replacing each good bag~$G_t$ by a~$K_4$ on the vertex set $Z\cup\{u,v\}$ where $u$ and $v$ are the adhesion-vertices of~$G_t$, leaving only $K_2$-bags and triangle-bags, and contracting some edges in $K_2$-bags.
    Hence $\tau$ is a generalised wheel with centre~$Z$.
\end{proof}




\subsection{Angry block-bagels}\label{sec:WheelAngry}

Let $X$ be a graph.
We call $X$ a \defn{double-wheel} with \defn{centre $\{u,v\}$} if $X$ is 4-connected and $u,v$ are distinct vertices of $X$ such that $X-u-v$ is a cycle.
So $u$ and $v$ send edges to all vertices of $X-u-v$, and the edge $uv$ may or may not exist.
The \defn{rim-length} of $X$ then means the length of the cycle $X-u-v$.
We call $X$ a \defn{double-wheel of triangles} with \defn{centre $\{u,v\}$} if $X$ is 4-connected and $u,v$ are distinct vertices of $X$ such that $X-u-v$ has a cycle-decomposition $(O,\cG)$ with all adhesion-sets of size 1 and into triangles.
The \defn{rim-length} of $X$ means the length of the cycle~$O$.

\begin{lemma}
\label{lem:double-wheel-all-bad}
    Let~$G$ be a 4-connected graph with a block-bagel $\cO=(O,\cG)$ with centre~$Z$ such that all bags of $\cO$ are bad.
    Then either~$G$ is a double-wheel with centre~$Z$ or~$G$ is a double-wheel of triangles with centre~$Z$.
    In either case, the rim-length equals $h(\cO)$.
\end{lemma}
\begin{proof}
    Since all bags of $\cO$ are bad, all bags are either $K_2$'s or triangles.
    Moreover, if there is a bag that is a triangle, then its neighbouring bags are triangles, too.
    It follows that if some bag is a triangle, then all bags are triangles.
    In this case,~$G$ is a double-wheel of triangles with centre~$Z$.
    Then $h(\cO)$ equals the number of triangle-bags of~$\cO$, and hence equals the rim-length.
    Otherwise, every bag is a~$K_2$.
    In this case,~$G$ is a double-wheel with centre~$Z$. 
    Then $h(\cO)$ equals the number $K_2$-bags of~$\cO$, and hence equals the rim-length.
\end{proof}

\begin{lemma}
\label{lem:double-wheel-crossing-tetra}
    Let~$G$ be a double-wheel with rim-length~$\geq 4$ and centre~$Z$. 
    Then~$G$ has two tetra-separations that cross with all links of size one and centre equal to~$Z$.
\end{lemma}
\begin{proof}
    Let $O$ denote the cycle $G-Z$.
    Let $e_1,f_1,e_2,f_2$ be the first four edges on~$O$.
    Let $(A_i,B_i)$ be the tetra-separation of $G$ with separator $\{e_i,f_i\}\cup Z$.
    Then $(A_1,B_1)$ crosses $(A_2,B_2)$ with the four edges as links and with centre equal to~$Z$.
\end{proof}

\begin{lemma}
\label{lem:double-wheel-of-triangles-crossing-tetra}
    Let~$G$ be a double-wheel of triangles with rim-length~$\geq 4$ and centre~$Z$. Then~$G$ has two tetra-separations that cross with all links of size one and centre equal to~$Z$.
\end{lemma}
\begin{proof}
    Since~$G$ is a double-wheel of triangles with rim-length~$\geq 4$, the graph $G-Z$ has a cycle-decomposition $\cO=(O,(G_t)_{t \in O})$ with $|O| \geq 4$ such that all bags are triangles.
    Let $(A,B)$ and $(C,D)$ be crossing 2-separations of~$O$.
    Let $\hat A:=Z\cup\bigcup_{t\in A}V(G_t)$ and define $\hat B,\hat C,\hat D$ similarly.
    Then $(\hat A,\hat B)$ and $(\hat C,\hat D)$ are tetra-separations of $G$ that cross as desired.
\end{proof}

\begin{keylemma}
\label{keylem:double-wheel-angry}
    Let~$G$ be a 4-angry graph. Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{itm:double-wheel-angry-1} $G$ has two tetra-separations that cross with all links of size one;
        \item\label{itm:double-wheel-angry-2} $G$ has a block-bagel~$\cO$ with $h(\cO) \geq 4$ all whose bags are bad;
        \item\label{itm:double-wheel-angry-3} $G$ is a double-wheel with rim-length~$\geq 4$ or a double-wheel of triangles with rim-length~$\geq 4$.
    \end{enumerate}
\end{keylemma}
\begin{proof}
    \ref{itm:double-wheel-angry-1} $\Rightarrow$ \ref{itm:double-wheel-angry-2}. 
    Assume that~$G$ has two tetra-separations~$(A,B)$ and~$(C,D)$ that cross with all links of size one.
    Let~$Z$ be the centre of~$(A,B)$ and~$(C,D)$, which is equal to the vertex-centre and has size two, by the \allref{keylem:crossing}.
    Let~$\cO$ be the block-bagel induced by~$(A,B)$ and~$(C,D)$.
    Then we have the \allref{set:block-bagel}.
    By the \allref{lem:helpful-lemma}, we have~$h(\cO) \geq 4$.
    If $\cO$ has a good bag, then $G$ has a totally-nested tetra-separation by \cref{cor:double-wheel-totally-nested}, contradicting that~$G$ is 4-angry.
    Hence, every bag of~$\cO$ is bad.

    \ref{itm:double-wheel-angry-2} $\Rightarrow$ \ref{itm:double-wheel-angry-3}. Follows from \cref{lem:double-wheel-all-bad}.

    \ref{itm:double-wheel-angry-3} $\Rightarrow$ \ref{itm:double-wheel-angry-1}. Follows from \cref{lem:double-wheel-crossing-tetra} and \cref{lem:double-wheel-of-triangles-crossing-tetra}.
\end{proof}





\section{Cycles of 2-connected torsos}\label{sec:CycleOfGraphs}

One of the outcomes of \cref{MainDecomp} is a cycle of triangle-torsos and 3-connected torsos on $\le 5$ vertices.
To investigate how this outcome arises, we assume that we are given two tetra-separations $(A,B)$ and $(C,D)$ of a 4-connected graph $G$ that cross with empty vertex-centre.
In order to construct a cycle-decomposition for analysing the cyclic structure that is determined by $(A,B)$ and $(C,D)$, we first use the corner-diagram to divide $G$ into four smaller pieces (\cref{sec:BagelBananas}).
We then apply the Tutte-decomposition to all four pieces and merge them to obtain a cycle-decomposition of $G$ (\cref{sec:BagelTutteBanana}).
In \cref{sec:BagelSettings}, we summarise assumptions shared by a fair share of the lemmas to come.
\cref{sec:BagelNpaths} provides machinery that exploits the structure of the cycle-decomposition to find independent paths.
We use this machinery in \cref{sec:BagelTotallyNested} to characterise which bags of the cycle-decomposition give rise to totally-nested tetra-separations (\cref{cor:bagel-totally-nested}).
\cref{sec:BagelSplitting} shows that these totally-nested tetra-separations form a splitting star as in \cref{MainDecomp}, and determines the structure of its torso (\cref{bagelTorso}).
Finally, \cref{sec:BagelAngry} characterises the special case where additionally all tetra-separations of the graph are crossed.


\subsection{Bananas}\label{sec:BagelBananas}

Let $G$ be a 4-connected graph.
Assume that two tetra-separations $(A,B)$ and $(C,D)$ of $G$ cross with all links of size two.
Recall that the centre is empty by the \allref{keylem:crossing}.
We obtain the graph $\defnMath{G^*}$ from $G$ by adding edges, as follows.
For each $L$-link $\{x,y\}$ and each adjacent corner~$K=LS$ (where $L,S$ are sides), we join the unique vertices in $\hat x\cap S$ and $\hat y\cap S$ by an edge, which we call the \defn{$K$-edge for the $L$-link}; see \cref{fig:GStarDef}.
We will only use $G^*$ when $(A,B)$ and $(C,D)$ are clear from context.
The \defn{expanded corner for $AC$} is obtained from the corner $(A\sm B)\cap (C\sm D)$ for $AC$ by adding the endvertices of all edges contained in the two adjacent links.
The \defn{banana for $AC$}, or \defn{$AC$-banana}, is the subgraph of $G^*$ induced by the expanded corner for~$AC$.
The expanded corners and bananas are defined similarly for the other three corners.

