\begin{lemma}
\label{lem:size-expanded-corner}
    Let $G$ be a 4-connected graph.
    Let $(A,B)$ and $(C,D)$ be tetra-separations of $G$ that cross with all links of size two.
    Let $K$ be a corner.
    Then the expanded corner for~$K$ has size~$\ge 4$.
\end{lemma}
\begin{proof}
    Assume $K=AC$ without loss of generality.
    Let~$L$ be the union of the $A$-link and the $C$-link, and note that $|L| = 4$.
    For each element~$x$ in~$L$, we define~$v_x:=x$ if~$x$ is a vertex, and $v_x:=u$ if~$x$ is an edge and~$u$ is the endvertex of~$x$ in $(B \sm A) \cup (D \sm C)$.
    By the matching-condition for~$(A,B)$ and~$(C,D)$, $x \mapsto v_x$ is an injection that maps elements in~$L$ to vertices of the expanded corner for~$AC$.
    So, the expanded corner for~$AC$ has size~$\ge 4$.
\end{proof}

\begin{lemma}\label{bananaEndNumberChar}
    Let $G$ be a 4-connected graph.
    Let $(A,B)$ and $(C,D)$ be tetra-separations of $G$ that cross with all links of size two.
    Let $K$ be a corner.
    Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{bananaEndNumberChar1} the $K$-edges for the links adjacent to $K$ are distinct;
        \item\label{bananaEndNumberChar2} the corner $K$ is not potter.
    \end{enumerate}
\end{lemma}
\begin{proof}
    $\neg$ \cref{bananaEndNumberChar1} $\Rightarrow$ $\neg$ \cref{bananaEndNumberChar2}.
    Say $K$ is the corner for $AC$.
    Let $\beta$ denote the $AC$-banana.
    Let $e(A)$ denote the $AC$-edge for the $A$-link, and let $e(C)$ denote the $AC$-edge for the $C$-link.
    Assume that $e(A)=e(C)=:e$.
    We will show that $AC$ is potter.
    If both endvertices of $e$ lie in the corner for $AC$, then each link adjacent to $AC$ consists of a matching of size two with the endvertices of $e$ as one side of the matching; see \cref{fig:bananaEndNumberChar}.
    As $G$ is 4-connected, the corner for $AC$ cannot contain any other vertices besides the endvertices of~$e$.
    But then both endvertices of $e$ have degree $\le 3$ in~$G$, contradicting that $G$ is 4-connected.
    So we may assume that $e$ has an endvertex $v$ that lies in the $A$-link, say.
    Then the $C$-link contains an edge $f$ that ends in~$v$.
    Hence $f$ dangles from the $A$-link through the $C$-link, which implies that the corner for $AC$ is potter by the \allref{keylem:crossing}.

    $\neg$ \cref{bananaEndNumberChar2} $\Rightarrow$ $\neg$ \cref{bananaEndNumberChar1} holds by definition.
\end{proof}


