    \centering
    \includegraphics[height=8\baselineskip]{Figures/bananaEndNumberChar.pdf}
    \caption{The situation in the proof of \cref{bananaEndNumberChar}}
    \label{fig:bananaEndNumberChar}
\end{figure}



\begin{lemma}\label{banana2con}
    Let $G$ be a 4-connected graph.
    Let $(A,B)$ and $(C,D)$ be tetra-separations of $G$ that cross with all links of size two.
    The bananas of the four corners are 2-connected.
\end{lemma}
\begin{proof}
    Consider the corner for $AC$, say, and let $\beta$ denote its banana.
    If $AC$ is potter, then $\beta$ is a union of two triangles sharing an edge, and hence $\beta$ is 2-connected.
    So we may assume that $AC$ is not potter.
    Then $\beta$ has $\ge 3$ vertices by \cref{lem:size-expanded-corner}.
    Suppose for a contradiction that $\beta$ has a $(\le 1)$-separation $(X,Y)$.
    Without loss of generality, the $AC$-edge $e(A)$ for the $A$-link lies in $\beta[X]$.
    Then the $AC$-edge $e(C)$ for the $C$-link lies in $\beta[Y]$, since $G$ is 4-connected; see \cref{fig:banana2con}.
    Let $\hat X:=X\cup D$ and $\hat Y:=Y\cup (B\cap C)$.
    Then $S(\hat X,\hat Y)=S(X,Y)\cup (B\text{-link})$.
    So $(\hat X,\hat Y)$ is a mixed-3-separation of~$G^*$.
    Hence $(\hat X,\hat Y)$ witnesses that $G^*$ is not 4-connected by \cref{kConMixed}, contradicting that $G^*$ is spanned by the 4-connected subgraph~$G$.
\end{proof}

