\subsection{Tutte-bananas and Tutte-bagels}\label{sec:BagelTutteBanana}
A \defn{Tutte-bagel} of $G$ is a cycle-decomposition $(O,\cG)$ of $G$ with $\cG=(G_t:t\in V(O))$ that satisfies all of the following conditions:
\begin{enumerate}
    \item every torso is 3-connected, a 4-cycle or a triangle;
    \item all adhesion sets have size two;
    \item whenever two triangle-torsos are neighbours, the adhesion-graph in between them is a~$K_2$.
\end{enumerate} 


\begin{lemma}\label{TutteBagelObservations}
    Let $G$ be a 4-connected graph, and let $(O,\cG)$ be a Tutte-bagel of~$G$.
    \begin{enumerate}
        \item If a torso is 3-connected or a 4-cycle, then its adhesion sets are disjoint.
        \item If a torso is a triangle, then its adhesion sets are distinct but share exactly one vertex.
        \item If a torso is a 4-cycle, then the two neighbouring torsos must be 3-connected.\qed
    \end{enumerate}
\end{lemma}

Let $G$ be a graph.
A 2-separation $(A,B)$ of $G$ is \defn{totally-nested} if it is nested with every 2-separation of~$G$.
This is equivalent to saying that $(A,B)$ is half-connected and at least one of $G[A]$ and $G[B]$ is 2-connected \cite[Corollary~3.3.3]{Tridecomp}.
Assume now that $G$ is 2-connected and $N$ denotes its set of totally-nested 2-separations.
Then the tree-decomposition $\cT=\cT(N)$ defined by $N$ is the \defn{Tutte-decomposition} of $G$.
Every torso of $\cT$ is 3-connected, a cycle or a $K_2$.
Tutte introduced his decomposition in \cite{TutteCon}.
A modern proof is included in the appendix of \cite{Tridecomp}.
The Tutte-decomposition $\cT=(T,\cV)$ has the following two properties:
\begin{enumerate}
    \item Every adhesion-set has size two.
    \item Every adhesion-set between two neighbouring cycle-torsos is spanned by an edge in~$G$.
    \item Every $K_2$-torso neighbours at least three torsos, none of which are $K_2$'s.
\end{enumerate}
These properties give an alternative characterisation of the Tutte-decomposition.


\begin{definition}[Tutte-bananas]
    Let $G$ be a 4-connected graph.
    Let $(A,B)$ and $(C,D)$ be tetra-separations of $G$ that cross with all links of size two.
    Let $K$ be one of the four corners.
    Recall that the $K$-banana is 2-connected by \cref{banana2con}.
    The \defn{$K$-Tutte-banana} is the Tutte-decomposition of the $K$-banana.
    The \defn{$K$-Tutte-path} is the decomposition-tree of the $K$-Tutte-banana.
\end{definition}

\begin{lemma}\label{TutteBananaIsBanana}
    Tutte-bananas are path-decompositions all whose torsos are either 3-connected graphs, 4-cycles or triangles.
\end{lemma}
\begin{proof}
    This follows from $G$ being 4-connected.
\end{proof}



\begin{lemma}\label{linkRepresentedByEqualTorsos}
    Let $G$ be a 4-connected graph.
    Let $(A,B)$ and $(C,D)$ be tetra-separations of $G$ that cross with all links of size two.
    Let $K$ be one of the four corners, and consider an adjacent $L$-link $\Lambda$.
    Let $(T,\cV)$ be the $K$-Tutte-banana.
    \begin{enumerate}
        \item\label{linkRepresentedByEqualTorsos1} If $\Lambda$ consists of two vertices, then there is a unique node $t$ of $T$ with $\Lambda\se V_t$.
        Moreover, the torso of $V_t$ is 3-connected, and $t$ is an end-node of the path~$T$.
        \item\label{linkRepresentedByEqualTorsos2} If $\Lambda$ contains an edge, then there is unique node $t$ of $T$ with $\hat \Lambda=V_t$.
        Moreover, the torso of $V_t$ is a 4-cycle or a triangle, and $t$ is an end-node of the path~$T$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    Say $K$ is the $AC$-corner and $\Lambda$ is the $A$-link.

    \cref{linkRepresentedByEqualTorsos1}. 
    Let $u,v$ be the two vertices in $\Lambda$.
    Recall that $uv$ is an edge in $G^*$.
    So there is at least one bag $V_t\in\cV$ that contains both $u$ and~$v$.
    Let $V_s\in\cV$ contain the two ends of the $AC$-edge for the $C$-link, and choose $V_s$ to minimise the distance from $s$ to $t$ in~$T$.
    Recall that $T$ is a path by \cref{TutteBananaIsBanana}.
    If $t$ is not an end of $T$, there is $V_r\in\cV$ with $t\in \mathring{r}Ts$ and $V_r\sm V_t$ non-empty, so every vertex in $V_r\sm V_t$ is separated from a vertex outside the $AC$-banana by the adhesion-set of $rt$ which has size two, contradicting 4-connectivity.
    Hence $t$ is an end of~$T$.
    Similarly, either $u$ or $v$ avoids the adhesion-set of $V_t$, say $u$.
    If the torso of $V_t$ is a cycle, then $u\in S(C,D)$ violates the degree-condition.
    Thus the torso is 3-connected.

    \cref{linkRepresentedByEqualTorsos2}.
    Since $\Lambda$ contains an edge~$e$, the subgraph $H$ of $G^*$ induced by $\hat \Lambda$ is either a triangle or a 4-cycle, depending on whether the other element of $\Lambda$ besides $e$ is a vertex $v$ or an edge $f$, respectively.
    If $H$ is a triangle, then $v\in D\sm C$ has degree two in the $AC$-banana.
    Hence $H$ is a leaf-bag of $(T,\cV)$, and no other bag of $(T,\cV)$ includes~$\Lambda$.
\end{proof}

The node $t$ of $T$ as in \cref{linkRepresentedByEqualTorsos} is said to \defn{represent} the $L$-link in $T$, and in the $K$-Tutte-banana.

\begin{lemma}\label{TutteBananaLinksRepresentedDifferently}
    Let $G$ be a 4-connected graph.
    Let $(A,B)$ and $(C,D)$ be tetra-separations of $G$ that cross with all links of size two.
    Let $K$ be one of the four corners, and let $(T,\cV)$ be its Tutte-banana.
    The two links adjacent to $K$ are represented by distinct end-nodes of $T$, unless $T$ has only one node.
    In the latter case, both links consist of vertices only, and the unique torso of $(T,\cV)$ is 3-connected.
\end{lemma}
\begin{proof}
    Without loss of generality, $K$ is the corner $AC$.
    Both the $A$-link and the $C$-link are represented by end-nodes $a$ and $c$ of $T$, respectively, by \cref{linkRepresentedByEqualTorsos}.
    Assume now that $a=c$.
    Then $T$ has no edge, since otherwise the adhesion-set of this edge would form a 2-separator of $G$, contradicting 4-connectivity.
    Hence $|T|=1$, and in particular the corner $AC$ is not potter.

    We claim that both the $A$-link and the $C$-link consist of vertices only.
    Indeed, if the $A$-link contains an edge, then the $AC$-edge $e$ for the $A$-link is distinct from the $AC$-edge for the $C$-link by \cref{bananaEndNumberChar}, so the ends of $e$ together form a 2-separator of the $AC$-banana.
    This 2-separator gives rise to a 2-separation of the $AC$-banana that cuts off the triangle-torso or 4-cycle-torso at $a$ by \cref{linkRepresentedByEqualTorsos}, and this 2-separation is totally-nested as its separator is spanned by the edge $e$.
    Hence the 2-separation corresponds to an edge of $T$, a contradiction.
\end{proof}

\begin{definition}[Tutte-bagel induced by crossing tetra-separations]
    Let $G$ be a 4-connected graph.
    Let $(A,B)$ and $(C,D)$ be tetra-separations of $G$ that cross with all links of size two.
    For each corner $K$ let $\cT^K=(T^K,\cV^K)$ denote the $K$-Tutte-banana.
    Recall that $T^K$ is a path by \cref{TutteBananaIsBanana}.

    We obtain $O$ from the disjoint union $\bigsqcup_K T^K$, where $K$ ranges over the four corners, by doing the following for each link~$L$:
    for both corners $K$ and $K'$ adjacent to $L$ we consider the nodes $t$ and $t'$ that represent the $L$-link in $T^K$ and $T^{K'}$, respectively, and
    \begin{itemize}
        \item we join the nodes $t$ and $t'$ by an edge $\defnMath{o(L)}$ in $O$ if the torsos associated with these nodes in their respective Tutte-bananas are 3-connected;
        \item we otherwise identify the nodes $t$ and $t'$ to a single node $\defnMath{o(L)}$ of~$O$.
    \end{itemize}
    We say that $o(L)$ \defn{represents} the $L$-link in~$O$.
    For each node $t$ of $O$ that is not of the form $o(L)$, we define $G_t:=G[V^K_t]$ where $K$ is the unique corner with $t\in T^K$.
    For each node of $O$ of the form $o(L)$ for some link~$L$, we consider the two nodes $t\in T^K$ and $t'\in T^{K'}$ that were identified to obtain~$o(L)$, and we let $G_{o(L)}:=G[V^K_t]$ which is independent of $K$ by \cref{linkRepresentedByEqualTorsos}.
    We refer to the pair $(O,(G_t:t\in V(O))$ as the \defn{Tutte-bagel induced by $(A,B)$ and $(C,D)$}.
    It remains to show that this really is a Tutte-bagel.
\end{definition}


\begin{lemma}
\label{lem:really-is-Tutte-bagel}
    Let $G$ be a 4-connected graph.
    Let $(A,B)$ and $(C,D)$ be tetra-separations of $G$ that cross with all links of size two.
    The Tutte-bagel induced by $(A,B)$ and $(C,D)$ really is a Tutte-bagel.
\end{lemma}

\begin{proof}
Let $\cO=(O,(G_t : t\in V(O))$ denote the Tutte-bagel induced by $(A,B)$ and $(C,D)$.
First, we show that $\cO$ is a cycle-decomposition.
That $O$ is a cycle follows from \cref{TutteBananaLinksRepresentedDifferently}.

\cref{GraphDec1}.
Recall that there are no jumping edges and no diagonal edges by the \allref{keylem:crossing}.
Every vertex and edge of $G$ is included in some expanded corner, and hence is included in the bag of some Tutte-banana.
Hence every vertex and edge of $G$ appears in some~$G_t$.

\cref{GraphDec2}.
Let $v\in G$ be a vertex and consider $O_v:=O[\,\{t\in V(O):v\in G_t\}\,]$.

If $v$ avoids $\hat\Lambda$ for every link $\Lambda$, then $v$ lies in a unique banana, and so $O_v$ is a subpath of the decomposition-path of the corresponding Tutte-banana.
If $v$ lies in $\hat\Lambda$ for precisely one $L$-link $\Lambda$, then $v$ lies in the bananas for the two corners adjacent to~$L$, and so $O_v$ is a path.
Otherwise $v$ lies in $\hat\Lambda_1\cap\hat\Lambda_2$ for two adjacent $L_i$-links~$\Lambda_i$.
Then $v$ lies in the corner $K$ in between the two links.
Then $v$ lies in all bags of the $K$-Tutte-banana, and in the unique bags at the nodes representing the $L_i$-links in the Tutte-bananas of the corners adjacent to~$K$.

Let $H_t$ be a torso of~$\cO$.
If $t$ represents some link, then $H_t$ is a 4-cycle or a triangle.
Otherwise $H_t$ stems from a Tutte-banana. Then $H_t$ is 3-connected, a 4-cycle or a triangle, by \cref{TutteBananaIsBanana}.

Since every adhesion-set between two neighbouring triangle-torsos of a Tutte-banana is spanned by an edge in~$G$, the same is true for~$\cO$.
\end{proof}

\begin{lemma}
    \label{TutteBagelAdhesionSetNote}
    Let $G$ be a 4-connected graph.
    Let $(A,B)$ and $(C,D)$ be tetra-separations of $G$ that cross with all links of size two.
    Let $\cO$ be the Tutte-bagel induced by $(A,B)$ and $(C,D)$.
    Every $K$-edge for an $L$-link spans a unique adhesion-set of~$\cO$.\qed
\end{lemma}



\subsection{Settings}\label{sec:BagelSettings}

The following settings are supported by \cref{fig:BagelBag}.

\begin{setting}[Tutte-bagel setting]\label{setting:TutteBagel}
    Let $G$ be a 4-connected graph.
    Let $(A,B)$ and $(C,D)$ be tetra-separations of $G$ that cross with all links of size two.
    Let $\cO=(O,(G_t:t\in V(O)))$ be the Tutte-bagel induced by $(A,B)$ and $(C,D)$, with torsos being denoted by~$H_t$.
    Write $O=:t(0),t(1),\ldots,t(m),t(0)$ with indices in $\Z_{m+1}$.
    Assume that the representatives of the links appear in this enumeration in the order $o(C),o(B),o(D),o(A)$.
    For each node $t$ of $O$ let $U'_t:=V(G_t)$ and $W'_t:=\bigcup\,\{\,V(G_s):s\in V(O-t)\,\}$.
    Let $(U_t,W_t)$ denote the right-left-shift of $(U'_t,W'_t)$.
\end{setting}

\begin{setting}[Tutte-bagel torso setting]\label{BagelBag}
    Assume the \allref{setting:TutteBagel}.
    Assume that the torso $H_{t(0)}$ of $\cO$ is 3-connected; so $H_{t(0)}$ stems from the $AC$-banana.    
    Let $\{x'_1,x'_2\}$ be the adhesion set of $t(-1) t(0)$ and let $\{y'_1,y'_2\}$ be the adhesion set of $t(0) t(1)$.
    Let $(U',W'):=(U'_{t(0)},W'_{t(0)})$ and $(U,W):=(U_{t(0)},W_{t(0)})$.
    Note that $S(U',W')=\{x'_1,x'_2,y'_1,y'_2\}$.
    Let $x_i\in S(U,W)$ be equal or incident to~$x'_i$, and let $x^W_i$ be the unique vertex in $\hat x_i \cap W$.
    Define $y_i$ and $y^W_i$ similarly.
\end{setting}

