\end{figure}

Let $\cO$ be a Tutte-bagel of a 4-connected graph $G$.
Let $H_t$ be a torso of $\cO$.
Assume first that $H_t$ is a 4-cycle.
Then $H_t$ has exactly two edges whose endvertices lie in distinct adhesion-sets of $H_t$.
We call these edges the \defn{free edges} of $H_t$.
Assume now that $H_t$ is a triangle.
Then the adhesion-sets of $H_t$ share exactly one vertex $v$.
We call $v$ the \defn{tip} of the triangle $H_t$.
There is a unique edge of $H_t$ whose endvertices lie in distinct adhedion-sets of $H_t$.
We call this edge the \defn{free edge} of the triangle~$H_t$.

\begin{lemma}\label{BagelBagAdhesionSet}
    Assume the \allref{BagelBag}.
    The vertex-set $\{y^W_1,y^W_2\}$ is the adhesion-set at $t(0)\, t(1)$ if the torso $H_{t(1)}$ is 3-connected, and it is the adhesion-set at $t(1)\, t(2)$ otherwise.
    In the latter case, the torso at $t(2)$ is not a 4-cycle.
\end{lemma}
\begin{proof}
    The former case is straightforward, so it remains to consider the case where $H_{t(1)}$ is not 3-connected.
    If the torso $H_{t(1)}$ is a 4-cycle, then the $y_i$ are the free edges of $H_{t(1)}$, and so $\{y^W_1,y^W_2\}$ is the adhesion-set at $t(1) t(2)$.
    Hence we may assume that the torso $H_{t(1)}$ is a triangle.
    The next torso $H_{t(2)}$ cannot be 4-cycle by \cref{TutteBagelObservations}, so it is 3-connected or a triangle.

    Assume first that $H_{t(2)}$ is 3-connected.
    Since $H_{t(2)}$ shares a vertex with $H_{t(1)}$, say $y'_1$, the vertex-set of $H_{t(2)}$ must be included in~$C$.
    Hence the $\ge 2$ neighbours of $y'_1$ in the bag $G_{t(2)}$ lie in~$W'\sm U'$.
    Thus $y^W_1=y'_1$.
    Since $H_{t(1)}$ is a triangle, $y_2$ is its free edge, so $\{y^W_1,y^W_2\}$ is the adhesion-set at~$t(1)\, t(2)$.

    Otherwise it is a triangle, so the adhesion-graph at $t(1)\, t(2)$ is a $K_2$-subgraph of~$G$.
    Then the $y'_i$ incident to the free edge of the triangle $H_{t(1)}$ corresponds to an edge~$y_i$.
    The $y'_j$ that is the tip of $H_{t(1)}$ has $y^W_i$ as a neighbour and is incident to the free edge of $H_{t(2)}$, so $y'_j=y_j$.
    Hence $\{y^W_1,y^W_2\}$ is the adhesion-set at $t(1)\, t(2)$.
\end{proof}

Recall that $O_v=O[\,\{t\in V(O):v\in G_t\}\,]$ for a vertex $v\in V(G)$ in the context of a Tutte-bagel~$\cO$ of~$G$.

\begin{lemma}\label{trianglePath}
    Let $G$ be a 4-connected graph, and let $\cO=(O,\cG)$ be a Tutte-bagel of $G$.
    Then both of the following assertions hold:
    \begin{enumerate}
        \item\label{trianglePath2} Every two triangle-torsos of $\cO$ have distinct tips.
        \item\label{trianglePath1} Let $P \subseteq O_v$ be a path with ends~$r \neq t$ such that $H_r,H_t$ are triangles. Then $P=rt$ or $P=rst$ where $H_s$ is a triangle. 
    \end{enumerate} 
\end{lemma}

\begin{proof}
    \cref{trianglePath2}. 
    Suppose for a contradiction that two triangle-torsos of $\cO$ have the same tip.
    Say the torsos are~$H_r$ and~$H_t$, and~$v$ is their shared tip.
    Let~$e$ be the free edge of~$H_r$, and let~$e'$ be the free edge of~$H_t$.
    Then $\{v,e,e'\}$ is a mixed-3-separator, contradicting 4-connectivity by \cref{kConMixed}.

    \cref{trianglePath1}.
    First, assume that there is a node $p$ on $P$ other than $r,t$ with $v\in G_p$ such that the torso $H_p$ is a 4-cycle or 3-connected.
    That the adhesion-sets at $G_p$ are disjoint then contradicts that $v$ lies in all three bags $G_r,G_p,G_t$.
    Otherwise, all torsos of all nodes on~$P$ are triangles.
    Let~$e$ be the edge of~$P$ incident with~$r$, and let~$e'$ be the edge of~$P$ incident with~$t$.
    By~\ref{trianglePath2}, if $|P| \geq 4$ then the adhesion sets of~$e$ and~$e'$ are disjoint, which contradicts that~$v$ lies in all bags of nodes in~$P$ by $P\se O_v$.
    Otherwise $|P| \leq 3$ and we get the statement.
\end{proof}



\subsection{N-Paths lemmata}\label{sec:BagelNpaths}

\begin{lemma}\label{twoDisjointPathsOutsideBagel}
    Let $G$ be a 4-connected graph with a Tutte-bagel $\cO=(O,\cG)$ and decomposition-cycle $O=t(0),\ldots t(m),t(0)$.
    Let $0\le i< j\le m$.
    Let $\pi_\ell$ denote the adhesion-set of $t(\ell)t(\ell+1)$ for all relevant indices~$\ell$.
    There exist two disjoint $\pi_i$--$\pi_j$ paths in $G_{t(i+1)}\cup\cdots\cup G_{t(j)}$.
\end{lemma}
\begin{proof}
    For each torso $H_{t(\ell)}$ we use that it is 2-connected to find two disjoint paths $P_\ell,Q_\ell$ between its two adhesion-sets.
    These paths use no torso-edges, so they are subgraphs of their bags and of~$G$.
    Hence combining the paths in the bags $G_{t(i+1)},\ldots, G_{t(j)}$ yields a pair of desired $\pi_i$--$\pi_j$ paths.
\end{proof}

\begin{lemma}\label{3conAdhesionNoPathK4}
    Let $\cO$ be a Tutte-bagel of a 4-connected graph~$G$.
    Let $H_t$ be a 3-connected torso of $\cO$ with adhesion sets $\pi$ and $\pi'$.
    The two vertices in $\pi$ are linked by a path in $G_t-\pi'$, unless $H_t=K_4$.
\end{lemma}
\begin{proof}
    Assume that the two vertices $x_1,x_2$ in $\pi$ lie in distinct components $C_i$ of $G_t-\pi'$.
    Then $V(C_i)=\{x_i\}$ and $G_t-\pi'=C_1\cup C_2$, as $G$ is $4$-connected.
    Hence $G_t$ has only 4 vertices.
    Since $H_t$ is 3-connected, it is a $K_4$.
\end{proof}

\begin{lemma}\label{BagelLinkForm}
    Assume the \allref{setting:TutteBagel}.
    Let $K$ be a corner.
    If the $K$-Tutte-banana has no 3-connected torsos, then all its torsos are triangles, all its adhesion-graphs are $K_2$-subgraphs of~$G$, and the two links adjacent to $K$ are represented by triangle-torsos in the Tutte-banana.
\end{lemma}
\begin{proof}
    Since the Tutte-banana $\cT$ for $K$ has no 3-connected torsos, it also has no 4-cycles as torsos by \cref{TutteBagelObservations}.
    Hence all torsos of $\cT$ are triangles; in particular, both links adjacent to $K$ are represented by triangle-torsos of~$\cT$.
    Again by \cref{TutteBagelObservations}, it follows that all adhesion-graphs of $\cT$ are $K_2$-subgraphs of~$G$.
\end{proof}

\begin{lemma}[One-Path Lemma]\label{OnePathBagel}
    Assume the \allref{setting:TutteBagel}.
    Let $a_1 a_2$ be the $AD$-edge for the $A$-link.
    Then there is an $a_1$--$a_2$ path $P$ in $G[A\cap D]$ that uses at most one vertex in the $D$-link.
    Moreover, if $AD$ is not potter, then for each vertex $d$ in the $D$-link there is such a path $P$ that avoids~$d$.
    And if both $a_1,a_2$ lie in the $A$-link, then $P$ does not use the edge $a_1 a_2$ (if it exists).
\end{lemma}
\begin{proof}
    If the corner $AD$ is potter, then $a_1 a_2$ is an edge in $G$, and the path $a_1 a_2$ is as desired.
    So we may assume that the corner $AD$ is not potter.
    Let $\cT$ denote the $AD$-Tutte-banana.
    We distinguish two cases.

    Suppose first that $\cT$ has a 3-connected torso $H_t$.
    We find two disjoint $a_i$--$H_t$ paths $P_i$ for $i=1,2$ in the $AD$-banana using \cref{twoDisjointPathsOutsideBagel}.
    We even get that both $P_i$ are subgraphs of~$G$.
    Note that the ends of the $P_i$ in $H_t$ together form an adhesion-set.
    If $H_t$ is a $K_4$, then we link the ends of the $P_i$ in the bag $G_t$ by a path that avoids any prescribed vertex $d$ in the $D$-link and that uses no torso-edges.
    Otherwise $H_t$ is not a $K_4$, so we may use \cref{3conAdhesionNoPathK4} to link the ends of the $P_i$ in the bag $G_t$ with a path that avoids all vertices in the $D$-link and that uses no torso-edges.

    Suppose second that $\cT$ has no 3-connected torsos.
    Then all torsos of $\cT$ are triangles, both the $A$-link and the $D$-link are represented by triangle-torsos, and $a_1 a_2\in E(G)$ by \cref{BagelLinkForm}.
    In particular, exactly one of $a_1,a_2$ lies in the $A$-link, say it is~$a_1$.
    Now $a_2$ cannot lie in the $D$-link, since otherwise some edge dangles from the $D$-link through the $A$-link which by the \allref{keylem:crossing} implies that the corner $AD$ is potter, a contradiction.
    Hence the path $a_1 a_2$ is as desired.
\end{proof}



\begin{lemma}[Two-Paths Lemma]\label{TwoPathsBagel}
    Assume the \allref{BagelBag}.
    Let $\ell\ge 1$ be maximum such that $t(\ell)$ stems from the BD-Tutte-banana.
    There exist two independent $y^W_1$--$y^W_2$ paths $P_1,P_2$ in $G_{t(1)}\cup\cdots\cup G_{t(\ell)}$ not using the edge $y'_1 y'_2$ (if it exists) such that:
    \begin{enumerate}
        \item $P_1\cup P_2$ uses at most one vertex of the $D$-link.
        \item If the corner $BD$ is not potter, then for every vertex $d$ in the $D$-link we can choose the two paths so that $d\notin P_1\cup P_2$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    By \cref{BagelBagAdhesionSet}, there is $i\in \{1,2\}$ such that $\{y^W_1,y^W_2\}$ is the adhesion-set at $t(i-1) t(i)$.
    Moreover, the torso $H_{t(i)}$ is not a 4-cycle.
    We consider two cases, supported by \cref{fig:BagelBagTwoPaths}.

    Suppose first that the torso at $t(i)$ is 3-connected.
    Then we find two $y^W_1$--$y^W_2$ paths $Q_1,Q_2$ in the torso at $t(i)$ that avoid the torso-edge $y^W_1 y^W_2$.
    Note that $G_{t(i)}\se G[C]$.
    If neither $Q_j$ uses the other torso-edge $z_1 z_2$, then we are done.
    So we may assume that $Q_1$, say, uses $z_1 z_2$.
    Let $e=u_1 u_2$ be the $BD$-edge for the $B$-link.
    Let $k\ge i$ be maximum such that $t(k)$ stems from the $BC$-Tutte-banana.
    By \cref{twoDisjointPathsOutsideBagel}, we find two disjoint $\{z_1,z_2\}$--$\{u_1,u_2\}$ paths $R_1,R_2$ in $G_{t(i+1)}\cup\cdots\cup G_{t(k)}$, taking the trivial paths if $k=i$.
    We apply the \allref{OnePathBagel} (with $B$ in place of $A$) to the $BD$-edge $u_1 u_2$ for the $B$-link to find a $u_1$--$u_2$ path $R_3$ in $G[B\cap D]$ that uses at most one vertex in the $D$-link.
    Moreover, if $BD$ is not potter, then we find $R_3$ so that it avoids any prescribed vertex $d$ in the $D$-link.
    Then $P_1:=(Q_1- z_1 z_2)\cup R_1 \cup R_2 \cup R_3$ and $P_2:=Q_2$ are as desired.

    Suppose otherwise that the torso at $t(i)$ is a triangle.
    Then $i=2$ and the torso at $t(1)$ is not 3-connected, by \cref{BagelBagAdhesionSet}.
    Since the torso at $t(2)$ is a triangle, the torso at $t(1)$ cannot be a 4-cycle by \cref{TutteBagelObservations}, so it must be a triangle as well.
    Then the adhesion-graph of $t(1) t(2)$ is a $K_2$-subgraph of~$G$ with vertices~$y^W_1,y^W_2$.
    Then we let $P_2:=Q_2:=y^W_1 y^W_2$ and construct $P_1:=R_1\cup R_2\cup R_3$ as in the first case with the \allref{OnePathBagel}.
\end{proof}

