\begin{lemma}[Three-Paths Lemma]\label{ThreePathsBagelLemma}
    Assume the \allref{BagelBag}.
    There exist three independent $\{x^W_1,y^W_1\}$--$\{x^W_2,y^W_2\}$ paths $P_1,P_2$ and $P_3$ in $G[W] - x'_1 x'_2 - y'_1 y'_2$ such that two $P_i$ link $y^W_1$ to $y^W_2$ and one $P_i$ links $x^W_1$ to $x^W_2$.
\end{lemma}

\begin{proof}
    Recall that not both corners $AD,BD$ are potter by \cref{obs:potter-adjacent-corner}.

    Suppose first that the corner $AD$ is not potter.
    We apply the \allref{TwoPathsBagel} to find two independent $y^W_1$--$y^W_2$ paths $P_1,P_2$ in $G[W] - y'_1 y'_2$ such that $P_1\cup P_2$ uses at most one vertex in the $D$-link.
    Then we apply the \allref{OnePathBagel} to find an $x^W_1$--$x^W_2$ path $P_3\se G[W] - x'_1 x'_2$ that avoids $P_1\cup P_2$.

    Suppose otherwise that the corner $BD$ is not potter.
    We proceed as in the first case, except that we find $P_3$ first and then find $P_1,P_2$ afterwards.
\end{proof}




\subsection{Totally-nested tetra-separations from good bags}\label{sec:BagelTotallyNested}


\begin{definition}[Good bag, bad bag]
    Let $\cO$ be a Tutte-bagel of a 4-connected graph~$G$.
    A torso $H_t$ of $\cO$ is \defn{good} if it is 3-connected and it satisfies at least one of the following conditions:
    \begin{enumerate}
        \item $|H_t|\ge 6$;
        \item some neighbouring torso is a 4-cycle;
        \item both neighbouring torsos are triangles; or
        \item $|H_t|=5$ and some neighbouring torso is a triangle.
    \end{enumerate} 
    If $H_t$ fails to be good, it is \defn{bad}.
\end{definition}

\begin{lemma}\label{GoodBagTetra}
    Assume the \allref{BagelBag}. The following assertions are equivalent:
    \begin{enumerate}
        \item\label{GoodBagTetra1} $(U,W)$ is a tetra-separation;
        \item\label{GoodBagTetra2} $H_{t(0)}$ is good.
    \end{enumerate}
\end{lemma}
\begin{proof}
    Note that $|W'\sm U'|\ge 2$.

    \cref{GoodBagTetra2} $\Rightarrow$ \cref{GoodBagTetra1}.
    Assume that $H_{t(0)}$ is good.
    If $|H_{t(0)}|\ge 6$, then $U'\sm W'$ has size~$\ge 2$, so $(U,W)$ is a tetra-separation by \cref{leftrightTetra}.
    If $|H_{t(0)}|= 5$ or $|H_{t(0)}|=4$, then $H_{t(0)}$ being good ensures via the neighbouring torsos that at least one or at least two vertices in $S(U',W')$ have exactly one neighbour in $W'\sm U'$, respectively, so $(U,W)$ is a tetra-separation by \cref{leftrightTetra}.

    \cref{GoodBagTetra1} $\Rightarrow$ \cref{GoodBagTetra2}.
    Assume that $(U,W)$ fails to be a tetra-separation.
    Then by \cref{leftrightTetra}, the number of vertices in $S(U',W')$ with $\le 1$ neighbour in $W'\sm U'$ fails to be $\ge 2-|U'\sm W'|$.
    Hence all sufficient conditions for $H_{t(0)}$ being good fail.
\end{proof}

\begin{center}
    \textbf{Half-connected}
\end{center}

\begin{lemma}\label{BagelHalfconnected}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Then $(U,W)$ is half-connected.
\end{lemma}
\begin{proof}
    If $S(U,W)$ contains an edge, then $G-S(U,W)$ has exactly two components by 4-connectivity, so $(U,W)$ is half-connected.
    Otherwise $(U,W)=(U',W')$.
    We will show that $G[W\sm U]$ is connected.
    Let $\pi$ denote the adhesion-set of~$\cO$ that is spanned by the $BD$-edge for the $D$-link by \cref{TutteBagelAdhesionSetNote}.

    We claim that every vertex $v\in W\sm U$ not in $\pi$ sends a fan of two paths to $\pi$ in $G[W\sm U]$.
    Indeed, $\pi$ together with $\{x'_1,x'_2\}$, say, separates $v$ from $G_{t(0)}$.
    Since $G$ is 4-connected, there is a fan of four paths from $v$ to $\{x'_1,x'_2\}\cup\pi$ by \cref{Menger}.
    The two paths ending in $\pi$ are as desired.

    So it remains to show that there is at least one vertex in $W\sm U$ besides the two vertices in~$\pi$.
    The vertex $x_1$ has at least two neighbours in $W\sm U$, at least one of which must be in $A\sm B$.
    The neighbour in $A\sm B$ avoids $\pi\se B$.
\end{proof}

\begin{center}
    \textbf{3-linked}
\end{center}

\begin{lemma}\label{CrossPathInBag}
    Let $\cO$ be a Tutte-bagel of a 4-connected graph~$G$.
    Let $H_t$ be a 3-connected torso of $\cO$ with adhesion sets $\{a_1,a_2\}$ and $\{b_1,b_2\}$.
    Then there is an $a_1$--$b_1$ path in $G_t-\{a_2,b_2\}$.
\end{lemma}
\begin{proof}
    Assume for a contradiction that the two vertices $a_1,b_1$ lie in distinct components $C,D$ of $G_t-\{a_2,b_2\}$.
    Then $V(C)=\{a_1\}$ and $V(D)=\{b_1\}$, as $G$ is $4$-connected.
    Hence $G_t$ has only 4 vertices.
    Since $H_t$ is 3-connected, it is a $K_4$.
    But then $a_1 b_1$ is an edge in $G_t$, a contradiction.
\end{proof}

\begin{lemma}\label{PathShortening}
    Assume the \allref{BagelBag}.
    Let $P'$ be a path in $G_{t(0)}$ that joins two vertices $v'_1,v'_2\in S(U',W')$ and avoids the other two vertices in $S(U',W')$.
    Let $v_i\in S(U,W)$ be equal or incident to~$v'_i$.
    Then $P'$ contains a $\hat v_1$--$\hat v_2$ path~$P$ that avoids the two vertices or edges in $S(U,W)$ besides $v_1$ and~$v_2$.
\end{lemma}
\begin{proof}
    If $v_i$ is an edge, then all neighbours of $v'_i$ in $G_{t(0)}$ lie in $S(U',W')$ except the one that is joined to $v'_i$ via the edge~$v_i$, so $P'$ uses~$v_i$.
    Hence $P'$ contains the desired subpath.
\end{proof}

\begin{lemma}\label{bagelHowFar}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Let $1\le k\le m$ be maximum with $y^W_1\in G_{t(k)}$.
    Assume that $y_2$ is a vertex.
    Then exactly one of the following two assertions holds:
    \begin{enumerate}
        \item\label{bagelHowFar1} The torso $H_{t(k)}$ is 3-connnected, there are $\le 2$ torsos in between $H_{t(0)}$ and $H_{t(k)}$, and they are triangles.
        \item\label{bagelHowFar2} $H_{t(k)}$ is a triangle, the two edges in $H_{t(k)}$ incident to $y^W_1$ exists in~$G$ and $y^W_2\notin H_{t(k)}$.
        Moreover, there are exactly two triangle-torsos between $H_{t(0)}$ and $H_{t(k)}$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    If $H_{t(1)}$ is 3-connected, we have~\cref{bagelHowFar1}.
    Otherwise $H_{t(1)}$ is a 4-cycle or a triangle.
    Since $y_2$ is a vertex by assumption, $H_{t(1)}$ is a triangle and $y_2=y^W_2$ is its tip, by \cref{BagelBagAdhesionSet}.
    Hence $y^W_1$ is incident to the free edge of $H_{t(1)}$.
    If $H_{t(2)}$ is 3-connected, then we have~\cref{bagelHowFar1}.
    Otherwise $H_{t(2)}$ is a triangle, by \cref{TutteBagelObservations}.
    By \cref{trianglePath}, $y^W_1$ is the tip of $H_{t(2)}$.
    Hence $y^W_2$ is not contained in the adhesion-set between $H_{t(2)}$ and $H_{t(3)}$, and in particular $y^W_2$ is not contained in $H_{t(3)}$.
    If $H_{t(3)}$ is 3-connected, we have~\cref{bagelHowFar1}.
    Otherwise $H_{t(3)}$ also is a triangle.
    By \cref{trianglePath}, $y^W_1$ is incident to the free edge of $H_{t(3)}$.
    By \cref{TutteBagelObservations}, the adhesion-graph between the triangle-torsos $H_{t(2)}$ and $H_{t(3)}$ is a $K_2$-subgraph of~$G$.
    Hence the two edges of $H_{t(3)}$ incident to $y^W_1$ exist in~$G$.
    Thus we have~\cref{bagelHowFar2}.
\end{proof}

\begin{lemma}\label{bagelTwoPaths}
    Let $\cO$ be a Tutte-bagel of a 4-connected graph~$G$.
    Let $H_t$ be a 3-connected torso of $\cO$ with adhesion-sets $\{a_1,a_2\}$ and $\{b_1,b_2\}$.
    Then either
    \begin{enumerate}
        \item\label{bagelTwoPaths1} there exist two independent $a_1$--$b_1$ paths in the bag $G_t$, or
        \item\label{bagelTwoPaths2} the torso $H_t$ is a 4-wheel with rim $a_1 a_2 b_1 b_2$ and both edges $a_1 a_2, b_1 b_2$ are missing from~$G$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    Assume that \cref{bagelTwoPaths1} fails.
    Then there exists a cutvertex $v$ of $G_t$ that separates $a_1$ from $b_1$.
    Since $H_t$ is 3-connected and $G_t$ misses at most two of the torso-edges, $v$ is distinct from $a_2$ and~$b_2$.
    Adding the edges $a_1 a_2$ and $b_1 b_2$ makes $v$ into the separator of a mixed-3-separation $(X,Y)$ of $H_t$ with $a_1\in X\sm Y$ and $b_1\in Y\sm X$.
    Since $S(X,Y)$ contains edges, $H_t -S(X,Y)$ has exactly two components.
    These components include the vertex-sets $\{a_1,v,b_2\}$ and $\{a_2,v,b_1\}$, respectively.
    Since $G$ is 4-connected, these inclusions are equalities, and $v$ has degree four in~$H_t$.
    As $H_t$ is 3-connected, $H_t$ is a 4-wheel with rim $a_1 a_2 b_1 b_2$.
    Since \cref{bagelTwoPaths1} fails by assumption, both torso-edges $a_1 a_2$ and $b_1 b_2$ must be missing from~$G$.
\end{proof}



\begin{lemma}\label{outsidePaths}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Assume that both $x_2$ and $y_2$ are vertices.
    There are two independent $x^W_1$--$y^W_1$ paths in $G[W]-x_2-y_2$.
\end{lemma}
\begin{proof}
    Let $1\le i\le m$ be maximum with $y^W_1\in G_{t(i)}$.
    Let $1\le j\le m$ be minimum with $x^W_1\in G_{t(j)}$.
    Let $\pi_\ell$ denote the adhesion-set at $t(\ell)t(\ell+1)$ for all~$\ell$.
    We consider two cases.

    \casen{Case $i<j$.}
    This case is supported by \cref{fig:outsidePaths}.
    If $H_{t(i)}$ is 3-connected, we let $F_y$ by a $y^W_1$--$\pi_i$ fan of two paths in $G_{t(i)}$ avoiding the vertex in $\pi_{i-1}-y^W_1$.
    Otherwise, by \cref{bagelHowFar}, $H_{t(i)}$ is a triangle avoiding $y^W_2$ such that both edges incident to $y^W_1$ in $H_{t(i)}$ exist in~$G$,
    and we let $F_y$ denote the $y^W_1$--$\pi_i$ fan of two paths defined by these two edges.
    In both cases, $F_y$ avoids~$y_2$.
    Similarly, we obtain an $x^W_1$--$\pi_{j-1}$ fan $F_x\se G_{t(j)}$ avoiding $x_2$.
    By \cref{twoDisjointPathsOutsideBagel}, we find two disjoint $\pi_i$--$\pi_{j-1}$ paths in $G_{t(i+1)}\cup\cdots\cup G_{t(j-1)}$.
    Call these paths $P$ and~$Q$.
    Then $F_x\cup P\cup Q\cup F_y$ is a union of two independent $x^W_1$--$y^W_1$ paths in $G[W]-x_2-y_2$.

    \begin{figure}[ht]
        \centering
        \includegraphics[height=6\baselineskip]{Figures/BagelDualPaths.pdf}
        \caption{Case $i<j$ in the proof of \cref{outsidePaths}. 
        Here, $H_{t(i)}$ is 3-connected and $H_{t(j)}$ is a triangle. The unique vertex in $\pi_{i-1}-y^W_1$ is black.}
        \label{fig:outsidePaths}
    \end{figure}

    \casen{Case $i\ge j$.}
    This case is supported by \cref{fig:outsidePathsOther}.
    We claim that the corner $BD$ is not potter, and assume for a contradiction that it is.
    Let $\pi$ denote the unique adhesion-set of the $BD$-Tutte-banana.
    Since $BD$ is potter, neither corner $BC$ nor $AD$ is potter by \cref{obs:potter-adjacent-corner}.
    Hence if $y_1$ is an edge, it neither dangles from the $C$-link through the $B$-link nor from the $B$-link through the $C$-link, by the \allref{keylem:crossing}.
    So $y^W_1\in C\sm D$, and hence $y^W_1\notin\pi$.
    Similarly, $x^W_1\notin\pi$.
    But this contradicts $i\ge j$, so the corner $BD$ is not potter.

    We claim that $y^W_1$ lies in the $B$-link and $x^W_1$ lies in the $D$-link.
    Assume for a contradiction that $y^W_1$ avoids the $B$-link, say.
    Then $y^W_1\in C\sm D$.
    Let $\pi$ denote the adhesion-set defined by the $BD$-edge for the $B$-link.
    Since $BD$ is not potter, no edge dangles from the $D$-link through the $B$-link.
    Hence $\pi\se (B\sm A)\cap D$.
    Now $y^W_1\notin\pi$ since $y^W_1\notin D$, and $x^W_1\notin\pi$ since $x^W_1\notin B\sm A$, contradicting $i\ge j$.
    So $y^W_1$ lies in the $B$-link and $x^W_1$ lies in the $D$-link.

    By \allref{keylem:crossing}, the corners $BC$ and $AD$ are potter.
    Let $T$ denote the $BD$-Tutte-path.
    Then $o(B)$ and $o(D)$ are the ends of~$T$.
    Note that $T$ has $\ge 3$ nodes.

    Assume first that $o(B)$ or $o(D)$ has a neighbour in $T$ with a triangle-torso in~$\cO$.
    Say this is a neighbour $t$ of $o(B)$.
    Since $y^W_1$ is the tip of the triangle $H_{o(B)}$, the vertex $y^W_1$ is an end of the free edge $f$ of $H_t$ by \cref{trianglePath}.
    Let $u$ denote the other end of~$f$.
    Let $v$ denote the tip of $H_t$.
    Note that $\{u,v\}$ is an adhesion-set, so $x^W_1\in\{u,v\}$.
    Hence $x^W_1$ lies in the two triangle-torsos from the potter corner $AD$ and in the triangle-torso $H_t$.
    Thus $o(D)$ and $t$ are neighbours in~$T$ by \cref{trianglePath}.
    In particular, $T$ has exactly three nodes.
    Since $v$ lies in the two triangle-torsos $H_t$ and $H_{o(B)}$ while $x^W_1$ lies in the two triangle-torsos for the potter corner $AD$, we cannot have $v=x^W_1$ by \cref{trianglePath}.
    Hence $x^W_1=u$.
    By \cref{TutteBagelObservations}, the two adhesion-sets of $H_t$ are spanned by edges in~$G$.
    Hence $x^W_1 y^W_1$ and $x^W_1 v y^W_1$ are desired paths.

    \begin{figure}[ht]
        \centering
        \includegraphics[height=9\baselineskip]{Figures/outsidePathsVersionB.pdf}
        \caption{Case $i\ge j$ in the proof of \cref{outsidePaths}. Left: $H_t$ is a triangle.\\ Right: $H_t$ is 3-connected.}
        \label{fig:outsidePathsOther}
    \end{figure}

    Assume otherwise that neither $o(B)$ nor $o(D)$ has a neighbour in $T$ with a triangle-torso.
    Then the torsos neighbouring $o(B)$ and $o(D)$ via $T$ are 3-connected.
    Since 3-connected torsos have disjoint adhesion-sets and $i\ge j$, we have $|T|=3$.
    Let $t$ denote the internal node of~$T$.
    Let $\{x^W_1,u\}$ denote the adhesion-set of the edge $o(D)t$, and let $\{y^W_1,v\}$ denote the adhesion-set of the edge $o(B)t$.
    We find two independent $y^W_1$--$x^W_1$ paths in $G_t$, and are done, unless $H_t$ is a 4-wheel with rim $x^W_1 u y^W_1 v$ and $x^W_1 u,y^W_1 v\notin E(G)$, by \cref{bagelTwoPaths}.
    But in the latter case, $u$ and $v$ have degree three in $G$, contradicting 4-connectivity.
\end{proof}


\begin{lemma}\label{Bagel3linkedAntisym}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Then $\{x_i,y_j\}$ is 3-linked around $S(U,W)$ for all $i,j\in [2]$.
\end{lemma}

\begin{proof}
    Say $i=j=1$.
    If $x_2$ or $y_2$ is an edge, then we are done by \ref{itm:3-linked-1}, so assume that both are vertices.
    By \cref{CrossPathInBag}, there is an $x'_1$--$y'_1$ path $P'$ in $G_{t(0)}-\{x'_2,y'_2\}$.
    Then $P'$ contains a $\hat x_1$--$\hat y_1$ path~$P$ that avoids the vertices~$x_2$ and~$y_2$, by \cref{PathShortening}.
    We find two independent $x^W_1$--$y^W_1$ paths in $G[W]-x_2-y_2$ using \cref{outsidePaths}.
    Hence $\{x_1,y_1\}$ is 3-linked around $S(U,W)$ by \ref{itm:3-linked-3}.
\end{proof}

\begin{lemma}\label{Bagel3linkedSym}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Then $\{x_1,x_2\}$ is 3-linked around $S(U,W)$.
    Similarly, $\{y_1,y_2\}$ is 3-linked around $S(U,W)$.
\end{lemma}
\begin{proof}
    If $y_1$ or $y_2$ is an edge, we are done, so assume that both are vertices.
    There exist two independent $x^W_1$--$x^W_2$ paths in $G[W]-\{y_1,y_2\}$ by the \allref{ThreePathsBagelLemma}.
    So it remains to find an $x'_1$--$x'_2$ path in $G':=G_{t_0}-\{y'_1,y'_2\}$ (as any such path contains a suitable $\hat x_1$--$\hat x_2$ path by \cref{PathShortening}).
    Assume for a contradiction that such a path is missing.
    Then $H_{t(0)}$ is a $K_4$ by \cref{3conAdhesionNoPathK4}.
    Since both $y_1$ and $y_2$ are vertices, the torso $H_{t(1)}$ is 3-connected by \cref{BagelBagAdhesionSet}.
    Since $H_{t(0)}$ is good, it follows that $H_{t(-1)}$ is a 4-cycle.
    So $x_1$ and $x_2$ are the two free edges on this 4-cycle.
    By 4-connectivity of $G$, both $x'_1$ and $x'_2$ have degree at least four.
    Since $H_{t(-1)}$ is a 4-cycle and $H_{t(0)}$ is a $K_4$, it follows that the edge $x'_1 x'_2$ must exist in~$G$, contradicting that there is no $x'_1$--$x'_2$ path in $G':=G_{t_0}-\{y'_1,y'_2\}$.
\end{proof}



\begin{center}
    \textbf{Potter-linked}
\end{center}

\begin{lemma}\label{Bagel0potter}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Then $(U,W)$ is 0-potter-linked.
\end{lemma}

\begin{proof}
    Let $\{\pi_1,\pi_2\}$ be a balanced bipartition of $S(U,W)$.
    It suffices to find five independent $\hat\pi_1$--$\hat\pi_2$ paths in~$G$.

    Suppose first that $\pi_1=\{x_1,x_2\}$ and $\pi_2=\{y_1,y_2\}$.
    We find two independent $\hat\pi_1$--$\hat\pi_2$ paths $P_1,P_2$ in $G[W]$ using \cref{twoDisjointPathsOutsideBagel,BagelBagAdhesionSet}.
    The torso $H_{t(0)}$ is 3-connected by assumption, and hence it contains three independent $\{x'_1,x'_2\}$--$\{y'_1,y'_2\}$ paths by \allref{Menger}.
    None of these paths use torso-edges, so all three paths are subgraphs of the bag~$G_{t(0)}$.
    The three $\{x'_1,x'_2\}$--$\{y'_1,y'_2\}$ paths can be shortened to three independent $\hat\pi_1$--$\hat\pi_2$ paths $Q_1,Q_2,Q_3$ by \cref{PathShortening}.
    Hence $\pi_1$ is 0-potter-linked to~$\pi_2$.

    Suppose otherwise that $\pi_1=\{x_1,y_1\}$ and $\pi_2=\{x_2,y_2\}$, say.
    We find three independent $\hat\pi_1$--$\hat\pi_2$ paths $P_1,P_2,P_3$ in $G[W] - x'_1 x'_2 - y'_1 y'_2$ using the \allref{ThreePathsBagelLemma}.
    By \cref{bagelTwoPaths}, we find two independent $\{x'_1,y'_1\}$--$\{x'_2,y'_2\}$ paths in the bag $G_{t(0)}$, which shorten to two independent $\hat\pi_1$--$\hat\pi_2$ paths $P_4,P_5$ in $G_{t(0)}$ by \cref{PathShortening}, unless $H_{t(0)}$ is a 4-wheel and both torso-edges $x'_1 x'_2,y'_1 y'_2$ are missing in~$G$.
    But the latter is impossible: since $H_{t(0)}$ is good, some neighbouring torso would be a triangle or a 4-cycle, but then a vertex in the adhesion-set would have degree three in~$G$, contradicting 4-connectivity.
\end{proof}

Assume the \allref{BagelBag}.
We call $x_i$ an \defn{inward edge} if $x_i$ is an edge and $x^W_i=x'_i$; that is, if $x_i$ is an edge with both endvertices in $G_{t(0)}$.
We call $x_i$ an \defn{outward edge} if $x_i$ is an edge but not an inward edge; that is, if the endvertex $x^W_i$ of $x_i$ lies outside of $G_{t(0)}$.

\begin{lemma}\label{bagelInwardEdge}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Assume that $x_1$ is an inward edge.
    Then all of the following hold:
    \begin{enumerate}
        \item\label{bagelInwardEdge1} Some $y'_i$ is a neighbour of $x'_1$ and $y^W_i=y'_i$.
        \item\label{bagelInwardEdge2} $\{x_1,x_2\}$ is not $W$-weird.
    \end{enumerate}
\end{lemma}
\begin{proof}
    \cref{bagelInwardEdge1}.
    Since $H_{t(0)}$ is 3-connected, the vertex $x'_1$ has $\ge 3$ neighbours in $H_{t(0)}$.
    Let $u$ be a neighbour of $x'_1$ in $H_{t(0)}$ distinct from $x'_2$ and the end of the edge $x_1$ besides~$x'_1$.
    All interior vertices of $H_{t(0)}$ are contained in $U\sm W$, so $u\in\{y'_1,y'_2\}$.
    Say $u=y'_1$.
    Assume for a contradiction that $y^W_1\notin H_{t(0)}$.
    Then $x'_1 y'_1$ is a $(W\sm U)$--$(U\sm W)$ edge, so $(U,W)$ violates the matching-condition, a contradiction.

    \cref{bagelInwardEdge2}.
    Assume for a contradiction that $\{x_1,x_2\}$ is $W$-weird.
    Then $x_2=x'_2$ since $x_1$ is an edge by assumption.
    Moreover, $x'_2$ has exactly one neighbour outside $H_{t(0)}$ by weirdness.
    But then $x_2$ should be an edge in $S(U,W)$ by the definition of right-left-shift of $(U',W')$, contradicting that $x_2$ is a vertex.
\end{proof}


\begin{lemma}\label{bagelPotterExtra}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Let $\pi_1:=\{x_1,x_2\}$ and $\pi_2:=\{y_1,y_2\}$.
    Assume that $x_1$ is an outward edge.
    Assume that~$\pi_1$ is $U$-weird.
    Then $x_2=x'_2$ and there is an $x_2$--$\{y'_1,y'_2\}$ edge~$x_2 y_i'$ in~$G$ with~$y_i'=y_i^W$.
\end{lemma}
\begin{proof}
    Since $\pi_1$ is $U$-weird and $x_1$ is an outward edge, we get that $x_2=x'_2$, that $x_2 x'_1$ is an edge, and that $x_2$ has at most one neighbour in $U\sm\{x'_1\}$.
    However, $H_{t(0)}$ is 3-connected, so $x_2$ has some two neighbours $u,v$ in $H_{t(0)}$ besides $x'_1$.
    Hence one of these neighbours, say $v$, is not in $U$.
    Since all interior vertices of $H_{t(0)}$ lie in $U\sm W$, the vertex $v$ must be one of the $y'_i$, say $v=y'_1$.
    Since $v\notin U$, we get that $y_1$ is an inward edge.
    In particular, $y^W_1=y'_1$.
\end{proof}

\begin{lemma}\label{bagelPotterExtra2}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Let $\pi_1:=\{x_1,x_2\}$ and $\pi_2:=\{y_1,y_2\}$.
    Assume that~$\pi_1$ is $W$-weird and~$x_1$ is an outward edge.
    Then no~$y_i$ is an inward edge.
\end{lemma}
\begin{proof}
    Assume otherwise, say~$y_1$ is an inward edge.
    Then by \cref{bagelInwardEdge} we have $y^W_1=y'_1$ and some $x'_j$ is a neighbour of $y^W_1$.
    Then $j\neq 1$ since otherwise $x'_1 y^W_1$ is a $(U\sm W)$--$(W\sm U)$ edge, contradicting the matching-condition.
    So $j=2$.
    Then~$y_1' = y_1^W$ is the only neighbour of~$x_2$ in~$W \sm \{x_1^W\}$.
    It follows that~$x_1^W$ is the only neighbour of~$x_2'$ in~$W' \sm U'$.
    This contradicts that~$x_2$ is a vertex by definition of right-left-shift.
\end{proof}

\begin{lemma}\label{bagel1potterAdhVsAdh}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Let $\pi_1:=\{x_1,x_2\}$ and $\pi_2:=\{y_1,y_2\}$.
    Then $\{\pi_1,\pi_2\}$ is 1-potter-linked.
\end{lemma}
\begin{proof}
    By symmetry, it suffices to show that $\pi_1$ is 1-potter-linked to $\pi_2$.
    If $\pi_1$ is not weird for any side of $(U,W)$, then $\pi_1$ is 1-potter-linked to $\pi_2$ by \ref{itm:1-potter-linked-1}.
    So we may assume that $\pi_1$ is weird for some side; in particular, $x_1$ is an edge and $x_2=x'_2$ is a vertex, say.

    \casen{Case: $x_1$ is an inward edge.}
    By \cref{bagelInwardEdge}, there is a neighbour $y'_i$ of $x'_1$ with $y'_i=y^W_i$, and $\pi_1$ is not $W$-weird.
    So~$\pi_1$ is 1-potter-linked to~$\pi_2$ around~$W$ by \ref{itm:1-potter-linked-1}.
    Since we assumed earlier that $\pi_1$ is weird for some side of $(U,W)$, but showed that $\pi_1$ is not $W$-weird, it follows that $\pi_1$ is $U$-weird.
    By \cref{twoDisjointPathsOutsideBagel}, there exist two disjoint $\{x^W_1,x^W_2\}$--$\{y^W_1,y^W_2\}$ paths in $\bigcup_{t\in O-t(0)}G_t$.
    Since $x_1$ is an inward edge and $y'_i=y^W_i$, the edge $x'_1 y'_i$ can also be written as $x^W_1 y^W_i$.
    This edge together with the two paths forms a set of three independent $\hat\pi_1$--$\hat\pi_2$ paths in $G[W]$, so $\pi_1$ is 1-potter-linked to $\pi_2$ around~$U$ by \ref{itm:1-potter-linked-3}.

    \casen{Case: $x_1$ is an outward edge.}
    If $\pi_1$ is $U$-weird, then we find an $x_2$--$\{y'_1,y'_2\}$ edge $e=x_2 y_i'$ with~$y_i'=y_i^W$ by \cref{bagelPotterExtra}.
    Since $x_2\in\pi_1$ and $y_i'\in\hat\pi_2 \cap W$, the edge $e$ is a $\pi_1$--$(\hat\pi_2 \cap W)$ edge, which witnesses that $\pi_1$ is 1-potter-linked to $\pi_2$ around~$U$ by~\ref{itm:1-potter-linked-2}.
    So it remains to show that $\pi_1$ is 1-potter-linked to~$\pi_2$ around~$W$.
    For this, we assume that~$\pi_1$ is $W$-weird by~\ref{itm:1-potter-linked-1}.
    By \cref{bagelPotterExtra2}, no~$y_i$ is an inward edge.
    Since $H_{t(0)}$ is 3-connected, we find three independent $\{x'_1,x'_2\}$--$\{y'_1,y'_2\}$ paths in $H_{t(0)}$ by \allref{Menger}.
    All three paths are subgraphs of $G[U]$ since no $y_i$ is an inward edge.
    Moreover, they are three $\hat\pi_1$--$\hat\pi_2$ paths in $G[U]$.
    This means $\pi_1$ is 1-potter-linked to $\pi_2$ around~$W$ by \ref{itm:1-potter-linked-3}.
\end{proof}

\begin{lemma}\label{bagel2potterAdhVsAdh}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Let $\pi_1:=\{x_1,x_2\}$ and $\pi_2:=\{y_1,y_2\}$.
    Then $\{\pi_1,\pi_2\}$ is 2-potter-linked.
\end{lemma}
\begin{proof}
    By symmetry and by \cref{obs:weird-no-edges-in-separator}, it suffices to show the following: if $\pi_1$ is $U$-weird and $\pi_2$ is $W$-weird, then there is a $\pi_1$--$\pi_2$ edge in $G$.
    So we assume that $\pi_1$ is $U$-weird and $\pi_2$ is $W$-weird.
    Then no $y_i$ is an inward edge by \cref{bagelInwardEdge}.
    Without loss of generality,~$y_1$ is an outward edge.
    Then by \cref{bagelPotterExtra2}, no~$x_i$ is an inward edge.
    So we can assume that~$x_1$ is an outward edge.
    Then by \cref{bagelPotterExtra}, we find an $x_2$--$\{y'_1,y'_2\}$ edge~$x_2y_i'$ with~$y_i'=y_i^W$.
    Note that $y_i$ is a vertex, so~$y_i'=y_i \in \pi_2$. 
    Then~$x_2y_i'$ is the desired edge.
\end{proof}

\begin{lemma}\label{UWedgeEndsInA}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    If $x_1$ is an edge, then $x^W_1\in A$.
\end{lemma}
\begin{proof}
    Suppose for a contradiction that $x^W_1\in B\sm A$.
    By the \allref{keylem:crossing}, there are no jumping edges and no diagonal edges.
    Then $x_1$ dangles from the $A$-link through the $D$-link.
    Hence the corner $AD$ is potter by the \allref{keylem:crossing}.
    But then $x'_1$ has a neighbour in $D$-link, so $x'_1$ has $\ge 2$ neighbours in $W'\sm U'$, contradicting that $x_1$ is an edge rather than the vertex $x'_1$.
\end{proof}

\begin{lemma}\label{bagelPotterCrossNotWweird}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Then $\{x_1,y_1\}$ is not $W$-weird.
\end{lemma}
\begin{proof}
    Assume for a contradiction that $\{x_1,y_1\}$ is $W$-weird.
    Then $x_1$ is an edge and $y_1=y'_1$ is a vertex, say.

    Assume first that $x_1$ is an inward edge.
    Then $y'_1$ has $\le 1$ neighbour in $W\sm\{x'_1\}\supseteq V(G-G_{t(0)})$.
    But then, by the definition of $(U,W)$ via right-left-shift, $y_1$ should be an edge rather than the vertex $y'_1$, a contradiction.

    Assume otherwise that $x_1$ is an outward edge.
    By \cref{UWedgeEndsInA}, $x^W_1\in A$.
    However, since $y'_1$ is contained in $A\cap C$ and the Tutte-bagel induces a path-decomposition of $G[A]$, the vertex $y'_1=y_1$ does not neighbour $x^W_1$, contradicting that $\{x_1,y_1\}$ is $W$-weird.
\end{proof}

\begin{lemma}\label{bagelPotterCross12}
    Assume the \allref{BagelBag} with $(U,W)$ a tetra-separation.
    Let $\pi_1:=\{x_1,y_1\}$ and $\pi_2:=\{x_2,y_2\}$.
    Then $\{\pi_1,\pi_2\}$ is both 1-potter-linked and 2-potter-linked.
\end{lemma}
\begin{proof}
    By \cref{bagelPotterCrossNotWweird}, neither $\pi_1$ nor $\pi_2$ is $W$-weird.
    Hence $\{\pi_1,\pi_2\}$ is 2-potter-linked.
    It remains to show that $\pi_1$ is 1-potter-linked to $\pi_2$, say.
    Since $\pi_1$ is not $W$-weird, it remains to consider the case where $\pi_1$ is $U$-weird.
    We find three independent $\hat\pi_1$--$\hat\pi_2$ paths in $G[W]$ with the \allref{ThreePathsBagelLemma}.
    Hence $\pi_1$ is 1-potter-linked to $\pi_2$ via \ref{itm:1-potter-linked-3}.
\end{proof}



\begin{keylemma}
    \label{cor:bagel-totally-nested}
    Assume the~\allref{setting:TutteBagel}.
    Then the following two assertions are equivalent for every node $t$ of~$O$:
    \begin{enumerate}
        \item $(U_t,W_t)$ is a totally-nested tetra-separation;
        \item the torso of $\cO$ at $t$ is good.
    \end{enumerate}
\end{keylemma}
\begin{proof}
    If $H_t$ is bad, then $(U_t,W_t)$ is not even a tetra-separation by \cref{GoodBagTetra}, let alone totally-nested.
    So we may assume now that $H_t$ is good.
    In particular, we may assume the \allref{BagelBag} with $t=t(0)$.

    By \cref{GoodBagTetra}, $(U,W)$ is a tetra-separation.
    It suffices to show that $(U,W)$ is externally 5-connected by \cref{keylem:nestedness-external-connectivity}.
    By \cref{BagelHalfconnected}, $(U,W)$ is half-connected.
    To see that $(U,W)$ is 3-linked, we combine \cref{Bagel3linkedAntisym} with \cref{Bagel3linkedSym}.
    By \cref{Bagel0potter}, $(U,W)$ is 0-potter-linked.
    We get that $(U,W)$ is 1-potter-linked and 2-potter-linked from \cref{bagel1potterAdhVsAdh,bagelPotterCross12,bagel2potterAdhVsAdh}.
\end{proof}




\subsection{Splitting stars and torsos}\label{sec:BagelSplitting}


\begin{lemma}\label{BagelMovingCD}
    Assume the \allref{setting:TutteBagel}.
    Let $H_s$ be a torso of $\cO$.
    Assume that $s$ stems from the $AC$-Tutte-path~$T$.
    Assume that the $A$-link is represented by a triangle-torso, and that $s$ is neither equal nor adjacent to the node $o(A)$ in~$O$.
    Then $G_s\se G[C\sm D]$.
\end{lemma}
\begin{proof}
    Let $r$ be the unique neighbour of $o(A)$ in~$T$.
    If $H_r$ is 3-connected or a 4-cycle, then its adhesion sets are disjoint, and we get $G_s\se G[C\sm D]$.
    Otherwise $H_r$ is a triangle.
    The tips of $H_{o(A)}$ and $H_r$ are the two vertices in the adhesion-set of the edge $o(A)r$.
    It follows that the other adhesion-set of $H_r$ is included in $C\sm D$, so $G_s\se G[C\sm D]$.
\end{proof}

\begin{lemma}\label{BagelMovingTip}
    Assume the \allref{setting:TutteBagel}.
    Let $H_s$ be a triangle-torso with tip~$u$.
    Assume that $s$ stems from the $AC$-Tutte-path.
    Assume that $s\neq o(A)$, and that if the $A$-link is represented by a triangle-torso then $s$ is not adjacent to~$o(A)$.
    Then $u$ has no neighbour in the $D$-link.
\end{lemma}
\begin{proof}
    Assume not for a contradiction, and let $v$ be a neighbour of $u$ in the $D$-link.
    Recall that $u\notin D$ by \cref{BagelMovingCD}.
    So the edge $uv$ dangles from the $D$-link through the $A$-link.
    Hence the corner $AD$ is potter by the \allref{keylem:crossing}, and the triangle-torso $H_{o(A)}$ has $uv$ as free edge.
    By assumption, $o(A)$ and $s$ are not adjacent in~$O$.
    By \cref{trianglePath}, there is precisely one torso $H_r$ in between the two triangle-torsos $H_{o(A)}$ and $H_s$, which also contains~$u$.
    But $H_r$ has $u$ as tip since $uv$ is free in $H_{o(A)}$, which by \cref{trianglePath} contradicts that $H_s$ also has $u$ as tip.
\end{proof}




\begin{figure}[ht]
    \centering
    \includegraphics[height=12\baselineskip]{Figures/MovingLinkDetails.pdf}
    \caption{The situation in \cref{BagelMovingLemmaC3C4}.}
    \label{fig:BagelMovingC3C4}
\end{figure}

Let $P$ be a path, and let $u,v$ be vertices on~$P$.
Recall that $uP\mathring v$ denotes the subpath of $P$ that starts at $u$ and ends just before the vertex~$v$.
The statement of the following lemma is supported by \cref{fig:BagelMovingC3C4}.

\begin{lemma}[Link-Moving Lemma for vertices]\label{BagelMovingLemmaC3C4}
    Assume the \allref{setting:TutteBagel}.
    Let $P$ and $Q$ be the two paths that are the two components of $O-o(C)-o(D)$.
    Assume that $o(A)\in P$ and $o(B)\in Q$.
    Let $c$ denote the end of $P$ that is adjacent or incident to $o(C)$ in~$O$.
    Define $d$ similarly.
    Let $s$ be a node in the same component of $P-o(A)$ as $c$ such that $H_s$ is a 4-cycle or a triangle.
    Assume that if the $A$-link is represented by a triangle-torso, then $s$ is not adjacent to $o(A)$ in~$P$.
    Let $P':=dP\mathring{s}$ and $Q':=\mathring{s}Pc\cup Q$.
    Then:
    \begin{enumerate}
        \item\label{BagelMovingLemmaC3C4_1} $A':=\bigcup_{t\in V(P')}V(G_t)$ and $B':=\bigcup_{t\in V(Q')}V(G_t)$ are the two sides of a tetra-separation of~$G$.
        \item\label{BagelMovingLemmaC3C4_2} $S(A',B')=S\cup (D$-link$)$, where $S$ consists of the two free edges of $H_s$ if $H_s$ is a 4-cycle and of the free edge and the tip of $H_s$ if $H_s$ is a triangle.
        \item\label{BagelMovingLemmaC3C4_3} $(A',B')$ separates some two vertices in $B\cup D$.
    \end{enumerate}
\end{lemma}



\begin{proof}
    \cref{BagelMovingLemmaC3C4_2} holds by construction, and gives that the mixed-separation $(A',B')$ has order four.
    We show \cref{BagelMovingLemmaC3C4_1} next.

    \casen{Matching-condition.}
    Let $ab$ be an edge in the $D$-link with $a\in A\sm B$ and $b\in B\sm A$.
    Let $f$ be an edge in~$S$.
    Assume for a contradiction that $ab$ and $f$ share an endvertex, which can only be~$a$.
    Since $a\in (A\sm B)\cap D$ and $V(G_s)\se A\cap C$, we find that $a$ is in the $A$-link.
    So $ab$ dangles from the $A$-link through the $D$-link.
    Then the corner~$AD$ is potter by the \allref{keylem:crossing}.
    Thus the $A$-link
    is represented by a triangle-torso, so $a\notin D$ by \cref{BagelMovingCD}, a contradiction.

    \casen{Degree-condition.} 
    It is straightforward to check that every vertex in $S(A',B')$ has $\ge 2$ neighbours in $B'\sm A'$.
    Now let $v\in S(A',B')$ be a vertex; we claim that it has $\ge 2$ neighbours in $A'\sm B'$.
    If $v$ is in $S$, then $H_s$ is a triangle with tip $v$.
    Let $H_r$ denote the torso neighbouring $H_s$ in the direction of $o(A)$ on the path~$P$.
    If $H_r$ is 3-connected, then $v$ has two neighbours in $G_r$, both of which lie in $A'\sm B'$ since $G_s\se G[A\cap C]$.
    Otherwise $H_r$ is a triangle, and the adhesion-graph in between $H_r$ and $H_s$ is a $K_2$-subgraph of~$G$ by \cref{TutteBagelObservations}.
    Hence $v$ has two neighbours in $G_r$, both of which lie in $A'\sm B'$ since $r\neq o(A)$ by assumption.
    So we may assume next that $v$ lies in the $D$-link.
    Every neighbour of $v$ in $A\sm B$ also lies in $A'\sm B'$, except possibly when a neighbour of $v$ lies in $S$ or an edge incident to $v$ lies in $S$.
    The former exception is impossible by \cref{BagelMovingTip}, while the latter is excluded by \cref{BagelMovingCD}.
    This conclude the proof of \cref{BagelMovingLemmaC3C4_1}.

    \cref{BagelMovingLemmaC3C4_3}.
    We have to find two vertices in $B\cup D$ that are contained in $A'\sm B'$ and in $B'\sm A'$, respectively.
    Every vertex in $B\sm A$ lies in the intersection of $B\cup D$ with $B'\sm A'$, and $B\sm A$ is non-empty.
    Any vertex in $D\sm B$ lies in $A'\sm B'$ by \cref{BagelMovingCD}, so it remains to show that $D\sm B$ is non-empty.
    If $D\sm B$ is empty, then the $D$-link consists of two edges.
    But both these edges have ends in the corner for~$AD$ by the \allref{keylem:crossing}, a contradiction.
\end{proof}


\begin{lemma}[Link-Moving Lemma for edges]\label{BagelMovingLemma33}
    Assume the \allref{setting:TutteBagel}.
    Let $P$ and $Q$ be the two paths that are the two components of $O-o(C)-o(D)$.
    Assume that $o(A)\in P$ and $o(B)\in Q$.
    Let $c$ denote the end of $P$ that is adjacent or incident to $o(C)$ in~$O$.
    Define $d$ similarly.
    Let $e$ be an edge of $O$ such that the torsos at the ends of $e$ are 3-connected.
    Assume that $e$ stems from the $AC$-Tutte-path.
    Let $P':=dP\mathring{e}$ and $Q':=\mathring{e}Pc\cup Q$.
    Then:
    \begin{enumerate}
        \item\label{BagelMovingLemma33_1} $A':=\bigcup_{t\in V(P')}V(G_t)$ and $B':=\bigcup_{t\in V(Q')}V(G_t)$ are the two sides of a tetra-separation of~$G$.
        \item\label{BagelMovingLemma33_2} $S(A',B')=\pi\cup (D$-link$)$, where $\pi$ is the adhesion-set of $ac$.
        \item\label{BagelMovingLemma33_3} $(A',B')$ separates some two vertices in $B\cup D$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    The proof is analogous to the proof of \cref{BagelMovingLemmaC3C4}, except that everything is straightforward because the two 3-connected torsos at the ends of $e$ both have disjoint adhesion-sets and have all their vertices contained in $A\cap C$.
\end{proof}









\begin{lemma}\label{RightUWchar}
    Assume the \allref{setting:TutteBagel}.
    Let $i:=1$ if $H_{t(1)}$ is 3-connected, and $i:=2$ otherwise.
    Similarly, let $j:=-1$ if $H_{t(-1)}$ is 3-connected, and $j:=-2$ otherwise.
    The right-shift of $(U'_t,W'_t)$ has sides
    \[
        V(G_{t(0)})\quad\text{and}\quad \bigcup\,\{\,V(G_{t(\ell)}):i\le\ell\le j\text{ in the cyclic ordering of }\Z_{m+1}\,\}.
    \]
\end{lemma}
\begin{proof}
    This is just a different perspective on \cref{BagelBagAdhesionSet}.
\end{proof}




\begin{definition}[Tetra-star $\sigma(\cO)$]
    Assume the \allref{setting:TutteBagel}.
    The \defn{tetra-star} of $\cO$ is the set of all $(U_t,W_t)$ for good torsos $H_t$ of~$\cO$.
    We denote the tetra-star of $\cO$ by $\defnMath{\sigma(\cO)}$.
\end{definition}





\begin{lemma}\label{BagelInterlaceRightShift}
    Assume the \allref{setting:TutteBagel}.
    Let $(E,F)$ be a totally-nested tetra-separation of $G$ that interlaces $\sigma$.
    Then there is a 3-connected torso $H_t$ of~$\cO$ such that $(E,F)\le (U''_t,W''_t)$ or $(F,E)\le (U''_t,W''_t)$, where $(U''_t,W''_t)$ denotes the right-shift of $(U'_t,W'_t)$.
\end{lemma}
\begin{proof}
    Since $(E,F)$ is totally-nested, we have $(E,F)\le (A,B)$ and $(E,F)\le (C,D)$, say. In particular, $E\se A\cap C$.
    Let $\beta$ denote the $AC$-banana, and let $(T,\cV)$ denote the $AC$-Tutte-banana.

    An element $x\in V(T)\cup E(T)$ is \defn{admissible} if
    \begin{itemize}
        \item $x$ is an edge with 3-connected torsos at its end-nodes; or
        \item $x$ is an interior node of $T$ with a triangle or 4-cycle as torso.
    \end{itemize}
    A mixed-1-separation $(M,N)$ of $T$ is \defn{admissible} if the vertex or edge in $S(M,N)$ is admissable.
    The \defn{$\beta$-lift} of an admissible $(M,N)$ is
    \begin{itemize}
        \item $(\bigcup_{t\in M}V_t,\bigcup_{t\in N}V_t)$ if $S(M,N)$ consists of an edge, and
        \item $(\bigcup_{t\in M\sm N}V_t,\bigcup_{t\in N\sm M}V_t)$ if $S(M,N)$ consists of a vertex.
    \end{itemize}
    Note that the $\beta$-lift is a mixed-2-separation of the banana~$\beta$.
    A \defn{$G$-lift} of an admissible $(M,N)$ is a tetra-separation of $G$ that induces the $\beta$-lift of $(M,N)$ on~$\beta$ and separates some two vertices in~$F$. 

    We claim that:
    \begin{equation}\label{eq:GliftsExist}
        \textit{Every admissible $(M,N)$ has a $G$-lift.}
    \end{equation}
    Given an admissible $(M,N)$, let $x$ denote the element of its separator.
    If $x$ is an edge, then the \allref{BagelMovingLemma33} produces a $G$-lift.
    So we may assume that $x$ is an interior node of $T$.
    Let $T'$ be obtained from $T$ by removing any endvertex with a triangle or 4-cycle torso that represents a link.
    Any vertex removed in this way is not admissible, and neither is its incident edge in~$T$.
    Hence $x\in T'$.



    Let us show that $x$ is not the only vertex of~$T'$.
    Otherwise the torso $H_x$ is a triangle or 4-cycle.
    By \cref{BagelLinkForm}, $H_x$ is a triangle and both the $A$-link and the $C$-link are represented by triangle-torsos.
    In particular, $A\cap C=3$.
    But $E$, as a side of a tetra-separation, has size $\ge 4$, and $E$ is included in $A\cap C$, a contradiction.
    So $x$ is not the only vertex of~$T'$.

    Let $y$ be an endvertex of $T'$ that is distinct from~$x$.
    By symmetry, we may assume that $y$ is adjacent or incident to $o(A)$ when viewed as a node of~$O$.
    Then the \allref{BagelMovingLemmaC3C4} produces a $G$-lift.
    This concludes the proof that \cref{eq:GliftsExist} holds.

    For every admissible $(M,N)$ we use \cref{eq:GliftsExist} to choose a $G$-lift $(\bar M,\bar N)$ so that for $(N,M)$ we choose $(\bar N,\bar M)$.
    We claim that exactly one of $E\se \bar M$ and $E\se\bar N$ holds, for all~$(M,N)$.
    Indeed, otherwise $(\bar M,\bar N)$ separates~$E$, and since it also separates~$F$ by definition, $(\bar M,\bar N)$ crosses $(E,F)$, a contradiction.
    We let
    \begin{align*}
        \omega &{}:=\{\,(M,N):(M,N)\text{ is admissable and }\bar N\supseteq E\,\}\\
        \Omega&{}:=\bigcap\,\{\,N\sm M:(M,N)\in\omega\,\}\cap V(T').
    \end{align*}
    We claim that $\Omega\neq\emptyset$.
    Assume for a contradiction that $\Omega$ is empty.

    Suppose first that $\omega$ is empty.
    Then $V(T')$ is empty.
    Hence $T$ is a $K_2$ both whose endvertices have triangle or 4-cycle torsos that represent links.
    By \cref{TutteBagelObservations}, both torsos are triangles.
    Hence the corner $AC$ is potter, so $A\cap C=2$, contradicting that $E\se A\cap C$ where $E$ has size~$\ge 4$.

    Suppose otherwise that $\omega$ is non-empty.    
    So $\omega$ has one or two maximal elements.
    Assume first that $\omega$ has a unique maximal element $(M,N)$.
    Since $\Omega$ is empty but $N\sm M$ is not, $N\sm M$ must consist of an end of $T$ that misses in $T'$.
    Hence $N\sm M=\{o(C)\}$, say, and the unique element $x$ of $S(M,N)$ is not an edge.
    So $x$ is a neighbour of $o(C)$, and both $x$ and $o(C)$ have a triangle or 4-cycle as torso.
    Hence $\bar N\cap A$ equals the adhesion-set of the edge $x o(C)$, contradicting that $E$ has size $\ge 4$ and $E\se \bar N\cap A$.

    Assume otherwise that $\omega$ has two maximal elements $(M_1,N_1)$ and $(M_2,N_2)$.
    Let $x_i$ denote the unique element of $S(M_i,N_i)$ for both~$i$.
    We claim that both $x_i$ are vertices.
    Otherwise $x_1$ is an edge, say.
    Then both endvertices of $x_1$ have 3-connected torsos.
    Hence $x_2$ cannot be an endvertex of~$x_1$.
    Therefore, an endvertex of $x_1$ is in $\Omega$, a contradiction.
    So both $x_i$ are vertices.
    Since $\Omega$ is empty, the vertices $x_i$ are neighbours.
    Hence $E$ is included in the adhesion-set of $x_1 x_2$, contradicting that $E$ has size~$\ge 4$.
    Thus $\Omega\neq\emptyset$.

    Every node in $\Omega$ has a 3-connected torso in~$\cO$.
    Since $\Omega$ spans a subpath of~$T$ that contains no admissible edges, we have $|\Omega|=1$.
    Hence $\Omega$ consists of exactly one node $t^*$, and its torso $H_{t^*}$ is 3-connected.

    To show that $(E,F)\le$ the right-shift of $(U'_t,W'_t)$, by \cref{RightUWchar} and \cref{Righty} it remains to show $E\se V(G_{t^*})$.
    Assume for a contradiction that there is a vertex $v\in E\sm V(G_{t^*})$.
    Recall that $E\se A\cap C$, so in particular $E\se V(\beta)$.
    Hence there is a node $s$ of $T$ with $v\in V_s$, and $s\neq t^*$ by assumption.
    Let $r$ be the penultimate node on the path $s T t^*$.

    Assume first that the torso $H_r$ is 3-connected.
    Then the edge $rt^*$ is admissible.
    Let $(M,N)\in\omega$ with $S(M,N)=\{rt^*\}$.
    Note that $r\in M\sm N$ and $t^*\in N\sm M$ since $\{t^*\}=\Omega$.
    Let $(\hat M,\hat N)$ be the $\beta$-lift of $(M,N)$.
    Observe that $v\in\hat M\sm\hat N$.
    Therefore, $v\in\bar M\sm \bar N$, contradicting that $E\se\bar N$.

    Assume otherwise that the torso $H_r$ is either a triangle or a 4-cycle.
    Then $r$ is admissible or $r$ is one of $o(A)$ and $o(C)$.
    Assume first that $r$ is admissible.
    Let $(M,N)\in\omega$ with $S(M,N)=\{r\}$.
    Note that $r,s\in M$ and $t^*\in N\sm M$.
    Let $(\hat M,\hat N)$ be the $\beta$-lift of $(M,N)$.
    Then $v\in\hat M\sm\hat N$, so $v\in \bar M\sm \bar N$, contradicting that $E\se\bar N$.
    Assume otherwise that $r=o(A)$, say.
    Then $H_r$ is a triangle or 4-cycle representing the $A$-link.
    Since $v$ does not lie in $H_{t^*}$, we in particular have that $v$ does not lie in the adhesion-set of the edge $rt^*$.
    But then $v$ lies in $D\sm C$, contradicting that $E\se C$.
\end{proof}

\begin{lemma}\label{BagelSplittingStar}
    Assume the \allref{setting:TutteBagel}.
    Every tetra-separation of $G$ that interlaces the tetra-star $\sigma$ of $\cO$ is crossed.
\end{lemma}
\begin{proof}
    Assume for a contradiction that $\sigma$ is interlaced by a totally-nested tetra-separation $(E,F)$ of~$G$.
    By \cref{BagelInterlaceRightShift}, there is a 3-connected torso $H_t$ of~$\cO$ such that $(E,F)\le (U''_t,W''_t)$, say, where $(U''_t,W''_t)$ denotes the right-shift of $(U'_t,W'_t)$.

    Assume first that $H_t$ is good.
    Then $(U_t,W_t)$ is a totally-nested tetra-separation by \cref{cor:bagel-totally-nested}.
    In particular, $(U_t,W_t)\in\sigma$.
    Since $(E,F)$ interlaces $\sigma$, we have one of $(U_t,W_t)<(E,F)$ and $(U_t,W_t)<(F,E)$.
    We cannot have $(U_t,W_t)<(F,E)$, since otherwise $\emptyset\neq  E\sm F\se (W_t\sm U_t)\cap (U''_t\sm W''_t)$ contradicts the fact that $U''_t\sm W''_t\se U_t\sm W_t$ by \cref{obs:shift-maintains-proper-sides}.
    Hence $(U_t,W_t)<(E,F)\le (U''_t,W''_t)$.
    Since $(U_t,W_t)$ is the left-shift of $(U''_t,W''_t)$, some vertex in $S(E,F)$ must have $\le 1$ neighbour in $E\sm F$, contradicting the degree-condition.

    Assume otherwise that $G_t$ is bad.
    Hence $G_t$ has four or five vertices.
    If $H_t$ has four vertices, then all but at most one of the four vertices in $S(U'_t,W'_t)$ has $\ge 2$ neighbours in $W'_t\sm U'_t$.
    If $H_t$ has five vertices, then all four vertices in $S(U'_t,W'_t)$ have $\ge 2$ neighbours in $W'_t\sm U'_t$.
    In either case, we have $|U''_t\sm W''_t|\le 1$.
    Since $(E,F)\le (U''_t,W''_t)$, we have $E\sm F\se U''_t\sm W''_t$.
    Therefore, $|E\sm F|\le 1$, which by \cref{leftDegreeStrongerMatching} contradicts that $(E,F)$ is a tetra-separation.
\end{proof}



\begin{keylemma}\label{bagelTorso}
    Let $G$ be a 4-connected graph, and let $N$ denote the set of totally-nested tetra-separations of~$G$.
    Let $\sigma$ be a splitting star of~$N$ that is interlaced by two tetra-separations $(A,B)$ and $(C,D)$ of $G$ that cross with empty vertex-centre.
    Then the torso $\tau$ of $\sigma$ is a cycle of triangle-torsos and 3-connected torsos on $\le 5$ vertices.
\end{keylemma}

\begin{proof}
    By the \allref{keylem:crossing}, all links have size two.
    By \cref{lem:really-is-Tutte-bagel}, $(A,B)$ and $(C,D)$ induce a Tutte-bagel~$\cO$.
    By \cref{cor:bagel-totally-nested}, the tetra-star $\sigma(\cO)$ is a star of totally-nested tetra-separations of~$G$.
    By \cref{BagelSplittingStar}, the tetra-star $\sigma(\cO)$ is a splitting star of~$N$.
    Since both $(A,B)$ and $(C,D)$ interlace both $\sigma$ and $\sigma(\cO)$, we obtain $\sigma=\sigma(\cO)$.
    Hence it remains to compute the torso $\tau$ of $\sigma(\cO)$.
    The torso $\tau$ is 4-connected by \cref{dotTorso4con}.
    We can obtain $\tau$ from $\cO$ by replacing each good torso with a $K_4$, leaving only 3-connected torsos with five or four vertices, and contracting some free edges in torsos that are 4-cycles or triangles.
    Each torso that is a 4-cycle neighbours two 3-connected torsos by \cref{TutteBagelObservations}, and the 4-cycle-torso witnesses that both 3-connected torsos are good.
    Hence the free edges of the 4-cycle-torsos are contained in the separators of the elements of $\sigma(\cO)$ that stem from the good neighbouring torsos, and so they are contracted.
    Hence $\tau$ is a cycle of triangle-torsos and 3-connected torsos on $\le 5$ vertices.
\end{proof}

\subsection{Angry Tutte-bagels}\label{sec:BagelAngry}

Let $G$ be a 4-connected graph with a Tutte-bagel $\cO=(O,\cG)$.
A \defn{triangle-strip} of $\cO$ is a maximal connected subgraph $\Delta$ of $O$ such that every node in $\Delta$ has a triangle-torso with regard to~$\cO$.
Phrased differently, a triangle-strip is a component of 
\[
    O[\,\{t\in V(O):t\text{ has a triangle-torso}\}\,].
\]
Triangle-strips are paths unless all torsos of $O$ are triangles.
An element of $V(O)\cup E(O)$ is \defn{furious} if either
\begin{itemize}
    \item it is an edge with 3-connected torsos at both ends, or
    \item it is a vertex with a 4-cycle as torso.
\end{itemize}
We define
\[
    \defnMath{\alpha(\cO)}:=\#(\text{furious edges and vertices of }\cO)+\sum_\Delta\left\lceil\tfrac{2}{3}|\Delta|\right\rceil
\]
where the sum ranges over all triangle-strips $\Delta$ of $\cO$.

\begin{lemma}\label{CrossedBagelsAngryFactor}
    Assume the \allref{setting:TutteBagel}.
    Then $\alpha(\cO)\ge 4$.
\end{lemma}
\begin{proof}
    The four links injectively correspond to furious edges or vertices or nodes in triangle-strips.
    Hence it suffices to show that there is no path $rst$ in $O$ with all three nodes $r,s,t$ having triangle-torsos representing links.
    Assume otherwise.
    Then two adjacent corners are potter, contradicting \cref{obs:potter-adjacent-corner}.
\end{proof}


\begin{lemma}\label{AngryFactorYieldsCrossed}
    Let $G \neq K_5$ be a 4-connected graph with a Tutte-bagel $\cO=(O,\cG)$ such that all torsos of $\cO$ are bad and $\alpha(\cO)\ge 4$.
    Then $G$ has two tetra-separations that cross with all links of size two.
\end{lemma}
\begin{proof}
    We claim that we can select four elements $x(i)$ of $V(O)\cup E(O)$, where $i\in\Z_4$, such that
    \begin{itemize}
        \item every selected element is furious or belongs to some triangle-strip;
        \item no three consecutive nodes are chosen from any triangle-strip.
    \end{itemize}
    If all torsos of~$\cO$ are triangles, then we use~$|O| \geq 6$, which we have since~$G \neq K_5$ and $\alpha(\cO) \geq 4$. Otherwise, we use $\alpha(\cO) \geq 4$ and that the triangle-strips of~$\cO$ are induced paths in~$O$.

    We may assume that $O$ traverses the $x(i)$ in the cyclic ordering of $\Z_4$.
    Let $P_A,P_B$ denote the components of $O-x(0)-x(2)$, let $A:=\bigcup_{t\in V(P_A)}V(G_t)$ and define $B$ similarly.
    We use $x(1),x(3)$ to define $P_C,P_D$ and $C,D$ analogously.

    We define $S(i)$ for $i\in\Z_4$ to consist of
    \begin{itemize}
        \item the two vertices in the adhesion-set of $x(i)$ if $x(i)$ is a furious edge;
        \item the two free edges of the 4-cycle-torso at $x(i)$ if $x(i)$ is a furious vertex;
        \item the tip and the free edge of the triangle-torso at $x(i)$ if $x(i)$ stems from a triangle-strip.
    \end{itemize}

    We claim that $(A,B)$ and $(C,D)$ are tetra-separations with separators
    $S(A,B)=S(0)\cup S(2)$ and $S(C,D)=S(1)\cup S(3)$.
    By symmetry, it suffices to show that
    \begin{enumerate}
        \item\label{vxTech} every vertex in $S(0)$ has $\ge 2$ neighbours in $A\sm B$, and
        \item\label{edgeTech} every edge in $S(0)$ has an end in $A\sm B$ avoiding $\widehat{S(2)}$.
    \end{enumerate}
    For this, let $t(1),t(2),t(3)$ denote the first three vertices on $P_A$ that come just after $x(0)$ on~$O$.

    \casen{Case: $x(0)$ is a furious vertex.}
    So $H_{x(0)}$ is a 4-cycle and $S(0)$ consists of two edges, and we only have to show \cref{edgeTech}.
    The neighbouring torso $H_{t(1)}$ must be 3-connected by \cref{TutteBagelObservations}, so the adhesion-set of $x(0)t(1)$ is included in $A\sm B$ and avoids $\widehat{S(2)}$.
    Hence \cref{edgeTech} holds.

    \casen{Case: $x(0)$ is a furious edge.}
    Then $S(0)$ is the adhesion-set of the edge $x(0)$, and we only have to show \cref{vxTech}.
    Note that $t(1)$ is an end of $x(0)$, so the torso $H_{t(1)}$ is 3-connected.
    Let $U:=V(H_{t(1)}-S(0))$.
    Every vertex in $S(0)$ has two neighbours in $G$ that are contained in $U$.
    To ensure that these neighbours lie in $A\sm B$, it suffices to show that the adhesion-set $\pi$ of $t(1)t(2)$ is included in $A\sm B$.
    Since $t(1) t(2)$ is the first candidate for $x(1)$, with $x(2)$ coming later, $\pi$ can only meet $B$ if $H_{t(2)}$ is a triangle.
    But then $t(2)$ is the first candidate for $x(1)$, so $x(2)$ comes after $t(2)$.
    If $H_{t(3)}$ is not a triangle, we are done, and otherwise the tip of the triangle $H_{t(3)}$ avoids $\pi$ by \cref{trianglePath}.
    Hence $\pi\se A\sm B$ as desired.

    \casen{Case: $x(0)$ is in a triangle-strip.}
    Assume first that $H_{t(1)}$ is 3-connected.
    Since $H_{t(1)}$ is bad and neighboured by the triangle-torso $H_{x(0)}$, its other neighbouring torso $H_{t(2)}$ must be 3-connected.
    Hence the edge $t(1)t(2)$ is the first candidate for $x(1)$, and so the edge $t(2)t(3)$ is the first candidate for $x(2)$.
    Therefore, the entire vertex-set of $H_{t(1)}$ is included in $A\sm B$, which ensures \cref{vxTech} and \cref{edgeTech}.

    Assume otherwise that $H_{t(1)}$ is a triangle.
    Let $\pi$ denote the adhesion-set of the edge $t(1)t(2)$.
    Note that $\pi$ contains an end of the free edge in $S(0)$ and both vertices in $\pi$ are neighbours of the tip of the triangle $H_{x(0)}$.
    Hence to show both \cref{vxTech} and \cref{edgeTech}, it suffices to show that $\pi$ is included in $A\sm B$.
    The node $t(1)$ is the first candidate for $x(1)$, so $t(2)$ is the first candidate for $x(2)$.
    By \cref{TutteBagelObservations}, $H_{t(2)}$ is either a triangle or 3-connected.
    If $H_{t(2)}$ is 3-connected, then $\pi$ is included in $A\sm B$.
    Otherwise $H_{t(2)}$ is a triangle.
    Then $H_{x(0)}$, $H_{t(1)}$ and $H_{t(2)}$ are three consecutive triangles.
    The way we have selected the $x(i)$ then ensures that $x(2)$ comes after $t(2)$.
    Again, $H_{t(3)}$ is either a triangle or 3-connected. If $H_{t(3)}$ is 3-connected, then $\pi$ is included in $A\sm B$. Otherwise, if $H_{t(3)}$ is a triangle, then its tip is distinct from the tip of $H_{t(2)}$ by \cref{trianglePath}, and $t(3)$ is the first candidate for~$x(2)$.
    So $\pi$ is included in $A\sm B$.

    This completes the proof of \cref{vxTech} and \cref{edgeTech}.
    Hence $(A,B)$ and $(C,D)$ are tetra-separations with $S(A,B)=S(0)\cup S(2)$ and $S(C,D)=S(1)\cup S(3)$.
    The tetra-separations $(A,B)$ and $(C,D)$ cross with all links of size two as the links are precisely the four non-empty sets $S(i)$.
\end{proof}

\begin{keylemma}\label{AngryBagel}
    Let $G$ be a 4-angry graph.
    Then the following two assertions are equivalent:
    \begin{enumerate}
        \item\label{AngryBagel1} $G$ has two tetra-separations that cross with all links of size two;
        \item\label{AngryBagel2} $G\neq K_5$ and $G$ has a Tutte-bagel $\cO$ with $\alpha(\cO)\ge 4$ all whose torsos are bad.
    \end{enumerate}
\end{keylemma}
\begin{proof}
    \cref{AngryBagel1} $\Rightarrow$ \cref{AngryBagel2}.
    Clearly,~$G \neq K_5$ since~$K_5$ does not have a tetra-separation.
    By \cref{lem:really-is-Tutte-bagel}, $(A,B)$ and $(C,D)$ induce a Tutte-bagel~$\cO$.
    By \cref{cor:bagel-totally-nested}, the tetra-star $\sigma(\cO)$ is a star of totally-nested tetra-separations of~$G$.
    Since $G$ has no totally-nested tetra-separations by assumption,
    all torsos of $\cO$ are bad.
    We get $\alpha(\cO)\ge 4$ from \cref{CrossedBagelsAngryFactor}.

    \cref{AngryBagel2} $\Rightarrow$ \cref{AngryBagel1} is \cref{AngryFactorYieldsCrossed}.
\end{proof}



\section{Quasi-5-connected torsos}\label{sec:Quasi5con}

This section deals with the quasi-5-connected outcome of \cref{MainDecomp}; see \cref{Quasi5conSummary}.

A mixed-separation\pl\ $(A,B)$ of a graph $G$ \defn{almost interlaces} a star $\sigma$ of mixed-separations\pl\ of $G$ if $(C,D)\le (A,B)$ or $(C,D)\le (B,A)$ for all $(C,D)\in\sigma$.
The difference between `interlaces' and `almost interlaces' is `$<$' versus `$\le$' in the definitions.

\begin{lemma}\label{HyperLiftProperties}
    \textnormal{(Analogue of \cite[Lemma~2.6.7]{Tridecomp})}
    Let $G$ be a 4-connected graph.
    Let $\sigma$ be a star of mixed-4-separations of $G$ satisfying the matching-condition.
    Let $(A,B)$ be a separation of the torso $\tau$ of~$\sigma$.
    Then there exists a mixed-separation $(\hat A,\hat B)$ of~$G$ such that:
    \begin{enumerate}
        \item\label{HyperLiftProperties1} the order of $(\hat A,\hat B)$ is at most the order of $(A,B)$;
        \item\label{HyperLiftProperties2} $(\hat A,\hat B)$ almost interlaces~$\sigma$;
        \item\label{HyperLiftProperties3} $|\hat A\sm\hat B|\ge |A\sm B|$ and $|\hat B\sm\hat A|\ge |B\sm A|$; and
        \item\label{HyperLiftProperties4} for every $(U,W)\in\sigma$ we have $|W\cap (\hat A\sm\hat B)|\ge |A\sm B|$ and $|W\cap (\hat B\sm\hat A)|\ge |B\sm A|$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    The proof is the same as the proof of \cite[Lemma~2.6.7]{Tridecomp}, with one exception: we replace Lemma~1.2.3 with the matching-condition.
\end{proof}


\begin{lemma}\label{tetraShield}
    Let $(A,B)$ be a tetra-separation in a 4-connected graph~$G$.
    Let $(C,D)$ be a mixed-4-separation\pl\ in $G$ with $(A,B)\le (C,D)$.
    Let $(C',D')$ denote either the left-right-shift or the right-left-shift of $(C,D)$.
    Then $(A,B)\le (C',D')$.
\end{lemma}
\begin{proof}
    We have $B\supseteq D\supseteq D'$.
    Since $A\se C$, it remains to show that every vertex in $S(C,D)\cap A$ also lies in $S(C',D')$.
    Every vertex $v$ in $S(C,D)\cap A$ also lies in $S(A,B)$.
    Hence every such $v$ has $\ge 2$ neighbours in $A\sm B\se C\sm D$.
    Thus $v\in S(C',D')$.
\end{proof}

\begin{lemma}\label{technicalInterlaces}
    Let $G$ be a 4-connected graph.
    Let $(U,W)$ be a tetra-separation of~$G$, and let $(A,B)$ be a mixed-4-separation of~$G$ such that $(U,W)\le (A,B)$.
    Suppose that $|W\cap (A\sm B)|\ge 1$.
    Let $(A',B')$ be either the left-right-sift or the right-left-shift of $(A,B)$.
    Then $(U,W)<(A',B')$.
\end{lemma}
\begin{proof}
    We have $(U,W)\le (A',B')$ by \cref{tetraShield}.
    Recall that $A\sm B\se A'\sm B'$ by \cref{obs:reduction-maintains-proper-sides}.
    Hence $W\cap (A'\sm B')$ is nonempty, so in particular the inclusion $W\supset B'$ is proper.
\end{proof}

\begin{lemma}\label{big4sepInterlaces}
    Let $G$ be a 4-connected graph.
    Let $\sigma$ be a star of tetra-separations of~$G$.
    Suppose that the torso $\tau$ of $\sigma$ has a 4-separation $(A,B)$ such that both sides have size~$\ge 6$.
    Then $\sigma$ is interlaced by a tetra-separation of~$G$.
\end{lemma}
\begin{proof}
    By \cref{HyperLiftProperties}, there is a mixed-$k$-separation\pl\ $(\hat A,\hat B)$ of $G$ such that
    \begin{itemize}
        \item $k\le 4$ by \cref{HyperLiftProperties1};
        \item $(\hat A,\hat B)$ almost interlaces $\sigma$ by \cref{HyperLiftProperties2};
        \item $|\hat A\sm\hat B|\ge 2$ and $|\hat B\sm\hat A|\ge 2$ by \cref{HyperLiftProperties3}; and
        \item for every $(U,W)\in\sigma$ we have $|W\cap (\hat A\sm \hat B)|\ge 2$ and $|W\cap (\hat B\sm\hat A)|\ge 2$ by \cref{HyperLiftProperties4}.
    \end{itemize}
    Since $G$ is 4-connected, $(\hat A,\hat B)$ is a mixed-4-separation by \cref{kConMixed}.
    Let $(\bar A,\bar B)$ denote the left-right-shift of $(\hat A,\hat B)$.
    Then $(\bar A,\bar B)$ is a tetra-separation by \cref{leftrightTetra}.
    By \cref{technicalInterlaces}, $(\bar A,\bar B)$ interlaces~$\sigma$.
\end{proof}


\begin{keylemma}\label{Quasi5conSummary}
    Let $G$ be a 4-connected graph, and let $N$ denote the set of totally-nested tetra-separations of~$G$.
    Let $\sigma$ be a splitting star of~$N$ that is not interlaced by any tetra-separation of~$G$.
    Then the torso $\tau$ of $\sigma$ is quasi-5-connected.
\end{keylemma}
\begin{proof}
    By \cref{dotTorso4con}, $\tau$ is 4-connected or a $K_4$, and we are done in the latter case.
    By the contrapositive of \cref{big4sepInterlaces}, every 4-separation of $\tau$ has a side of size five.
\end{proof}



\section{An Angry Theorem for 4-connectivity}\label{sec:Angry}

A key step in proving Tutte's decomposition theorem is to characterise the graphs that are \defn{2-angry}: those that are 2-connected and all whose 2-separators are crossed -- hence the name.
Tutte proved the first \emph{angry theorem}: the 2-angry graphs are precisely the 3-connected graphs and the cycles~\cite{TutteCon}.
For a modern proof, see \cite[Theorem 3.3.4]{Tridecomp}.
An angry theorem for 3-connectivity has been proved using tri-separations \cite[Theorem 1.1.5]{Tridecomp}.
However, like here, the angry theorem was not used in the proof of the decomposition theorem.
Still, angry theorems have recently found an application in group theory: 
the local version of the 2-angry theorem \cite{Local2sep} was used as a key ingredient in \cite{StallingsNilpotent}, and versions for higher connectivity are expected to be needed to continue in the direction of \cite{StallingsNilpotent}.
Here we prove an angry theorem for 4-connectivity.
A graph $G$ is \defn{4-angry} if it is 4-connected and every tetra-separation of $G$ is crossed by a tetra-separation.

\begin{theorem}[Angry Theorem for 4-connectivity]\label{4angry}
    A 4-connected graph $G$ with $|G|\ge 8$ is 4-angry if and only if it is one of the following:
    \begin{enumerate}
        \item\label{4angry1} quasi-5-connected;
        \item\label{4angry3} a cycle $\cO$ of triangles, 4-cycles, 3-connected graphs on $\le 5$ vertices, with only bad torsos and $\alpha(\cO)\ge 4$;
        \item\label{4angry2} a double-wheel with rim of length~$\geq 4$ or a double-wheel of triangles with rim of length~$\geq 4$;
        \item\label{4angry4} a sprinkled $K_{4,m}$ with $m\ge 4$.
    \end{enumerate}
\end{theorem}
\begin{proof}
    \casen{Forward implication.}
    Assume that $G$ is 4-angry.
    If $G$ has no tetra-separation, then \cref{4angry1} by \cref{quasi5conVtetra}.
    So $G$ has a tetra-separation $(A,B)$, which is crossed by a tetra-separation $(C,D)$ as $G$ is 4-angry.
    By the \allref{keylem:crossing}, all links have the same size $\ell$, and $\ell\in\{0,1,2\}$.
    \begin{itemize}
        \item If $\ell=0$, then \cref{4angry4} by \cref{keylem:K4m}.
        \item If $\ell=1$, then \cref{4angry2} by \cref{keylem:double-wheel-angry}.
        \item If $\ell=2$, then \cref{4angry3} by \cref{AngryBagel} and since $G \neq K_5$ by $|G| \geq 8$.
    \end{itemize}

    \casen{Backward implication.} We use one of \cref{quasi5conVtetra}, \cref{keylem:K4m}, \cref{keylem:double-wheel-angry} and \cref{AngryBagel}. Here \cref{quasi5conVtetra} needs $|G|\ge 8$.
\end{proof}





\section{Vertex-transitive graphs}\label{sec:vertexTransitive}

In this section, we prove \cref{mainthm:transitive}.
Let~$G=(V,E)$ be a graph. The \defn{clique-expansion} of~$G$ is the graph~$G'$ that is obtained from~$G$ by replacing every vertex~$v \in V(G)$ by a clique~$C_v$ of size the degree of~$v$, and every edge~$e=uv$ by a $C_u$--$C_v$ edge~$e'$ such that these edges~$e'$ form a perfect matching in~$G'$.
The clique-expansion is unique up to isomorphism.
If~$G$ is $r$-regular, then we also refer to its clique-expansion as the \defn{$K_r$-expansion} of~$G$.

Recall that a graph~$G$ is \defn{arc-transitive} if for every two ordered pairs~$(u_1,v_1),(u_2,v_2)$ of vertices forming edges $u_1 v_1,u_2 v_2\in E(G)$, there is an automorphism $\varphi$ of~$G$ such that~$(\varphi(u_1),\varphi(v_1))=(u_2,v_2)$.

\begin{theorem}\textnormal{\cite[Theorem~3.4.2]{Godsil}}\label{GodsilResult}
    Every finite vertex-transitive $d$-regular graph is $k$-connected for $k:=\lceil \frac{2}{3}(d+1)\rceil$.
\end{theorem}

\begin{corollary}\label{4reg4con}
    Every finite $d$-regular graph with $d\ge 4$ is 4-connected.\qed
\end{corollary}


A graph~$G$ is \defn{essentially 5-connected} if~$G$ is 4-connected and every tetra-separation $(A_1,A_2)$ of $G$ has only edges in its separator and at least one side~$A_i$ with~$G[A_i]=K_4$.


\begin{definition}\label{dfn:transitive-cycles}
Let $G$ be a graph with a cycle-decomposition $\cO=(O,(G_t)_{t \in V(O)})$.
Let $\ell$ denote the length of the cycle~$O$.
We say that~$G$ is a
    \begin{itemize}[leftmargin=*]
        \item \defn{cycle of~$K_4$-bags of length~$\ell$} if all bags of $\cO$ are $K_4$'s and all adhesion-sets of~$\cO$ are disjoint (\cref{fig:CycleOfK4s});
        \item \defn{cycle alternating between~$K_4$-bags and~$C_4$-bags of length~$\ell$} if the bags along $O$ alternate between being $K_4$'s and being 4-cycles, and all adhesion-sets of $\cO$ are disjoint (\cref{fig:CycleAlternating});
        \item \defn{cycle of triangle-bags of length~$\ell$} if all bags are triangles, and every two non-consecutive edges on~$O$ have disjoint adhesion-sets (\cref{fig:cycleOfTriangles});
        \item \defn{cycle of~$K_{2,2}$-bags of length~$\ell$} if all bags of $\cO$ are $K_{2,2}$'s, all torsos of $\cO$ are $K_4$'s and all adhesion-sets of~$\cO$ are disjoint (\cref{fig:CycleOfK22s}).
    \end{itemize}
\end{definition}

\begin{observation}{\,}
\begin{itemize}[leftmargin=*]
    \item Every cycle of~$K_4$-bags of length~$\ell$ is isomorphic to~$K_2 \boxtimes C_\ell$.
    \item Every cycle of~$K_4$-bags of length~3 is isomorphic to~$K_6$.
    \item Every cycle of~$K_{2,2}$-bags of length~3 is isomorphic to the octahedron.
    \item Every cycle of~$K_{2,2}$-bags of length~4 is isomorphic to~$K_{4,4}$.
    \item Every cycle alternating between~$K_4$-bags and~$C_4$-bags of length~$\ell\in\{4,6\}$ is essentially 5-connected.
    \item Every cycle of triangle-bags of length~$\ell$ is isomorphic to~$C_\ell^2$ (the graph obtained from the $\ell$-cycle~$C_\ell$ by joining every vertex~$v$ to all vertices of distance at most~2 from~$v$ on~$C_\ell$).
    \item Every cycle of~triangle-bags of length~5 is isomorphic to~$K_5$.
    \qed
\end{itemize}
\end{observation}



\begin{lemma}
\label{lem:transitive-totally-nested}
    Let $G$ be a vertex-transitive 4-connected finite graph, and let $(A_1,A_2)$ be a totally-nested tetra-separation in~$G$. Then $S(A_1,A_2)$ consists of four edges, and $(A_1,A_2)$ has a side~$A_i$ with $G[A_i]=K_4$.
\end{lemma}
\begin{proof}
    Let $M$ be the union of the $\Aut(G)$-orbits of $(A_1,A_2)$ and $(A_2,A_1)$. Let $(C,D)$ be $\leq$-minimal in~$M$; that is, $(C',D') \not< (C,D)$ for every $(C',D') \in M$.

    We claim that $S(C,D)$ contains no vertex.
    Assume otherwise that $u\in S(C,D)$ is a vertex.
    Then let $v$ be an arbitrary vertex in $C \sm D$ and let $\phi \in \Aut(G)$ such that $\phi(u)=v$. 
    Then $(\varphi(C),\varphi(D))<(C,D)$ or $(\varphi(D),\varphi(C))<(C,D)$, contradicting the $\leq$-minimality of~$(C,D)$.
    Hence $S(C,D)$ consists of four edges.

    We claim that every vertex in $C$ is incident to an edge in~$S(C,D)$.
    Assume for a contradiction that $v\in C$ is not.
    Let $u\in C\sm D$ be an endvertex of one of the four edges in $S(C,D)$ and let $\phi \in \Aut(G)$ such that $\varphi(u)=v$.
    Then $(\varphi(C),\varphi(D))<(C,D)$ or $(\varphi(D),\varphi(C))<(C,D)$, contradicting the $\leq$-minimality of~$(C,D)$.

    Finally, since $G$ is 4-connected, every vertex has degree $\ge 4$, so $G[C]$ is a~$K_4$.
    The tetra-separation $(A_1,A_2)$ shares the above properties of $(C,D)$ since $(C,D)\in M$.
\end{proof}

\begin{corollary}
\label{cor:transitive-essentially-5-connected}
    Let $G$ be a vertex-transitive 4-connected finite graph such that every tetra-separation is totally-nested. Then~$G$ is essentially 5-connected.\qed
\end{corollary}


\begin{lemma}
\label{lem:transitive-K4m}
    Let $G$ be a vertex-transitive 4-connected finite graph that has two tetra-separations $(A,B),(C,D)$ that cross with all links empty.
    Then~$G=K_{4,4}$, which is a cycle of $K_{2,2}$-bags of length~4.
\end{lemma}
\begin{proof}
    Let~$Z$ be the centre of the crossing-diagram, which consists of four vertices by the \allref{keylem:crossing}.
    Note that~$G-Z$ has at least four components.

    We claim that every every component of $G-Z$ has only one vertex.
    Assume not, and let $K$ be a component of $G-Z$ with $\ge 2$ vertices.
    Let~$(U_K',W_K'):=(V(K) \cup Z, V(G-K))$ and let~$(U_K,W_K)$ be the left-right-shift of~$(U_K',W_K')$.
    By \cref{K4mTotallyNestedChar},~$(U_K,W_K)$ is totally-nested.
    By \cref{lem:transitive-totally-nested},~$S(U_K,W_K)$ consists of four edges, and either~$G[U_K]=K_4$ or~$G[W_K]=K_4$.
    Since~$G[W_K]$ contains two vertices from distinct components of $G-Z$ with no edge in between them, we must have~$G[U_K]=K_4$.
    By \cref{K4mMonotoneShift}, we have~$U_K = V(K)$ and~$W_K = V(G - K)$.
    In particular,~$G$ is 4-regular and every vertex of~$U_K$ is in a~$K_4$. 
    By vertex-transitivity, so is every vertex of~$G$.
    It follows that there exists an edge between two vertices~$z_1$ and~$z_2$ in~$Z$. 
    But now,~$z_1$ and~$z_2$ have degree~5, contradicting 4-regularity of~$G$.
    Hence every component of $G-Z$ has only one vertex.

    By 4-connectivity of~$G$, each of the $\ge 4$ vertices of $G-Z$ has neighbourhood equal to~$Z$.
    So,~$G$ is 4-regular by vertex-transitivity.
    In particular,~$G-Z$ has exactly four vertices, and~$G[Z]$ is independent.
    So,~$G=K_{4,4}$.
\end{proof}

\begin{lemma}
\label{lem:transitive-block-bagel}
    Let $G$ be a vertex-transitive 4-connected finite graph that has two tetra-separations $(A,B),(C,D)$ that cross with all links of size~one. 
    Let~$\cO$ be the block-bagel induced by~$(A,B)$ and~$(C,D)$. 
    Then every bag of~$\cO$ is bad.
\end{lemma}
\begin{proof}
    Assume for a contradiction that $\cO=:(O,\cG)$ has a good bag~$G_t$.
    Then we have the \allref{set:bag-setting} with $t=t(0)$, which we assume in the following.
    By \cref{cor:double-wheel-totally-nested}, $(U,W)$ is a totally-nested tetra-separation of~$G$.
    By \cref{lem:transitive-totally-nested}, the separator $S(U,W)$ consists of four edges, and either~$G[U]=K_4$ or~$G[W]=K_4$.
    It follows with vertex-transitivity that $G$ is 4-regular and that the neighbourhood around each vertex induces $K_1\sqcup K_3$ in~$G$.

    By the \allref{lem:helpful-lemma}, $O$ has at least four helpful edges or vertices.
    By 4-regularity, there are exactly four helpful edges or nodes of~$O$.
    For each helpful edge, we colour its adhesion-vertex red.
    For each helpful node~$t$, there exists a unique interior vertex of $G_t$ that is a neighbour of $z'_1$ (by 4-regularity), and we colour this vertex red.
    Then exactly four vertices have been coloured red.
    By the above, the red vertices induced a $K_1\sqcup K_3$ in~$G-Z'$, where $Z'$ is the centre of the crossing-diagram.
    None of the red vertices in the $K_3$ can be an interior vertex of a bag, so all three are adhesion-vertices.
    But then $O$ would have to be a triangle, contradicting that $O$ has four helpful edges or nodes.
\end{proof}



\begin{lemma}
\label{lem:transitive-no-K3}
    Let $G$ be a vertex-transitive 4-connected finite graph that has two tetra-separations $(A,B),(C,D)$ that cross with all links of size~one. 
    Let $\cO$ be the Block-bagel induced by $(A,B)$ and $(C,D)$. 
    Then every bag of~$\cO$ is a~$K_2$.
\end{lemma}
\begin{proof}
    Write $\cO =: (O, (G_t)_{t \in V(O)})$, and let $u,v$ be the two vertices in the centre.
    By \cref{lem:transitive-block-bagel}, every bag of~$\cO$ is bad.
    In particular, every bag of~$\cO$ is a $K_2$ or a triangle.
    Assume for a contradiction that $\cO$ has a bag that is a triangle.
    Since every bag of $\cO$ is bad, it follows that all bags of $\cO$ are triangles.

    Let $G_t$ be an arbitrary bag of $\cO$, and let $x$ be the vertex in~$G_t$ that is not an adhesion-vertex. 
    By 4-connectivity of~$G$, we have~$x u, x v \in E(G)$ and~$x$ has degree~4.
    Hence~$G$ is 4-regular, and since $G_t$ was arbitrary, we get $|O|\le 4$.
    As every node of $O$ is helpful, we get $|O|\ge 4$ from the \allref{lem:helpful-lemma}, so $O$ has length~4.
    Hence each of $u,v$ has four neighbours, one in the interior of each bag, so by 4-regularity the edge $uv$ cannot exist in~$G$.
    Therefore, $u$ is not contained in a triangle.
    But all bags are triangles, contradicting vertex-transitivity.
\end{proof}


\begin{lemma}
\label{lem:transitive-double-wheel}
    Let $G$ be a vertex-transitive 4-connected finite graph that has two tetra-separations $(A,B),(C,D)$ that cross with all links of size one. Then~$G$ is an octahedron, which is a cycle of $K_{2,2}$-bags of length~3.
\end{lemma}
\begin{proof}
    By \cref{lem:transitive-no-K3}, every bag of the block-bagel $\cO=(O,\cG)$ induced by $(A,B)$ and $(C,D)$ is a~$K_2$.
    Hence every edge of $O$ is helpful, so $|O|\ge 4$ by the \allref{lem:helpful-lemma}. 
    Since each vertex of $G$ contained in $\bigcup_{t \in V(O)} G_t$ has degree $\le 4$ in~$G$, the graph~$G$ is 4-regular. 
    Let $u,v$ be the vertices in the centre. 
    By \cref{lem:path-from-helpful-edge} it follows that $|O|=4$ and $uv \notin E(G)$. 
    Then~$G$ is an octahedron.
\end{proof}

\begin{lemma}
\label{lem:transitive-tutte-good-bag}
    Let $G$ be a vertex-transitive 4-connected finite graph that has two tetra-separations $(A,B),(C,D)$ that cross with all links of size two. 
    Let~$\cO$ be the Tutte-bagel induced by~$(A,B)$ and~$(C,D)$.
    Let $H_t$ be a good torso of $\cO$.
    Then the bag $G_t$ is a $K_4$ and its two neighbouring torsos are 4-cycles.
\end{lemma}
\begin{proof}
    We may assume the \allref{BagelBag} with $t=t(0)$.
    By \cref{cor:bagel-totally-nested},~$(U,W)$ is a totally-nested tetra-separation.
    By \cref{lem:transitive-totally-nested}, $S(U,W)$ consists of four edges, and we have either~$G[U]=K_4$ or~$G[W]=K_4$.

    We claim that $G[U]= K_4$.
    Assume otherwise, so $G[W]=K_4$.
    Then $G[W]=G_s$ for some bag $G_s\neq G_t$.
    Hence $O$ has length $\le 4$, two 3-connected bags (namely $G_s,G_t$), and all other bags have triangles or 4-cycles as torsos by \cref{BagelBagAdhesionSet}.
    But then $\alpha(\cO)<4$ contradicts \cref{CrossedBagelsAngryFactor}.

    Hence $G[U]=K_4$.
    Next, we claim that $S(U,W)$ contains no inward edge, and assume for a contradiction that $x_1\in S(U,W)$ is an inward edge with endvertex $u$ in the interior of~$G_t$.
    By \cref{bagelInwardEdge}, some $y'_i$, say $y'_1$, is a neighbour of $x'_1$ and $y^W_1=y'_1$.
    In particular, $y_1$ cannot be an outward edge.
    Since $S(U,W)$ consists of four edges and $y_1$ is one of them, $y_1$ must be an inward edge.
    Let $u$ be the endvertex of $y_1$ in the interior of~$G_t$.
    Then $u\neq v$ by the matching-condition for $(U,W)$.
    Let $w$ be a neighbour of $x'_1$ in $G$ but outside of~$G_t$.
    Then the vertex-set $\{u,v,w\}$ is independent in~$G$ and consists entirely of neighbours of $x'_1$.
    Since $G[U]=K_4$ and $S(U,W)$ consists of four edges, $G$ is 4-regular and every vertex lies in a $K_4$ by vertex-transitivity.
    But $\{u,v,w\}$ witnesses that $x'_1$ does not lie in a~$K_4$, a contradiction.
    Therefore, $S(U,W)$ contains no inward edge.

    So all edges in $S(U,W)$ are outward edges.
    Hence $G_t=K_4$ and both neighbouring torsos are 4-cycles.
\end{proof}

\begin{lemma}
\label{lem:transitive-tutte-bagel}
    Let $G$ be a vertex-transitive 4-connected finite graph that has two tetra-separations $(A,B),(C,D)$ that cross with all links of size~two. 
    Let~$\cO$ be the Tutte-bagel induced by~$(A,B)$ and~$(C,D)$.
    If some torso of $\cO$ is good, then~$G$ is a cycle alternating between $K_4$-bags and $C_4$-bags of length~$\ge 8$.
\end{lemma}
\begin{proof}
    Write $\cO =: (O,(G_t)_{t \in V(O)})$.
    Write $O=t(0)\,t(1)\ldots t(m)\, t(0)$ with indices in~$\Z_{m+1}$.
    By \cref{lem:transitive-tutte-good-bag}, if a torso such as $H_{t(0)}$ is good, then its bag is a~$K_4$ and the two neighbouring torsos $H_{t(-1)}$ and $H_{t(1)}$ are 4-cycles.
    Then, by \cref{TutteBagelObservations}, the torsos $H_{t(-2)}$ and $H_{t(2)}$ are 3-connected.
    Hence, both of these torsos are good as they neighbour torsos that are 4-cycles.
    By induction, we get that~$O$ has even length, that bags $G_{t(i)}$ are $K_4$'s for even~$i$, and that torsos $H_{t(i)}$ are 4-cycles for odd~$i$.
    By \cref{CrossedBagelsAngryFactor}, there are $\ge 4$ bags that are~$K_4$'s.
    It follows that~$G$ is a cycle alternating between $K_4$-bags and $C_4$-bags of length~$\ge 8$.
\end{proof}

\begin{lemma}
\label{lem:tutte-bagel-wheel}
    Let $\cO$ be a Tutte-bagel of a 4-connected graph.
    Let $G_t$ be a bag of $\cO$ on five vertices.
    Let $\pi,\pi'$ be the two adhesion-sets at~$G_t$, and let $v$ be the interior vertex of~$G_t$.
    Then the bag $G_t$ contains a full matching between $\pi$ and~$\pi'$, and $v$ sends edges to all four vertices in $\pi\cup\pi'$.
\end{lemma}
\begin{proof}
    Since $G$ is 4-connected, $v$ sends edges to all four vertices in $\pi\cup\pi'$.
    Since the torso $H_t$ is 3-connected with $|H_t|=5$, it is either a $4$-wheel, a $K_5^-$ or a $K_5$.
    In each case, $H_t$ contains a full matching between $\pi$ and $\pi'$, and both edges in the matching also exist in the bag~$G_t$.
\end{proof}

\begin{lemma}
\label{lem:transitive-cube}
    Let $G$ be a vertex-transitive 4-connected finite graph that has two tetra-separations $(A,B),(C,D)$ that cross with all links of size two. 
    Let~$\cO$ be the Tutte-bagel induced by~$(A,B)$ and~$(C,D)$.
    Assume that $\cO$ has a torso on five vertices.
    Then~$G$ is the line graph of the cube.
\end{lemma}
\begin{proof}
    Write $\cO=:(O,\cG)$.
    By \cref{lem:transitive-tutte-bagel}, all bags of $\cO$ are bad.
    Let $H_t$ be a torso of $\cO$ on five vertices.
    Since the unique interior vertex~$x$ of~$H_t$ has degree~4, the graph~$G$ is 4-regular.
    Since~$H_t$ is bad, it is neighboured by a 3-connected torso~$H_s$.
    Since $H_s$ is bad as well, it has $\le 5$ vertices.
    That is, the torso of~$H_s$ either is a~$K_4$ or has exactly five vertices.

    We claim that $H_s$ has exactly five vertices.
    Otherwise $H_s=K_4$.
    Let $\{u,v\}$ denote the adhesion-set in between the torsos $H_t$ and~$H_s$.
    Then $uv \notin E(G)$ by 4-regularity of~$G$.
    Let $\{u',v'\}$ denote the other adhesion-set at~$H_s$.
    Since~$v$ is contained in at least two triangles in~$G$, we must have $u'v' \in E(G)$.
    The vertex $v$ is contained in exactly two triangles: one from $H_s$ and the other is $vu'v'$.
    The vertex~$v'$, however, is contained in at least two triangles (namely $vu'v'$ and $uu'v'$), two of which intersect in the edge~$u'v'$.
    This contradicts the vertex-transitivity of~$G$.
    Hence $H_s$ has exactly five vertices.

    It follows by induction that all torsos of $\cO$ have exactly five vertices.
    By \cref{lem:tutte-bagel-wheel}, each bag contains a 2-matching between its two adhesion-sets, and the interior vertex of the bag sends edges to all four other vertices in the bag.
    By 4-regularity and since every bag looks like this, these are all the edges that there are in the bags.

    Since each bag has a unique interior vertex, the set $X$ of all these vertices has size~$|O|$.
    Since all torsos are 3-connected, we have $|O|\ge 4$ by \cref{CrossedBagelsAngryFactor}.
    If~$|O| \geq 5$, then every vertex in $X$ is contained in exactly two induced 4-cycles in~$G$, while every vertex in an adhesion set is contained in exactly one induced 4-cycle in~$G$, contradicting vertex-transitivity. 
    Therefore, we have~$|O|=4$. 
    Consider the graph~$H :=  G - X$, which is either an 8-cycle or a disjoint union of two 4-cycles. 
    If~$H$ is an 8-cycle, then every vertex in~$X$ is contained in two induced 4-cycles of~$G$ while every vertex in $V(G - X)$ is only contained in one induced 4-cycle of~$G$, contradicting vertex-transitivity. 
    Therefore $H$ is a disjoint union of two 4-cycles, and it follows that~$G$ is the line graph of the cube.
\end{proof}

\begin{lemma}
\label{lem:transitive-bagel-without-K5}
    Let $G$ be a vertex-transitive 4-connected finite graph that has two tetra-separations $(A,B),(C,D)$ that cross with all links of size~two.
    Let~$\cO$ be the Tutte-bagel induced by~$(A,B)$ and~$(C,D)$.
    Assume that every bag of $\cO$ has $\le 4$ vertices.
    Then~$G$ is one of the following graphs:
    \begin{itemize}
        \item a cycle alternating between $K_4$-bags and $C_4$-bags of length~$\ge 8$;
        \item a cycle of triangle-bags of length~$\ge 6$;
        \item a cycle of~$K_{2,2}$-bags of length~$\ge 4$;
        \item a cycle of~$K_4$-bags of length~$\ge 4$.
    \end{itemize}
\end{lemma}
\begin{proof}
    If~$\cO$ has a good torso, then~$G$ is a cycle alternating between $K_4$-bags and $C_4$-bags by \cref{lem:transitive-tutte-bagel}, and it is of length $\ge 8$ by \cref{CrossedBagelsAngryFactor}.
    Hence, we may assume that all torsos of $\cO$ are bad.

    We claim that $\cO$ has no 4-cycle as torso.
    Indeed, if $\cO$ has a 4-cycle as a torso, then the neighbouring torsos are 3-connected by \cref{TutteBagelObservations}, and they are good, a contradiction.
    Thus,
    \begin{equation}\label{lem:transitive-bagel-without-K5-eq}
        \textit{all torsos are either triangles or $K_4$'s.}
    \end{equation}

    We claim that if some torso of $\cO$ is a triangle, then also its neighbouring torsos are triangles.
    For this, let $H_t$ and $H_s$ be neighbouring torsos with $H_t$ a triangle.
    By \cref{lem:transitive-bagel-without-K5-eq}, the torso $H_s$ is either a triangle or a~$K_4$.
    Assume for a contradiction that $H_s=K_4$.
    Let $\{u,v\}$ be the adhesion-set in between $H_t$ and $H_s$, so that $v$ is the tip of the triangle-torso~$H_t$, say.
    Since every vertex has degree~$\ge 4$, the edge $uv$ must exist in $G$, and $G$ must be 4-regular.
    Let $w$ be the vertex of the triangle $H_t$ besides $u$ and~$v$.
    Let $G_r$ be the bag neighbouring $G_t$ besides~$G_s$.
    Then $v$ has exactly one neighbour in the bag~$G_r$.
    By \cref{lem:transitive-bagel-without-K5-eq}, the torso $H_r$ can only be a triangle or a~$K_4$.
    As $v$ has exactly one neighbour in the bag~$G_r$, the torso $H_r$ cannot be a~$K_4$, so it must be a triangle.
    But then the edge $vw$ exists by \cref{TutteBagelObservations}, so $v$ has two neighbours in~$G_r$, giving it degree five in~$G$, contradicting 4-regularity.
    Therefore, every triangle-torso of $\cO$ is neighboured by two triangle-torsos.

    So if $\cO$ has at least one triangle-torsos, then all torsos are triangles, and all adhesion-sets are spanned by edges by~\cref{TutteBagelObservations}.
    Hence $G$ is a cycle of triangle-bags, and it has length $\ge 6$ by \cref{CrossedBagelsAngryFactor} and since $G \neq K_5$.

    So we may assume that $\cO$ has no triangle-torsos.
    Then by \cref{lem:transitive-bagel-without-K5-eq}, all torsos of $\cO$ are $K_4$'s.
    Then either all adhesion-sets are spanned by edges in~$G$, in which case~$G$ is a cycle of~$K_4$-bags; or none of them are, in which case~$G$ is a cycle of~$K_{2,2}$-bags.
    In both cases, the length is $\ge 4$ by \cref{CrossedBagelsAngryFactor}.
\end{proof}

\begin{lemma}
\label{lem:transitive-bagel-case}
    Let $G$ be a vertex-transitive 4-connected finite graph that has two tetra-separations $(A,B),(C,D)$ that cross with all links of size~two. Then~$G$ is one of the following:
    \begin{itemize}
        \item a cycle alternating between $K_4$-bags and $C_4$-bags of length~$\ge 8$;
        \item a cycle of triangle-bags of length~$\ge 6$;
        \item a cycle of~$K_{2,2}$-bags of length~$\ge 4$;
        \item a cycle of~$K_4$-bags of length~$\ge 4$;
        \item line graph of the cube.
    \end{itemize}
\end{lemma}
\begin{proof}
    We combine~\cref{lem:transitive-cube,lem:transitive-bagel-without-K5}.
\end{proof}

\begin{corollary}
\label{cor:transitive-crossing}
    Let $G$ be a vertex-transitive 4-connected finite graph that has two tetra-separations $(A,B),(C,D)$ that cross.
    Then~$G$ is one of the following:
    \begin{itemize}
        \item a cycle alternating between $K_4$-bags and $C_4$-bags of length~$\ge 8$;
        \item a cycle of triangle-bags of length~$\ge 6$;
        \item a cycle of~$K_{2,2}$-bags of length~$\ge 3$;
        \item a cycle of~$K_4$-bags of length~$\ge 4$;
        \item line graph of the cube.
    \end{itemize}
\end{corollary}
\begin{proof}
    By the \allref{keylem:crossing}, all links have the same size $0$, $1$ or~$2$.
    If all links have size~$0$, then $G$ is a cycle of~$K_{2,2}$-bags of length~$4$ by \cref{lem:transitive-K4m}.
    If all links have size~$1$, then $G$ is a cycle of~$K_{2,2}$-bags of length~$3$ by \cref{lem:transitive-double-wheel}.
    Otherwise all links have size~$2$, and we apply \cref{lem:transitive-bagel-case}.
\end{proof}

\begin{observation}
\label{obs:expansion-maintains-degrees}
    Let~$G'$ be the expansion of a graph~$G$.
    Let~$v$ be a vertex of degree~$d$ in~$G$, and let~$C_v$ be the clique of~$G'$ that corresponds to~$v$.
    Then every vertex in~$C_v$ has degree~$d$ in~$G'$.\qed
\end{observation}

\begin{observation}
    \label{obs:expansion-clique-partition}
    Let~$G$ be a graph of minimum degree at least~$2$, and let~$G'$ be the expansion of~$G$.
    Then there is a unique partition~$\cP$ of~$V(G')$ into (the vertex-sets of) $|\cP|=|V(G)|$ cliques.
    Moreover, the contraction-minor $G' / \cP$ is isomorphic to~$G$.\qed
\end{observation}

\begin{observation}
\label{obs:expansion-isomorphic}
    The expansion of a graph~$G$ is isomorphic to the graph~$H$ with 
    \begin{align*}
        V(H) & {}=\{(u,v),(v,u) : uv \in E(G)\}\text{ and}\\
        E(H) & {}=\Big\{\{(u,v),(v,u)\} : uv \in E(G)\Big\}\,\cup\,\Big\{\{(u,v_1),(u,v_2)\} : uv_1,uv_2 \in E(G) \Big\}.
    \end{align*}\qed
\end{observation}

\begin{lemma}
\label{lem:expansion-edge-transitive}
    Let~$G$ be an $r$-regular graph with $r \geq 3$.
    Then the following assertions are equivalent:
    \begin{enumerate}
        \item\label{lem:expansion-edge-transitive1} the $K_r$-expansion of~$G$ is vertex-transitive;
        \item\label{lem:expansion-edge-transitive2} $G$ is arc-transitive.
    \end{enumerate}
\end{lemma}
\begin{proof}
    Let $G'$ denote the $K_r$-expansion of~$G$.
    By \cref{obs:expansion-clique-partition},~$G'$ has a unique partition~$\cP$ of its vertex-set into vertex-sets of $r$-cliques.
    Let $\gamma\colon \cP \to V(G)$ be the corresponding bijection.
    Since $\cP$ is unique, $\Aut(G')$ acts on~$\cP$.

    \cref{lem:expansion-edge-transitive1} $\Rightarrow$ \cref{lem:expansion-edge-transitive2}. 
    Let $(u_1,v_1),(u_2,v_2)$ be ordered pairs of vertices in~$G$ with $u_i v_i\in E(G)$.
    We will find an automorphism~$\phi$ of~$G$ such that $\varphi(u_1)=u_2$ and $\varphi(v_1)=v_2$.
    For this, we abbreviate $x_i :=(u_i,v_i)$.
    Let~$P_i \in \cP$ be the unique partition-class of~$\cP$ that contains~$x_i$. 
    Since~$G'$ is vertex-transitive by assumption, there is an automorphism~$\phi'$ of~$G'$ that maps~$x_1$ to~$x_2$.
    Note that $\varphi$ then maps $P_1$ to~$P_2$.
    We define $\phi := \gamma \circ \phi' \circ \gamma^{-1}$ by abuse of notation, using that $\Aut(G')$ acts on~$\cP$.
    Clearly, $\phi$ is a bijection $V(G)\to V(G)$.
    Moreover, we have
    \begin{align*}
        & \text{ }xy\in E(G)\\
        \Leftrightarrow & \text{ there is a $\gamma^{-1}(x)$--$\gamma^{-1}(y)$ edge in~$G'$}\\
        \Leftrightarrow & \text{ there is a $\phi'(\gamma^{-1}(x))$--$\phi'(\gamma^{-1}(y))$ edge in~$G'$}\\
        \Leftrightarrow & \text{ $\phi(x)\phi(y) \in E(G)$.}
    \end{align*}
    So,~$\phi$ is an automorphism of~$G$.
    Moreover, we have
    \[
        \phi(u_1) = \gamma(\phi'(\gamma^{-1}(u_1))) = \gamma(\phi'(P_1)) = \gamma(P_2) = u_2.
    \]
    Similarly, $\phi(v_1)=v_2$.

    \cref{lem:expansion-edge-transitive2} $\Rightarrow$ \cref{lem:expansion-edge-transitive1}.
    We assume without loss of generality that $G'$ takes the form described in~\cref{obs:expansion-isomorphic}.
    Let $x_1,x_2 \in V(G')$ be two vertices.
    We will find an automorphism~$\phi'$ of~$G'$ that maps~$x_1$ to~$x_2$.
    We write $x_i=:(u_i,v_i)$ using \cref{obs:expansion-isomorphic}, so $u_i v_i$ is an edge of $G$.
    Since~$G$ is arc-transitive, there is an automorphism~$\phi$ of~$G$ such that $\varphi(u_1)=u_2$ and $\varphi(v_1)=v_2$.
    Now $\varphi$ defines an automorphism $\varphi'$ of $G'$ that sends every vertex $x=(u,v)$ to the vertex $\varphi'(x):=(\varphi(u),\varphi(v))$.
    The automorphism $\varphi'$ satisfies
    \[
        \phi'(x_1)=(\phi(u_1),\phi(v_1)) = (u_2,v_2) = x_2.\qedhere
    \]
\end{proof}

\begin{corollary}
    \label{cor:expansion-mixed-separation-not-transitive}
    Let~$G$ be an $r$-regular graph with $r\ge 3$.
    Let $(A,B)$ be a mixed-$r$-separation of $G$ such that $S(A,B)$ consists only of edges and~$S(A,B)$ is a matching and $G[A] = K_r$.
    Then~$G$ is not arc-transitive.
    Moreover, the $K_r$-expansion of~$G$ is not vertex-transitive.
\end{corollary}
\begin{proof}    
    By \cref{lem:expansion-edge-transitive}, it suffices to show that~$G$ is not arc-transitive.
    Indeed, if~$u$ is a vertex in~$A$, then $G[N(u)]=K_1 \sqcup K_{r-1}$ with $r-1 \geq 2$.
    Let~$v_1$ be the isolated vertex in~$G[N(u)]$ and let~$v_2 \neq v_1$ be another vertex in~$N(u)$.
    Then there is no automorphism of~$G$ that maps~$(u,v_1)$ to~$(u,v_2)$.
\end{proof}

\begin{corollary}
    \label{cor:iterated-expansion-not-transitive}
    Let $r \geq 3$.
    The $K_r$-expansion of an $r$-regular graph~$G$ is not arc-transitive.
    In particular, the $K_r$-expansion of the $K_r$-expansion of an $r$-regular graph~$G$ is not vertex-transitive.
\end{corollary}
\begin{proof}
    Follows from \cref{cor:expansion-mixed-separation-not-transitive}.
\end{proof}

\begin{corollary}
    \label{cor:cycle-of-triangles-not-transitive}
    A cycle of triangle-bags of length~$\geq 6$ is not arc-transitive.
    In particular, the $K_4$-expansion of a cycle of triangle-bags of length~$\ge 6$ is not vertex-transitive.
\end{corollary}
\begin{proof}
    Let~$G$ be a cycle of triangle-bags of length~$\ge 6$, and let~$\cO$ be the corresponding cycle-decomposition.
    Note that every free edge of~$\cO$ is contained in exactly one triangle of~$G$, while every other edge of~$G$ is contained in exactly two triangles.
    So,~$G$ is not edge-transitive.
    In particular, it is not arc-transitive.
    By \cref{lem:expansion-edge-transitive}, the $K_4$-expansion of a cycle of triangle-bags of length~$\ge 6$ is not vertex-transitive. 
\end{proof}

\begin{corollary}
    \label{cor:symmetric-crossing}
    Let $G$ be a finite graph that is arc-transitive, 4-connected, 4-regular and has two tetra-separations that cross.
    Then~$G$ is the line graph of the cube or a cycle of~$K_{2,2}$-bags of length~$\ge 3$.
\end{corollary}
\begin{proof}
    This follows from \cref{cor:transitive-crossing} together with the following observations.
    First, a cycle of~$K_4$-bags of length~$\ge 4$ is not 4-regular.
    Second, a cycle alternating between $K_4$-bags and $C_4$-bags of length~$\ge 8$ is not arc-transitive by \cref{cor:expansion-mixed-separation-not-transitive}.
    Finally, a cycle of triangle-bags of length~$\ge 6$ is not arc-transitive by \cref{cor:cycle-of-triangles-not-transitive}.
\end{proof}

\begin{lemma}
\label{lem:transitive-partition-into-K4}
    Let~$G$ be a vertex-transitive essentially 5-connected graph. 
    Then either~$G$ is quasi-5-connected or there is a partition~$\cP$ of~$V(G)$ into vertex-sets of~$K_4$'s such that the edges in $G$ with ends in different classes of~$\cP$ form a perfect matching in~$G$.
\end{lemma}
\begin{proof}
    If~$G$ does not have a tetra-separation, then~$G$ is quasi-5-connected by \cref{quasi5conVtetra}~\ref{quasi5conVtetra1}.
    Hence, we may assume that~$G$ has a tetra-separation~$(A,B)$.
    Since~$G$ is essentially 5-connected, the separator of $(A,B)$ consists of four edges and there is a side, say~$A$, that induces a~$K_4$ in~$G$.
    Let~$u \in A$ and observe that $G[N(u)]=K_1 \sqcup K_3$; in particular,~$u$ is contained in exactly one~$K_4$.
    By vertex-transitivity, so is every vertex of~$G$.
    It follows that~$G$ admits a partition of its vertex-set into the vertex-sets of~$K_4$'s.
    Moreover,~$G$ is 4-regular since~$u$ has degree~4 in~$G$. Then it follows that the edges between distinct partition-classes of~$\cP$ form a perfect matching in~$G$.
\end{proof}

\begin{lemma}
\label{lem:transitive-contract-essentially-5-connected}
    Let~$G$ be a vertex-transitive essentially 5-connected graph. Then~$G$ is one of the following:
    \begin{itemize}
        \item quasi-5-connected;
        \item a cycle alternating between $K_4$-bags and $C_4$-bags of length $\ell \in \{4,6\}$;
        \item the $K_4$-expansion of an arc-transitive 4-connected 4-regular graph.
    \end{itemize}
\end{lemma}
\begin{proof}
    Assume that~$G$ is not quasi-5-connected.
    Then by \cref{lem:transitive-partition-into-K4}, there is a partition~$\cP$ of~$V(G)$ into the vertex-sets of~$K_4$'s such that edges between distinct partition-classes of~$\cP$ form a perfect matching in~$G$.
    %
    We distinguish the following cases.

    \casen{Case 1:} there are two parts~$P_1 \neq P_2$ of~$\cP$ such that there are at least three $P_1$--$P_2$ edges~$e_1,e_2,e_3$ in~$G$.
    Let~$f_i \notin \{e_1,e_2,e_3\}$ be the remaining edge incident with a vertex in~$P_i$.
    By 4-connectivity of~$G$, $\{f_1,f_2\}$ is not a mixed-2-separator. 
    It follows that $f_1 = f_2$, so~$G$ is a cycle alternating between $K_4$-bags and $C_4$-bags of length~4.

    \casen{Case 2:} there are two parts~$P_1 \neq P_2$ of~$\cP$ such that there are exactly two $P_1$--$P_2$ edges in~$G$. 
    Let~$e_1,e_2$ be the two edges incident with~$P_1$ but not with~$P_2$, and let~$f_1,f_2$ be the two edges incident with~$P_2$ but not with~$P_1$.
    We define $(A,B):=(P_1 \cup P_2, V(G) \sm (P_1 \cup P_2))$.
    Then $S(A,B)=\{e_1,e_2,f_1,f_2\}$, so~$(A,B)$ is a tetra-separation.
    By assumption, there is a side of~$(A,B)$ that induces a~$K_4$.
    Since $|A|=8$, we must have $G[B] = K_4$.
    It follows that~$G$ is a cycle alternating between $K_4$-bags and $C_4$-bags of length~$6$.

    \casen{Case 3:} for every two parts~$P_1 \neq P_2$ of~$\cP$, there is at most one $P_1$--$P_2$ edge in~$G$. Then we define $H:=G / \cP$, which is a 4-regular graph.
    Moreover, observe that~$G$ is the $K_4$-expansion of~$H$.
    Then by \cref{lem:expansion-edge-transitive},~$H$ is arc-transitive. By \cref{4reg4con},~$H$ is 4-connected.
\end{proof}

\begin{corollary}
\label{cor:symmetric-contract-essentially-5-connected}
    Let~$G$ be an arc-transitive essentially 5-connected graph. Then~$G$ is quasi-5-connected.
\end{corollary}
\begin{proof}
    Follows from \cref{lem:transitive-contract-essentially-5-connected} together with the following observations.
    First, a cycle alternating between $K_4$-bags and $C_4$-bags of length $\ell \in \{4,6\}$ is not arc-transitive by \cref{cor:expansion-mixed-separation-not-transitive}.
    Second, the $K_4$-expansion of a graph is not arc-transitive by \cref{cor:iterated-expansion-not-transitive}.
\end{proof}


\begin{proof}[Proof of~\cref{mainthm:transitive}]
    Let $G$ be a 4-connected finite graph.

    ($\Rightarrow$).
    Assume that $G$ is vertex-transitive.
    If~$G$ has two tetra-separations that cross, then we are done by \cref{cor:transitive-crossing}.
    Otherwise, every tetra-separation of~$G$ is totally-nested.
    Then~$G$ is essentially 5-connected by \cref{cor:transitive-essentially-5-connected}.
    By \cref{lem:transitive-contract-essentially-5-connected},~$G$ is either quasi-5-connected, or a cycle alternating between $K_4$-bags and $C_4$-bags of length $\ell \in\{4,6\}$, or the $K_4$-expansion of an arc-transitive 4-connected 4-regular graph.
    In the first two cases, we are done.
    So assume that~$G$ is the $K_4$-expansion of an arc-transitive 4-connected 4-regular graph~$H$.
    In particular,~$H$ is vertex-transitive.

    If~$H$ has two tetra-separations that cross, then we apply \cref{cor:symmetric-crossing} to get that~$H$ is the line graph of the cube or that~$H$ is a cycle of~$K_{2,2}$-bags of length~$\geq 3$. 
    Here we are done.
    Otherwise, every tetra-separation of~$H$ is totally-nested. 
    By \cref{cor:transitive-essentially-5-connected},~$H$ is essentially 5-connected.
    By \cref{cor:symmetric-contract-essentially-5-connected},~$H$ quasi 5-connected. 
    Thus, $G$ is the $K_4$-expansion of an arc-transitive quasi-5-connected graph, and we are done.

    ($\Leftarrow$). 
    Clearly, if~$G$ is one of the graphs in~\ref{mainitm:transitive-1}, \ref{mainitm:transitive-3}, \ref{mainitm:transitive-4}, \ref{mainitm:transitive-5}, then~$G$ is vertex-transitive.
    If~\ref{mainitm:transitive-2} $G$ is the $K_4$-expansion of a quasi-5-connected arc-transitive graph, then~$G$ is vertex-transitive by \cref{lem:expansion-edge-transitive}.
    Both~\ref{mainitm:transitive-6} a cycle of~$K_{2,2}$-bags and~\ref{mainitm:transitive-7} the line graph of the cube are arc-transitive.
    If~$G$ is a $K_4$-expansion of~\ref{mainitm:transitive-6} or~\ref{mainitm:transitive-7}, then~$G$ is vertex-transitive by \cref{lem:expansion-edge-transitive}.    
\end{proof}




