\section{Circular saws}\label{sec:saw}

Here we verify that the circular saws from the introduction have the desired properties.

\begin{lemma}\label{SawPaths}
    Let $G$ be a $k$-regular circular saw on $\Z_n\times\Z_2$ with $n\gg k$.
    Let $aa'$ and $bb'$ be two edges of $G$ such that $\{a,a'\}$ and $\{b,b'\}$ are disjoint and there is no $\{a,a'\}$--$\{b,b'\}$ edge.
    Let $X$ denote the neighbourhood of $\{a,a'\}$, and let $Y$ denote the neighbourhood of $\{b,b'\}$.
    There are $2(k-1)$ disjoint $X$--$Y$ paths in~$G$.
\end{lemma}
\begin{proof}
    For each vertex $x\in X$ we construct two $x$--$Y$ paths $P^+_x,P^-_x$ inductively, as follows.
    See \cref{fig:SawPaths} for an example.

    In the first step of the construction of $P^+_x$, we let $P^+_x$ start and end with~$x$.
    Assume now that $P^+_x$ ends with the vertex $(\ell,i)$.
    If $(\ell,i)\in Y$, then we terminate the construction.
    Otherwise $(\ell,i)\notin Y$.
    If $i=0$ we append the vertex $(\ell+k-1,1)$, and if $i=1$ we add the vertex $(\ell,0)$.
    This completes the construction of $P^+_x$.

    In the first step of the construction of $P^-_x$, we let $P^-_x$ start and end with~$x$.
    Assume now that $P^-_x$ ends with the vertex $(\ell,i)$.
    If $(\ell,i)\in Y$, then we terminate the construction.
    Otherwise $(\ell,i)\notin Y$.
    If $i=0$ we append the vertex $(\ell,1)$, and if $i=1$ we add the vertex $(\ell-k+1,0)$.
    This completes the construction of $P^-_x$.

    Exactly one of the paths $P^+_x,P^-_x$ has an internal vertex in~$X$.
    Let $P_x$ denote the other path.
    Then $(P_x:x\in X)$ is a family of disjoint $X$--$Y$ paths.
    There are $|X|=2(k-1)$ of these paths.
\end{proof}

\begin{figure}[ht]
    \centering
    \includegraphics[height=7\baselineskip]{Figures/QKCpaths.pdf}
    \caption{Paths constructed in the proof of \cref{SawPaths}. The edges $aa'$ and $bb'$ are coloured blue, the paths are coloured red.}
    \label{fig:SawPaths}
\end{figure}


\begin{lemma}\label{SawWorks}
    Let $G$ be a $k$-regular circular saw on $\Z_n\times\Z_2$ with $n\gg k\ge 3$.
    Then $G$ is $k$-connected and the neighbourhoods of its vertices are precisely its $k$-separators.
\end{lemma}
\begin{proof}
    We show first that $G$ is $k$-connected, and assume for a contradiction that some two vertices $a,b$ of $G$ are separated by a set $S$ of $k-1$ vertices.
    Let $a'$ be a neighbour of $a$ outside $S$, and let $b'$ be a neighbour of $b$ outside~$S$.
    Note that $2(k-1)\ge k+1$ since $k\ge 3$.
    Hence by \cref{SawPaths}, there are $k+1$ disjoint $N(\{a,a'\})$--$N(\{b,b'\})$ paths in~$G$, contradicting that $|S|\le k-1$.
    Hence $G$ is $k$-connected.

    Next, we assume for a contradiction that $G$ has a $k$-separation $(A,B)$ such that $S(A,B)$ fails to be the neighbourhood of some vertex of $G$.
    Let $a\in A\sm B$ and $b\in B\sm A$.
    Then there are vertices $a'\in N(a)\sm S(A,B)$ and $b'\in N(b)\sm S(A,B)$.
    Now \cref{SawPaths} yields $k+1$ disjoint $N(\{a,a'\})$--$N(\{b,b'\})$ paths in $G$, contradicting that $(A,B)$ has order~$k$.
\end{proof}



\section{Comparison of \texorpdfstring{\trisp s}{strict tri-separations} and tri-separations}\label{sec:comparison}

The \trisp -decomposition (\cref{3Decomp}) is different from the tri-separation decomposition \cite[Theorem~1]{Tridecomp} as can be seen in \cref{fig:Trisplit,fig:Triseparation}.
However, the \trisp -decomposition can be viewed as a refinement of the tri-separation decomposition via \cref{trisepGivesTrisplit}.


