A tri-separation $(A,B)$ is \defn{negligible} if $|A\sm B|\le 1$ or $|B\sm A|\le 1$.

\begin{lemma}\label{trisepGivesTrisplit}
    Let $G$ be a 3-connected graph.
    Let $(A,B)$ be a totally-nested non-trivial tri-separation of $G$.
    Then the left-right-shift $(A',B')$ of $(A,B)$ is a totally-nested \trisp , or $(A,B)$ is negligible.
\end{lemma}
\begin{proof}
    Assume that $(A,B)$ is not negligible.
    Then $(A',B')$ is a \trisp\ by \cref{leftrightTetra} (which generalises to \trisp s via an apex-argument as in the proof of \cref{3DecompStrengthening}).
    Assume for a contradiction that there is a \trisp\ $(C,D)$ of $G$ that crosses $(A',B')$ with $C$-link $\gamma'$ and $D$-link $\delta'$.
    We will show that $(C,D)$ crosses $(A,B)$ with non-empty $C$-link $\gamma$ and non-empty $D$-link $\delta$.
    For this, we consider the crossing-diagram of $(C,D)$ and $(A',B')$.
    By \cite[Lemma 1.3.10]{Tridecomp}, there are two cases.

    \casen{Case: the centre consists of one vertex and all links have size one.}
    Then $\gamma'$ and $\delta'$ are non-empty.
    If $\gamma'$ consists of a vertex $v$, then $\gamma$ also consists of~$v$.
    Otherwise $\gamma'$ consists of an edge~$e$.
    The edge $e$ cannot be dangling, since then its endvertex in $S(C,D)$ would violate the degree-condition.
    Hence the endvertices of $e$ are contained in the corners $A'C$ and $B'C$, respectively.
    So $e$ or an endvertex of $e$ is contained in $\gamma$.
    This concludes the proof that $\gamma$ is non-empty, and a similar argumentation shows that $\delta$ is non-empty.
    Hence $(C,D)$ and $(A,B)$ cross with non-empty opposite links $\gamma$ and~$\delta$.

    \casen{Case: the centre consists of three vertices and all links are empty.}
    Then $S(A',B')$ consists of three vertices, so $(A',B')=(A,B)$.
    But all corners are non-empty, so $(A',B')$ is not half-connected.
    However, $(A,B)$ is half-connected because it is totally-nested, by \cite[Lemma 2.3.4]{Tridecomp}, contradicting that $(A',B')=(A,B)$.
\end{proof}


