 \section{Proof of Lemma~\ref{lem:bound}} \label{app:bound-proof}
 \begin{proof}
 For ease of notation, we set $f(x) := (1+p\cdot x)/\sqrt{(1+\norm{p}^2)(1+\norm{x}^2)}$.

 First suppose $p=0$.
 Then $f(x) = (1+\norm{x}^2)^{-1/2}$ and $\norm{x}=\norm{x-p}\geq\Delta>0$, so we bound
 \[
 f(x) = \frac{1}{\sqrt{1+\norm{x}^2}} \leq \frac{1}{\sqrt{1+\Delta^2}}:= B_{0,\Delta} <1
 \]
 and we are done.

 Otherwise $p\neq 0$ and we assume without loss of generality that $\Delta < \norm{p}$.
 To find a lower bound for $f(x)$ which is strictly greater than $-1$, we first use the Cauchy-Schwarz inequality $p\cdot x\geq -\norm{p}\norm{x}$ to bound $f(x)$ below by the value
 \[
 \frac{1-\norm{p}\norm{x}}{\sqrt{(1+\norm{p}^2)(1+\norm{x}^2)}}
 \]
 which is strictly decreasing with respect to $\norm{x}$.
 Thus
 \begin{align*}
 f(x)\geq \frac{1-\norm{p}\norm{x}}{\sqrt{(1+\norm{p}^2)(1+\norm{x}^2)}} & \geq \lim_{N\to\infty} \frac{1-N\norm{p}}{\sqrt{(1+\norm{p}^2)(1+N^2)}}\\
 &= - \frac{\norm{p}}{\sqrt{1+\norm{p}^2}} > -1
 \end{align*}
 For the remainder of the proof, we now use the equality
 \[
 (1+\norm{p}^2)(1+\norm{x}^2) = (1+\norm{p}\norm{x})^2 + (\norm{x}-\norm{p})^2
 \]
 to rewrite the denominator of $f(x)$.
 To find an upper bound for $f(x)$ we now consider a further two cases.

 \textbf{Case 1: $|\norm{x}-\norm{p}|\geq\Delta$.}\\
 We first use the Cauchy-Schwarz inequality $p\cdot x\leq \norm{p}\norm{x}$ to bound $f(x)$ above by the value
 \[
 \frac{1+\norm{p}\norm{x}}{\sqrt{(1+\norm{p}\norm{x})^2 + (\norm{x}-\norm{p})^2}}
 \]
 which achieves a maximum value with respect to $\norm{x}$ when $\norm{x}=\norm{p}$.
 But $|\norm{x}-\norm{p}|\geq\Delta$ so the maximum value must be achieved when $\norm{x}=\norm{p}+\Delta$ or $\norm{x}=\norm{p}-\Delta$.
 Thus
 \begin{align*}
 f(x)&\leq \frac{1+\norm{p}\norm{x}}{\sqrt{(1+\norm{p}\norm{x})^2 + (\norm{x}-\norm{p})^2}}\\
 &\leq \max\left(\frac{1+ \Delta \norm{p}+\norm{p}^2}{(1+ \Delta \norm{p}+\norm{p}^2)^2 + \Delta^2},\frac{1- \Delta \norm{p}+\norm{p}^2}{(1- \Delta \norm{p}+\norm{p}^2)^2 + (2\norm{p}-\Delta)^2}\right)
 \end{align*}

 \textbf{Case 2: $|\norm{x}-\norm{p}|\leq\Delta$.}\\
 We first observe
 \[
 \norm{x-p}^2 = (x-p)\cdot(x-p) = \norm{x}^2+\norm{p}^2-2p\cdot x
 \]
 to rewrite
 \[
 f(x) = \frac{1}{2}\frac{2+ \norm{p}^2+\norm{x}^2-\norm{x-p}^2}{\sqrt{(1+\norm{p}\norm{x})^2 + (\norm{x}-\norm{p})^2}} \leq \frac{1}{2}\frac{2+ \norm{p}^2+\norm{x}^2-\Delta^2}{\sqrt{(1+\norm{p}\norm{x})^2 + (\norm{x}-\norm{p})^2}}.
 \]
 Since we assume $\Delta<\norm{p}$, the bound achieves a maximum with respect to $\norm{x}$ when $\norm{x}=0$ and a minimum when $\norm{x}^2=\norm{p}^2-\Delta^2$.
 Since $|\norm{x}-\norm{p}|\leq\Delta$ and $\norm{p}-\Delta\leq \sqrt{\norm{p}^2-\Delta^2}\leq\norm{p+\Delta}$ this means the maximum is achieved again when $\norm{x}=\norm{p}+\Delta$ or $\norm{x}=\norm{p}-\Delta$.
 Thus
 \begin{align*}
 f(x)&\leq \frac{1}{2}\frac{2+ \norm{p}^2+\norm{x}^2-\Delta^2}{\sqrt{(1+\norm{p}\norm{x})^2 + (\norm{x}-\norm{p})^2}} \\
 &\leq \max\left(\frac{1+ \Delta \norm{p}+\norm{p}^2}{(1+ \Delta \norm{p}+\norm{p}^2)^2 + \Delta^2},\frac{1- \Delta \norm{p}+\norm{p}^2}{(1- \Delta \norm{p}+\norm{p}^2)^2 + (2\norm{p}-\Delta)^2}\right)
 \end{align*}

 In either case, we may bound $|f(x)|$ uniformly so that
 \[
 B_{p,\Delta} = \max\left(\frac{\norm{p}}{\sqrt{1+\norm{p}^2}},\frac{1+ \Delta \norm{p}+\norm{p}^2}{(1+ \Delta \norm{p}+\norm{p}^2)^2 + \Delta^2},\frac{1- \Delta \norm{p}+\norm{p}^2}{(1- \Delta \norm{p}+\norm{p}^2)^2 + (2\norm{p}-\Delta)^2}\right)
 \]
 for $p\neq0$.
 \end{proof}





