\section{Preliminaries}\label{sec:preliminaries}

\paragraph*{Basics}

Let $\Sigma = \{a_1,a_2,\dots,a_{\sigma}\}$ be a finite sorted set of \emph{letters} $a_1<a_2<\dots <a_\sigma$, which we call an \emph{alphabet}.
A \emph{finite word} $w = w[0]w[1]\cdots w[|w|-1]$ is any finite sequence of letters where $w[i] \in \Sigma$, for $i \in [0, |w|-1]$, and $|w|$ is the \emph{length} of the word.
%We let $\alp(w)$ denote the subset of letters of $\Sigma$ occurring in $w$.
The \emph{empty word}, denoted by $\varepsilon$, is the unique word of length $0$.
The set of all finite words (resp.~all non-empty words) over the alphabet $\Sigma$ is denoted by $\Sigma^*$ (resp.~$\Sigma^+$).
  For a letter $a_i\in\Sigma$, $|w|_{a_i}$ denotes the number of occurrences of $a_i$ in $w$. The vector $(|w|_{a_{1}},\ldots,|w|_{a_{\sigma}})$ is called the \emph{Parikh vector} of $w$.

 If $u = u[0]\cdots u[n-1]$ and $v = v[0]\cdots v[m-1]$ are words, the \emph{concatenation} $uv$ of $u$ and $v$ is $uv  = u[0] \cdots u[n-1] v[0] \cdots v[m-1]$.
 We let $\Pi^{k}_{i=1} w_i$ denote the concatenation of the words $w_1, w_2,\dots,w_k$ in that order, and $w^k$ the concatenation of the word $w$ with itself $k$ times.

 For any $1\leq i\leq j\leq |w|$, we use the notation $w[i,j]$ to denote the word $w[i]w[i+1]\cdots w[j]$, which we call a \emph{factor} of $w$.
 If $i>j$, then we assume $w[i,j]=\varepsilon$.
 We let $\fact(w)$ denote the set of all factors of $w$. For any $\La\subseteq\Sigma^*$, we write $\fact(\La)=\bigcup_{w\in\La}\fact(w)$.
 A factor of $w$ is \emph{proper} if it is different from $w$ itself.
 The factor $w[i,j]$ is called a \emph{prefix} when $i = 1$, and a \emph{suffix} when $j = n$. 
The \emph{longest common prefix} between two words $u$ and $v$ is the longest word that is a prefix of both words. The length of this word is denoted by $\lcp(u,v)$. The \emph{longest common suffix} and the associated function $\lcs$ are defined symmetrically.

  The \emph{run-length encoding} of a word $w$, denoted $\rle(w)$, is the sequence of pairs $(c_i, l_i$) with $c_i \in \Sigma$ and $l_i > 0$, such that $w = c_1^{l_1}c_2^{l_2}\cdots c_r^{l_r}$ and $c_i \neq c_{i+1}$ for every $i\in[1,r-1]$. The length $|\rle(w)|$ is the number of \emph{equal-letter runs} in $w$.

 A \emph{rotation}, or \emph{conjugate}, of the word $w=w[0]w[1]\cdots w[n-1]$ is a word of the form $w[i+1,n-1] w[0,i]$, for some $0\leq i< n$, obtained by shifting $i$ letters cyclically.
 We let $\R{w}$ denote the multiset of all the $|w|$ rotations of $w$.
 A word in $\cfact(w):=\fact(\R{w})$ is called a \emph{circular factor} of $w$.

%\paragraph*{Primitive words and Lyndon--Sch\"utzenberger Theorem}
A word $w$ is \emph{primitive} if for every word $u \in \Sigma^+$, $w = u^k$ implies $k = 1$; otherwise, $w$ is called \emph{non-primitive} (or \emph{a power}). A word of length $n$ is primitive if and only if it has exactly $n$ distinct rotations, i.e., if $\R{w}$ has all-distinct elements.
We let $\Prim{\Sigma^*}$ denote the set of all primitive words in $\Sigma^*$, and $\Pow{\Sigma^*}$  the set of all non-primitive words in $\Sigma^*$. 
We say two non-empty words $u,v$ \emph{commute} if $uv=vu$. This is equivalent to saying that both $uv$ and $vu$ are not primitive. 
In a well-known paper~\cite{lyndon}, Lyndon and Sch\"utzenberger established strong connections between primitive words and some equations in a free group. We report these classical results in the Appendix~\ref{ap:Lyndon}. 



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\paragraph*{Codes and morphisms}

A set $X\subseteq \Sigma^+$ is a \emph{code} if for all $m,\ell\geq 0$ and $u_i,v_j\in X$ with $i\in[1,\ell], j\in[1,m]$, the equation $u_1 u_2 \cdots u_\ell = v_1 v_2 \cdots v_m$ implies that $\ell = m$ and $u_k = v_k$, for all $k\in [1,\ell]$. Or equivalently, every word $w\in X^+$ has a unique factorization in words in $X$.
Given a word $w\in X^+$, a word $u$ is an \emph{$X$-factor} of $w$ if there exists a rotation $w'$ of $w$ (which can be $w$ itself) that can be factored as $w' = s u  p$ such that $u, ps\in X^*$.

Whenever a code $X$ consists of two words, the following property holds~\cite{Huang,Shyr77}.

\begin{lemma}
\label{le:codedontcommute}
    A set $X=\{u,v\}$, $u,v\in \Sigma^+$, is a code if and only if $u$ and $v$ do not commute, i.e., $uv\neq vu$.
\end{lemma}

If $u$ and $v$ do not commute, then they are not powers of the same word, but in principle this does not exclude the case that either $u$, $v$, or both are non-primitive. For example, $X=\{aa,bb\}$ is a code.

Let $\Sigma$ and $\Gamma$ be two alphabets. A \emph{morphism}  $\mu$ is a map from $\Sigma^*$ to  $\Gamma^*$ such that $\mu(uv) = \morph(u)\morph(v)$ for all words $u, v \in \Sigma^*$.
Therefore, a morphism $\mu$ can be defined by specifying its action on the letters of $\Sigma$, and can therefore be denoted as $\morph=(\mu(a_1),\ldots,\mu(a_\sigma))$. 
The \emph{size} of the morphism $\morph$ is defined as $|\morph| = \sum_{c\in\Sigma}|\morph(c)|$. 
When $\Sigma=\Gamma$, for all $t> 0$ and $w\in\Sigma^+$, we have $\morph^t(w)=\morph(\morph^{t-1}(w))$ and $\morph^0(w)=w$.

\begin{remark}\label{rem:rot}
Let $\morph$ be a morphism. If $w$ and $w'$ are conjugates, then so are  $\morph(w)$ and $\morph(w')$. Moreover, since every conjugate of a power is a power, if   $\morph(w)$ is a power, so is $\morph(w')$ for every conjugate $w'$ of $w$.
\end{remark}

A morphism $\mu$ is \emph{cyclic} if there exists $z\in \Gamma^+$ such that $\mu(a)\in z^*$ for each $a\in \Sigma$. Otherwise, it is called \emph{acyclic}.

As shown in the following proposition, there is a very strong relation between codes and injective morphisms.


\begin{proposition}[\cite{codesautomata}]
\label{prop:codesmorphism}
Let $X\subset \Gamma^*$ be a code. Then, any morphism $\morph: \Sigma^* \rightarrow \Gamma^*$ which induces a bijection of some alphabet $\Sigma$ onto $X$ is injective. Conversely, let $\morph : \Sigma^* \rightarrow \Gamma^*$ be an injective morphism. Then, $X = \morph(\Sigma)$ is a code.
\end{proposition}

%We call \emph{injective morphism} any morphism $\morph:\Sigma^*\rightarrow\Gamma^*$ such that $\morph(\Sigma)$ is a code.

%In the binary case, a morphism $\mu$ is cyclic if and only if $\mu(ab)=\mu(ba)$.  %Notice that $\morph=(\mu(a_1),\mu(a_2))$ is acyclic if and only if $X_{\mu}=\{\mu(a_1),\mu(a_2)\}$ is a code. 
By Lemma~\ref{le:codedontcommute} and Proposition~\ref{prop:codesmorphism}, one can easily derive that for a binary morphism $\morph:\{a,b\}^*\rightarrow\Gamma^*$, injectivity is equivalent to acyclicity, which in turn is equivalent to the condition $\morph(ab)\neq\morph(ba)$.




Examples of injective morphisms are the \emph{Fibonacci morphism}  $\fibmorph= (ab,a)$, the \emph{Thue--Morse morphism}  $\tmmorph=(ab,ba)$, and the \emph{period-doubling morphism} $\pdmorph=(ab,aa)$.


From the relationship between codes and morphisms, many properties of codes are reflected in the corresponding properties of injective morphisms. Combinatorial properties of injective morphisms are explored in Section 3. 

The Fibonacci morphism belongs to a wider class of morphisms called \emph{Sturmian morphisms}, strictly related to the well-known Sturmian words~\cite{DBLP:conf/mfcs/BerstelS93}. 
Sturmian morphisms can be defined as those that can be obtained by composition from: the Fibonacci morphism $\varphi$, the morphism $E=(b,a)$, and the morphism $\Tilde{\fibmorph}=(ba,a)$.

Let us suppose that both $\Sigma$ and $\Gamma$ are endowed with a total order relation that yields a lexicographic order, denoted by $<_{\Gamma}$ and $<_{\Sigma}$, respectively.
A morphism $\morph : \Sigma^* \rightarrow \Gamma^*$ is \emph{abelian order-preserving} if for every pair of distinct words $x,y\in \Sigma^*$ having the same Parikh vector, it holds that $x <_{\Sigma} y \iff \mu(x) <_{\Gamma} \mu(y)$. 
A morphism $\mu$ is \emph{abelian order-reversing} if for every pair of distinct words $x$ and $y$ having the same Parikh vector, it holds that $x <_{\Sigma} y \iff \mu(x) >_{\Gamma} \mu(y)$. We simply write $<$ whenever $\Sigma$ and $\Gamma$ are clear from the context.

When $\Sigma=\{a,b\}$, the following result holds.

\begin{lemma}[\cite{Fici23}]
\label{lem:abelian_order}
Let $\mu : \{a,b\}^* \mapsto \Gamma^*$ be an acyclic morphism.
Then $\mu$ is either abelian order-preserving or abelian order-reversing.
\end{lemma}

For our purposes, the fact that binary acyclic morphisms are either abelian order-preserving or abelian order-reversing is a crucial property, since it implies that they preserve or reverse the order on the set of rotations of any given binary word.

\paragraph*{Burrows--Wheeler transform}
The \emph{Burrows--Wheeler transform} (BWT) of a word $w$, denoted by $\bwt(w)$, is a permutation of the letters of $w$ obtained by sorting all the rotations of $w$ in ascending lexicographic order and then concatenating the last letter of each rotation.
The original word can be recovered if one stores the position where it appears in the list of sorted rotations.
Figure  \ref{fig:BWT} shows the sorted rotations of the word $w=\fibmorph^4(a)=abaababa$ and $bwt(w)=bbbaaaaa$.

We let $\rbwt(w)$ denote the number of equal-letter runs of $\bwt(w)$, i.e., $\rbwt(w)=|\rle(\bwt(w))|$. Such a value can be considered as a measure of the repetitiveness of $w$. In fact, if a word $w$ is highly repetitive, the number of equal-letter runs of its BWT tends to be small. From Figure \ref{fig:BWT}, one can see that $r(abaababa)=2$.

% A property of the BWT is that the $i$th occurrence of a symbol $c$ corresponds to the $i$th rotation starting with the same symbol $c$ in lexicographic order.
% Such a property is a direct consequence of the following lemma.

% \begin{lemma}\label{le:relativeorder}
%     Let $u,v\in\Sigma^n$ and $c\in\Sigma$. Then, $uc<vc$ if and only if $cu<cv$.
% \end{lemma}

One can easily verify that for each word $v\in \R{w}$, $\bwt(v)=\bwt(w)$ and, consequently, $r(v)=r(w)$ and  $r(\morph(v))=r(\morph(w))$ for every morphism $\morph$.

Let $w$ be a non-primitive word, i.e., $w=z^p$, for some $z\in \Sigma^+$ and $p>1$. It is well known that if $\bwt(z)=a_1a_2\cdots a_{|z|}$, then $\bwt(w)=a_1^pa_2^p\cdots a_{|z|}^p$~\cite{DBLP:journals/ipl/MantaciRS03}. This implies that $r(w)=r(z)$. 

Some results proved in~\cite{DBLP:journals/ipl/MantaciRS03, DBLP:journals/tcs/Paquin09, DBLP:journals/tcs/Chuan99} establish a strong connection between the BWT and Sturmian morphisms, as synthesized in the following theorem.

