\begin{theorem}
    \label{bwsturmian}
Let $w$ be a word over $\{a,b\}$ that is not a power of a single letter. Then the following are equivalent:
\begin{enumerate}
    %\item\label{circbal} $w$ is circularly balanced;
    %\item\label{conjstand} $w\in \mathcal{R}(s^\ell)$, for some standard Sturmian word $s$ and for some $\ell>0$;
    \item\label{morph0} $w=(\mu(a))^\ell$ for a Sturmian morphism $\mu$ and for some $\ell>0$.
    \item\label{2runs} $\rbwt(w)=2$.
    \end{enumerate}
\end{theorem}

