The next lemma provides a characterization of the structure of the set $P^\morph$ for an injective morphism $\morph$. The proof can be found in Appendix \ref{ap:Lyndon}.

\begin{lemma}
\label{le:P_mu_structure}
    Let $\morph = (u, v)$ be an injective morphism, and let $W = \{u^nv \mid n\geq1\} \cup \{uv^n \mid n>1\}$. We can distinguish the two cases:
    \begin{enumerate}
        \item \label{Pmu_1}$|W\cap \Pow{\{a,b\}^*}|=0$. Then only one of the following occurs:
    \begin{enumerate}
        \item \label{Pmu_1a}$P^\morph = \emptyset$; 
        \item \label{Pmu_1b}$P^\morph = \{c\}$, for some $c\in\{a,b\}$;
        \item \label{Pmu_1c}$P^\morph = \{a,b\}$.
    \end{enumerate}
    \item \label{Pmu_2}$|W\cap \Pow{\{a,b\}^*}|=1$. Then there exists a unique $w\in\{a,b\}^*$ such that $\morph(w)\in W\cap \Pow{\{a,b\}^*}$, and only one of the following occurs:
    \begin{enumerate}
        \item \label{Pmu_2a}$P^\morph = \R{w}$;
        \item \label{Pmu_2b}$P^\morph = \R{w}\cup\{c\}$, for some $c\in \{a,b\}$.
    \end{enumerate}
    \end{enumerate}
\end{lemma}

