\begin{theorem}
\label{th:primitivitynoncircular=thuemorse}
    Let $\morph:\{a,b\}^*\rightarrow\Gamma^*$ be a primitivity-preserving binary morphism. Then exactly one of the following cases occurs:
    \begin{enumerate}
        \item $\morph$ is recognizable;
        \item $\morph = \psi \circ \tau$ for some injective morphism $\psi$,  where $\tmmorph$ is the Thue--Morse morphism.
    \end{enumerate}
\end{theorem}

\begin{proof}
We show that, under the hypothesis of the theorem, it holds that $\morph=(uv,vu)$ if and only if $\morph = \psi\circ \tmmorph$ for some injective morphism $\psi$, and by Lemma~\ref{prop:purenotcircular=rotation}, the thesis directly follows. 
For the first direction, one can define $\psi=(u,v)$, and therefore $\morph=(\psi(\tmmorph(a)),\psi(\tmmorph(b))) = (\psi(ab),\psi(ba)) = (uv, vu)$.
For the other direction, if $\morph=\psi\circ\tau$, then $\morph = (\psi(\tau(a)), \psi(\tau(b))) = (\psi(ab),\psi(ba)) = (\psi(a)\psi(b), \psi(b)\psi(a))$,  and the thesis follows. 
\end{proof}

