The following lemma shows that cyclic morphisms produce words with a fixed number of BWT-runs, whatever the words on which they are applied. 

\begin{lemma}\label{le:cyclic_sensitivity}
Let $\morph:\{a,b\}^*\rightarrow\Gamma^*$ be a cyclic morphism. Then, there exist two constants $k^+_{\morph}, k^\times_\morph$, which depend on $\morph$, such that $\bwas(n) = k^+_\morph$ and $\bwms(n) = k^\times_\morph$, for all $n\geq2$.
\end{lemma}
\begin{proof}
Recall that a binary morphism is cyclic if and only if there exist two integers $t_1,t_2>0$ and a non-empty word $z\in\Gamma^+$ such that $\morph(a)=z^{t_1}$ and $\morph(b)=z^{t_2}$. Hence, for each word $w\in\Sigma^+$ it holds that $r(\morph(w)) = r(z^{|w|_{a}t_1+|w|_{b}t_2}) = r(z)$.
Let us fix the claimed constants $k_\morph = r(z)-2$ and $k'_\morph=r(z)/2$. 
For all $n\geq 2$, let us consider the word $s_n=a^{n-1}b$. By Lemma~\ref{bwsturmian}, it follows that $r(s_n)=2$.
The proof follows by observing that since $r(\morph(w))$ is constant, the values of $\Delta_\morph^+$ and $\Delta_\morph^\times$ are maximal when $r(w)$ assumes the smallest value, that in the case of binary words is $2$, i.e., $AS_\morph(n) = \max_{w \in \Sigma^n}(r(\morph(w) - r(w)) = r(z)-r(s_n) = k^+_\morph$ and $MS_\morph(n) = \max_{w \in \Sigma^n}(r(\morph(w)/r(w)) = r(z)/r(s_n) =k^\times_\morph$.
\end{proof}

\begin{example}
Let us consider the cyclic morphism $\mu=(ababbba,(ababbba)^2)$. It is possible to verify that for every $w\in\{a,b\}^+$, one has $\mu(w)=(ababbba)^p$, for some integer $p>0$ depending on $w$. This means that $r(\mu(w))=r(ababbba)=6$ for every $w\in\{a,b\}^+$. For every length $n$, we can consider the word $a^{n-1}b$. We have $r(a^{n-1}b)=2$, which is the lowest value that $r$ can take on a binary word. Then, $AS_{\mu}(n)=6-2=4$ and $MS_{\mu}(n)=6/2=3$, for $n\geq 2$. 
\end{example}

The following characterization of Sturmian morphisms in terms of the BWT additive sensitivity function was proved in~\cite{Fici23}.

\begin{proposition}[\cite{Fici23}]
\label{prop:sturmian0bwt}
Let $\morph$ be a binary injective morphism. Then $AS_\morph(n)=0$ for every $n\geq 2$ if and only if $\morph$ is a Sturmian morphism.
\end{proposition}

In the same paper, we showed that the Thue--Morse morphism $\tmmorph$ increases by 2 the BWT-runs of every binary word, while in the case of the period-doubling morphism $\pdmorph$, for each $n \geq 2$ we can find an $n$-length word $w$ for which $\Delta_\pdmorph^+(w) = \Theta(\sqrt{n})$.
We summarize these results in the following proposition.

\begin{proposition}[\cite{Fici23}]
\label{prop:tmpd}
Let $\tmmorph$ and $\pdmorph$ be the Thue--Morse and the period-doubling morphisms, respectively. The following properties hold:
\begin{enumerate}
\item \label{item:tm} $AS_\tmmorph(n)=2$, for all $n\geq 2$;
\item \label{item:pd} $AS_\pdmorph(n)=\Omega(\sqrt{n})$.
\end{enumerate}
\end{proposition}

Note that $\tmmorph$ is not the only morphism for which the additive sensitivity function is $2$. In~\cite{Fici23} it is proved that this property also holds for the \emph{Thue--Morse-like} morphisms $\tau_{p,q} = (ab^p, ba^q)$, for some $p,q > 0$, and any composition of these morphisms with any Sturmian morphism.  

\begin{example}
Let us consider the morphism $\morph=(abbaab,ababba)$. It is possible to verify that $\morph=\tmmorph \circ \fibmorph \circ \tmmorph$, where $\tmmorph$ and $\fibmorph$ are, respectively, the Thue--Morse and the Fibonacci morphism. By using Propositions~\ref{prop:sturmian0bwt} and~\ref{prop:tmpd}, item~\ref{item:tm}, it follows that $AS_\morph(n)=4$ for all $n\geq 2$.
\end{example} 


