\section{The theorem of Lyndon and Sch\"utzenberger and binary injective morphisms}
\label{ap:Lyndon}
Here, we report two classical results that are used in this paper to prove combinatorial properties of injective morphisms, and more specifically, of primitivity-preserving morphisms.


\begin{lemma}[\cite{lyndon}]
\label{commutepower}
Two words $u,v\in\Sigma^+$ commute if and only if there exist two integers $\ell,m\geq1$ and a word $z\in\Sigma^+$ such that $u=z^\ell$ and $v=z^m$.
\end{lemma}

More generally, the theorem of Lyndon and Sch\"utzenberger states that the word equation $u^\ell v^m=z^n$ has only trivial (i.e., periodic) solutions for $\ell,m,n\geq2$:

\begin{theorem}[\cite{lyndon}]
\label{lyndonS}
    Let $u,v,z\in\Sigma^+$ and $\ell, m, n\geq2$ such that $u^\ell v^m = z^n$. Then, there exists, and is unique, a primitive word $w$ such that $u=w^{t_1}$, $v = w^{t_2}$, and $z = w^{t_3}$, for some integers $t_1,t_2,t_3\geq1$.  
\end{theorem}

Notice that in the equation of Theorem~\ref{lyndonS} we can suppose, without loss of generality, that $|u|\geq|v|$, since $u^\ell v^m = z^n$ if and only if $v^m u^\ell = (z')^n$ for a rotation $z'$ of $z$. 
However, there can be nontrivial solutions when $\ell=1$ or $m=1$, and $n>1$. As an example, take $u=abba$, $v=b$. Then $uv^2=abba\cdot b \cdot b = (abb)^2$. In other words, the equation $u^\ell v=z^n$ (or $uv^m=z^n$) can have nontrivial solutions.

We now give the proof of Lemma \ref{le:P_mu_structure} in which we characterize the structure of the set of $\morph$--power words of an injective morphism $\morph$.
\begin{proof}[Proof of Lemma~\ref{le:P_mu_structure}]
Case~\ref{Pmu_1a} coincides with the definition of primitivity-preserving morphism.
Case~\ref{Pmu_1b} holds when only one between $u$ and $v$ is not primitive.
Case~\ref{Pmu_1c} holds when both $u$ and $v$ are not primitive.

Cases~\ref{Pmu_2a} and~\ref{Pmu_2b} both follow by Lemma~\ref{u*v*}, where we distinguish the case when either both $u$ and $v$ are primitive or only one between $u$ and $v$ is not primitive.
We now prove that there can not be further cases, that is if we fall in case~\ref{Pmu_2} then either $u$ or $v$ must be primitive.
By contradiction, let us assume that there exist $p,q\in\{a,b\}^*$ and $s,t >1$ such that $u = p^s$ and $v = q^t$, and let $m,n\geq1$ such that $w = a^m b^n$, and therefore $\morph(w) = u^m v^n = p^{ms} q^{nt} = z^k\in W\cap \Pow{\{a,b\}^*}$, for some primitive word $z$ and $k>1$. By Lemma~\ref{lyndonS}, it follows that $p$ and $q$ are powers of $z$, and by transitive relation so do $u$ and $v$, in contradiction with $\morph$ being an injective morphism.
\end{proof}

The following lemma reformulates~\cite[Theorem 8]{HolubRS23} and provides a parametric solution to Theorem~\ref{lyndonS}. It characterizes the structure of binary injective morphisms that map primitive words of length greater than $2$ to non-primitive words.
%considers the Cases~\ref{Pmu_2a} and~\ref{Pmu_2b}, in which $W\cap \Pow{\{a,b\}^*}\neq \emptyset$, and gives the classification of the corresponding not primitively preserving morphisms $\morph = (u, v)$ and their respectively $\morph$-power words. It reformulates ~\cite[Theorem 8]{HolubRS23} in the case of injective morphisms, which provides a parametric solution to the famous Lyndon-Schützenberger Theorem.  

%In Lemma~\ref{le: non_primitivepp_morph} we consider the case where $u$ and $v$ are not both primitive.
%In the following lemma we summarize the results from~\cite{HolubRS23} in terms of $\morph$-powers of a given injective morphism $\morph$.


\begin{lemma}
\label{le:Holub_classification}
    %Let $\morph=(u,v)$ be an injective morphism for some primitive words $u,v\in\{a,b\}^*$, and let us suppose $|u|\geq|v|$.
    Let $\morph=(u,v)$ be an injective morphism for some words $u,v\in\{a,b\}^*$ with $|u|\geq|v|$, and let $W = \{u^nv \mid n\geq1\} \cup \{uv^n \mid n>1\}$. If $W\cap \Pow{\{a,b\}^*}\neq \emptyset$, then exactly one of the following cases occurs:
    \begin{enumerate}
        \item $u= (pq)^m p$ and $v= q(pq)^n$, for some non-commuting words $p,q$ and two integers $m, n\geq0$ such that $m+n\geq1$. In this case, $W\cap \Pow{\{a,b\}^*} = \{uv\}$ and $\R{ab}\subseteq P^\morph$;
        \item $u=(pq^{n})^m p$ and $ v=q$, for some non-commuting words $p,q$ and three integers $m,n\geq1$.  In this case, $W\cap \Pow{\{a,b\}^*} = \{uv^n\}$ and $\R{ab^n}\subseteq P^\morph$;
        \item $u = pq(q(pq)^m)^{k-1})^n pq(q(pq)^m)^{k-2}qp$ and $v= q(pq)^m$, for some non-commuting words $p,q$ and three integers $k\geq2$, $m\geq1$, and $n\geq0$.  In this case, $W\cap \Pow{\{a,b\}^*} = \{uv^k\}$ and $\R{ab^k}\subseteq P^\morph$;
        \item $u =(pq)^m p$ and $v= qppq$, for some non-commuting words $p,q$ and an integer $m\geq2$.  In this case, $W\cap \Pow{\{a,b\}^*} = \{u^2v\}$ and $\R{a^2b}\subseteq P^\morph$.
    \end{enumerate}
\end{lemma}

Note that the hypothesis $|\morph(a)| \geq |\morph(b)|$ in Lemma~\ref{le:Holub_classification} is not restrictive, as when $|\morph(a)| < |\morph(b)|$ we can consider the morphism $\morph$ composed with the morphism $E$ that exchanges $a$ and $b$.

We give now the proof of Lemma \ref{prop:purenotcircular=rotation} in which we state that a binary primitivity-preserving morphism is not recognizable if and only if $\morph(a)$ and $\morph(b)$ are not conjugates.

\begin{proof}[Proof of Lemma \ref{prop:purenotcircular=rotation}]
    Without loss of generality, we can suppose throughout the proof that $|u|\geq|v|$.
    Observe that the statement is equivalent to: $\morph$ is not recognizable if and only if $\morph=(pq,qp)$ for some words $p,q$. 

    Let us prove the first direction by contraposition. If $\morph$ is injective and $u$ and $v$ are conjugates, then there exist two non-empty words $p,q$ such that $u=pq$ and $v=qp$.
    It is easy to see then that $pq,qp\in \{u,v\}^+$ but $p,q\notin \{u,v\}^+$, which by Lemma~\ref{le:rec=circ} implies that $\morph$ is not recognizable. 

    For the other direction, also by contraposition, if $\morph$ is not circular, then there exist $k,k'\geq0$ and $w\in \{u,v\}^+$ such that $w = x_1x_2\cdots x_k = q' y_2 \cdots y_{k'} p'$ with $y_1=p'q'$, $p',q'\neq \varepsilon$, and $x_1,x_2,\ldots,x_{k}, y_1,y_2,\ldots,y_{k'}\in \{u,v\}$.
    We now show that, under the above-mentioned conditions, if $u$ and $v$ are not conjugated, the morphism $\morph$ can not be primitivity-preserving, leading to a contradiction.

    Observe that both $u$ and $v$ have to occur in $w$ circularly in both the factorizations, otherwise, we end up having a prefix and a suffix of $u$ (or $v$) that commute, which by Lemma~\ref{commutepower} implies that $u$ (or $v$) is a power, contradicting the hypothesis of $\morph$ being primitivity-preserving.
    Let $X_\morph=\{u,v\}$.
    We can then distinguish three cases: (i) $u^2$ is a $X_\morph$-factor of $w$, (ii) $u^2$ is not a $X_\morph$-factor of $w$ and $uv^\ell u$ is, for some $\ell>0$, and (iii) neither $u^2$ nor $uv^\ell u$, for all $\ell>0$, are $X_\morph$-factors of $w$ but $uv^m$ is, for some $m>0$.
    For case (i), by~\cite[Proposition A]{RestR85} follows that $\morph(a^2b) = u^2 v$ is a power, and by Lemma~\ref{le:pure=primitive} this contradicts $\morph$ being primitivity-preserving.
    For case (ii), if $uv^\ell u$ is a $X_\morph$-factor of $w$ for some $\ell>0$ and $u^2$ is not, then $w\in uv^+(uv^+)^+$, and therefore $|w|\geq2|u|+2|v|$. By~\cite[Proposition B]{RestR85} follows that $\morph(ab^m) = uv^m$ is a power for some $m>0$, which again by Lemma~\ref{le:pure=primitive} it contradicts $\morph$ being primitivity-preserving.
    Finally, for case (iii), observe that if neither $u^2$ nor $uv^\ell u$ are $X_\morph$-factors of $w$ for all $\ell>0$, then there exist $i\in[1,k],j\in[1,k']$ such that $x_i,y_j=u$ and $x_{i'}=y_{j'}=v$ for all $i'\neq i$, $j'\neq j$. This implies that $k=k'>1$ and that two rotation words coincide, and by Lemma~\ref{commutepower} follows that $\morph(ab^{k-1})=uv^{k-1}$ is a power, i.e. $\morph$ is not primitivity-preserving, and the thesis follows.
\end{proof}

The following result is used to show that it is possible to test in polynomial time, with respect to the total length of the images of the letters, whether a morphism is BWT-run preserving.

\begin{theorem}[\cite{HolubRS23}]
\label{th:holub}
 Let $\morph=\{u,v\}$ be an injective morphism, with $|u|\geq |v|$, and let $W = \{u^nv \mid n\geq1\} \cup \{uv^n \mid n>1\}$. If there exists a primitive word $z$ such that $u^\ell v^m = z^n$ for some $\ell,m\geq1$, $n>1$, then: 
 \begin{enumerate}
     \item if $\ell>1$,  $\ell = n = 2$ and $m=1$;
     \item if $\ell = 1$,  $1\leq m \leq \frac{|u|-4}{|v|}+2$.
 \end{enumerate}
\end{theorem}

