\section{Proofs of Propositions \ref{prop:rho_unbounded_AS} and \ref{prop:unbounded_increase_wk_power_morphisms}}
\label{ap:prop3435}

\begin{definition}[\cite{Giuliani2025}]\label{def:w_k}
For every $k > 5$,  let $s_i = ab^iaa$ and $e_i = ab^iaba^{i-2}$ for all $2 \leq i \leq k-1$, and $q_k = ab^ka$.
We define the word $$w_k = \left(\prod_{i=2}^{k-1}s_i e_i\right)q_k = \left(\prod_{i=2}^{k-1}ab^iaa ab^iaba^{i-2}\right)ab^ka.$$ 
\end{definition}


\begin{proof}[Proof of Proposition~\ref{prop:rho_unbounded_AS}]
Let us consider the family of words $w_k$ from Definition~\ref{def:w_k}.
First note that $\rho_p = (a, b^p)$ is abelian order-preserving. This implies that the last letters of the range of rotations starting with $a$ in the BWT matrix of $\rho_p(w_k)$ spell exactly $\bwt(w_k)[1,|w_k|_a]$. Similarly, the last characters of the (disjoint) ranges of rotations starting with $b^{ip}a$ for $i \in [1,k]$ spell exactly $\bwt(w_k)[|w_k|_a+1,|w_k|]$. Moreover, it has been shown in \cite{Giuliani2025} that the blocks of rotations of $w_k$ starting with $b^ia$, for some $i \in [1, k]$, spell a substring of $\bwt(w_k)$ that begins and ends with the letter $a$. Hence, the same holds for the blocks $b^{ip}a$ in $\rho_p(w_k)$. Strictly in between the ranges of rotations starting with $b^{(i-1)p}a$ and $b^{ip}a$ for some $i \in [2,k]$, there is a range of rotations starting with $b^{(i-1)p+s}a$ for each $s \in [1,p-1]$, all ending with the character $b$. These new blocks of rotations increase the number of runs by $2$ each,  and there are $k-1$ of them. Since $k=\Theta(\sqrt{n})$, the claim holds.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{prop:unbounded_increase_wk_power_morphisms}]
The composed morphism maps $a$ to $u^p$ and $b$ to $v^q$ through the substitution chains

$$a \xrightarrow{E} b  \xrightarrow{\rho_p} b^p \xrightarrow{E} a^p \xrightarrow{\rho_q} a^p \xrightarrow{\eta} u^p \text{ and } b \xrightarrow{E} a \xrightarrow{\rho_p} a \xrightarrow{E} b \xrightarrow{\rho_q} b^q \xrightarrow{\eta} v^q.$$

For the second claim, note that $AS_{\mu}(n) \ge AS_{\rho_p}(n)$, as $$r(\mu(E(w))) - r(E(w)) = r(\eta \circ \rho_q \circ E \circ \rho_p (w)) - r(w) \ge r(\rho_p(w)) - r(w)$$ holds for any word $w$. Similarly, when $p = 1$, it holds $AS_{\mu}(n) \ge AS_{\rho_q}(n)$, as
$$r(\mu(w)) - r(w) = r(\eta \circ \rho_q(w)) - r(w) \ge r(\rho_p(w)) - r(w).$$ 
By Proposition \ref{prop:rho_unbounded_AS}, when $pq > 1$, the claim follows.
\end{proof}


