\subparagraph{Infimum and supremum walks.}%\label{subsec:3:infsup}
Given an integer $j$, we denote by $[j]$ the set $\{1,\ldots, j\}$. Given an NFA $\mathcal{A}=(Q,\delta,\Sigma,s)$, and a state $u \in Q$, we say that a \textit{walk to} $u$, denoted as $P_{u} = (u_{i})_{i=1}^{l}$, is a non-empty sequence of $l$ states from $Q$ that satisfies the following conditions: 
$(i)$ $u_{1}=u$, and 
$(ii)$ for each $i \in [l-1]$, $u_{i} \in \delta_{a}(u_{i+1})$ where $a=\lambda(u_i)$. Moreover, we denote by $P_{u} = (u_{i})_{i\geq1}$ a walk of infinite length to $u \in Q$. We define $I_{u}$ as the set of all strings $\alpha \in \Sigma^{\omega}$, for which there exists a walk $P_{u} = (u_{i})_{i\geq1}$ such that $\alpha = \lambda(u_{1}) \lambda(u_{2}) \lambda(u_{3}) \ldots$. We now provide the definition of supremum and infimum strings of an NFA's state, which was introduced by Conte et al.~\cite{conte2023dcc} and Kim et al.~\cite[Definition 7]{kim2023faster}.

%\vspace{-3pt}
\begin{definition}[Infimum and supremum strings]\label{def:2:inf_sup_str}
    Let $\mathcal{A}$ be an NFA, and let $u$ be a state of $\mathcal{A}$. Then, the \emph{infimum string} of $u$, denoted $\inf I_{u}$, is the lexicographically smallest string in $I_{u}$. The supremum string of $u$, denoted $\sup I_{u}$, instead is the lexicographically largest string  $I_{u}$.
    %\nicola{I'm not 100\% sure if this definition is well-defined: in \cite{kim2023faster} we used limits. Note that we also considered $I_u$ to contain omega-strings, like you do. Note: that paper had a mistake in the definition of infimum/supremum. It was later fixed in \url{https://doi.org/10.4230/LIPIcs.CPM.2024.1}}\carlo{It should be well-defined, I the definition from a paper of Nicola C. Unfortunately I cannot use your definition, because you also consider strings of finite length, while we do not do that here.}
\end{definition}
%\ruben{Put a comment here that the definition of Kim et al.\ and the one here are equivalent, maybe refer to Nicola C.'s paper, where the same definition is used.}
It is easy to demonstrate that for each $u \in Q$, the strings $\inf I_{u}$ and $\sup I_{u}$ exist (for instance, it follows from Observation~8 in the work of Kim et al.~\cite{kim2023faster}, see also \cite{cotumaccio2023isaac}). We now provide the definition of infimum and supremum walks. 

\begin{definition}[infimum and supremum walks]\label{def:3:inf_sup_walks}
    Let $\mathcal{A}$ be an NFA, and let $u$ be a state in $\mathcal A$. Consider $\alpha = \inf I_{u}$ and $\beta = \sup I_{u}$ and a walk $P_{u} = (u_{i})_{i\geq1}$, then we say that:
    \begin{itemize}
        \item $P_{u}$ is an \emph{infimum walk to} $u$, denoted as $P_{u}^{\inf}$, if for each integer $i \geq 1$, $\lambda(u_{i}) = \alpha_{i}$.

        \item $P_{u}$ is a \emph{supremum walk to} $u$, denoted as $P_{u}^{\sup}$, if for each integer $i \geq 1$, $\lambda(u_{i}) = \beta_{i}$.
    \end{itemize}

\end{definition}
% \vspace{-3pt}
In other words, a walk to $u$ is an infimum (supremum) walk, if it is labeled with the infimum (supremum) string of $u$.

% \vspace{-5pt}
\subparagraph{Co-lex orders.}

A partial order $\leq$ on a set $U$ is a reflexive, antisymmetric and transitive relation on $U$. Given a partial order $\leq$ on a set $U$, for each $u,v \in U$, we write $u < v$ if $u \leq v$ and $u \neq v$. We now report the formal definition of co-lex order of an NFA, which was first introduced by Cotumaccio and Prezza \cite[Definition 3.1]{cotumaccio2021indexing}.
\begin{definition}[Co-lex order]\label{def:3:colex_order}
    Let $\mathcal{A}$ be an NFA. A \emph{co-lex order} of $\mathcal{A}$ is a partial order $\leq$ over $Q$ that satisfies the following two axioms:
    \begin{enumerate}
        \item For each $u,v \in Q$, if $u \leq v$, then $\lambda(u) \leq \lambda(v)$.
        \item For each pair $u \in \delta_{a}(u')$ and $v \in \delta_{a}(v')$, if $u < v$, then $u' \leq v'$.
    \end{enumerate}
\end{definition}

Note that every NFA $\mathcal{A}=(Q,\delta,\Sigma,s)$ admits a co-lex order; in fact, the partial order $\leq \coloneqq \{(u,u) : u \in Q \}$ trivially satisfies the two axioms of Definition~\ref{def:3:colex_order}. We say that a co-lex order $\leq$ of an automaton $\mathcal{A}$ is the \textit{maximum} co-lex order of $\mathcal{A}$ if $\leq$ is equal to the union of all co-lex orders of $\mathcal{A}$. Becker et al.~\cite[Lemma 3]{tosoni2024CFS} showed that every forward-stable NFA admits a maximum co-lex order. Hereafter, we will denote by $\leq_{FS}$ the maximum co-lex order of an NFA. 

\begin{observation}\label{trv_obs}
    Let $\mathcal{A}$ be a forward-stable NFA, and let $u,v$ be two states of $\mathcal{A}$ such that $\lambda(u) < \lambda(v)$. Then $u <_{FS} v$.
\end{observation}

\begin{proof}
    Consider the partial order $\leq$ defined as follows; $\leq \coloneqq \{(z,z) : z \in Q \} \cup \{(u,v)\}$. $\leq$ is a co-lex order of $\mathcal{A}$, as it does not violate the axioms of Definition~\ref{def:3:colex_order}. Therefore, since $\leq_{FS}$ is defined as the union of every co-lex order of $\mathcal{A}$, it follows that $u <_{FS} v$ holds.
\end{proof}

% \vspace{-5pt}
\subparagraph{Preceding pairs.} 
We start with the definition of preceding pairs~\cite[Definition 6]{cotumaccio2022graphs}.
\begin{definition}[Preceding pairs]\label{def:4:prec_pairs}
    Let $\mathcal{A}$ be an NFA and let $(\bar{u},\bar{v}),(u,v) \in Q \times Q$ be  pairs of distinct states. We say that $(\bar{u},\bar{v})$ \emph{precedes} $(u,v)$, denoted by $(\bar{u},\bar{v}) \rightrightarrows (u,v)$, if there exist two walks, $P_{u} = (u_{i})_{i=1}^{l}$ and $P_{v} = (v_{i})_{i=1}^{l}$, such that (i)~$u_{l} = \bar{u}$ and $v_{l} = \bar{v}$, (ii)~for each $i \in [l]$, $u_{i} \neq v_{i}$, and (iii)~for each $i \in [l-1]$, $\lambda(u_{i}) = \lambda(v_{i}) = a$, for some $a \in \Sigma$.
\end{definition}

Note that if $u,v \in Q$ are distinct states, then the pair $(u,v)$ trivially precedes itself. The following observation directly follows from Definition~\ref{def:4:prec_pairs}.

% \vspace{-3pt}
\begin{observation}\label{trivial:obs:precpair}
    The relation $(\bar{u},\bar{v}) \rightrightarrows (u,v)$ is transitive. 
\end{observation}
% \vspace{-3pt}

Preceding pairs characterize the maximum co-lex order of a forward-stable NFA as follows.

% \vspace{-3pt}
\begin{restatable}[]{corollary}{cori}\label{lem:4:prec_pairs_colex}
    Let $\mathcal{A}$ be a forward-stable NFA and let $\leq_{FS}$ be its maximum co-lex order. Then  $u <_{FS} v$ holds for two distinct states $u,v$ in of $\mathcal{A}$ if and only if, for each pair $(\bar{u},\bar{v})$ with $(\bar{u},\bar{v}) \rightrightarrows (u,v)$, it holds that $\lambda(\bar{u}) \leq \lambda(\bar{v})$.
\end{restatable}
% \vspace{-3pt}

\begin{proof}
    Let $u$ and $v$ be two distinct states. Following~\cite[Lemma 7]{cotumaccio2022graphs}, $(u,v)$ is contained in the maximum co-lex relation (see~\cite[Definition 4]{cotumaccio2022graphs}) if and only if $\lambda(\bar{u}) \leq \lambda(\bar{v})$ for every pair $(\bar u, \bar v)$ with $(\bar{u},\bar{v}) \rightrightarrows (u,v)$. The maximum co-lex order $\leq_{FS}$ of a forward-stable NFA $\mathcal{A}$ is equal to its maximum co-lex relation according to~\cite[Lemma 3]{tosoni2024CFS}.
\end{proof}

Note that for any distinct states $u,v$ of $\mathcal{A}$, the statement $\neg(u <_{FS}v)$ holds if and only if there exists $(\bar{u},\bar{v}) \rightrightarrows (u,v)$ with $\lambda(\bar{u}) > \lambda(\bar{v})$. We now define \textit{co-lex extensions}.

% \vspace{-3pt}
\begin{definition}[Co-lex extension]\label{linear_ext}
    Let $\mathcal{A}$ be a forward-stable NFA and $Q$ its set of states. Consider the maximum co-lex order $\leq_{FS}$ of $\mathcal{A}$. Then, a total order $\leq$ on $Q$ is a \emph{co-lex extension} of $\mathcal{A}$, if $\leq_{FS}\; \subseteq\; \leq$.
\end{definition}
% \vspace{-3pt}

Due to Lemma 11 of the work of Becker et al.~\cite{becker2023sorting}, it follows that the \emph{ordered partition refinement}~\cite[Algorithm 1]{becker2023sorting} represents a feasible algorithm for computing a co-lex extension.

\begin{restatable}[]{lemma}{lemi}\label{lem:4:inv_prop}
    Consider a forward-stable NFA $\mathcal{A} = (Q,\delta,\Sigma,s)$. Moreover, let $\leq_{FS}$ and $\leq$ be the maximum co-lex order and a co-lex extension of $\mathcal{A}$, respectively. Then, for every $u,v \in Q$ such that $u < v$, there exists a pair $(\bar{u},\bar{v})$ with $(\bar{u},\bar{v}) \rightrightarrows (u,v)$ such that $\lambda(\bar{u}) < \lambda(\bar{v})$.
\end{restatable}

\begin{proof}
    According to Definition~\ref{linear_ext} $u < v$ implies $\neg(v <_{FS}u)$. Corollary~\ref{lem:4:prec_pairs_colex} then yields that there exists $(\bar{u}, \bar{v})$ with $(\bar{u},\bar{v}) \rightrightarrows (u,v)$ such that $\lambda(\bar{u}) < \lambda(\bar{v})$.
\end{proof}

% \section{Relation between the maximum co-lex order and infimum/supremum walks}\label{sec:4}
\section{Infimum and Supremum Walks}
\label{section: infimum supremum walks}

In this section we prove structural properties of infimum and supremum walks in a forward-stable NFA $\mathcal A$. At the end of the section we define left-minimal infimum and right-maximal supremum walks, the special type of infimum/supremum walks that our data structure is based on.
As before, we let $\leq_{FS}$ be the maximum co-lex order of $\mathcal{A}$, and $\leq$ be a co-lex extension of $\mathcal{A}$. We further denote by $n$ the number of states of $\mathcal{A}$.
The following lemma states that infimum and supremum can be compared using their first $2n - 1$ characters (see \cite{conte2023dcc, alanko2024cpm, cotumaccio2023spire} for similar results).

% \vspace{-3pt}
\begin{restatable}[]{lemma}{lemiv}\label{2nbound}
   Let $ \mathcal{A} $ be an NFA with set of states $ Q $, where $ |Q| = n $, and let $ u, v \in Q $. If $ \sup I_u \not = \inf I_v $, then $ \sup I_u [1, 2n - 1] \not = \inf {I_v} [1, 2n - 1] $.
\end{restatable}

\begin{proof}    
    Let $ C $ be the set consisting of all strings $ \sup I_u $'s and all strings $ \inf I_u $'s, and write $ C = \{\gamma_1, \gamma_2, \dots, \gamma_{n'} \} $ where $ \gamma_1 < \gamma_2 < \dots < \gamma_{n'} $. Then, $ n' \le 2n $. Notice that for every $ u \in Q $, by the maximality of $ \sup I_u $ there exist $ c_1 \in \Sigma $ and $ u_1 \in Q $ such that $ \sup I_u = c_1 \sup I_{u_1} $, and by the minimality of $ \inf I_v $ there exist $ c_2 \in \Sigma $ and $ u_2 \in Q $ such that $ \inf I_u = c_2 \inf I_{u_2} $. This implies that for every $ 2 \le i \le n' $ there exist $ c \in \Sigma $ and $ 2 \le i' \le n' $ such that $ \gamma_i = c \gamma_{i'} $. We define the array $ \mathsf{LCP}[2, n'] $ such that $ \mathsf{LCP}[i] = \mathsf{lcp}(\gamma_{i - 1}, \gamma_i) $, where $ \mathsf{lcp}(\alpha, \beta) $ is the length of the longest common prefix between $ \alpha $ and $ \beta $. To prove the lemma it is sufficient to show that $ \mathsf{LCP}[i] \le n' - 2 $ for every $i$ with $ 2 \le i \le n' $. To prove this it is sufficient to show that if $\mathsf{LCP}[i] = d$ for some $d \geq 1$ and $i$ with $2 \leq i \leq n'$, then there exists $j$ with $ 2 \le j \le n' $ such that $ \mathsf{LCP}[j] = d - 1$, because then we obtain that $ \mathsf{LCP} $ has at least $ d + 1 $ distinct entries, so $ d + 1 \le n' - 1 $, which implies $ d \le n' - 2 $. Assume that $ \mathsf{LCP}[i] = d $, with $ d \ge 1 $.  Let $ c_1, c_2 \in \Sigma $ and $ 2 \le i', i'' \le n' $ be such that $ \gamma_i = c_1 \gamma_{i'} $ and $ \gamma_{i - 1} = c_2 \gamma_{i''} $. Since $ 1 \le d = \mathsf{LCP}[i] = \mathsf{lcp}(\gamma_{i - 1}, \gamma_i) = \mathsf{lcp}(c_1 \gamma_{i'}, c_2 \gamma_{i''}) $, we have $ c_1 = c_2 $ and from $ \gamma_{i - 1} < \gamma_i $ we obtain $ \gamma_{i''} < \gamma_{i'} $, which implies $ i'' < i' $. Then, $ \mathsf{LCP}[i] = 1 + \mathsf{lcp}(\gamma_{i'},  \gamma_{i''}) = 1 + \min_{i' + 1 \le j \le i''} \mathsf{lcp}(\gamma_{j - 1},  \gamma_{j}) = 1 + \min_{i' + 1 \le j \le i''} \mathsf{LCP}[j] $, so there exists $ i' + 1 \le j \le i'' $ such that $ d = \mathsf{LCP}[i] = 1 + \mathsf{LCP}[j] $, which implies $ \mathsf{LCP}[j] = d - 1 $.
\end{proof}
% \vspace{-3pt}

%because if $ \sup I_u = \gamma_k $ and $ \inf I_v = \gamma_{k'} $, where without loss of generality $ k < k' $, then $ \mathsf{lcp}(\sup I_u, \inf I_v) = \mathsf{lcp}(\gamma_k, \gamma_{k'}) = \min_{k + 1 \le i \le k'} \mathsf{lcp}(\gamma_{i - 1}, \gamma_i) = \min_{k + 1 \le i \le k'} \mathsf{LCP}[i] \le n' - 2 \le 2n - 2 $ and so $ \sup I_u [1, 2n - 1] \not = \inf {I_v} [1, 2n - 1] $.

% We will from now on fix a forward-stable NFA $\mathcal A$, its maximum co-lex order $\le_{FS}$, and a co-lex extension $\le$. Furthermore, we will denote by $n$ the number of states in $\mathcal{A}$.
The following lemma treats the case in which the relation between the supremum and infimum of two states already implies their respective order with respect to $\le_{FS}$.
% \vspace{-3pt}
\begin{restatable}[]{lemma}{lemii}\label{lem:5:sup_inf_co_lex}
    Let $u, v$ be two distinct states. Then, $\sup I_{u} \leq \inf I_{v}$ implies $u <_{FS}v$.
\end{restatable}
% \vspace{-3pt}

\begin{proof}
     We show the contrapositive. Assume that $\neg(u <_{FS} v)$. By Corollary~\ref{lem:4:prec_pairs_colex}, this implies the existence of a pair $(\bar{u},\bar{v})$ with $(\bar{u},\bar{v})\rightrightarrows(u,v)$ such that $\lambda(\bar{u})> \lambda(\bar{v})$. 
     %Let us now consider the walks $P_{u} = (u_{i})_{i=1}^{l}$ and $P_{v} = (v_{i})_{i=1}^{l}$ for which $(\bar{u},\bar{v})\rightrightarrows(u,v)$. Therefore, $u_1 = u, v_1 = v, u_l = \bar{u}, v_l = \bar{v}$. Furthermore, consider the strings $\alpha' = \lambda(u_{1})\lambda(u_{2})\ldots \lambda(u_{l}), \beta' = \lambda(v_{1})\lambda(v_{2})\ldots \lambda(v_{l})$. By Definition~\ref{def:4:prec_pairs}, we know that $\alpha'[1,l-1] = \beta'[1,l-1]$. From $\lambda(\bar{u})> \lambda(\bar{v})$, we conclude that $\alpha' > \beta'$.
     By Definition~\ref{def:4:prec_pairs}, this implies that there exist two walks $P_{u} = (u_{i})_{i=1}^{l}$ and $P_{v} = (v_{i})_{i=1}^{l}$ with $u_1 = u, v_1 = v, u_l = \bar{u}, v_l = \bar{v}$ such that $\alpha'= \beta'$ where $\alpha' := \lambda(u_{1})\lambda(u_{2})\ldots \lambda(u_{l-1})$ and $\beta' := \lambda(v_{1})\lambda(v_{2})\ldots \lambda(v_{l-1})$.
     Now recall that every state is reachable from the initial state $s$ and $s \in \delta(s,\#)$. Thus there exist infinite strings $\alpha'' \in I_{\bar{u}}$ and $\beta'' \in I_{\bar{v}}$. Note that $\alpha''>\beta''$ because $\lambda(\bar{u})>\lambda(\bar{v})$. Since $\alpha = \alpha'\alpha''\in I_u$ and $\beta = \beta'\beta''\in I_v$, 
     %and furthermore $\alpha' > \beta'$ and $\beta'$ is not a prefix of $\alpha'$ implies $\alpha > \beta$. 
     we obtain $\sup I_{u} \geq \alpha = \alpha'\alpha'' = \beta'\alpha'' > \beta'\beta'' = \beta \geq \inf I_{v}$, completing the proof.
\end{proof}

With the next lemma we show a case in which we can determine if $\neg(u <_{FS} v)$ holds.

% \vspace{-3pt}
\begin{restatable}[]{lemma}{lemv}\label{lem:5:sup_inf_vs_walks}
    Let $u, v$ be two states with $u < v$ and $\sup I_{u} > \inf I_{v}$. Furthermore, let $P_{u}^{\sup} = (u_{i})_{i\geq1}$ and $P_{v}^{\inf} = (v_{i})_{i\geq1}$. Then there exists an integer $j$ with $1 < j < 2n$ such that $v_{j} < u_{j}$ and  $u_{i} \leq v_{i}$ as well as $\lambda(u_{i}) = \lambda(v_{i})$ for each $i \in [j-1]$. In addition, if $u_{i} < v_{i}$ holds for all $i\in [j - 1]$, then $\neg(u <_{FS} v)$.
\end{restatable}
% \vspace{-3pt}

\begin{proof}
    Consider $\alpha = \sup I_{u}$ and $\beta = \inf I_{v}$. Let $k$ be the maximal integer such that $\alpha[1,k-1] = \beta[1,k-1]$. Since $\alpha > \beta$, it holds that $\lambda(u_{k}) > \lambda(v_{k})$. By Lemma~\ref{2nbound}, $k < 2n$. Moreover, by Observation~\ref{trv_obs}, $\lambda(u_{k}) > \lambda(v_{k})$ implies $v_{k} <_{FS} u_{k}$ which, by Definition~\ref{linear_ext}, in turn implies $v_{k} < u_{k}$. Therefore, if we define $j>1$ as the smallest integer for which $v_{j} < u_{j}$, then clearly for each $i \in [j-1]$, $u_{i} \leq v_{i}$. Moreover, since $j \leq k$, and $\alpha[1,k-1] = \beta[1,k-1]$, for each $i \in [j-1]$, it holds that $\lambda(u_{i}) = \lambda(v_{i})$. For the second part of the lemma, if $u_{i} < v_{i}$ (implying $u_{i}\ne v_{i}$) for each $i \in [j-1]$, then $(u_{j},v_{j})\rightrightarrows(u,v)$ by definition. Since $v_{j} < u_{j}$, by Lemma~\ref{lem:4:inv_prop}, there exists $(\bar{u},\bar{v})\rightrightarrows(u_{j},v_{j})$ with $\lambda(\bar{u}) > \lambda(\bar{v})$. Thus, by Observation~\ref{trivial:obs:precpair} it holds that $(\bar{u},\bar{v})\rightrightarrows(u,v)$ which by Corollary~\ref{lem:4:prec_pairs_colex} proves that $\neg(u <_{FS} v)$.
\end{proof}

We summarize what we achieved show so far. Given two distinct states $u,v$, to understand whether or not $u <_{FS} v$ holds we can proceed as follows. If according to a co-lex extension $\leq$, the statement $v < u$ holds, by Definition~\ref{linear_ext}, we know $\neg(u <_{FS} v)$. If $u < v$, then if $\sup I_{u} \leq \inf I_{v}$, by Lemma~\ref{lem:5:sup_inf_co_lex}, we know that $u <_{FS} v$. Otherwise, consider a supremum walk to $u$, $(u_{i})_{i\geq1}$, and an infimum walk to $v$, $(v_{i})_{i\geq1}$. If $\sup I_{u} > \inf I_{v}$, and there exists $j$ such that $v_{j} < u_{j}$ and  $u_{i} < v_{i}$ for each $i\in [j-1]$, then by Lemma~\ref{lem:5:sup_inf_vs_walks} $\neg(u <_{FS} v)$. See Figure~\ref{fig:6:enc_ex} for an example. The only remaining case to address is the existence of an integer $j'\in [j-1]$ such that $u_{j'} = v_{j'}$. 
To study this case, we introduce left-minimal (right-maximal) walks. 

% \vspace{-5pt}
\subparagraph{Left-minimal/right-maximal walks.}
We proceed with the definition of \emph{left-minimal infimum walks} and \emph{right-maximal supremum walks}. We first define infimum and supremum graphs.

\begin{definition}[Infimum and supremum graphs]\label{def:6:inf_sup_nfa}
     The \emph{infimum (supremum) graph} $G=(Q,E)$ of $\mathcal{A}$ is the directed unlabeled graph defined as follows: (i)~The node set of $G$ is identical to the one of $\mathcal A$. (ii)~For each $u,v \in Q$, we let $(u,v) \in E$ if and only if there exists an infimum (supremum) walk $(u_{i})_{i\geq 1}$ to a state $u' \in Q$ and an integer $j$ such that $u_{j+1} = u$ and $u_{j} = v$.
\end{definition}
We can now prove the following observation.
\begin{restatable}[]{observation}{obsii}\label{obs:6:walk_inf_sup_nfa}
    Let $\mathcal{A}$ be an NFA and let $G$ be its infimum (supremum) graph. Then, every walk of infinite length in $G$ is an infimum (supremum) walk in $\mathcal{A}$.
\end{restatable}

\begin{proof}
    Let $u$ be a state of $\mathcal{A}$, and let $P_{u} = (u_{i})_{i \geq 1}$ be an arbitrary walk of infinite length. We prove this result for infimum walks, the proof for the supremum walks is analogous. Suppose for the sake of a contradiction that $P_{u}$ is not an infimum walk. We consider the largest integer $j$ for which there exists an infimum walk $P_{u}^{\inf} = (\bar{u}_{i})_{i\geq1}$, such that, for each $i\in [j]$, $\bar{u}_{i} = u_{i}$. Thus, $\bar{u}_{j+1} \neq u_{j+1}$. By Definition~\ref{def:6:inf_sup_nfa}, there exists a state $v$, an infimum walk $P_{v}^{\inf} = (v_{i})_{i\geq1}$, and an integer $k$ for which $v_{k} = u_{j}$ and $v_{k+1} = u_{j+1}$. Consider $\alpha = \lambda(\bar{u}_{1}) \ldots \lambda(\bar{u}_{j})$, $\gamma = \lambda(\bar{u}_{j+1})\lambda(\bar{u}_{j+2})\ldots\,$, $\beta = \lambda(v_{1}) \ldots \lambda(v_{k})$, $\gamma' =  \lambda(v_{k+1})\lambda(v_{k+2})\ldots\,$, we know $\inf I_{u} = \alpha\gamma$, $\inf I_{v} = \beta\gamma'$. Moreover, consider the walks $P_{u}' = (\hat{u}_{i})_{i\geq1}$, where for each $i \in [j]$, $\hat{u}_{i} = \bar{u}_{i}$, and for each $i \geq j$, $\hat{u}_{i} = v_{i+k-j}$, and $P_{v}' = (\hat{v}_{i})_{i\geq1}$, where, for each $ i \in [k]$, $\hat{v}_{i} = v_{i}$, and, for each $i \geq k$, $\hat{v}_{i} = \bar{u}_{i+j-k}$. We know that $\alpha\gamma' \in I_{u}$ and $\beta\gamma \in I_{v}$. By Definition~\ref{def:3:inf_sup_walks}, $\alpha\gamma \leq \alpha\gamma'$ which implies $\gamma \leq \gamma'$, and $\beta\gamma' \leq \beta\gamma$ which implies $\gamma' \leq \gamma$. Thus $\gamma = \gamma'$. Consequently, $P_{u}'$ is an infimum walk. However, $\hat{u}_{j} = u_{j}$ and $\hat{u}_{j+1} = u_{j+1}$, a contradiction. 
\end{proof}

We now introduce leftmost/rightmost walks in directed (unlabeled) graphs. 

\begin{definition}[Leftmost/rightmost walk]\label{def:leftmost}
     Let $ G = (V, E) $ be a directed graph, let $\leq$ be a total order on $V$ and let $ u \in V $. A walk $P_{u}= (u_{i})_{i \ge 1}$ is a \emph{leftmost (rightmost)} walk to $u$, if for each walk $\bar{P}_u=(\bar{u}_i)_{i \geq 1} $ and integer $j > 1$, $u_j = \bar{u}_j$ implies $u_{j - 1} \leq \bar{u}_{j - 1}$ $(\bar{u}_{j - 1} \leq u_{j - 1})$.
\end{definition}
We are now ready to introduce left-minimal and right-maximal walks.

\begin{definition}[Left-minimal and right-maximal walks]\label{def:6:left_min_rig_max}
    Let $u$ be a state of $\mathcal{A}$. We say that an infimum (supremum) walk $P_{u}= (u_{i})_{i\geq 1}$ is \emph{left-minimal (right-maximal)} if $P_{u}$ is a leftmost (rightmost) walk to $u$ in the infimum (supremum) graph of $\mathcal{A}$ according to $\leq$.
\end{definition}

The proof of existences of left-minimal and right-maximal walks in directed graphs is given in Theorem~\ref{exleft} in Section~\ref{section: leftmost walk existence}. The next corollary then follows together with Observation~\ref{obs:6:walk_inf_sup_nfa}.

% \vspace{-3pt}
\begin{corollary}\label{ex:leftminimal}
    Let $Q$ be the states of $\mathcal{A}$. There exists $p : Q \rightarrow Q$, such that, for each $u \in Q$, the sequence $(p^{i}(u))_{i \geq 0}$ is a left-minimal infimum (right-maximal supremum) walk to $u$.
\end{corollary}


\section{Inf and Sup Conflicts}
\label{section: inf sup conflicts}
We still consider $\mathcal{A}$ to be a fixed forward-stable NFA and $\leq_{FS}$ and $\leq$ be the maximum co-lex order and a co-lex extension of $\mathcal{A}$, respectively. 
We now define inf/sup conflicts.
\begin{definition}[inf sup conflicts]\label{def:6:min_max_confl}
    Let $u$ be a state of $\mathcal{A}$ and let $P_{u} = (u_{i})_{i\geq1}$ be an infimum (supremum) walk. For $j > 1$, we say that $u_{j}$ is in \emph{inf (sup) conflict} with $P_{u}$, denoted as $u_{j} \sqcap P_{u}$ $(u_{j} \sqcup P_{u})$, if there exists $\bar P_{u} = (\bar{u}_{i})_{i=1}^{j}$ satisfying: (i)~For each $i$ with $1 < i \leq j$, it holds that $\bar{u}_{i} \neq u_{i}$ and $\lambda(\bar{u}_{i}) = \lambda(u_{i})$. (ii)~It holds that $\neg({u}_{j} <_{FS} \bar{u}_{j})$ $(\neg(\bar{u}_{j} <_{FS} {u}_{j}))$.
\end{definition}

At this point, we present a first result concerning inf and sup conflicts.

\begin{restatable}[]{lemma}{lemvi}\label{lem:6:prev_conflict}
    Let $u$ be a state of $\mathcal{A}$, and $P_{u}=(u_{i})_{i\geq1}$ be an infimum (supremum) walk. If for some $j > 1$, $u_{j} \sqcap P_{u}$ $(u_{j} \sqcup P_{u})$ holds, then for any integer $j'$ with $1 < j' \leq j$, it holds that $u_{j'} \sqcap P_{u}$ $(u_{j'} \sqcup P_{u})$.
\end{restatable}

\begin{proof}
    We prove the lemma for infimum walks and inf conflicts; the proof for supremum walks and sup conflicts is analogous. Consider an integer $j$ such that $u_{j} \sqcap P_{u}$ and an arbitrary integer $j'$ with $ 1 < j' <j$. Moreover, let $(\bar{u}_{i})_{i=1}^{j}$ be the walk for which state $u_{j}$ is in inf conflict with $P_{u}$. Clearly, $(\bar{u}_{i})_{i=1}^{j'}$ satisfies condition~(i) of Definition~\ref{def:6:min_max_confl} for $u_{j'} \sqcap P_{u}$. It remains to prove that $\neg(u_{j'} <_{FS} \bar{u}_{j'})$. Note that for each $i$ with $j' \leq i \leq j$, we have $\bar{u}_{i} \neq u_{i}$ and $\lambda(\bar{u}_{i}) = \lambda(u_{i})$. Hence every preceding pair of $(u_{j},\bar{u}_{j})$ is a preceding pair of $(u_{j'},\bar{u}_{j'})$ and it follows from Corollary~\ref{lem:4:prec_pairs_colex} that $\neg(u_{j} <_{FS} \bar{u}_{j})$ implies $\neg(u_{j'} <_{FS} \bar{u}_{j'})$. This proves the lemma.
\end{proof}

We introduce now two functions $\phi$ and $\gamma$ which will be at the basis of our data structure.

\begin{definition}[Functions $\phi$ and $\gamma$]\label{def:6:phi_gamma}
    Let $u$ be a state of $\mathcal{A}$ and let $P_{u}^{\inf}=(u_{i})_{i\geq1}$ and $P_{u}^{\sup}=(u_{i}')_{i\geq1}$ be an infimum walk and a supremum walk to $u$, respectively. We define two functions $\phi$ and $\gamma$ as
    \[
        \phi(u, P_{u}^{\inf}) \coloneqq \max(\{i < 2n : u_{i} \sqcap P_{u}^{\inf} \} \cup \{1\} ),\ 
        \gamma(u, P_{u}^{\sup}) \coloneqq \max(\{i < 2n : u_{i}' \sqcup P_{u}^{\sup} \} \cup \{1\} ).
    \]
    Furthermore, for every integer $j > 1$, we define two functions $\phi^j$ and $\gamma^j$ as 
    \[
        \phi^j(u,P_{u}^{\inf}) \coloneqq \max_{i \in [j-1]}\{\phi(u_{i}, P_{u_{i}}^{\inf}) + i - 1 \},\ 
        \gamma^j(u,P_{u}^{\sup}) \coloneqq \max_{i \in [j-1]}\{\gamma(u_{i}',P_{u_{i}'}^{\sup}) + i - 1\},
    \]
    % \begin{enumerate}
    %     \item $\phi(u,P_{u}^{\inf},j) \coloneqq \max\{\phi(u_{i}, P_{u_{i}}^{\inf}) + i - 1 : i < j\}$
    %     \item $\gamma(u,P_{u}^{\sup},j) \coloneqq \max\{\gamma(u_{i}',P_{u_{i}'}^{\sup}) + i - 1 : i < j\}$
    % \end{enumerate}
    where $P_{u_{i}}^{\inf} = (u_{i'})_{i'\geq i}$ and $P_{u'_{i}}^{\sup} = (u'_{i'})_{i'\geq i}$.
\end{definition}

In other words, the functions $\phi^j(u,P_{u}^{\inf})$ and $\gamma^j(u,P_{u}^{\sup})$ intuitively represent the largest integer $k$ for which either $u_{k} \sqcap P_{u_{i}}^{\inf}$ or $u_{k}' \sqcup P_{u_{i}'}^{\sup}$ holds for an integer $i$ with $i < j$.

\begin{lemma}\label{lem:6:main_lemma}
    Let $u,v$ be two states of $\mathcal{A}$ with $u < v$ and $\sup I_{u} > \inf I_{v}$ and let $P_{u}^{\sup} = (u_{i})_{i\geq 1}$ and $P_{v}^{\inf} = (v_{i})_{i\geq 1}$ be a right-maximal supremum walk and a left-minimal infimum walk according to the co-lex extension $\leq$, respectively. Furthermore, assume there exists an integer $j > 1$ such that $u_{j} = v_{j}$ and $u_{i} < v_{i}$ for each $i \in [j - 1]$. Then $\neg(u <_{FS} v)$ if and only if $\max\{ \gamma^j(u, P_{u}^{\sup}), \phi^j(v, P_{v}^{\inf}) \} \geq j$.
\end{lemma}
\begin{proof}
    $(\Rightarrow)$ By Corollary~\ref{lem:4:prec_pairs_colex}, $\neg(u <_{FS} v)$ implies the existence of a pair $(\bar{u},\bar{v})$ with $(\bar{u},\bar{v})\rightrightarrows(u,v)$ such that $\lambda(\bar{u}) > \lambda(\bar{v})$. 
    Let $(\bar{u}_{i})_{i=1}^{j'}$ and $(\bar{v}_{i})_{i=1}^{j'}$ be the walks for which $(\bar{u},\bar{v})\rightrightarrows(u,v)$ holds, respectively. 
    Lemma~\ref{lem:5:sup_inf_vs_walks} implies that $\lambda(u_{i}) = \lambda(v_{i})$ for each $i \in [j]$ and $j < 2n$. Furthermore, we have $\lambda(\bar{u}_{i}) \leq \lambda(u_{i})$ and $\lambda(v_{i}) \leq \lambda(\bar{v}_{i})$ for each $i \in [j']$ by the properties of supremum and infimum walks. By the properties of preceding pairs (see Definition~\ref{def:4:prec_pairs}), for each $i \in [j]$, it holds that $\lambda(\bar{u}_{i})= \lambda(\bar{v}_{i})$ and thus $\lambda(\bar{u}_{i}) = \lambda(u_{i})$ and $\lambda(v_{i}) = \lambda(\bar{v}_{i})$. Moreover, since $\lambda(\bar{u}) > \lambda(\bar{v})$, it follows that $j' > j$.
    Due to the walks $(\bar{u}_{i})_{i=j}^{j'}$ and $(\bar{u}_{i})_{i=j}^{j'}$, it holds that $(\bar{u},\bar{v})\rightrightarrows(\bar{u}_{j},\bar{v}_j)$, which by Corollary~\ref{lem:4:prec_pairs_colex} and $\lambda(\bar{u}) > \lambda(\bar{v})$ implies $\neg(\bar{u}_{j} <_{FS} \bar{v}_{j})$.
    Now, define $h := \max\{i\in [j-1] : \bar{u}_{i} = u_{i} \}$ and $h' := \max \{ i\in[j -1] :\bar{v}_{i} = v_{i}\}$ and consider $P_{u_{h}}^{\sup} = (u_{i})_{i\geq h}$ and $P_{v_{h'}}^{\inf} = (v_{i})_{i\geq h'}$. 
    In order to prove $\max\{ \gamma^j(u, P_{u}^{\sup}), \phi^j(v, P_{v}^{\inf}) \} \geq j$, since $j < 2n$, it is thus sufficient to prove that 
     $A:=
        u_{j} \sqcup P_{u_{h}}^{\sup} \, \vee \, 
        v_{j} \sqcap P_{v_{h'}}^{\inf}$
    holds. Due to the previous considerations, $(\bar{u}_{i})_{i=h}^{j}$ satisfies condition~(i) of Definition~\ref{def:6:min_max_confl} for $u_{j} \sqcup P^{\sup}_{u_{h}}$, while $(\bar{v}_i)_{i=h'}^{j}$ satisfies condition~(i) of Definition~\ref{def:6:min_max_confl} for $v_{j} \sqcap P_{v_{h'}}^{\inf}$. Hence, $A$ holds if and only if $\neg(\bar{u}_{j} <_{FS} u_{j}) \vee \neg(v_{j} <_{FS} \bar{v}_{j})$ or equivalently $\neg(\bar{u}_{j} <_{FS} u_{j}\wedge v_{j} <_{FS} \bar{v}_{j})$. Since $u_{j} = v_{j}$ and $\leq_{FS}$ is transitive, the conclusion is implied by $\neg(\bar{u}_{j} <_{FS} \bar{v}_{j})$, which we argued above.

    $(\Leftarrow)$ Consider the case where the maximum is attained by $\gamma^j(u, P_{u}^{\sup})$ (the other case is analogous) and call that value $h$. We know $h \geq j$ by hypothesis. By Corollary~\ref{lem:4:prec_pairs_colex}, we have to prove the existence of a pair $(\bar{u},\bar{v})$ with $(\bar{u},\bar{v})\rightrightarrows(u,v)$ such that $\lambda(\bar{u}) > \lambda(\bar{v})$. 
    Let $k\in[j-1]$ be such that $\gamma(u_{k},P_{u_{k}}^{\sup}) + k - 1 = h$. Due to Observation~\ref{obs:6:walk_inf_sup_nfa}, the walk $P_{u_{k}}^{\sup} = (u_{i})_{i \geq k}$ is a supremum walk to $u_k$. Since $u_{h} \sqcup P^{\sup}_{u_{k}}$ and $j \leq h$, by Lemma~\ref{lem:6:prev_conflict} it follows that $u_{j} \sqcup P^{\sup}_{u_{k}}$. Therefore, by Definition~\ref{def:6:min_max_confl} there exists a walk $(\bar{u}_{i})_{i=k}^{j}$ such that $\bar{u}_{i} \neq u_{i}$ and $\lambda(\bar{u}_{i}) = \lambda(u_{i})$ for each $i$ with $k < i \leq j$ as well as $\neg(\bar{u}_{j} <_{FS} u_{j})$. Now define $\bar{u}_{i} := u_{i}$ for $i \in [k]$ and consider the two walks $(\bar{u}_{i})_{i=1}^{j}$ and $(v_{i})_{i=1}^{j}$. Note that $\bar{u}_{k} = u_k$. From Definition~\ref{def:6:min_max_confl} and Lemma~\ref{lem:5:sup_inf_vs_walks} it follows that $\lambda(\bar{u}_i) = \lambda(v_{i})$ for each $i \in [j]$.
    Suppose now that $\bar{u}_{i'} = v_{i'}$ for some $i'$ with $k < i' < j$. We can then define a new supremum walk $(\hat{u}_{i})_{i\geq1}$ to $u$ as follows. We define (i)~$\hat{u}_{i} := \bar{u}_{i}$ for $i \in [i']$, (ii)~$\hat{u}_{i} := v_{i}$ for $i$ with $i' < i < j$, and (iii)~$\hat{u}_{i} := u_{i}$ for $i \geq j$. Since $u_{j} = \hat{u}_{j}$ and $u_{j-1} < \hat{u}_{j-1}$, we conclude that $P_{u}^{\sup}$ is not a right-maximal supremum walk to $u$, a contradiction. Hence, $\bar{u}_{i} \neq v_{i}$ for all $i\in [j]$ and consequently $(\bar{u}_{j},v_{j})\rightrightarrows(u,v)$. Note that $u_{j} = v_{j}$ holds by hypothesis. Finally, since $\neg(\bar{u}_{j} <_{FS} u_{j})$, by Corollary~\ref{lem:4:prec_pairs_colex}, there exists $(\bar{u},\bar{v})$ with $(\bar{u},\bar{v})\rightrightarrows(\bar{u}_{j}, u_{j})$ such that $\lambda(\bar{u}) > \lambda(\bar{v})$. Observation~\ref{trivial:obs:precpair} then implies $(\bar{u},\bar{v})\rightrightarrows(u,v)$.
    % and completes the proof.
\end{proof}

\section{Data Structure}
\label{section: data structure}
In this section, we present our data structure and finally prove Theorem~\ref{6:thr:final_theorem}, the main theorem of this article.
Motivated by the above lemma and our previous observations, the data structure that enjoys the properties promised in Theorem~\ref{6:thr:final_theorem} can be defined as follows.
\begin{description}
    \item[Store.] For each state $u$ of $\mathcal{A}$, we store (i)~a left-minimal infimum walk $P_{u}^{\inf}$ to $u$, (ii)~a right-maximal supremum walk $P_{u}^{\sup}$ to $u$, and (iii)~the integers $\phi(u,P_{u}^{\inf})$ and $\gamma(u,P_{u}^{\sup})$. Furthermore, we store a co-lex extension $\leq$ of $\mathcal{A}$. A possible co-lex extension of $\mathcal{A}$ can be computed in $O(m \log n)$ time using the \emph{ordered partition refinement algorithm}~\cite[Algorithm 1]{becker2023sorting}, where $n$ is the number of states of $\mathcal{A}$, and $m$ the number of transition.
    \item[Query.] The procedure of a query on two arbitrary states $u,v$ is illustrated in Figure~\ref{dectree}. If $u = v$, then $u \leq_{FS} v$ by reflexivity. If $v < u$, then $\neg(u <_{FS} v)$ by Definition~\ref{linear_ext}. If $u < v$, then four possible cases may arise. (i)~Let us consider $\sup I_{u}$ and $\inf I_{v}$, which can be reconstructed from $P_{u}^{\sup}$ and $P_{v}^{\inf}$. If $\sup I_{u} \leq \inf I_{v}$ by Lemma~\ref{lem:5:sup_inf_co_lex} $u <_{FS} v$. (ii)~Otherwise, $\sup I_{u} > \inf I_{v}$ holds. We then check, if there exists $j$ such that $v_{j} < u_{j}$ and $u_{i} < v_{i}$ for all $i\in [j-1]$. If this is the case, then $\neg(u <_{FS} v)$ according to Lemma~\ref{lem:5:sup_inf_vs_walks}. Otherwise, we let $j'$ with $1 < j' < j$ be such that $u_{j'} = v_{j'}$ and $u_{i} < v_{i}$ for all $i\in [j'-1]$. (iii)~By Lemma~\ref{lem:6:main_lemma}, if $h:=\max\{ \gamma^{j'}(u, P_{u}^{\sup}), \phi^{j'}(v, P_{v}^{\inf}) \} < j'$, we know that $u <_{FS} v$, (iv)~while if $h \geq j'$, we know that $\neg(u <_{FS} v)$. 
\end{description}
We refer the reader to Figure~\ref{fig:6:enc_ex} for an example of this data structure.
The correctness of our data structure follows immediately from the description above. In order to establish Theorem~\ref{6:thr:final_theorem}, it remains to argue why the space and query time bounds hold.
\begin{proof}[Proof of Theorem~\ref{6:thr:final_theorem}]
    By Corollary~\ref{ex:leftminimal}, we know that this information can be stored in $O(n)$ space.
    By Lemma~\ref{2nbound}, we can check $\sup I_{u} \leq \inf I_{v}$ in $O(n)$ time, and if this is the case by Lemma~\ref{lem:5:sup_inf_co_lex} $u <_{FS} v$.
    Otherwise, by Lemma~\ref{lem:5:sup_inf_vs_walks}, we can indentify in $O(n)$ time the integer $j < 2n$ such that $v_j < u_j$ and $u_i \leq v_i$ for all $i \in [j-1]$.
    If $u_i < v_{j}$ for all $i \in [j-1]$, then $\neg(u <_{FS} v)$ by Lemma~\ref{lem:5:sup_inf_vs_walks}. 
    On the other hand, if there exists $j'$ with (i)~$j' < j$, (ii)~$u_{j'} = v_{j'}$, and (iii)~$u_{i} < v_{i}$ for all $i \in [j'-1]$, by Definition~\ref{def:6:phi_gamma}, since $j' < 2n$, we can compute $\gamma^{j'}(u,P_u^{\sup})$ and $\phi^{j'}(v,P_v^{\inf})$ in $O(n)$ time.
    Hence the total time complexity is $O(n)$.
\end{proof}

