  \label{fig: intro flow}
\vspace{-0.6cm}
\end{figure*}

Under an action profile $\mathbf{x}$, each player $n\in \mathcal{N}$ has an incentive to deviate from its assigned action $\mathbf{x}_n$ if doing so can increase its utility. The strength of this incentive can be quantified by the difference
\vspace{-0.1cm}\begin{align}
    f_n(\mathbf{x})=\max\limits_{\mathbf{x}_n'\in\mathcal{X}_n}u_n(\mathbf{x}_n',\mathbf{x}_{-n})-u_n(\mathbf{x})\geq 0\label{eq: player i goal}
\end{align}
between the utility corresponding to action profile $\mathbf{x}$ and the maximum utility that player $n$ could obtain given the actions $\mathbf{x}_{-n}$ of the other players. We will refer to \eqref{eq: player i goal} as the \emph{dissatisfaction} of player $n$ at the action profile $\mathbf{x}$.

The set of PNEs for the strategic game at hand contains all action profiles $\mathbf{x}^*$ such that the dissatisfaction equals zero for each player $n\in \mathcal{N}$, i.e.,
\vspace{-0.1cm}\begin{align}
    \mathcal{X}^*:=\{\mathbf{x}^*\in\mathcal{X}|f_n(\mathbf{x}^*)=0\,\, \text{for}\,\, n\in \mathcal{N}\}.\label{eq: pure ne}
\end{align}
The PNE action profiles $\mathbf{x}^*$ in set \eqref{eq: pure ne} are incentive-compatible, such that each player has no reason to deviate from a recommended PNE action profile since following the recommendation is in their own best interest.  In practice, the PNE set may be empty, i.e., $\mathcal{X}^*=\emptyset$. Thus, it is useful to define the $\epsilon$-PNE set as
\vspace{-0.2cm}\begin{align}
    \mathcal{X}^{(\epsilon)}:=\{\mathbf{x}^{(\epsilon)}\in\mathcal{X}|f_n(\mathbf{x}^{(\epsilon)})\leq\epsilon\,\, \text{for}\,\, n\in \mathcal{N}\}\label{eq: epsilon pne}
\end{align}
for $\epsilon\geq 0$. The $\epsilon$-PNE set \eqref{eq: epsilon pne} includes solutions $\mathbf{x}^{(\epsilon)}$ from which unilateral deviations do not improve the local utility of any player by more than $\epsilon$. Thus, for an action profile $\mathbf{x}^{(\epsilon)}\in\mathcal{X}^{(\epsilon)}$, players have no incentive to deviate from the assigned action profile $\mathbf{x}^{(\epsilon)}\in\mathcal{X}^{(\epsilon)}$ as long as they consider a dissatisfaction level $\epsilon$ acceptable. The smallest achievable dissatisfaction level across all players is defined as
\vspace{-0.1cm}\begin{align}
    \epsilon^*=\inf\{\epsilon\in\mathbbm{R}|\mathcal{X}^{(\epsilon)}\neq \emptyset\}.\label{eq: epsilon definition}
\end{align}

The goal of this work is to design and analyze optimization methods that aims at approaching any $\epsilon^*$-PNE solution $\mathbf{x}^{*}\in\mathcal{X}^{(\epsilon^*)}$. As described next, this task is made challenging by the \emph{black-box} nature of the unknown utility functions. 

\subsection{Optimization}\label{ssec: optimization}
The centralized optimizer produces a series of action profiles $\mathbf{x}_t=[\mathbf{x}_{1,t},...,\mathbf{x}_{N,t}]$ at each time $t=1,...,T$ for all $N$ players. For each choice $\mathbf{x}_t$, the optimizer receives a noisy estimate of the utilities $\{u_n(\mathbf{x}_t)\}_{n=1}^N$. Specifically, we adopt a \emph{multi-fidelity} model, whereby the utilities can be measured at one of $M$ fidelity levels $\mathcal{M}=\{1,...,M\}$. Level $m=1$ corresponds to the \emph{lowest-fidelity} measurement, while $m=M$ to the \emph{highest-fidelity} level. Different fidelity levels may correspond to simulators with varying levels of accuracy for physical experiments, or to varying precision levels of measuring instruments. Accordingly, the central optimizer selects a fidelity level vector $\mathbf{m}_t=[m_{1,t},...,m_{N,t}]$ at each time $t$, along with the action profile $\mathbf{x}_t$, to form a decision pair $(\mathbf{x}_t,\mathbf{m}_t)$.

Define as $u_n^{(m)}(\mathbf{x})$ the approximation at fidelity level $m$ of the utility of player $n$. We have 
\vspace{-0.15cm}\begin{align}
    u_n^{(M)}(\mathbf{x})=u_n(\mathbf{x})\label{eq: true func}
\end{align}
for all $n\in\mathcal{N}$, so that the maximum-fidelity version coincides with the function itself. When the optimizer selects a decision pair $(\mathbf{x}_t,\mathbf{m}_{t})$ with fidelity $m_{n,t}$ for player $n$, it receives the noisy feedback
\begin{align}
    y_{n,t}^{(m_{n,t})}=u^{(m_{n,t})}_n(\mathbf{x}_{t})+z_{n,t},\label{eq: noisy utility}
\end{align}
where the observation noise variable $z_{n,t}\sim\mathcal{N}(0,\sigma^2)$ is independent across different players. As a result, at the end of time $t$, the optimizer updates the dataset of observations for each player $n\in\mathcal{N}$ as
\vspace{-0.1cm}\begin{align}
    \mathcal{D}_{n,t}=\Big\{(\mathbf{x}_{1},m_{n,1},y_{n,1}^{(m_{n,1})}),...,(\mathbf{x}_{t},m_{n,t},y_{n,t}^{(m_{n,t})})\Big\}.\label{eq: local dataset}
\end{align}

