Run MF-UCB-PNE-Episode$(\Lambda^{\text{tot}}_j,\{\mathcal{D}_{n,j,0}\}_{n\in\mathcal{N}})$ (Algorithm \ref{table: lf-mi-max}) to obtain the sequence of decision pairs $\mathcal{L}_{j}$, observations $\{\mathbf{y}_{n,j,t_j}\}_{n\in\mathcal{N}}$, accumulated cost $\Lambda_{\mathcal{L}_j}$ and updated dataset $\{\mathcal{D}_{n,j,t_j}\}_{n\in\mathcal{N}}$\\
Obtain the utility confidence interval $\{\mathcal{U}_{n,j}\}_{n\in\mathcal{N}}$ as in \eqref{eq: u j confidence interval}\\
Obtain the dissatisfaction confidence interval $\{\mathcal{C}_{n,j}\}_{n\in\mathcal{N}}$ as in \eqref{eq: j Delta ci} \\
Report the action profile $\tilde{\mathbf{x}}^{(j)}$ via \eqref{eq: j reported x}\\
Select the exploring action profile $\mathbf{x}^{(n_j)}$ via \eqref{eq: exploring strategy profile}\\
Produce the final decision pair $(\mathbf{x}_{j,t_j+1},M\cdot\mathbf{1})$ for current episode $\mathcal{E}_j$ with action profile $\mathbf{x}_{j,t_j+1}$ selected via \eqref{eq: x t+1}\\
Query $(\mathbf{x}_{j,t_j+1},M\cdot\mathbf{1})$ and update datasets as $\mathcal{D}_{n,j+1,0}=\mathcal{D}_{n,j,t_j}\cup(\mathbf{x}_{j,t_j+1},M,u_n(\mathbf{x}_{j,t_j+1})+z_{n,j,t_j+1})$ for all $n\in\mathcal{N}$\\
Update the MOGP posteriors using $\mathcal{D}_{n,j,t_j+1}$ as in \eqref{eq: mogp mean} and \eqref{eq: mogp variance} for all $n\in\mathcal{N}$\\
Calculate the remaining budget $\Lambda^{\text{tot}}_{j+1}=\Lambda^{\text{tot}}_j-\Lambda_{\mathcal{L}_{j}}-N\lambda^{(M)}$\\
Set episode index $j=j+1$
}
Return $\mathbf{x}^{*}=\mathbf{x}_{T_j}$\\
\end{algorithm}

\subsection{Multiple-Output Gaussian Process}\label{ssec: mogp}
For both exploration and evaluation phase, MF-UCB-PNE builds on probabilistic surrogate models for the multi-fidelity utility functions $\{\mathbf{u}_n(\mathbf{x})=[u_n^{(1)}(\mathbf{x}),...,u_n^{(M)}(\mathbf{x})]^{\sf T}\}$ for all players $n\in\mathcal{N}$. Under this model, the vectors $\mathbf{u}_n(\mathbf{x})$ are assumed to be independent across the player index $n$; while the approximations $\{u_n^{(m)}(\mathbf{x})\}_{m\in\mathcal{M}}$ are allowed to be generally correlated across the fidelity index $m$ for each player $n$, following a zero-mean MOGP with kernel function $k((\mathbf{x},m),(\mathbf{x},m'))$ \cite{kennedy2000predicting}. A common MOGP follows the auto-regressive model \cite{kennedy2000predicting,raissi2016deep},
\vspace{-0.1cm}\begin{align}
    u_n^{(m)}(\mathbf{x})= \rho^{(m)} u_n^{(m+1)}(\mathbf{x})+\sqrt{1-(\rho^{(m)})^2}q^{(m)}_n(\mathbf{x}),\label{eq: ar model}
\end{align}
where $0<\rho^{(m)}<1$ is a correlation coefficient, and we have $u_n^{(M)}(\mathbf{x})=u_n(\mathbf{x})\sim\mathcal{GP}(0,\kappa(\mathbf{x},\mathbf{x}'))$, and $q^{(m)}_n(\mathbf{x})\sim\mathcal{GP}(0,\kappa^{(m)}(\mathbf{x},\mathbf{x}'))$, where the kernel functions are often instantiated as the radial basis function (RBF) kernels
\vspace{-0.1cm}\begin{align}
    &\kappa(\mathbf{x},\mathbf{x}')=\exp(-h||\mathbf{x}-\mathbf{x}'||^2),\label{eq: rbf kernels}\\
    &\kappa^{(m)}(\mathbf{x},\mathbf{x}')=\exp(-\zeta^{(m)}||\mathbf{x}-\mathbf{x}'||^2)\label{eq: fidelity kernel}
\end{align}
with lengthscales $h>0$ and $\zeta^{(m)}>0$, respectively. 

Let $\mathbf{y}_{n,t}=[y_{n,1}^{(m_{n,1})},...,y_{n,t}^{(m_{n,t})}]^{\sf T}$ denote the $t\times 1$ observation vector obtained based on the selected actions profiles $\mathbf{X}_t=[\mathbf{x}_1,...,\mathbf{x}_t]$ and fidelity levels $\mathbf{M}_{n,t}=[m_{n,1},...,m_{n,t}]$ for each player $n$ up to time $t$. Using the $t\times t$ covariance matrix $\mathbf{K}(\mathbf{X}_t,\mathbf{M}_{n,t})$ with the $(i,j)$-th element $k((\mathbf{x}_i,m_{n,i}),(\mathbf{x}_j,m_{n,j}))$, the MOGP posterior distribution of the approximation $u_n^{(m)}(\mathbf{x})$ at any action profile $\mathbf{x}$ and fidelity level $m$ given the collected observations \eqref{eq: local dataset} is Gaussian with mean
\vspace{-0.3cm}\begin{equation}
    \mu^{(m)}_{n,t}(\mathbf{x})=\mathbf{k}(\mathbf{x},m)^{\sf T}(\tilde{\mathbf{K}}(\mathbf{X}_{t},\mathbf{M}_{n,t}))^{-1}\mathbf{y}_{n,t},\label{eq: mogp mean}
\end{equation}
and variance
\vspace{-0.1cm}\begin{align}
    [\sigma_{n,t}^{(m)}(\mathbf{x})]^2=&k((\mathbf{x},m),(\mathbf{x},m))-\nonumber\\&\mathbf{k}(\mathbf{x},m)^{\sf T}(\tilde{\mathbf{K}}(\mathbf{X}_{t},\mathbf{M}_{n,t}))^{-1}\mathbf{k}(\mathbf{x},m),\label{eq: mogp variance}
\end{align}
where the $t\times 1$ cross-variance vector $\mathbf{k}(\mathbf{x},m)=[k((\mathbf{x},m),(\mathbf{x}_{1},m_{n,1})),...,k((\mathbf{x},m),(\mathbf{x}_{t},m_{n,t}))]^{\sf T}$ and we defined $\tilde{\mathbf{K}}(\mathbf{X}_{t},\mathbf{M}_{n,t})=\mathbf{K}(\mathbf{X}_{t},\mathbf{M}_{n,t})+\sigma^2\mathbf{I}$. 

Overall, the MOGP mean $\mu^{(m)}_{n,t}(\mathbf{x})$ in \eqref{eq: mogp mean} provides an estimated value for the approximation $u_n^{(m)}(\mathbf{x})$ based on the collected dataset \eqref{eq: local dataset}, while the variance $[\sigma_{n,t}^{(m)}(\mathbf{x})]^2$ quantifies the corresponding uncertainty of the estimate.

\subsection{Exploration Phase}\label{ssec: exploration phase}
With this background in place, we can now define the two phases implemented by MF-UCB-PNE in each episode $\mathcal{E}_j$ (see Fig. \ref{fig: block diagram}). In the exploration phase, we adopt an \emph{information-theoretic} criterion for selecting the sequence of actions. To elaborate, denote as $\mathcal{D}_{n,j,\tau-1}$ the data collected up to time $\tau-1$ in episode $j$. By defined next, at the beginning of time $\tau\geq 1$ in episode $\mathcal{E}_j$, the optimizer's policy $\pi$ selects the next decision pair $(\mathbf{x}_{j,\tau},\mathbf{m}_{j,\tau})$ so as to maximize the ratio between the overall information obtained about the true value of the utility functions $\{u_n(\mathbf{x})\}_{n\in\mathcal{N}}$ and the cost of the selection $(\mathbf{x}_{j,\tau},\mathbf{m}_{j,\tau})$.

The information about the utility function is quantified by the \emph{mutual information} between the true utility value $u_n(\mathbf{x}_{j,\tau})$ and the corresponding observation $y_n^{(m_{n,j,\tau})}$ given the available dataset $\mathcal{D}_{n,j,\tau-1}$. This is defined as \cite{srinivas2012information}
\vspace{-0.15cm}\begin{align}
    &\mathrm{I}(y_n^{(m_{n,j,\tau})};u_n(\mathbf{x}_{j,\tau})|\mathbf{x}_{j,\tau},m_{n,j,\tau},\mathcal{D}_{n,j,\tau-1})\nonumber\\&=\frac{1}{2}\ln\Bigg(1+\frac{[\sigma_{n,j,\tau-1}^{(m_{n,j,\tau})}(\mathbf{x}_{j,\tau})]^2}{\sigma^2}\Bigg),\label{eq: mutual information}
\end{align}
where the GP posterior variance $[\sigma_{n,j,\tau-1}^{(m_{n,j,\tau})}(\mathbf{x}_{j,\tau})]^2$ is given in \eqref{eq: mogp variance}. The mutual information \eqref{eq: mutual information} measures the uncertainty reduction about utility $u_n(\mathbf{x}_{j,\tau})$ that can be obtained by choosing the pair $(\mathbf{x}_{j,\tau},\mathbf{m}_{j,\tau})$ at time step $\tau$ in episode $j$.

Define as 
\vspace{-0.3cm}\begin{align}
    \Lambda^{\text{tot}}_j=\Lambda-\sum_{j'=1}^{j-1}\Lambda_{j'}\label{eq: remaining budget}
\end{align}
the remaining query budget before starting episode $\mathcal{E}_j$, and as
\vspace{-0.3cm}\begin{align}
    \Lambda^{\text{tot}}_{j,\tau}=\Lambda^{\text{tot}}_j-\sum_{n=1}^N\sum_{\tau'=1}^{\tau-1}\lambda^{(m_{n,j,\tau'})}\label{eq: remaining budget at tau}
\end{align}
the remaining budget at step $\tau$ of episode $\mathcal{E}_j$. The following events may occur.
\begin{enumerate}
    \item \emph{Query budget insufficient for exploration}: If the budget is insufficient to accommodate another exploration step followed by the final evaluation step, i.e., if
    \vspace{-0.15cm}\begin{align}
        \Lambda^{\text{tot}}_j<N(\lambda^{(1)}+\lambda^{(M)}),\label{eq: insufficient budget}
    \end{align}
    the exploration phase is concluded, setting $t_j=\tau-1$.
    \item \emph{Query budget sufficient for exploration}: If \eqref{eq: insufficient budget} does not hold, MF-UCB-PNE obtains a \emph{candidate solution} by addressing the problem of maximizing the ratio between the sum of the mutual information \eqref{eq: mutual information} accrued on all players and the corresponding total query costs, i.e.,
    \begin{subequations}\label{eq: constrained opt}
    \vspace{-0.15cm}\begin{align}
        &(\tilde{\mathbf{x}}_{j,\tau},\tilde{\mathbf{m}}_{j,\tau})\nonumber\\&=\argmax\limits_{\mathbf{x}\in\mathcal{X},\mathbf{m}\in\mathcal{M}}\frac{\sum_{n=1}^N \mathrm{I}(y_n^{(m_n)};u_n(\mathbf{x})|\mathbf{x},m_n,\mathcal{D}_{n,j,\tau-1})}{\sum_{n=1}^N\lambda^{(m_n)}}\label{eq: select exploring decision}
    \end{align}
    \begin{equation}
        \text{s.t.}\quad \sum_{n=1}^N\lambda^{(m_n)}\leq\Lambda^{\text{tot}}_{j,\tau}-N\lambda^{(M)}.\label{eq: exploring condition 1}
    \end{equation}
    \end{subequations}
    The constraint \eqref{eq: exploring condition 1} ensures that the remaining query budget after the current query is sufficient for at least an evaluation step at the maximum fidelity level, which has cost $N\lambda^{(M)}$. Having solved problem \eqref{eq: constrained opt}, the following options may be realized.
    \begin{enumerate}
        \item \emph{Large fraction of maximum-fidelity evaluations}: If a sufficiently large fraction of fidelity levels in vector $\mathbf{m}_{j,\tau}$ are equal to $M$, i.e., if the inequality
        \begin{align}
            \frac{\sum_{n=1}^N\mathbbm{1}(m_{n,j,\tau}=M)}{N}\geq\eta\label{eq: exploring condition 2}
        \end{align}
        holds for some threshold $\eta\in[1/N,1]$, then MF-UCB-PNE sets $t_j=\tau-1$ and enters the evaluation phase.
        \item \emph{Small accumulated information gain-cost ratio}: If the information gain-cost ratio accumulated on selected sequence $\mathcal{L}_{j,\tau}=\{(\mathbf{x}_{j,1},\mathbf{m}_{j,1}),...,\\(\mathbf{x}_{j,\tau},\mathbf{m}_{j,\tau})\}$ in current episode $j$ satisfies the inequality
        \vspace{-0.15cm}\begin{align}
        &\frac{\sum_{n=1}^N\mathrm{I}(\mathbf{y}_{n,j,\tau};\{u_n(\mathbf{x})\}_{\mathbf{x}\in\mathcal{L}_{j,\tau}}|\mathcal{L}_{j,\tau},\mathcal{D}_{n,j,0})}{\sum_{n=1}^N\sum_{\tau'=1}^{\tau}\lambda^{(m_{n,j,\tau'})}}\nonumber\\&<1/\sqrt{\Lambda^{\text{tot}}_j},\label{eq: exploring condition 3}
    \end{align}
    then MF-UCB-PNE sets $t_j=\tau-1$ and enters the evaluation phase.
    \item \emph{All other cases}: If neither of the conditions \eqref{eq: exploring condition 2} or \eqref{eq: exploring condition 3} is satisfied, the algorithm sets $(\tilde{\mathbf{x}}_{j,\tau},\tilde{\mathbf{m}}_{j,\tau})$ via \eqref{eq: select exploring decision} and continues the exploration phase.
    \end{enumerate}
\end{enumerate}

\begin{algorithm}[t!]
\caption{MF-UCB-PNE-Episode}\label{table: lf-mi-max}
\SetKwInOut{Input}{Input}
\Input{Remaining budget $\Lambda^{\text{tot}}_j$, datasets $\{\mathcal{D}_{n,j,0}\}_{n\in\mathcal{N}}$, threshold $\eta$}
\SetKwInOut{Output}{Output}
\Output{Sequence $\mathcal{L}_j$, observations $\{\mathbf{y}_{n,j,t_j}\}_{n\in\mathcal{N}}$, accumulated cost $\Lambda_{\mathcal{L}_j}$ and updated dataset $\{\mathcal{D}_{n,j,t_j}\}_{n\in\mathcal{N}}$}\
Initialize episode time $\tau=1$, sequence $\mathcal{L}_{j,0}=\emptyset$, and accumulated cost $\Lambda_{\mathcal{L}_j}=0$\\
\While{\emph{Not End}}{
Select decision pair $(\tilde{\mathbf{x}}_{j,\tau},\tilde{\mathbf{m}}_{j,\tau})$ by solving \eqref{eq: constrained opt}\\
      \If{inequality \eqref{eq: exploring condition 2} or \eqref{eq: exploring condition 3} hold true}
      {
        break 
      }

      \Else{

Update datasets $\mathcal{D}_{n,j,\tau}$ with observation $y_{n}^{(m_{n,j,\tau})}$ for all $n\in\mathcal{N}$\\
Update sequence $\mathcal{L}_{j,\tau}=\mathcal{L}_{j,\tau-1}\cup(\tilde{\mathbf{x}}_{j,\tau},\tilde{\mathbf{m}}_{j,\tau})$\\
Update the MOGP posteriors using $\mathcal{D}_{n,j,\tau}$ as in \eqref{eq: mogp mean} and \eqref{eq: mogp variance} for all $n\in\mathcal{N}$\\
Calculate the accumulated cost $\Lambda_{\mathcal{L}_j}=\Lambda_{\mathcal{L}_j}+\sum_{n=1}^N\lambda^{(m_{n,j,\tau})}$ \\
Set episode time $\tau=\tau+1$
}
Obtain $\mathcal{L}_j=\mathcal{L}_{j,\tau}$ and $\{\mathcal{D}_{n,j,t_j}=\mathcal{D}_{n,j,\tau}\}_{n\in\mathcal{N}}$} 
Return $\mathcal{L}_j$, $\{\mathcal{D}_{n,j,t_j}\}_{n\in\mathcal{N}}$, $\Lambda_{\mathcal{L}_j}$ and $\{\mathbf{y}_{n,j,t_j}\}_{n\in\mathcal{N}}$\\
\end{algorithm}

\subsection{Evaluation Phase}\label{ssec: evaluation phase}
In the final evaluation step, MF-UCB-PNE adopts a strategy that follows UCB-PNE \cite{tay2023no} to select the candidate action profile $\mathbf{x}_{j,t_j+1}$. Accordingly, MF-UCB-PNE starts by computing a confidence interval for true utility function $u_n(\mathbf{x})$ of each player $n$ as
\vspace{-0.1cm}\begin{align}
    \mathcal{U}_{n,j}(\mathbf{x})&=[\check{u}_{n,j}(\mathbf{x}), \hat{u}_{n,j}(\mathbf{x})]\nonumber\\&=[\mu^{(M)}_{n,j,t_j}(\mathbf{x})-\beta_{n,j}\sigma^{(M)}_{n,j,t_j}(\mathbf{x}), \mu^{(M)}_{n,j,t_j}(\mathbf{x})\nonumber\\&\hspace{0.5cm}+\beta_{n,j}\sigma^{(M)}_{n,j,t_j}(\mathbf{x})],\label{eq: u j confidence interval}
\end{align}
where $\beta_{n,j}>0$ is a scaling parameter. We will elaborate on the selection of parameter $\beta_{n,j}$ in the next section. Using the confidence interval $\mathcal{U}_{n,j}(\mathbf{x})$ in \eqref{eq: u j confidence interval} for the utility function, the optimizer also calculates confidence interval for the dissatisfaction $f_n(\mathbf{x})$ in \eqref{eq: player i goal} at each player $n$ as
\begin{align}
    \mathcal{C}_{n,j}(\mathbf{x})&=[\check{f}_{n,j}(\mathbf{x}),\hat{f}_{n,j}(\mathbf{x})]\nonumber\\&=\Big[\max\limits_{\mathbf{x}_n'\in\mathcal{X}}\check{u}_{n,j}(\mathbf{x}_n',\mathbf{x}_{-n})-\hat{u}_{n,j}(\mathbf{x}), \nonumber\\&\hspace{0.6cm}\max\limits_{\mathbf{x}_n'\in\mathcal{X}}\hat{u}_{n,j}(\mathbf{x}_n',\mathbf{x}_{-n})-\check{u}_{n,j}(\mathbf{x})\Big].\label{eq: j Delta ci}
\end{align}

The optimizer then reports an action profile $\tilde{\mathbf{x}}^{(j)}$ for possible execution at the end of episode $j$ as
\begin{align}
    \tilde{\mathbf{x}}^{(j)}=\arg\min\limits_{\mathbf{x}\in\mathcal{X}}\max\limits_{n\in\mathcal{N}}\check{f}_{n,j}(\mathbf{x}).\label{eq: j reported x}
\end{align}
The reported action profile \eqref{eq: j reported x} minimizes the optimistic estimate $\check{f}_{n,j}(\mathbf{x})$ of the dissatisfaction function \eqref{eq: player i goal} for the player $n\in\mathcal{N}$ that has the strongest incentive to deviate. 

To allow for exploration at the maximum fidelity level $M$, the optimizer also searches for the player $n_{j}$ with the maximum dissatisfaction upper confidence bound under the reported action profile $\tilde{\mathbf{x}}^{(j)}$ in \eqref{eq: j reported x}, i.e.,
\vspace{-0.1cm}\begin{align}
    n_{j}=\arg\max\limits_{n\in\mathcal{N}}\hat{f}_{n,j}(\tilde{\mathbf{x}}^{(j)}),\label{eq: worst player}
\end{align}
and then updates the reported action profile $\tilde{\mathbf{x}}^{(j)}$ to the \emph{exploring action profile}
\vspace{-0.1cm}\begin{align}
    \mathbf{x}^{(n_j)}=\Big(\tilde{\mathbf{x}}^{(j)}_{-n_j}, \arg\max\limits_{\mathbf{x}'_{n_j}\in\mathcal{X}_{n_j}}\hat{u}_{n_j,j}(\mathbf{x}'_{n_{j}},\tilde{\mathbf{x}}^{(j)}_{-n_j})\Big).\label{eq: exploring strategy profile}
\end{align}
The exploring action profile $\mathbf{x}^{(n_j)}$ attempts to improve the utility gain for the player $n_j$ that the optimizer believes to have the strongest incentive to deviate from $\tilde{\mathbf{x}}^{(j)}$.

The final decision for the next action profile at the end of episode $\mathcal{E}_j$ is selected between the reported action profile $\tilde{\mathbf{x}}^{(j)}$ in \eqref{eq: j reported x} and the exploring action profile $\mathbf{x}^{(n_j)}$ in \eqref{eq: exploring strategy profile} that brings higher GP posterior variance, i.e.,
\vspace{-0.2cm}\begin{align}
    \mathbf{x}_{j,t_j+1}=\arg\max\limits_{\mathbf{x}\in\{\tilde{\mathbf{x}}^{(j)},\mathbf{x}^{(n_j)}\}}\bigg\{\max_{n\in\mathcal{N}}\Big[\sigma^{(M)}_{n,j,t_j}(\mathbf{x})\Big]^2\bigg\}.\label{eq: x t+1}
\end{align}
The rationale of the choice \eqref{eq: x t+1} refers to a double application of the principle of \emph{optimism in the face of uncertainty} \cite{lai1985asymptotically}.

\section{Theoretical Analysis}\label{sec: theorems}
In this section, we establish theoretical results on the performance of MF-UCB-PNE in terms of the regret \eqref{eq: regret goal}.

Previous work has addressed the analysis of the regret $R(\Lambda)$ in two special cases:
\begin{itemize}
    \item \emph{Multi-fidelity single-player case}: Reference \cite{song2019general} studied the special case of MF-UCB-PNE corresponding to $N=1$ player. In this setting, the goal is to find a maximizer for the utility function of the only player. Note that the notion of PNE does not apply in this case. The work \cite{song2019general} demonstrates that the resulting policy attains a regret that grows sublinearly with the budget $\Lambda$, ensuring the asymptotic \emph{no-regret} condition
    \vspace{-0.1cm}\begin{align}
        \lim_{\Lambda\to\infty}\frac{R(\Lambda)}{\Lambda}=0.\label{eq: no regret}
    \end{align}
    \item \emph{Single-fidelity multi-player case}: Reference \cite{tay2023no} analyzes the scenario with $M=1$, i.e., with a single fidelity level, demonstrating the validity of the limit \eqref{eq: no regret} also in this case.
\end{itemize}
In this section, we extend the proof of the sublinearity of the regret \eqref{eq: regret goal} in the general case with multiple fidelity levels and players.

\subsection{Technical Assumptions}\label{ssec: assumptions}
We start by separating the contribution of different episodes $\{\mathcal{E}_j\}_{j=1}^J$ to the regret $R(\Lambda)$ in \eqref{eq: regret goal}. This is done by defining the episode regret $R(\mathcal{E}_j)$. As detailed next, this captures the gap between the accumulated loss \eqref{eq: additive mf} incurred within the episode $\mathcal{E}_j$ and the optimal dissatisfaction performance that can be achieved given the episode budget $\Lambda_j$, namely $(\Lambda_j/N\lambda^{(M)})\epsilon^*$.
\begin{definition}[Episode Regret]\label{definition: episode regret}
    Denote by $\Lambda_j$ the overall query cost accumulated in episode $\mathcal{E}_j$, i.e.,
    \vspace{-0.2cm}\begin{align}
        \Lambda_j=\sum_{n\in\mathcal{N}}\sum_{\tau=1}^{t_j}\lambda^{(m_{n,j,\tau})}+N\cdot\lambda^{(M)},\label{eq: Lambda j}
    \end{align}
    where $t_j$ is the number of exploration steps in episode $\mathcal{E}_j$. Given a total budget $\Lambda$ and a total number of episodes $J$ satisfying the inequality $\sum_{j=1}^J\Lambda_j\leq\Lambda$, the regret \eqref{eq: regret goal} of MF-UCB-PNE can be expressed as a sum over episodes as
    \vspace{-0.1cm}\begin{align}
        R(\Lambda)=\sum_{j=1}^J R(\mathcal{E}_j).\label{eq: cumulative episode regret}
    \end{align}
    Specifically, in \eqref{eq: cumulative episode regret}, the regret of the $j$-th episode, $\mathcal{E}_j$, is defined as
    \vspace{-0.2cm}\begin{align}
        R(\mathcal{E}_j)=(t_j\cdot C+\epsilon_j)-\frac{\Lambda_j}{N\lambda^{(M)}}\cdot\epsilon^*,\label{eq: episode regret}
    \end{align}
    where $\epsilon_j$ is the maximum dissatisfaction \eqref{eq: player i goal} incurred by the final action profile $\mathbf{x}_{j,t_j+1}$ across all players, i.e.,
    \begin{align}
        \epsilon_j=\max\limits_{n\in\mathcal{N}}f_n(\mathbf{x}_{j,t_j+1}).\label{eq: maximum complaint}
    \end{align}
\end{definition}

% \begin{definition}[Cumulative Regret]\label{definition: cumulative regret}
%     The cumulative regret of MF-UCB-PNE with total budget $\Lambda$ is defined as
%     \begin{align}
%         R(\Lambda)=\sum_{j=1}^JR(\mathcal{E}_j),\label{eq: cumulative episode regret}
%     \end{align}
%     where $J$ is the total number of episodes satisfying $\sum_{j=1}^J\Lambda_j\leq\Lambda$.
% \end{definition}

As in \cite{tay2023no}, we make the following regularity assumptions on the true utility functions of each player.
\begin{assumption}[Function space]\label{assumption: RKHS}
    The utility function $u_n(\mathbf{x})$ for each player $n\in\mathcal{N}$ is assumed to lie in the reproducing kernel Hilbert space (RKHS) $\mathcal{H}_k$ associated with the same kernel function assumed by the MOGP prior. Therefore, the utility function of each player $n\in\mathcal{N}$ can be expressed as
    \begin{align}
        u_n(\mathbf{x})=\sum_{s=1}^{S_n}a_{s}k((\mathbf{x},M),(\mathbf{x}_{s},M)),\label{eq: rkhs function}
    \end{align}
    for some real-valued coefficients $\{a_{s}\}_{s=1}^{S_n}$ and inducing vectors $\{\mathbf{x}_{s}\}_{s=1}^{S_n}$, where the number of terms in the sum, $S_n$, may be unbounded.
\end{assumption}

We also make the standard assumption that the complexity of each utility function $u_n(\mathbf{x})$, as measured by the RKHS norm $||u_n||_{\mathcal{H}_k}$, is bounded \cite{chowdhury2017kernelized,zhang2024bayesian}.
\begin{assumption}[RKHS norm bound]\label{assumption: rkhs norm}
    The RKHS norm of the utility function $u_n(\mathbf{x})$ satisfies the inequality $||u_n||_{\mathcal{H}_k}\leq B$, for all players $n\in\mathcal{N}$ for some known upper bound $B>0$.
\end{assumption}

