\subsection{Regret Analysis}\label{ssec: regret analysis}
To obtain guarantees on the regret $R(\Lambda)$, we select the scaling parameter $\beta_{n,j}>0$ used in the confidence intervals \eqref{eq: u j confidence interval} and \eqref{eq: j Delta ci} as \cite{chowdhury2017kernelized}
\begin{align}
    \beta_{n,j}=B+4\sigma\sqrt{1+\gamma_{n,j}+\ln(1/\delta)},\label{eq: beta}
\end{align} 
where $\delta\in(0,1)$ is a parameter, and $\gamma_{n,j}$ is the \emph{maximal information gain} for player $n\in\mathcal{N}$ at episode $j$. The maximal information gain quantifies the maximum reduction in uncertainty about the utility function $u_n(\mathbf{x})$ that can be attained in episode $\mathcal{E}_j$, which contains $t_j+1$ timesteps. This is defined as the mutual information \cite{srinivas2012information,berkenkamp2023bayesian}
\begin{align}
    \gamma_{n,j}=\max\limits_{\mathbf{X}_{j},\mathbf{M}_{n,j}}\mathrm{I}(\mathbf{Y}_{n,j};\{u_n(\mathbf{x})\}_{\mathbf{x}\in\mathbf{X}_{j}}|\mathbf{X}_{j},\mathbf{M}_{n,j})\label{eq: Tj maximal mi}
\end{align}
between the observations $\mathbf{Y}_{n,j}=[y^{(m_{n,1,1})}_{n},...,y_n^{(m_{n,1,t_1+1})},\\...,y_n^{(m_{n,j,1})},...,y_n^{(m_{n,j,t_j+1})}]$ and the true utility values $\{u_n(\mathbf{x})\}_{\mathbf{x}\in\mathbf{X}_{j}}$ for a given selection of action profiles $\mathbf{X}_{j}=[\mathbf{x}_{1,1},...,\mathbf{x}_{1,t_1+1},...,\mathbf{x}_{j,1},...,\mathbf{x}_{j,t_j+1}]$ and fidelity levels $\mathbf{M}_{n,j}=[m_{n,1,1},...,m_{n,1,t_1+1},...,m_{n,j,1},...,m_{n,j,t_j+1}]$. Evaluating the information gain \eqref{eq: Tj maximal mi} is often computationally infeasible due to the need to optimize over action profiles $\mathbf{X}_j$ and fidelity levels $\mathbf{M}_{n,j}$. Therefore, it is typically approximated via a greedy algorithm \cite{srinivas2012information}. Using the notion $\mathcal{J}=\{1,...,J\}$, the following lemma demonstrates the key property of the confidence interval \eqref{eq: u j confidence interval} with the scaling factor \eqref{eq: beta}.

\begin{lemma}[Uniform Error Bound in RKHS \texorpdfstring{\cite[Theorem 2]{chowdhury2017kernelized}}{}]\label{lemma: tj rkhs utility uniform error bound}
    Let the scaling parameter $\beta_{n,j}$ be selected as in \eqref{eq: beta}. Then, under Assumptions \ref{assumption: RKHS} and \ref{assumption: rkhs norm}, with probability at least $1-\delta$ for any $\delta\in(0,1)$, the confidence interval \eqref{eq: u j confidence interval} is simultaneously valid for all inputs $\mathbf{x}\in\mathcal{X}$ and episodes $j\in\mathcal{J}$, i.e.,
    \begin{align}
        \Pr\big(&|\mu^{(M)}_{n,j,t_j}(\mathbf{x})-u_n(\mathbf{x})|\leq\beta_{n,j}\sigma^{(M)}_{n,j,t_j}(\mathbf{x}),\nonumber\\&\text{for all $\mathbf{x}\in\mathcal{X}$ and $j\in\mathcal{J}$}\big)\geq 1-\delta.\label{eq: rkhs utility uniform error bound}
    \end{align}
\end{lemma}
Lemma \ref{lemma: tj rkhs utility uniform error bound} implies the following properties for the bounds \eqref{eq: pr f cover} on the dissatisfaction of each player $n\in\mathcal{N}$.
\begin{lemma}[Dissatisfaction Coverage \texorpdfstring{\cite[Lemma 1]{tay2023no}}{}]\label{lemma: f interval}
    By building the confidence interval as in \eqref{eq: j Delta ci} for each player $n\in\mathcal{N}$, with probability at least $1-\delta$ for any $\delta\in(0,1)$, the inequalities
    \begin{align}
        \check{f}_{n,j}(\mathbf{x})\leq f_n(\mathbf{x})\leq\hat{f}_{n,j}(\mathbf{x})\label{eq: pr f cover}
    \end{align}
    and
    \begin{align}
        \hat{f}_{n,j}(\mathbf{x})-\check{f}_{n,j}(\mathbf{x})\leq 2\beta_{n,j}\Big(\sigma^{(M)}_{n,j,t_j}(\mathbf{x})+\sigma^{(M)}_{n,j,t_j}(\mathbf{x}^{(n_j)})\Big)
    \end{align}
    are simultaneously valid for all inputs $\mathbf{x}\in\mathcal{X}$ and episodes $j\in\mathcal{J}$.
\end{lemma}

Using these results, the regret $R(\Lambda)$ of MF-UCB-PNE is upper bounded as follows.


\begin{theorem}[Regret Bound of MF-UCB-PNE]\label{theorem: regret bound}
    Under Assumptions \ref{assumption: RKHS} and \ref{assumption: rkhs norm}, with probability at least $1-N\delta$, with $\delta\in(0,1/N)$, the sequence of decision pairs selected by MF-UCB-PNE given total query budget $\Lambda$ incurs a cumulative regret bounded as
    \begin{align}
        R(\Lambda)\leq\bigg(\frac{C}{\lambda^{(1)}}-\frac{\epsilon^*}{\lambda^{(M)}}\bigg)\sqrt{\Lambda}\cdot\gamma_{J}+4\beta_{J}\sqrt{4(J+2)\gamma_{J}},\label{eq: regret upper bound}
    \end{align}
    where $\beta_{J}=\max_{n\in\mathcal{N}}\beta_{n,J}$, and $\gamma_{J}=\max_{n\in\mathcal{N}}\gamma_{n,J}$.
    % \begin{align}
    %     \gamma_{\mathcal{L}}=\sum_{j=1}^J\sum_{n=1}^N\mathrm{I}(\mathbf{y}_{n,j,t_j};\{u_{n}(\mathbf{x})\}_{\mathbf{x}\in\mathcal{L}_{j}}|\mathcal{L}_j,\mathcal{D}_{n,j,0}).\label{eq: gamma L}
    % \end{align}
\end{theorem}
\begin{proof}
    Please see Appendix \ref{appendix: theorem 1 proof}.
\end{proof}

Leveraging the per-episode decomposition \eqref{eq: episode regret}, the regret upper bound \eqref{eq: regret upper bound} is the sum of a regret term incurred while exploring lower fidelity utilities and of a regret term that accounts for the dissatisfaction levels accrued during the evaluation phases. Specifically, the first term in \eqref{eq: regret upper bound} is derived by considering the largest regret obtained during the exploration phases by selecting the minimum fidelity levels $m_{n,j,\tau}=1$ for all players $n$ and episodes $j$. In contrast, the second term in \eqref{eq: regret upper bound} is akin to the regret bound for the single-fidelity multi-player case studied in \cite{tay2023no}.

The upper bound \eqref{eq: regret upper bound} can be leveraged to derive the following no-regret result.

\begin{corollary}[No-Regret of MF-UCB-PNE]\label{corollary: no regret}
    Adopting the RBF kernels \eqref{eq: rbf kernels} and \eqref{eq: fidelity kernel} in the MOGP surrogate model, under Assumptions \ref{assumption: RKHS} and \ref{assumption: rkhs norm}, the MF-UCB-PNE policy ensures the asymptotic no-regret performance \eqref{eq: no regret}.
\end{corollary}
\begin{proof}
    See Appendix \ref{appendix: corollary proof}.
\end{proof}

Finally, we note that the threshold $\eta$ in condition \eqref{eq: exploring condition 2} is not explicitly included in the regret \eqref{eq: regret upper bound}, but setting smaller $\eta$ would lead to shorter episodes with larger $J$, thus increasing the regret upper bound \eqref{eq: regret upper bound}. As verified via numerical results in the following section, this result suggests that it is preferable to choose larger values of the threshold $\eta$ when total query budget $\Lambda$ increases.

\section{Experiments}\label{sec: experiment}
In this section, we empirically evaluate the performance of the proposed MF-UCB-PNE on the synthetic random utility functions adopted in \cite{tay2023no}, as well as on applications to wireless communications systems at the physical and medium access control layers \cite{liang2007power,gkatzikis2011medium}.



\subsection{Benchmarks}\label{ssec: benchmarks}
To the best of our knowledge, MF-UCB-PNE is the first multi-fidelity optimization framework for evaluating PNEs. In light of this, the following \emph{single-fidelity} benchmarks are considered  in the experiments:
\begin{itemize}
    \item \emph{Probability of Equilibrium} (PE) \cite{picheny2019bayesian}: PE selects iterates $\mathbf{x}_t$ with the goal of maximizing the probability of obtaining a PNE, where the probability is approximated using the GP posterior at the maximum fidelity level $M$.
    \item \emph{UCB-PNE} \cite{tay2023no}: UCB-PNE applies only the evaluation phase of MF-UCB-PNE at each episode, choosing each iterate $\mathbf{x}_t$ as in \eqref{eq: x t+1}.
\end{itemize}

Being single fidelity schemes, both PE and UCB-PNE select the maximum-fidelity levels $\mathbf{m}_t=M\cdot\mathbf{1}$ at each round $t$.

