\subsection{Proof of Theorem \ref{theorem: regret bound}}\label{appendix: theorem 1 proof}
We start the proof of Theorem \ref{theorem: regret bound} by deriving an upper bound for the episode regret \eqref{eq: episode regret} as a function of the allocated query budget $\Lambda_j$. By Definitions \ref{definition: episode} and \ref{definition: episode regret}, we have the inequality
\begin{align}
    R(\mathcal{E}_j)&=(t_j\cdot C+\epsilon_j)-\frac{\Lambda_j}{N\lambda^{(M)}}\epsilon^*\nonumber\\&\leq\frac{\Lambda_j-N\lambda^{(M)}}{N\lambda^{(1)}}C+\epsilon_j-\frac{\Lambda_j}{N\lambda^{(M)}}\epsilon^*,\label{eq: expansion of episode regret}
\end{align}
where we set $t_j=\frac{\Lambda_j-N\lambda^{(M)}}{N\lambda^{(1)}}$ as the maximum number of steps during the exploration phase in episode $\mathcal{E}_j$. Assuming that MF-UCB-PNE terminates within $J$ episodes, by Definition \ref{definition: episode regret}, the regret upper bound can be then obtained as
\begin{align}
    R(\Lambda)&\leq\frac{\Lambda-JN\lambda^{(M)}}{N\lambda^{(1)}}C+\sum_{j=1}^J\epsilon_j-\frac{\Lambda}{N\lambda^{(M)}}\epsilon^*\tag{54a}\label{eq: regret line 1}\\&=\frac{\Lambda-JN\lambda^{(M)}}{N\lambda^{(1)}}C-\frac{\Lambda-JN\lambda^{(M)}}{N\lambda^{(M)}}\epsilon^*+\sum_{j=1}^J(\epsilon_j-\epsilon^*)\tag{54b}\label{eq: regret line 3}\\&=\bigg(\frac{C}{N\lambda^{(1)}}-\frac{\epsilon^*}{N\lambda^{(M)}}\bigg)\sum_{j=1}^J\Lambda_{\mathcal{L}_{j}}+\sum_{j=1}^J(\epsilon_j-\epsilon^*).\tag{54c}\label{eq: expanded cumulative regret}
\end{align}
The inequality \eqref{eq: regret line 1} is obtained by summing the episode regret upper bound in \eqref{eq: expansion of episode regret}; equation \eqref{eq: regret line 3} subtracts the best achievable dissatisfaction $J\epsilon^*$ from \eqref{eq: regret line 1} across $J$ episodes, and applies the associative law.
The first term in \eqref{eq: expanded cumulative regret} represents the regret incurred from decision sequences in exploration phases, while the second term in \eqref{eq: expanded cumulative regret} describes the regret obtained by optimizing the utility functions at the maximum fidelity level.


As shown in Algorithm \ref{table: lf-mi-max}, the exploration phase termination conditions \eqref{eq: exploring condition 2} and \eqref{eq: exploring condition 3} are checked by the optimizer sequentially at each time step before including the decision pair \eqref{eq: select exploring decision} in the sequence $\mathcal{L}_{j}$. Therefore, we can guarantee that the cumulative information gain-cost ratio induced on sequence $\mathcal{L}_{j}$ always satisfies the inequality
\begin{align}\tag{55}
    \frac{\sum_{n=1}^N\mathrm{I}(\mathbf{y}_{n,j,t_j};\{u_n(\mathbf{x})\}_{\mathbf{x}\in\mathcal{L}_{j}}|\mathcal{L}_{j},\mathcal{D}_{n,j,0})}{\Lambda_{\mathcal{L}_{j}}}\geq\frac{1}{\sqrt{\Lambda^{\text{tot}}_j}},\label{eq: stopping condition}
\end{align}
where the $t_j\times 1$ vector $\mathbf{y}_{n,j,t_j}$ includes the utility observations obtained on sequence $\mathcal{L}_{j}$ performed by player $n$. Therefore, the cumulated query cost in \eqref{eq: expanded cumulative regret} can be upper bounded as
\begin{align}
    \sum_{j=1}^J\Lambda_{\mathcal{L}_{j}}&\leq\sum_{j=1}^J\frac{\sum_{n=1}^N\mathrm{I}(\mathbf{y}_{n,j,t_j};\{u_n(\mathbf{x})\}_{\mathbf{x}\in\mathcal{L}_{j}}|\mathcal{L}_{j},\mathcal{D}_{n,j,0})}{\frac{1}{\sqrt{\Lambda^{\text{tot}}_j}}}\nonumber\\&\leq N\sqrt{\Lambda}\gamma_{J},\tag{56}\label{eq: low fidelity regret upper bound}
\end{align}
with the maximal information gain $\gamma_{J}=\max_{n\in\mathcal{N}}\gamma_{n,J}$. 
% \begin{align}
%     \gamma_{\mathcal{L}}=\sum_{j=1}^J\sum_{n=1}^N\mathrm{I}(\mathbf{y}_{n,j,t_j};\{u_{n}(\mathbf{x})\}_{\mathbf{x}\in\mathcal{L}_{j}}|\mathcal{L}_j,\mathcal{D}_{n,j,0}).
% \end{align}

Let us denote $\beta_{J}=\max_{n\in\mathcal{N}}\beta_{n,J}$ as the maximum scaling parameter among all players. Then the upper bound for the second term in \eqref{eq: expanded cumulative regret} can be obtained as
\begin{align}
    &\sum_{j=1}^J(\epsilon_j-\epsilon)\nonumber\\&=\sum_{j=1}^J\Big[\max_{n\in\mathcal{N}}f_n(\mathbf{x}_{j,t_j+1})-\max_{n'\in\mathcal{N}}f_{n'}(\mathbf{x}^*)\Big]\tag{57a}\\&\leq\sum_{j=1}^J\Big[\max_{n\in\mathcal{N}}\hat{f}_{n,j}(\mathbf{x}_{j,t_j+1})-\max_{n'\in\mathcal{N}}\check{f}_{n',j}(\mathbf{x}_{j,t_j+1})\Big]\tag{57b}\label{eq: epsilon diff line 4}\\&\leq\sum_{j=1}^J\Big[\hat{f}_{n_j,j}(\mathbf{x}_{j,t_j+1})-\check{f}_{n_j,j}(\mathbf{x}_{j,t_j+1})\Big]\tag{57c}\label{eq: epsilon diff line 5}\\&\leq\sum_{j=1}^J2\beta_{n,j}\Big(\sigma^{(M)}_{n,j,t_j}(\mathbf{x}_{j,t_j+1})+\sigma^{(M)}_{n,j,t_j}(\mathbf{x}^{(n_j)})\Big)\tag{57d}\label{eq: from lemma 1}\\&\leq 4\beta_{J}\Bigg(\sum_{j=1}^J\max\Big(\sigma^{(M)}_{n,j,t_j}(\mathbf{x}_{j,t_j+1}),\sigma^{(M)}_{n,j,t_j}(\mathbf{x}^{(n_j)})\Big)\Bigg)\tag{57e}\\&\leq 4\beta_{J}\sqrt{4(J+2)\gamma_{J}},\tag{57f}\label{eq: sfbo upper bound}
\end{align}
where the inequality \eqref{eq: epsilon diff line 4} is obtained by introducing the upper and lower confidence intervals obtained on the selected action profile $\mathbf{x}_{j,t_j+1}$ instead of the $\epsilon^*$-PNE solution $\mathbf{x}^*$; \eqref{eq: epsilon diff line 5} is obtained by aligning the player index which has the maximum dissatisfaction upper confidence bound as in \eqref{eq: worst player}; \eqref{eq: from lemma 1} is obtained by applying the union bound to Lemma \ref{lemma: f interval}; and the inequality \eqref{eq: sfbo upper bound} is obtained from \cite[Lemma 4]{chowdhury2017kernelized}. 

Therefore, combining \eqref{eq: low fidelity regret upper bound} and \eqref{eq: sfbo upper bound}, we get the upper bound for the regret $R(\Lambda)$ as in \eqref{eq: regret upper bound}, concluding the proof.


\subsection{Proof of Corollary \ref{corollary: no regret}}\label{appendix: corollary proof}
We start the proof of Corollary \ref{corollary: no regret} by showing that the maximal information gain terms in Theorem \ref{theorem: regret bound} grows sub-linearly with the query budget $\Lambda$. According to the selection subroutine in Algorithm \ref{table: lf-mi-max}, the maximal mutual information at the first time step is obtained at the highest fidelity level, i.e.,
\begin{align}
    &\max\limits_{\substack{\mathbf{x}\in\mathcal{X}\\m_n\in\mathcal{M}}}\{\mathrm{I}(y_n^{(m_n)};u_n(\mathbf{x})|\mathbf{x},m_n)=\frac{1}{2}\ln(1+\frac{1}{1+[\sigma_{n,0}^{(m_n)}(\mathbf{x})]^2})\}\nonumber\\&=\max\limits_{\mathbf{x}\in\mathcal{X}}\{\mathrm{I}(y_n^{(M)};u_n(\mathbf{x})|\mathbf{x},M)\}.\tag{58}\label{eq: first step mi}
\end{align}
When the fidelity decision at each time step is selected as $M$, we only perform the evaluation phase. For brevity of notation, we omit the episode index and let $\mathbf{M}_{n,t-1}=M\cdot\mathbf{1}$ denote the fidelity decisions for all the previous $t-1$ time steps in the optimization process. The maximal mutual information in \eqref{eq: first step mi} can be then inductively expressed as
\begin{align}
    \max\limits_{\substack{\mathbf{x}\in\mathcal{X}\\m_n\in\mathcal{M}}}\Bigg\{&\mathrm{I}(y_n^{(m_n)};u_n(\mathbf{x})|\mathbf{x},m_n,\mathbf{X}_{t-1},\mathbf{M}_{n,t-1})\nonumber\\&=\frac{1}{2}\ln\bigg(1+\frac{[\sigma_{n,t-1}^{(M)}(\mathbf{x})]^2}{[\sigma_{n,t-1}^{(M)}(\mathbf{x})]^2+[\sigma_{n,t-1}^{(m_n)}(\mathbf{x})]^2}\bigg)\Bigg\},\tag{59}\label{eq: inductive mi}
\end{align}
which indicates that the maximal mutual information \eqref{eq: inductive mi} is obtained by always querying the action profiles at the maximum-fidelity level $M$. Since the maximal information gain $\gamma_{n,t}$ satisfies submodularity, a diminishing returns property \cite{krause2005near}, it can be upper bounded via a greedy procedure at each time \cite[Section V.A]{srinivas2012information}, i.e.,
\begin{align}
    \gamma_{n,t}&=\max\limits_{\substack{\mathbf{X}_{t}\subset\mathcal{X}\\\mathbf{M}_{n,t}\subset\mathcal{M}}}\mathrm{I}(\mathbf{y}_{t};\{u_n(\mathbf{x})\}_{\mathbf{x}\in\mathbf{X}_t}|\mathbf{X}_{t},\mathbf{M}_{n,t})\nonumber\\&\leq\frac{1}{2}\bigg(1-\frac{1}{e}\bigg)^{-1}\sum_{t'=1}^{t}\max\limits_{\substack{\mathbf{x}_{t'}\in\mathcal{X}\\m_{n,t'}\in\mathcal{M}}} \mathrm{I}(y_{n,t'}^{(m_{n,t'})};u_n(\mathbf{x}_{t'})\nonumber\\&\hspace{0.5cm}|\mathbf{x}_{t'},m_{n,t'},\mathbf{X}_{t'-1},\mathbf{M}_{n,t'-1}).\tag{60}\label{eq: chain rule}
\end{align}
The inequality \eqref{eq: chain rule}, obtained by applying the chain rule of mutual information to \eqref{eq: inductive mi}, shows that the maximal information gain $\gamma_{n,t}$ is accrued by performing greedy mutual information maximization over action profile $\mathbf{x}_{t'}$ with highest fidelity level $m_{n,t'}=M$ at each time step $t'\geq 1$.

Given the selected RBF kernel in MOGP, the maximal information gain is upper bounded by $\gamma_{n,t}=\mathcal{O}(\log (t)^{d+1})$ \cite[Theorem 5]{srinivas2012information}

Therefore, denoting the overall number of time steps as $T_J=\sum_{j=1}^J(t_j+1)$ and plugging the maximal information gain upper bound into the regret upper bound \eqref{eq: regret upper bound}, we get
\begin{align}
    &R(\Lambda)\nonumber\\&\leq\bigg(\frac{C}{\lambda^{(1)}}-\frac{\epsilon^*}{\lambda^{(M)}}\bigg)\sqrt{\Lambda}\cdot\gamma_{J}+4\beta_{J}\sqrt{4(J+2)\gamma_{J}}\tag{61a}\\&\leq \mathcal{O}(\sqrt{\Lambda}\log(T_J)^{d+1})+\mathcal{O}(\sqrt{J}\log(T_J)^{d+1})\tag{61c}\label{eq: no regret line 2}\\&\leq\mathcal{O}\bigg((\sqrt{J}+\sqrt{\Lambda})\log\Big(\frac{\Lambda-J\lambda^{(M)}}{\lambda^{(1)}}+J\Big)^{d+1}\bigg),\tag{61e}\label{eq: final O}
\end{align}
where inequality \eqref{eq: no regret line 2} is obtained by using $\beta_J=\mathcal{O}(\sqrt{\gamma_J})$, and applying the maximal information gain upper bound; and inequality \eqref{eq: final O} is obtained by considering the maximum number of steps one can query given budget $\Lambda$.
The upper bound \eqref{eq: final O} satisfies the limit \eqref{eq: no regret}, hence, MF-UCB-PNE incurs asymptotic no-regret performance.







