    \begin{subfigure}[b]{0.48\textwidth}
    \includegraphics[width=\textwidth]{inter_output2-1}
    \caption{Birth size during life time.}
    \end{subfigure}
    \hfill
    \begin{subfigure}[b]{0.48\textwidth}
        \includegraphics[width=\textwidth]{time_pop_size.png}
        \caption{Full vs random algorithm.}
    \end{subfigure}
