  atime;time.

:-objects
  0..c :: step;
  0..c-1  :: astep.

:-constants
  amt(step) :: int[0..c];
  fill(astep) :: boolean.

:-variables
  T :: step;
  ST :: astep;
  X :: int[0..c].

{amt(ST+1) = X-1} <- amt(ST) = X.
{fill(ST) = true}.
{fill(ST) = false}.

amt(ST+1) = X <- fill(ST) = true & X = c.
<- amt(T) = X & X < 2.

amt(0) = 5.
<- not (amt(c) = 10).
\end{lstlisting}
