\cbla
\end{itemize}
\item[d]: $F := F_1 \lor \dots \lor F_k$.
\end{itemize}

\item[3]: Eliminate variables from $G$ as follows
\begin{itemize}
\item[a]: $G := \forall v{\bf x} ((B_1({\bf x}) \lor \dots \lor B_k({\bf x})) \rightarrow f = v)$ and then equivalently,
