  \caption{Node Path Set}
  \label{tab:path}
  \newcolumntype{P}[1]{>{\raggedright\arraybackslash}p{#1}}
  \begin{tabular}{p{0.5cm}p{3.6cm}p{1cm}p{1.9cm}}
    \toprule
    Node &$e$($\cdot$) &$r$($\cdot$) &Intersection\\
    \midrule
    \textit{1} & \{1 $\rightarrow$ 3, 1 $\rightarrow$ 5, 3 $\rightarrow$ 5, 3 $\rightarrow$ 6, 5 $\rightarrow$ 6, 5 $\rightarrow$ 8, 6 $\rightarrow$ 9\} &\{0 $\rightarrow$ 1\} & \multirow{2}{=}{\{3 $\rightarrow$ 5, 3 $\rightarrow$ 6, 5 $\rightarrow$ 6, 5 $\rightarrow$ 8, 6 $\rightarrow$ 9\} \\ \{0 $\rightarrow$ 1\}} \\
    \textit{3} & \{3 $\rightarrow$ 5, 3 $\rightarrow$ 6, 5 $\rightarrow$ 6, 5 $\rightarrow$ 8, 6 $\rightarrow$ 9\} & \{0 $\rightarrow$ 1, 1 $\rightarrow$ 3\} & \\

